// ============================================================
// GLOBAL ERROR HANDLER  -  shows JS errors on screen for debugging
// ============================================================
function _showErrBanner(text) {
  var d = document.getElementById('jsErrorBanner');
  if (!d) {
    d = document.createElement('div');
    d.id = 'jsErrorBanner';
    d.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#b00020;color:#fff;padding:10px 16px 10px 16px;font:12px/1.5 monospace;max-height:40vh;overflow:auto;';
    d.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;"><b>JavaScript-Fehler:</b>'
      + '<button onclick="document.getElementById(\'jsErrorBanner\').remove()" style="flex-shrink:0;background:rgba(255,255,255,.2);border:none;color:#fff;font-size:15px;line-height:1;padding:1px 6px;cursor:pointer;border-radius:3px;" title="Schließen">&times;</button></div>'
      + '<small style="opacity:.7">Browser: ' + navigator.userAgent.slice(0,80) + '</small><br>';
    document.body.appendChild(d);
  }
  var line = document.createElement('div');
  line.textContent = text;
  d.appendChild(line);
}
window.onerror = function(msg, src, line, col, err) {
  console.error('JS Error:', msg, src, line, col, err);
  var detail = msg + ' [' + (src || '?').replace(/.*\//, '') + ':' + line + ']';
  if (err && err.stack) detail += '\n' + err.stack;
  _showErrBanner(detail);
};

// ============================================================
// DEBOUNCE UTILITY
// ============================================================
function _debounce(fn, ms) {
  let t;
  return function(...a) { clearTimeout(t); t = setTimeout(() => fn.apply(this, a), ms); };
}
const _debouncedFilterMat = _debounce(v => filterMatRows(v), 250);
const _debouncedFilterOv  = _debounce(v => filterUebersichtRows(v), 250);
const _debouncedFilterAz  = _debounce(v => filterAzRows(v), 250);
window.onunhandledrejection = function(e) {
  console.error('Unhandled rejection:', e.reason);
  var r = e.reason;
  var detail = r ? ((r.message || String(r)) + (r.stack ? '\n' + r.stack : '')) : 'Unhandled Promise Rejection';
  _showErrBanner(detail);
};

