function ico(name, cls) {
  const p = _ICON_PATHS[name];
  if (!p) return '';
  const extra = cls ? ' ' + cls : '';
  return `<span class="ico${extra}"><svg viewBox="0 0 24 24">${p}</svg></span>`;
}

