// -- Early theme application (avoid flash) --------------------
(function() {
  var t = localStorage.getItem('bk_theme');
  if (t === 'dark') document.body.classList.add('dark-theme');
})();

// -- Service Worker Registrierung (PWA) -----------------------
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('./sw.js', { updateViaCache: 'none' }).then(reg => {
    console.log('Service Worker registriert.');
    reg.update().catch(err => {
      // Registration was uninstalled (e.g. external URL/proxy) - re-register
      if (String(err).includes('uninstalled')) {
        navigator.serviceWorker.register('./sw.js', { updateViaCache: 'none' }).catch(() => {});
      }
    });
    // Background Sync registrieren, wenn unterstützt
    if ('sync' in reg) {
      reg.sync.register('bk-sync').catch(() => {});
    }
    // Neuen SW sofort aktivieren wenn wartend
    if (reg.waiting) {
      reg.waiting.postMessage({ type: 'SKIP_WAITING' });
    }
    // Warten-auf-Update: SKIP_WAITING senden
    reg.addEventListener('updatefound', () => {
      const nw = reg.installing;
      if (nw) nw.addEventListener('statechange', () => {
        if (nw.state === 'installed' && navigator.serviceWorker.controller) {
          nw.postMessage({ type: 'SKIP_WAITING' });
        }
      });
    });
  }).catch(err => console.warn('SW Registrierung fehlgeschlagen:', err));

  // Nachrichten vom Service Worker empfangen
  navigator.serviceWorker.addEventListener('message', ev => {
    if (ev.data && ev.data.type === 'BK_SYNC_NOW') {
      syncOfflineData();
    }
  });

  // Bei Controller-Wechsel Seite neu laden
  let refreshing = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!refreshing) { refreshing = true; window.location.reload(); }
  });
}

// -- Online / Offline Events ----------------------------------
window.addEventListener('online',  () => {
  isOffline = false;
  document.body.classList.remove('is-offline');
  showNotification('Verbindung hergestellt - Daten werden synchronisiert —');
  syncOfflineData();
});
window.addEventListener('offline', () => {
  isOffline = true;
  document.body.classList.add('is-offline');
  showNotification('Keine Verbindung - Änderungen werden lokal gespeichert.');
});

// -- Collapsible section helpers ------------------------------
function sectionCollapsed(key) {
  return !!collapsedSections[key];
}

function toggleSection(key) {
  const sec = document.getElementById('sec-' + key);
  if (!sec) return;
  collapsedSections[key] = !collapsedSections[key];
  sec.classList.toggle('collapsed', collapsedSections[key]);
  localStorage.setItem('collapsedSections', JSON.stringify(collapsedSections));
}

// ============================================================
// CONFIRM DELETE – Wiederverwendbares Löschbestätigungs-Modal
// ============================================================
/**
 * Zeigt ein Modal-Bestätigungsdialog für Löschoperationen.
 * @param {string}   message              - Anzuzeigende Nachricht (\n wird zu <br>)
 * @param {Function} onConfirm            - Callback bei Bestätigung (kann async sein)
 * @param {object}   [opts]
 * @param {boolean}  [opts.requireTyping] - Nutzer muss "LÖSCHEN" eintippen (default: false)
 */
function confirmDelete(message, onConfirm, { requireTyping = false } = {}) {
  document.querySelector('.confirm-del-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'confirm-del-overlay';
  const typingHtml = requireTyping
    ? `<p class="confirm-del-typing-hint">Zur Bestätigung <strong>LÖSCHEN</strong> eingeben:</p>
       <input type="text" class="confirm-del-input" id="confirmDelInput" placeholder="LÖSCHEN" autocomplete="off">`
    : '';
  overlay.innerHTML = `
    <div class="confirm-del-modal" role="dialog" aria-modal="true">
      <div class="confirm-del-icon">⚠️</div>
      <div class="confirm-del-message">${message.replace(/\n/g, '<br>')}</div>
      ${typingHtml}
      <div class="confirm-del-actions">
        <button class="confirm-del-cancel-btn" id="confirmDelCancel">Abbrechen</button>
        <button class="confirm-del-ok-btn" id="confirmDelOk"${requireTyping ? ' disabled' : ''}>Löschen</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  const cancelBtn = document.getElementById('confirmDelCancel');
  const okBtn     = document.getElementById('confirmDelOk');
  const input     = document.getElementById('confirmDelInput');
  const close = () => { overlay.remove(); document.removeEventListener('keydown', keyHandler); };
  const exec  = () => { close(); onConfirm(); };
  function keyHandler(e) {
    if (e.key === 'Escape') { close(); }
    else if (e.key === 'Enter' && okBtn && !okBtn.disabled) { exec(); }
  }
  document.addEventListener('keydown', keyHandler);
  cancelBtn.addEventListener('click', close);
  overlay.addEventListener('mousedown', e => { if (e.target === overlay) close(); });
  okBtn.addEventListener('click', exec);
  if (requireTyping && input) {
    input.addEventListener('input', () => { okBtn.disabled = input.value.trim() !== 'LÖSCHEN'; });
    setTimeout(() => input.focus(), 50);
  }
}

// ============================================================
// INIT
// ============================================================
async function init() {
  // Offline-Status initialisieren
  isOffline = !navigator.onLine;
  if (isOffline) document.body.classList.add('is-offline');

  // Aktuellen Benutzer ermitteln und Rollen-basierte UI einblenden
  try {
    const r = await fetch('api.php?action=check');
    const j = await r.json();
    if (j.loggedIn) {
      currentUser       = j.username;
      currentRole       = j.role || 'normal';
      currentKuerzel    = j.kuerzel || '';
      currentPerms      = j.permissions || {};
      currentVisibility = j.visibility || 'all';
      currentIsSubunternehmer = j.isSubunternehmer || false;
      currentDienstleisterId  = j.dienstleisterId || null;
      currentStundenKategorie = j.stundenKategorie || '';
      appSettings = j.settings || {};
      setAppVersionFooter(j.version);
      applyTheme(j.theme || localStorage.getItem('bk_theme') || 'light');
      // Offline-Modus: User-Daten lokal sichern
      if (!j.offline) {
        localStorage.setItem('bk_user', JSON.stringify({
          username: currentUser, role: currentRole, kuerzel: currentKuerzel,
          permissions: currentPerms, visibility: currentVisibility,
          isSubunternehmer: currentIsSubunternehmer, dienstleisterId: currentDienstleisterId,
          stundenKategorie: currentStundenKategorie, settings: appSettings
        }));
      }
      // Admin-Buttons
      if (currentRole === 'admin') {
        const btn = document.getElementById('btnUserMgmt');
        if (btn) btn.style.display = '';
        const btn2 = document.getElementById('btnStoragePaths');
        if (btn2) btn2.style.display = '';
        const btn3 = document.getElementById('btnAllgemein');
        if (btn3) btn3.style.display = '';
        const btn4 = document.getElementById('btnUpdate');
        if (btn4) btn4.style.display = '';
      }
      // Offenes Material Button (konfigurierbar über Berechtigungen)
      if (canDo('canSeeOffenesMaterial')) {
        const btn = document.getElementById('btnOffenesMaterial');
        if (btn) btn.style.display = '';
      }
      // Zeitübersicht Button (Admin/Master)
      if (canDo('canSeeZeituebersicht')) {
        const btn = document.getElementById('btnZeituebersicht');
        if (btn) btn.style.display = '';
      }
      // Stundenabgleich Button (Admin/Master)
      if (currentRole === 'admin' || currentRole === 'master') {
        const btn = document.getElementById('btnStundenabgleich');
        if (btn) btn.style.display = '';
      }
      // Wochenplanung Button (Berechtigung prüfen)
      if (canDo('canSeeAllWochenplan') || canDo('canSeeOwnWochenplan')) {
        const btn = document.getElementById('btnWochenplanung');
        if (btn) btn.style.display = '';
      }
      // Stundenauswertung Button (Berechtigung prüfen)
      if (canDo('canSeeStundenauswertung')) {
        const btn = document.getElementById('btnStundenauswertung');
        if (btn) btn.style.display = '';
      }
      // WhatsApp Button (Admin/Master)
      if (currentRole === 'admin' || currentRole === 'master') {
        const btn = document.getElementById('btnWhatsApp');
        if (btn) btn.style.display = '';
        initWhatsApp();
      }
      // Schnellnotizen Button (Admin/Master)
      if (currentRole === 'admin' || currentRole === 'master') {
        const btn1 = document.getElementById('btnSchnellnotizenSidebar');
        if (btn1) btn1.style.display = '';
        const btn2 = document.getElementById('btnSchnellnotizen');
        if (btn2) btn2.style.display = '';
        // Badge laden
        fetch('api.php?action=load_schnellnotizen').then(r=>r.json()).then(j=>{
          if(j.ok){schnellnotizenData=j.notes||[];updateSchnellnotizBadge();}
        }).catch(()=>{});
      }
      // Sicherung wiederherstellen: nur Admin/Master
      if (currentRole === 'normal') {
        const btnRestore = document.getElementById('btnBackupRestore');
        if (btnRestore) btnRestore.style.display = 'none';
      }
      // Vollexport-Download: nur Admin/Master
      if (currentRole === 'admin' || currentRole === 'master') {
        const btnFull = document.getElementById('btnFullExcelDownload');
        if (btnFull) btnFull.style.display = '';
      }
      // Auswertung Button (Berechtigung prüfen)
      if (canDo('canSeeAuswertung') && appSettings.modul_auswertung !== false) {
        const btn = document.getElementById('btnAuswertung');
        if (btn) btn.style.display = '';
      }
      // Dienstleister Button (Admin/Master mit Berechtigung)
      if (canDo('canManageDienstleister') && appSettings.modul_dienstleister !== false) {
        const btn = document.getElementById('btnDienstleister');
        if (btn) btn.style.display = '';
      }
      // Subunternehmer-Bericht Button
      if (canDo('canSeeSubunternehmerReport')) {
        const btn = document.getElementById('btnSubunternehmerReport');
        if (btn) btn.style.display = '';
      }
      // Rechnungen & Angebote Button + Sub-Buttons
      const canSeeAnyRechnung = canDo('canSeeRechnungen') || canDo('canManageRechnungen') || canDo('canSeeAngebote') || canDo('canManageAngebote');
      if (appSettings.modul_rechnungen !== false && canSeeAnyRechnung) {
        const btn = document.getElementById('btnRechnungen');
        if (btn) btn.style.display = '';
        const btnReSub = document.getElementById('btnRechnungenSub');
        if (btnReSub) btnReSub.style.display = (canDo('canSeeRechnungen') || canDo('canManageRechnungen')) ? '' : 'none';
        const btnAnSub = document.getElementById('btnAngeboteSub');
        if (btnAnSub) btnAnSub.style.display = (canDo('canSeeAngebote') || canDo('canManageAngebote')) ? '' : 'none';
      }
      // Terminplanung Button (Berechtigung prüfen)
      if (canDo('canSeeOwnTermine') || canDo('canSeeAllTermine')) {
        const btn = document.getElementById('btnTermine');
        if (btn) btn.style.display = '';
        loadTermineData();
      }
      // Gruppen für aktuellen User laden (v2.10.0)
      fetch('api.php?action=load_gruppen_for_user').then(r=>r.json()).then(j=>{
        if(j.ok) gruppenData = j.gruppen || [];
      }).catch(()=>{});
      // Module visibility based on settings
      applyModuleSettings();
      preloadMetallprofileCatalogToDb();
      maybeAskBrancheOnboarding();
      // Dienstleister-Daten laden
      loadDienstleisterData();
      // User-Badge im Header anzeigen
      showHeaderUserBadge();
    }
  } catch (e) {
    // Offline: lokale User-Daten laden
    const storedUser = localStorage.getItem('bk_user');
    if (storedUser) {
      try {
        const u = JSON.parse(storedUser);
        currentUser       = u.username;
        currentRole       = u.role || 'normal';
        currentKuerzel    = u.kuerzel || '';
        currentPerms      = u.permissions || {};
        currentVisibility = u.visibility || 'all';
        if (currentRole === 'admin') {
          const btn = document.getElementById('btnUserMgmt');
          if (btn) btn.style.display = '';
          const btn2 = document.getElementById('btnStoragePaths');
          if (btn2) btn2.style.display = '';
        }
        if (canDo('canSeeOffenesMaterial')) {
          const btn = document.getElementById('btnOffenesMaterial');
          if (btn) btn.style.display = '';
        }
        if (canDo('canSeeZeituebersicht')) {
          const btn = document.getElementById('btnZeituebersicht');
          if (btn) btn.style.display = '';
        }
        if (currentRole === 'admin' || currentRole === 'master') {
          const btn = document.getElementById('btnStundenabgleich');
          if (btn) btn.style.display = '';
        }
        if (canDo('canSeeAllWochenplan') || canDo('canSeeOwnWochenplan')) {
          const btn = document.getElementById('btnWochenplanung');
          if (btn) btn.style.display = '';
        }
        if (currentRole === 'admin' || currentRole === 'master') {
          const btn = document.getElementById('btnWhatsApp');
          if (btn) btn.style.display = '';
        }
        if (currentRole === 'admin' || currentRole === 'master') {
          const btn1 = document.getElementById('btnSchnellnotizenSidebar');
          if (btn1) btn1.style.display = '';
          const btn2 = document.getElementById('btnSchnellnotizen');
          if (btn2) btn2.style.display = '';
        }
        if (canDo('canSeeAuswertung')) {
          const btn = document.getElementById('btnAuswertung');
          if (btn) btn.style.display = '';
        }
        showHeaderUserBadge();
      } catch (e2) {}
    }
  }

  try {
    await loadData();
  } catch (e) {
    console.error('loadData() fehlgeschlagen:', e);
  }
  applyPermissions();
  checkSidebarResponsive();
  updateOfflineBadge();
  _initIdleLogout();

  // Kundenstamm vorladen (immer, für Baustelle-Zuordnung
  try {
    const kr = await fetch('api.php?action=load_kunden');
    const kj = await kr.json();
    if (kj.ok) kundenData = kj.kunden || [];
  } catch (e) { console.warn('Kunden vorladen fehlgeschlagen:', e); }

  renderSidebar();
  restoreSidebarSections();
  // Startseite aus Einstellungen ermitteln
  const _startseite = appSettings.startseite || '';
  if (_startseite === 'uebersicht') { showUebersicht(); }
  else if (_startseite === 'kundenstamm') { showKundenstamm(); }
  else if (_startseite === 'materialkatalog') { showMaterialKatalog(); }
  else if (_startseite === 'stundenkatalog') { showStundenKatalog(); }
  else if (_startseite === 'rechnungen' && canDo('canSeeRechnungen') || _startseite === 'rechnungen' && canDo('canManageRechnungen')) { showRechnungenView(); }
  else if (_startseite === 'auswertung' && canDo('canSeeAuswertung')) { showAuswertung(); }
  else if (_startseite === 'dashboard' && appSettings.modul_dashboard === true && canDo('canReadDashboard')) { showDashboard(); }
  else if (_startseite === 'schnellnotizen') { showSchnellnotizen(); }
  else if (_startseite === 'dienstleister' && canDo('canManageDienstleister')) { showDienstleister(); }
  else if (appData.baustellen.length > 0) {
    selectBaustelle(appData.baustellen[0].id);
  }

  // Falls Sync ausstehend, automatisch versuchen
  if (navigator.onLine && localStorage.getItem('bk_syncPending')) {
    setTimeout(syncOfflineData, 2000);
  }
}

function showHeaderUserBadge() {
  const el = document.getElementById('headerUserBadge');
  if (!el || !currentUser) return;
  const kTag = currentKuerzel ? `<span class=\"kuerzel-tag\">${esc(currentKuerzel)}</span>` : '';
  el.innerHTML = `${ico('users')} ${esc(currentUser)} ${kTag}`;
  el.style.display = '';
}

async function loadData() {
  try {
    const r = await fetch('api.php?action=load');
    if (r.status === 401) {
      window.location.replace('login.html?from=index.html');
      return;
    }
    const j = await r.json();
    if (j.data) {
      appData = j.data;
      // Optimistic Locking: Revision übernehmen, auf der dieser Stand basiert
      appDataRev = (typeof j.data.rev === 'number') ? j.data.rev : null;
      delete appData.rev;
      migrateAppData();
      // Baseline für Auto-Merge festhalten (tiefe Kopie des server-synchronen Stands)
      try { appDataBaseline = JSON.parse(JSON.stringify(appData)); } catch (be) { appDataBaseline = null; }
      // Doppelte Positions-IDs wurden korrigiert -> Reparatur sofort dauerhaft sichern.
      if (_posIdRepairNeeded) { _posIdRepairNeeded = false; try { saveData(); } catch (_) {} }
      // Online-Daten lokal sichern für Offline-Modus
      try {
        localStorage.setItem('bk_appData', JSON.stringify(appData));
      } catch (lsErr) {
        console.warn('localStorage voll – Offline-Cache deaktiviert:', lsErr.message);
      }
    } else if (j.offline) {
      // Vom Service Worker: Offline, lade lokale Daten
      loadFromLocalStorage();
    }
  } catch (e) {
    console.warn('Server nicht erreichbar - lade lokale Daten.', e);
    loadFromLocalStorage();
  }
}

function loadFromLocalStorage() {
  const stored = localStorage.getItem('bk_appData');
  if (stored) {
    try {
      appData = JSON.parse(stored);
      migrateAppData();
      try { appDataBaseline = JSON.parse(stored); } catch (_) { appDataBaseline = null; }
      appDataRev = null;
      showNotification('Offline-Modus - lokale Daten geladen.', 'warning');
      _scheduleOnlineRefresh();
    } catch (e) {
      console.error('Lokale Daten fehlerhaft:', e);
    }
  } else {
    showNotification('Keine lokalen Daten vorhanden.');
  }
}

// Sobald Netz wieder da: frische Daten vom Server laden (verhindert Arbeit mit veralteten Daten)
let _onlineRefreshTimer = null;
function _scheduleOnlineRefresh() {
  if (_onlineRefreshTimer) return;
  const doRefresh = async () => {
    if (_onlineRefreshTimer) { clearInterval(_onlineRefreshTimer); _onlineRefreshTimer = null; }
    window.removeEventListener('online', doRefresh);
    try {
      await loadData();
      if (appDataRev !== null) {
        renderSidebar();
        if (selectedId) selectBaustelle(selectedId);
        showNotification('Aktuelle Daten vom Server geladen.', 'success');
      }
    } catch (_) {}
  };
  window.addEventListener('online', doRefresh, { once: true });
  // Fallback: periodischer Retry alle 30s (max 5 Min) falls online-Event nicht feuert
  let attempts = 0;
  _onlineRefreshTimer = setInterval(async () => {
    attempts++;
    if (attempts > 10) { clearInterval(_onlineRefreshTimer); _onlineRefreshTimer = null; return; }
    if (!navigator.onLine) return;
    doRefresh();
  }, 30000);
}

// Erzwingt eindeutige Positions-IDs in einem Array und liefert den korrekten
// nächsten Zählerstand (> größte vorhandene ID). Doppelte/fehlende IDs werden
// neu vergeben. Verhindert, dass Löschen/Bearbeiten einer Position mehrere oder
// die falsche trifft (Ursache: kollidierende IDs durch falschen Zähler).
// true, sobald migrateAppData doppelte/fehlende Positions-IDs korrigiert hat.
let _posIdRepairNeeded = false;

function _ensureUniquePosIds(arr, idField, curNext) {
  if (!Array.isArray(arr)) return parseInt(curNext) || 1;
  let maxId = 0;
  arr.forEach(r => { const v = (r && typeof r[idField] === 'number') ? r[idField] : 0; if (v > maxId) maxId = v; });
  let next = Math.max(parseInt(curNext) || 1, maxId + 1);
  const seen = new Set();
  arr.forEach(r => {
    if (!r) return;
    let v = (typeof r[idField] === 'number') ? r[idField] : null;
    if (v == null || v <= 0 || seen.has(v)) { v = next++; r[idField] = v; _posIdRepairNeeded = true; }
    seen.add(v);
  });
  return next;
}

function migrateAppData() {
  _posIdRepairNeeded = false;
  if (!appData.baustellen)       appData.baustellen       = [];
  if (!appData.pauschalen)       appData.pauschalen       = [];
  if (!appData.materialKatalog)  appData.materialKatalog  = [];
  if (!appData.stundenKatalog)   appData.stundenKatalog   = [];
  (appData.stundenKatalog || []).forEach(k => { if (k.fixkosten == null) k.fixkosten = 0; });
  if (!appData.nextBaustelleId)  appData.nextBaustelleId  = Math.max(1, ...appData.baustellen.map(b => (b.id||0)+1));
  if (!appData.nextPauschaleId)  appData.nextPauschaleId  = Math.max(1, ...appData.pauschalen.map(p => (p.id||0)+1));
  if (!appData.nextKatalogId)    appData.nextKatalogId    = Math.max(1, ...appData.materialKatalog.map(m => (m.id||0)+1));
  if (!appData.nextStundenKatId) appData.nextStundenKatId = Math.max(1, ...appData.stundenKatalog.map(s => (s.id||0)+1));
  if (!appData.nextProjektSeq)   appData.nextProjektSeq   = 1;
  // Backfill missing projektNr: scan existing to find max per year
  const yyNow = String(new Date().getFullYear()).slice(-2);
  const prefixNow = `P${yyNow}-`;
  const mainNrRx = new RegExp(`^P${yyNow}-\\d{4}$`);
  let maxSeqMigrate = 0;
  appData.baustellen.forEach(b => {
    if (b.projektNr && mainNrRx.test(b.projektNr)) {
      const num = parseInt(b.projektNr.substring(prefixNow.length), 10);
      if (!isNaN(num) && num > maxSeqMigrate) maxSeqMigrate = num;
    }
  });
  appData.baustellen.forEach(b => {
    if (!b.projektNr) {
      maxSeqMigrate++;
      b.projektNr = `${prefixNow}${String(maxSeqMigrate).padStart(4, '0')}`;
    }
    if (!b.material)           b.material           = [];
    if (!b.arbeitszeit)        b.arbeitszeit        = [];
    if (!b.abschlaege)         b.abschlaege         = [];
    if (!b.fehlendesMaterial)  b.fehlendesMaterial  = [];
    if (!b.bautagebuch)        b.bautagebuch        = [];
    if (!b.aktivePauschalen)   b.aktivePauschalen   = [];
    // Eindeutige Positions-IDs erzwingen + Zähler korrekt (verhindert, dass
    // Löschen/Bearbeiten einer Position mehrere oder die falsche trifft).
    b.nextMatId          = _ensureUniquePosIds(b.material,          'id', b.nextMatId);
    b.nextAzId           = _ensureUniquePosIds(b.arbeitszeit,       'id', b.nextAzId);
    b.nextAbschlagId     = _ensureUniquePosIds(b.abschlaege,        'id', b.nextAbschlagId);
    b.nextFehlendesMatId = _ensureUniquePosIds(b.fehlendesMaterial, 'id', b.nextFehlendesMatId);
    b.nextTagebuchId     = _ensureUniquePosIds(b.bautagebuch,       'id', b.nextTagebuchId);
    b.arbeitszeit.forEach(r => { if (r.fixkosten == null) r.fixkosten = 0; });
    // -- Datum absichern: NULL/undefined -> '' (String) ----------------------
    // Hintergrund: Wird eine Position (z. B. Arbeitszeit) ohne Datum erfasst,
    // war datum undefined. Diverse Stellen rufen direkt .localeCompare()/.split()
    // bzw. new Date(datum) auf -> TypeError -> Crash der Gesamtübersicht, der
    // Angebots- und Rechnungserstellung. Ein leerer String ist für all diese
    // Operationen unkritisch. Die Eingabe ohne Datum bleibt erhalten (kein
    // Datenverlust), die Summen nutzen kein Datum und stimmen weiterhin.
    ['arbeitszeit', 'material', 'abschlaege', 'fehlendesMaterial', 'bautagebuch', 'pauschalen'].forEach(sec => {
      (b[sec] || []).forEach(r => {
        if (r && (r.datum == null)) r.datum = '';
      });
    });
    // -- Migrate AZ: stundenpreis aus stundenKatalog nachfüllen wenn Feld fehlt --
    // (17.000+ ältere Einträge haben stundenpreis nie gespeichert → recalc/Gesamtübersicht zeigten 0)
    // Nur wenn stundenpreis == null (undefined/null), NICHT wenn explizit 0 gesetzt.
    // WICHTIG: Nur migrieren wenn kat.preis tatsächlich vorhanden (nicht durch PriceFilter entfernt).
    // Ist kat.preis == null (kein canSeePrices), wird stundenpreis NICHT auf 0 gesetzt –
    // sonst würde ein Benutzer ohne Preissicht beim Speichern alle Preise korrumpieren.
    b.arbeitszeit.forEach(r => {
      if (r.stundenpreis == null) {
        if (r.stundenKatId) {
          const kat = (appData.stundenKatalog || []).find(k => k.id === r.stundenKatId);
          if (kat && kat.preis != null) {
            // Preisfelder vorhanden (Admin-Load): aus Katalog befüllen
            r.stundenpreis = parseFloat(kat.preis) || 0;
            r.fixkosten    = parseFloat(kat.fixkosten ?? 0) || 0;
          } else if (!kat) {
            // Kategorie nicht im Katalog (gelöscht?): auf 0 setzen
            r.stundenpreis = 0;
          }
          // Wenn kat vorhanden aber preis == null: PriceFilter hat Preise entfernt.
          // stundenpreis bleibt null → JSON.stringify lässt das Feld weg → kein
          // Datenverlust beim Speichern durch Benutzer ohne canSeePrices.
        } else {
          // Kein stundenKatId: auf 0 setzen (kein Katalogbezug)
          r.stundenpreis = 0;
        }
      }
    });
    // -- Migrate material: menge → anzahl (Feldname-Umbenennung älterer Daten) --
    b.material.forEach(m => {
      if (m.anzahl == null && m.menge != null) { m.anzahl = m.menge; delete m.menge; }
      if (m.anzahl == null) m.anzahl = 0;
    });
    // -- Migrate aktivePauschalen → pauschalen (alter Feldname) --
    if ((!b.pauschalen || b.pauschalen.length === 0) && Array.isArray(b.aktivePauschalen) && b.aktivePauschalen.length > 0) {
      b.pauschalen = b.aktivePauschalen.map(ap => ({
        entryId: ap.id,
        id: ap.pauschaleId,
        anzahl: ap.anzahl || 1,
        datum: ap.datum || ''
      }));
    }
    // -- Migrate pauschalen: old [id,...] ? new [{entryId, id, anzahl, datum},...] --
    if (Array.isArray(b.pauschalen)) {
      b.pauschalen = b.pauschalen.map(entry => {
        if (typeof entry === 'number') return { id: entry, anzahl: 1, datum: '' };
        if (typeof entry === 'object' && entry !== null && entry.id != null) return entry;
        return null;
      }).filter(Boolean);
    } else {
      b.pauschalen = [];
    }
    if (!b.nextPauschaleEntryId) b.nextPauschaleEntryId = 1;
    b.nextPauschaleEntryId = _ensureUniquePosIds(b.pauschalen, 'entryId', b.nextPauschaleEntryId);
  });

  // Unterprojekt-Nummern konsistent auf Parent-Basis setzen (z.B. P26-0001.01)
  normalizeUnterprojektProjektNummern();

  // Bestehende Unterprojekte in der Sidebar standardmäßig sichtbar machen
  (appData.baustellen || []).forEach(p => {
    if (hasSubprojects(p.id) && expandedBaustellen[p.id] == null) {
      expandedBaustellen[p.id] = true;
    }
  });
  localStorage.setItem('expandedBaustellen', JSON.stringify(expandedBaustellen));
}

// Fire-and-forget: persists in background, does not block UI
// Offline: speichert lokal und markiert Sync-Queue
let _saveInProgress = false;
let _savePendingRetry = false;
let _savedBadgeTimer = null;
let _saveDebounceTimer = null;

// Debounced version for oninput handlers - avoids saving on every keystroke
function saveDataDebounced(delay) {
  clearTimeout(_saveDebounceTimer);
  _saveDebounceTimer = setTimeout(() => saveData(), delay || 400);
}

function saveData() {
  clearTimeout(_saveDebounceTimer);
  // Einmal serialisieren – für localStorage und Fetch-Body wiederverwenden
  const _appDataJson = JSON.stringify(appData);
  try {
    localStorage.setItem('bk_appData', _appDataJson);
  } catch (e) {
    // localStorage voll (5 MB Limit) – Offline-Cache nicht verfügbar, Server-Sync läuft weiter
    console.warn('localStorage voll – Offline-Cache deaktiviert:', e.message);
  }

  if (isOffline || !navigator.onLine) {
    // Offline ? nur lokal speichern, Sync markieren
    markSyncPending();
    return;
  }

  // Ein Speicherkonflikt-Dialog ist offen -> nicht erneut mit veralteter baseRev speichern.
  // Die lokalen Änderungen bleiben in appData/localStorage erhalten, bis der Nutzer entscheidet.
  if (_saveConflictActive) return;

  if (_saveInProgress) { _savePendingRetry = true; showSavingBadge(); return; }
  _saveInProgress = true;
  _savePendingRetry = false;
  showSavingBadge();
  const snapshot = '{"data":' + _appDataJson + ',"baseRev":' + (appDataRev === null ? 'null' : appDataRev) + '}';

  fetch('api.php?action=save', {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    snapshot,
  })
  .then(r => {
    if (r.status === 401) { window.location.replace('login.html?from=index.html'); }
    return r.json();
  })
  .then(j => {
    if (j && j.conflict) {
      // Optimistic Locking: ein anderer Nutzer hat zwischenzeitlich gespeichert.
      // Nicht still überschreiben – erst automatischen Merge versuchen, sonst Dialog.
      _savePendingRetry = false;   // keinen Auto-Retry mit veralteter baseRev auslösen
      _saveConflictActive = true;  // weitere Saves pausieren bis Konflikt gelöst ist
      resolveSaveConflict(j);
      return;
    }
    if (j.ok) {
      if (typeof j.rev === 'number') appDataRev = j.rev;
      // Server hält jetzt exakt unseren lokalen Stand -> neue Baseline (String wiederverwenden)
      try { appDataBaseline = JSON.parse(_appDataJson); } catch (be) {}
      _autoMergeAttempts = 0;
      updateFooterStatus(j.ts);
      clearSyncPending();
      if (!_savePendingRetry) showSavedBadge();
    } else {
      console.warn('Server lehnte Speichern ab:', j.error || j);
      markSyncPending();
    }
  })
  .catch(e => {
    console.warn('Speichern fehlgeschlagen - lokal gesichert:', e);
    markSyncPending();
  })
  .finally(() => {
    _saveInProgress = false;
    // Bei offenem Konflikt-Dialog keinen Auto-Retry auslösen
    if (_saveConflictActive) return;
    // Wenn während dem Speichern neue Änderungen kamen, speichern erneut versuchen
    if (_savePendingRetry) saveData();
    // Falls während des Saves weitere Änderungen eingegangen sind, nachholen
    if (_savePendingRetry || syncPending || localStorage.getItem('bk_syncPending')) {
      _savePendingRetry = false;
      setTimeout(() => saveData(), 50);
    }
  });
}

// -- Speicherkonflikt (Optimistic Locking) --------------------
// Zeigt einen Dialog, wenn ein anderer Nutzer zwischenzeitlich gespeichert hat.
function showSaveConflictDialog(info) {
  // Doppelte Dialoge vermeiden
  if (document.getElementById('saveConflictOverlay')) return;
  const by = (info && info.updatedBy) ? String(info.updatedBy) : '';
  let whenTxt = '';
  if (info && info.updatedAt) {
    const d = new Date(info.updatedAt);
    whenTxt = isNaN(d.getTime()) ? String(info.updatedAt)
      : d.toLocaleString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  }
  const whoWhen = (by ? esc(by) : 'Ein anderer Nutzer')
    + (whenTxt ? (' hat um ' + esc(whenTxt) + ' gespeichert') : ' hat zwischenzeitlich gespeichert');

  const ov = document.createElement('div');
  ov.id = 'saveConflictOverlay';
  ov.className = 'modal-overlay';
  ov.style.zIndex = '99999';
  ov.innerHTML = `
    <div class="modal" style="max-width:520px">
      <h3 style="margin-top:0">${ico('alert-triangle')} Speicherkonflikt</h3>
      <p>${whoWhen}.</p>
      <p><strong>Deine Änderungen wurden NICHT gespeichert</strong>, um die Änderungen des anderen Nutzers nicht zu überschreiben.</p>
      <div style="display:flex;flex-direction:column;gap:8px;margin-top:16px">
        <button id="conflictReload" class="btn btn-primary">Neu laden (aktuelle Server-Version übernehmen)</button>
        <button id="conflictForce" class="btn btn-danger">Meine Version erzwingen (überschreibt die andere)</button>
        <button id="conflictCancel" class="btn">Später entscheiden</button>
      </div>
      <p style="font-size:12px;color:var(--muted, #888);margin-bottom:0;margin-top:12px">
        „Neu laden" verwirft deine ungespeicherten lokalen Änderungen. „Erzwingen" überschreibt die zwischenzeitlich gespeicherten Änderungen des anderen Nutzers.
      </p>
    </div>`;
  document.body.appendChild(ov);

  const close = () => { ov.remove(); };

  ov.querySelector('#conflictReload').onclick = async () => {
    close();
    _saveConflictActive = false;
    try {
      await loadData();
      renderSidebar();
      if (typeof selectedId !== 'undefined' && selectedId) selectBaustelle(selectedId);
      clearSyncPending();
      showNotification('Aktuelle Server-Version geladen.');
    } catch (e) {
      console.warn('Neu laden nach Konflikt fehlgeschlagen:', e);
      markSyncPending();
    }
  };

  ov.querySelector('#conflictForce').onclick = () => {
    close();
    _saveConflictActive = false;
    if (appDataRev === null) {
      showNotification('Erzwingen nicht möglich – lokale Daten haben keine gültige Revision. Bitte zuerst Server-Version laden.', 'error');
      markSyncPending();
      return;
    }
    forceSaveData();
  };

  ov.querySelector('#conflictCancel').onclick = () => {
    close();
    _saveConflictActive = false;
    markSyncPending();
    _startConflictRetry();
  };
}

// Erzwingt das Speichern der lokalen Version (überschreibt fremde Änderungen).
function forceSaveData() {
  showSavingBadge();
  const _forceJson = JSON.stringify(appData);
  const snapshot = '{"data":' + _forceJson
    + ',"baseRev":' + (appDataRev === null ? 'null' : appDataRev)
    + ',"forceOverwrite":true}';
  fetch('api.php?action=save', {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    snapshot,
  })
  .then(r => {
    if (r.status === 401) { window.location.replace('login.html?from=index.html'); }
    return r.json();
  })
  .then(j => {
    if (j && j.ok) {
      if (typeof j.rev === 'number') appDataRev = j.rev;
      try { appDataBaseline = JSON.parse(_forceJson); } catch (be) {}
      _autoMergeAttempts = 0;
      updateFooterStatus(j.ts);
      clearSyncPending();
      showSavedBadge();
      showNotification('Deine Version wurde gespeichert (überschrieben).');
    } else {
      console.warn('Erzwungenes Speichern abgelehnt:', j && (j.error || j));
      markSyncPending();
    }
  })
  .catch(e => {
    console.warn('Erzwungenes Speichern fehlgeschlagen:', e);
    markSyncPending();
  });
}

// -- Automatischer Merge bei Speicherkonflikt (Phase 2) -------
// Kanonische Normalform für den Vergleich: Schlüssel sortiert, Zahlen gerundet
// (neutralisiert Key-Reihenfolge nach PHP-Round-Trip und Float-Rauschen).
function _mergeCanonNorm(v) {
  if (v === null || v === undefined) return null;
  const t = typeof v;
  if (t === 'number') return Math.round(v * 1e4) / 1e4;
  if (Array.isArray(v)) return v.map(_mergeCanonNorm);
  if (t === 'object') {
    const out = {};
    Object.keys(v).sort().forEach(k => { out[k] = _mergeCanonNorm(v[k]); });
    return out;
  }
  return v;
}
function _mergeCanonStr(v) {
  if (v === undefined) return '\u0000undef';
  return JSON.stringify(_mergeCanonNorm(v));
}
function _mergeById(arr) {
  const m = {};
  (Array.isArray(arr) ? arr : []).forEach(b => { if (b && b.id != null) m[b.id] = b; });
  return m;
}
function _isNextIdKey(k) { return /^next[A-Za-z]*Id$/.test(k); }
function _mergeSectionLabel(k) {
  const map = { pauschalen: 'Pauschalen', materialKatalog: 'Materialkatalog', stundenKatalog: 'Stundenkatalog' };
  return map[k] || k;
}

// Sektionen INNERHALB einer Baustelle, die per Element-id zusammengeführt werden.
// So verlieren gleichzeitige Bearbeitungen verschiedener Sektionen derselben Baustelle
// (z.B. Abschlagsrechnung vs. Material) sich nicht mehr gegenseitig.
const _BAUSTELLE_MERGE_SECTIONS = ['abschlaege', 'material', 'arbeitszeit', 'pauschalen', 'fehlendesMaterial', 'bautagebuch'];
function _baustelleSectionLabel(k) {
  const map = { abschlaege: 'Abschlagsrechnungen', material: 'Material', arbeitszeit: 'Arbeitszeit', pauschalen: 'Pauschalen', fehlendesMaterial: 'Fehlendes Material', bautagebuch: 'Bautagebuch' };
  return map[k] || k;
}
function _baustelleFieldLabel(k) {
  const map = { name: 'Name', kundeId: 'Kunde', notizen: 'Notizen', matKategorien: 'Material-Kategorien', status: 'Status' };
  return map[k] || k;
}

// 3-Wege-Merge einer Array-Sektion per Element-id. Disjunkte Element-Änderungen
// werden immer übernommen; nur dasselbe Element von beiden Seiten geändert = Konflikt.
function _mergeArrayById(base, loc, srv, resolution) {
  const baseM = _mergeById(base), locM = _mergeById(loc), srvM = _mergeById(srv);
  const out = {};
  let conflict = false;
  (Array.isArray(srv) ? srv : []).forEach(it => { if (it && it.id != null) out[it.id] = it; });
  const ids = new Set([...Object.keys(baseM), ...Object.keys(locM), ...Object.keys(srvM)]);
  ids.forEach(id => {
    const iCh = _mergeCanonStr(locM[id]) !== _mergeCanonStr(baseM[id]);
    if (!iCh) return; // ich unverändert -> Server-Element behalten (inkl. fremd Neues/Geändertes)
    const theyCh = _mergeCanonStr(srvM[id]) !== _mergeCanonStr(baseM[id]);
    if (iCh && theyCh) { conflict = true; if (resolution === 'server') return; }
    if (locM[id] === undefined) delete out[id]; // ich habe dieses Element gelöscht
    else out[id] = locM[id];                    // meine Element-Version
  });
  // Reihenfolge: Server-Reihenfolge zuerst, danach neue lokale Elemente anhängen.
  const arr = [], seen = new Set();
  (Array.isArray(srv) ? srv : []).forEach(it => {
    if (it && it.id != null && out[it.id] !== undefined && !seen.has(String(it.id))) { arr.push(out[it.id]); seen.add(String(it.id)); }
  });
  Object.keys(out).forEach(id => { if (!seen.has(id)) { arr.push(out[id]); seen.add(id); } });
  return { arr, conflict };
}

// Führt eine einzelne Baustelle sektionsweise zusammen (beide Seiten haben sie geändert).
// resolution ('mine'|'server') entscheidet NUR über echte Element-/Feld-Überschneidungen.
function _mergeBaustelleSections(baseB, locB, srvB, resolution) {
  const labels = [];
  const merged = JSON.parse(JSON.stringify(srvB || locB || baseB || {}));
  _BAUSTELLE_MERGE_SECTIONS.forEach(sec => {
    const hasSec = (baseB && sec in baseB) || (locB && sec in locB) || (srvB && sec in srvB);
    if (!hasSec) return;
    const { arr, conflict } = _mergeArrayById(baseB && baseB[sec], locB && locB[sec], srvB && srvB[sec], resolution);
    merged[sec] = arr;
    if (conflict) labels.push(_baustelleSectionLabel(sec));
  });
  const fieldKeys = new Set([...Object.keys(baseB || {}), ...Object.keys(locB || {}), ...Object.keys(srvB || {})]);
  fieldKeys.forEach(k => {
    if (_BAUSTELLE_MERGE_SECTIONS.includes(k)) return;
    if (_isNextIdKey(k)) {
      merged[k] = Math.max(Number(locB && locB[k]) || 0, Number(srvB && srvB[k]) || 0, Number(baseB && baseB[k]) || 0) || 1;
      return;
    }
    const iCh = _mergeCanonStr(locB && locB[k]) !== _mergeCanonStr(baseB && baseB[k]);
    if (!iCh) return; // ich unverändert -> Server-Feld behalten
    const theyCh = _mergeCanonStr(srvB && srvB[k]) !== _mergeCanonStr(baseB && baseB[k]);
    if (iCh && theyCh) { labels.push(_baustelleFieldLabel(k)); if (resolution === 'server') return; }
    if (locB && k in locB) merged[k] = JSON.parse(JSON.stringify(locB[k]));
    else delete merged[k];
  });
  return { baustelle: merged, conflicts: labels };
}

// Ermittelt Konflikte (dieselbe Baustelle-Sektion/-Feld von beiden Seiten geändert).
function _diffMergeConflicts(serverData, baseline) {
  const conflicts = [];
  const baseB = _mergeById(baseline.baustellen), locB = _mergeById(appData.baustellen), srvB = _mergeById(serverData.baustellen);
  const ids = new Set([...Object.keys(baseB), ...Object.keys(locB), ...Object.keys(srvB)]);
  ids.forEach(id => {
    const iCh = _mergeCanonStr(locB[id]) !== _mergeCanonStr(baseB[id]);
    if (!iCh) return;
    const theyCh = _mergeCanonStr(srvB[id]) !== _mergeCanonStr(baseB[id]);
    if (!theyCh) return;
    const name = (locB[id] && locB[id].name) || (srvB[id] && srvB[id].name) || ('#' + id);
    // Lösch-Überschneidung (eine Seite gelöscht, andere geändert) -> ganze Baustelle als Konflikt.
    if (locB[id] === undefined || srvB[id] === undefined) {
      conflicts.push('Baustelle „' + name + '"');
      return;
    }
    // Beide geändert -> nur die tatsächlich überschneidenden Sektionen/Felder melden.
    const { conflicts: secLabels } = _mergeBaustelleSections(baseB[id], locB[id], srvB[id], 'server');
    secLabels.forEach(l => conflicts.push('Baustelle „' + name + '" – ' + l));
  });
  const keys = new Set([...Object.keys(baseline), ...Object.keys(appData), ...Object.keys(serverData)]);
  keys.forEach(k => {
    if (k === 'baustellen' || k === 'rev' || _isNextIdKey(k)) return;
    const iCh = _mergeCanonStr(appData[k]) !== _mergeCanonStr(baseline[k]);
    if (!iCh) return;
    const theyCh = _mergeCanonStr(serverData[k]) !== _mergeCanonStr(baseline[k]);
    if (theyCh) conflicts.push(_mergeSectionLabel(k));
  });
  return conflicts;
}

// Baut den zusammengeführten Datensatz. resolution: 'mine' | 'server' entscheidet
// nur über die konfliktbehafteten Teile; disjunkte Änderungen werden immer übernommen.
function _buildMergedData(serverData, baseline, resolution) {
  const merged = JSON.parse(JSON.stringify(serverData));
  delete merged.rev;
  // Baustellen
  const baseB = _mergeById(baseline.baustellen), locB = _mergeById(appData.baustellen), srvB = _mergeById(serverData.baustellen);
  const mById = _mergeById(merged.baustellen);
  const ids = new Set([...Object.keys(baseB), ...Object.keys(locB), ...Object.keys(srvB)]);
  ids.forEach(id => {
    const iCh = _mergeCanonStr(locB[id]) !== _mergeCanonStr(baseB[id]);
    if (!iCh) return; // ich habe nichts geändert -> Server-Stand behalten
    const theyCh = _mergeCanonStr(srvB[id]) !== _mergeCanonStr(baseB[id]);
    if (!theyCh) {
      // nur ich habe geändert -> meine Version (inkl. Löschung)
      if (locB[id] === undefined) delete mById[id];
      else mById[id] = locB[id];
      return;
    }
    // Beide geändert
    if (locB[id] === undefined || srvB[id] === undefined) {
      // Lösch-Überschneidung -> resolution entscheidet über die ganze Baustelle
      if (resolution === 'server') { if (srvB[id] === undefined) delete mById[id]; else mById[id] = srvB[id]; }
      else { if (locB[id] === undefined) delete mById[id]; else mById[id] = locB[id]; }
      return;
    }
    // Sektionsweiser Merge: disjunkte Sektionen (z.B. Abschläge vs. Material) bleiben ALLE erhalten.
    const { baustelle } = _mergeBaustelleSections(baseB[id], locB[id], srvB[id], resolution);
    mById[id] = baustelle;
  });
  merged.baustellen = Object.values(mById);
  // Top-Level-Sektionen (Kataloge/Pauschalen/nextIds/übrige Felder)
  const keys = new Set([...Object.keys(baseline), ...Object.keys(appData), ...Object.keys(serverData)]);
  keys.forEach(k => {
    if (k === 'baustellen' || k === 'rev') return;
    if (_isNextIdKey(k)) {
      merged[k] = Math.max(Number(appData[k]) || 0, Number(serverData[k]) || 0, Number(baseline[k]) || 0) || 1;
      return;
    }
    const iCh = _mergeCanonStr(appData[k]) !== _mergeCanonStr(baseline[k]);
    if (!iCh) return; // Server-Stand behalten
    const theyCh = _mergeCanonStr(serverData[k]) !== _mergeCanonStr(baseline[k]);
    if (iCh && theyCh && resolution === 'server') return; // Konflikt -> Server gewinnt
    merged[k] = JSON.parse(JSON.stringify(appData[k]));
  });
  return merged;
}

// Übernimmt den gemergten Stand lokal und speichert ihn (baseRev = frische Server-Revision).
function _applyMergedAndSave(merged, serverRev, msg) {
  appData = merged;
  appDataRev = serverRev;
  try { appDataBaseline = JSON.parse(JSON.stringify(appData)); } catch (be) { appDataBaseline = null; }
  if (typeof migrateAppData === 'function') migrateAppData();
  _saveConflictActive = false;
  _stopConflictRetry();
  try {
    renderSidebar();
    if (typeof selectedId !== 'undefined' && selectedId) selectBaustelle(selectedId);
    if (typeof recalc === 'function') recalc();
  } catch (re) { console.warn('Re-Render nach Merge:', re); }
  if (msg) showNotification(msg);
  saveData();
}

// Löst einen 409-Konflikt auf: frische Server-Daten holen, disjunkte Änderungen
// automatisch zusammenführen; nur bei echter Überschneidung den Dialog zeigen.
async function resolveSaveConflict(info) {
  if (_autoMergeAttempts > 5 || !appDataBaseline) {
    // Kein sicherer Merge möglich -> klassischer Konflikt-Dialog
    showSaveConflictDialog(info);
    return;
  }
  _autoMergeAttempts++;
  try {
    const r = await fetch('api.php?action=load');
    if (r.status === 401) { window.location.replace('login.html?from=index.html'); return; }
    const jl = await r.json();
    if (!jl || !jl.data) throw new Error('Keine Server-Daten');
    const serverData = jl.data;
    const serverRev = (typeof serverData.rev === 'number') ? serverData.rev : null;
    delete serverData.rev;
    const conflicts = _diffMergeConflicts(serverData, appDataBaseline);
    if (conflicts.length === 0) {
      const merged = _buildMergedData(serverData, appDataBaseline, 'mine');
      _applyMergedAndSave(merged, serverRev, 'Änderungen automatisch zusammengeführt.');
    } else {
      showMergeConflictDialog(info, conflicts, serverData, serverRev);
    }
  } catch (e) {
    console.warn('Auto-Merge fehlgeschlagen, zeige Dialog:', e);
    showSaveConflictDialog(info);
  }
}

// Scoped-Dialog: nur die tatsächlich kollidierenden Teile müssen entschieden werden;
// alle disjunkten Änderungen bleiben in beiden Varianten erhalten.
function showMergeConflictDialog(info, conflicts, serverData, serverRev) {
  if (document.getElementById('saveConflictOverlay')) return;
  const by = (info && info.updatedBy) ? esc(String(info.updatedBy)) : 'Ein anderer Nutzer';
  const list = conflicts.map(c => '<li>' + esc(c) + '</li>').join('');
  const ov = document.createElement('div');
  ov.id = 'saveConflictOverlay';
  ov.className = 'modal-overlay';
  ov.style.zIndex = '99999';
  ov.innerHTML = `
    <div class="modal" style="max-width:560px">
      <h3 style="margin-top:0">${ico('alert-triangle')} Speicherkonflikt</h3>
      <p>${by} hat dieselben Daten gleichzeitig bearbeitet. Deine übrigen Änderungen
         wurden bereits automatisch übernommen – nur hier gibt es eine Überschneidung:</p>
      <ul style="margin:8px 0 14px">${list}</ul>
      <div style="display:flex;flex-direction:column;gap:8px">
        <button id="conflictTakeServer" class="btn btn-primary">Fremde Version übernehmen (meine übrigen Änderungen bleiben)</button>
        <button id="conflictTakeMine" class="btn btn-danger">Meine Version erzwingen (nur die betroffenen Teile)</button>
        <button id="conflictCancel" class="btn">Später entscheiden</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  const close = () => ov.remove();
  ov.querySelector('#conflictTakeServer').onclick = () => {
    close();
    _applyMergedAndSave(_buildMergedData(serverData, appDataBaseline, 'server'), serverRev,
      'Zusammengeführt – bei Überschneidung wurde die fremde Version übernommen.');
  };
  ov.querySelector('#conflictTakeMine').onclick = () => {
    close();
    _applyMergedAndSave(_buildMergedData(serverData, appDataBaseline, 'mine'), serverRev,
      'Zusammengeführt – deine Version wurde bei Überschneidung erzwungen.');
  };
  ov.querySelector('#conflictCancel').onclick = () => {
    close();
    _saveConflictActive = false;
    markSyncPending();
    _startConflictRetry();
  };
}

// -- Zyklischer Hintergrund-Merge nach "Später entscheiden" ---
// Versucht alle 30s einen Auto-Merge (max 5 Min = 10 Versuche).
// Löst sich der Konflikt auf (anderer Nutzer hat inzwischen gespeichert,
// Überschneidung ist weg), wird lautlos zusammengeführt.
function _startConflictRetry() {
  _stopConflictRetry();
  _conflictRetryCount = 0;
  _conflictRetryTimer = setInterval(async () => {
    _conflictRetryCount++;
    if (_conflictRetryCount > 10 || _saveConflictActive || !navigator.onLine) {
      _stopConflictRetry();
      return;
    }
    if (document.getElementById('saveConflictOverlay')) return; // Dialog offen
    try {
      _autoMergeAttempts = 0; // Reset für frischen Versuch
      _saveConflictActive = true;
      await resolveSaveConflict({});
      // Wenn resolveSaveConflict erfolgreich merged, setzt es _saveConflictActive=false
      // und ruft saveData() auf → bei Erfolg: Timer stoppen
      if (!_saveConflictActive && !localStorage.getItem('bk_syncPending')) {
        _stopConflictRetry();
        showNotification('Änderungen im Hintergrund zusammengeführt ✓');
      }
    } catch (e) {
      _saveConflictActive = false;
    }
  }, 30000);
}
function _stopConflictRetry() {
  if (_conflictRetryTimer) { clearInterval(_conflictRetryTimer); _conflictRetryTimer = null; }
  _conflictRetryCount = 0;
}

// -- Offline-Sync Hilfsfunktionen -----------------------------
function markSyncPending() {
  syncPending = true;
  localStorage.setItem('bk_syncPending', '1');
  updateOfflineBadge();
}

function clearSyncPending() {
  syncPending = false;
  localStorage.removeItem('bk_syncPending');
  updateOfflineBadge();
}

function _ensureBadge() {
  let badge = document.getElementById('offlineBadge');
  if (!badge) {
    badge = document.createElement('div');
    badge.id = 'offlineBadge';
    badge.className = 'offline-badge';
    document.body.appendChild(badge);
  }
  return badge;
}

function showSavingBadge() {
  if (_savedBadgeTimer) { clearTimeout(_savedBadgeTimer); _savedBadgeTimer = null; }
  const badge = _ensureBadge();
  badge.textContent = 'wird gespeichert —';
  badge.classList.add('show');
}

function showSavedBadge() {
  const badge = _ensureBadge();
  badge.textContent = 'gespeichert';
  badge.classList.add('show');
  if (_savedBadgeTimer) clearTimeout(_savedBadgeTimer);
  _savedBadgeTimer = setTimeout(() => {
    _savedBadgeTimer = null;
    updateOfflineBadge();   // hides badge if no pending sync
  }, 1500);
}

function updateOfflineBadge() {
  // Don't override "gespeichert" or "wird gespeichert" while active
  if (_savedBadgeTimer || _saveInProgress) return;
  const badge = _ensureBadge();
  if (isOffline || !navigator.onLine) {
    badge.textContent = 'Offline';
    badge.classList.add('show');
  } else if (syncPending || localStorage.getItem('bk_syncPending')) {
    badge.textContent = 'Sync ausstehend —';
    badge.classList.add('show');
  } else {
    badge.classList.remove('show');
  }
}

async function syncOfflineData() {
  if (!navigator.onLine) return;
  if (!localStorage.getItem('bk_syncPending')) return;

  let allOk = true;

  // Sync appData – mit baseRev, damit veraltete Offline-Daten nicht die DB überschreiben
  const stored = localStorage.getItem('bk_appData');
  if (stored) {
    try {
      const payload = { data: JSON.parse(stored) };
      // baseRev aus dem letzten erfolgreichen Laden/Speichern mitgeben
      if (appDataRev !== null) payload.baseRev = appDataRev;
      const r = await fetch('api.php?action=save', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify(payload),
      });
      const j = await r.json();
      if (j.ok) {
        if (typeof j.rev === 'number') appDataRev = j.rev;
        updateFooterStatus(j.ts);
      } else if (j.conflict) {
        // Offline-Daten kollidieren mit zwischenzeitlichen Server-Änderungen.
        // Auto-Merge versuchen (disjunkte Änderungen zusammenführen);
        // nur bei echter Überschneidung wird der Konflikt-Dialog gezeigt.
        _saveConflictActive = true;
        await resolveSaveConflict(j);
      } else { allOk = false; }
    } catch (e) { allOk = false; console.warn('AppData sync fehlgeschlagen:', e); }
  }

  // Sync Wochenplanung (offline queue)
  const wpOffline = localStorage.getItem('bk_wpPlan_offline');
  if (wpOffline) {
    try {
      const r = await fetch('api.php?action=save_wochenplanung', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    wpOffline,
      });
      const j = await r.json();
      if (j.ok) {
        localStorage.removeItem('bk_wpPlan_offline');
      } else { allOk = false; }
    } catch (e) { allOk = false; console.warn('WP sync fehlgeschlagen:', e); }
  }

  if (allOk) {
    clearSyncPending();
    showNotification('Offline-Daten erfolgreich synchronisiert.');
  }
}

// ============================================================
// BAUSTELLEN  -  CRUD
// ============================================================
function generateProjektNr() {
  const yy = String(new Date().getFullYear()).slice(-2);
  const prefix = `P${yy}-`;
  const mainNrRx = new RegExp(`^P${yy}-\\d{4}$`);
  let maxSeq = 0;
  (appData.baustellen || []).forEach(b => {
    if (b.projektNr && mainNrRx.test(b.projektNr)) {
      const num = parseInt(b.projektNr.substring(prefix.length), 10);
      if (!isNaN(num) && num > maxSeq) maxSeq = num;
    }
  });
  return `${prefix}${String(maxSeq + 1).padStart(4, '0')}`;
}

function preloadMetallprofileCatalogToDb() {
  if (appSettings.modul_metall_erfassung === false) return;
  fetch('api.php?action=metallprofile_catalog')
    .then(r => r.json())
    .then(() => {})
    .catch(() => {});
}

function generateUnterprojektNr(parent) {
  const baseNr = (parent?.projektNr || '').trim() || generateProjektNr();
  let maxSubSeq = 0;
  const escaped = baseNr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const rx = new RegExp(`^${escaped}\\.(\\d{2})$`);

  (appData.baustellen || []).forEach(b => {
    if (b.parentId !== parent.id || !b.projektNr) return;
    const m = b.projektNr.match(rx);
    if (!m) return;
    const n = parseInt(m[1], 10);
    if (!isNaN(n) && n > maxSubSeq) maxSubSeq = n;
  });

  return `${baseNr}.${String(maxSubSeq + 1).padStart(2, '0')}`;
}

function normalizeUnterprojektProjektNummern() {
  const projects = appData.baustellen || [];
  const parentById = Object.fromEntries(projects.map(p => [p.id, p]));

  projects.forEach(parent => {
    const subs = projects
      .filter(p => p.parentId === parent.id)
      .sort((a, b) => (a.id || 0) - (b.id || 0));

    if (!subs.length) return;

    if (!parent.projektNr) parent.projektNr = generateProjektNr();
    const base = parent.projektNr;

    subs.forEach((sub, idx) => {
      sub.projektNr = `${base}.${String(idx + 1).padStart(2, '0')}`;
      if (!sub.kundeId && parent.kundeId) sub.kundeId = parent.kundeId;
    });
  });

  // Verwaiste Unterprojekte bereinigen (falls parent gelöscht wurde)
  projects.forEach(p => {
    if (p.parentId && !parentById[p.parentId]) {
      p.parentId = null;
      if (!p.projektNr) p.projektNr = generateProjektNr();
    }
  });
}

function addBaustelle(prefillKundeId) {
  if (!canDo('canCreateBaustelle')) { showNotification('Keine Berechtigung.'); return; }
  // Ensure Kunden data is loaded
  const showDialog = () => {
    const kundenOpts = (() => {
      let html = '<option value="">— kein Kunde —</option>';
      const sorted = [...(kundenData||[])].sort((a,b) => (a.firma||a.nachname||'').localeCompare(b.firma||b.nachname||''));
      sorted.forEach(k => {
        const label = [k.firma, k.vorname, k.nachname].filter(Boolean).join(' ');
        html += `<option value="${k.id}"${k.id === prefillKundeId ? ' selected' : ''}>${esc(label)}</option>`;
      });
      return html;
    })();
    const overlay = document.createElement('div');
    overlay.className = 'kunde-form-overlay';
    overlay.id = 'addBaustelleOverlay';
    overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
    overlay.innerHTML = `<div class="kunde-form-card" style="max-width:520px">
      <h3>Neues Projekt anlegen</h3>
      <div style="margin-bottom:12px">
        <label style="font-size:.82rem;font-weight:600;color:var(--grey-600);display:block;margin-bottom:4px">Projektname</label>
        <input id="newBaustelleNameInput" class="form-control" style="width:100%;padding:8px" placeholder="z.B. Einfamilienhaus Müller" autofocus>
      </div>
      <div style="margin-bottom:12px">
        <label style="font-size:.82rem;font-weight:600;color:var(--grey-600);display:block;margin-bottom:4px">Kunde zuweisen</label>
        <input id="newBaustelleKundeSearch" class="form-control" style="width:100%;padding:6px 8px;margin-bottom:4px;font-size:.82rem" placeholder="Kunde suchen..." oninput="filterNewBaustelleKunde(this.value)">
        <select id="newBaustelleKunde" class="form-control" style="width:100%;padding:8px">${kundenOpts}</select>
        <button class="btn btn-ghost btn-sm" style="margin-top:6px;font-size:.75rem" onclick="openKundeFormFromBaustelle()">+ Neuer Kunde</button>
      </div>
      <div class="kunde-form-actions">
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('addBaustelleOverlay')?.remove()">Abbrechen</button>
        <button class="btn btn-primary btn-sm" onclick="confirmAddBaustelleDesktop()">Erstellen</button>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    setTimeout(() => {
      const inp = document.getElementById('newBaustelleNameInput');
      if (inp) { inp.focus(); inp.addEventListener('keydown', e => { if (e.key === 'Enter') confirmAddBaustelleDesktop(); }); }
    }, 100);
  };
  if (!kundenData || kundenData.length === 0) {
    fetch('api.php?action=load_kunden').then(r=>r.json()).then(j=>{
      kundenData = j.kunden || [];
      showDialog();
    }).catch(() => showDialog());
  } else {
    showDialog();
  }
}

let _baustelleKundeCallback = null;

// Filtert die Kundenauswahl im „Neues Projekt"-Dialog (Options werden neu aufgebaut).
function filterNewBaustelleKunde(query) {
  const sel = document.getElementById('newBaustelleKunde');
  if (!sel) return;
  const q = (query || '').toLowerCase().trim();
  const prev = sel.value;
  const sorted = [...(kundenData || [])].sort((a, b) => (a.firma || a.nachname || '').localeCompare(b.firma || b.nachname || ''));
  sel.innerHTML = '<option value="">— kein Kunde —</option>';
  sorted.forEach(k => {
    const label = [k.firma, k.vorname, k.nachname].filter(Boolean).join(' ');
    if (q && !label.toLowerCase().includes(q)) return;
    const opt = document.createElement('option');
    opt.value = k.id;
    opt.textContent = label;
    if (String(k.id) === String(prev)) opt.selected = true;
    sel.appendChild(opt);
  });
}

function closeKundeForm() {
  document.getElementById('kundeFormOverlay')?.remove();
  // If we came from the Baustelle dialog, re-show it
  if (_baustelleKundeCallback) {
    const bauOverlay = document.getElementById('addBaustelleOverlay');
    if (bauOverlay) bauOverlay.style.display = '';
    _baustelleKundeCallback = null;
  }
}

function openKundeFormFromBaustelle() {
  // Remember the current Baustelle name so we can restore it
  const nameVal = document.getElementById('newBaustelleNameInput')?.value || '';
  // Hide the Baustelle overlay (don't remove)
  const bauOverlay = document.getElementById('addBaustelleOverlay');
  if (bauOverlay) bauOverlay.style.display = 'none';
  // Set callback to re-open Baustelle dialog with new Kunde pre-selected
  _baustelleKundeCallback = (newKundeId) => {
    _baustelleKundeCallback = null;
    if (bauOverlay) bauOverlay.remove();
    addBaustelle(newKundeId);
    // Restore the name after a tick
    setTimeout(() => {
      const inp = document.getElementById('newBaustelleNameInput');
      if (inp) inp.value = nameVal;
    }, 50);
  };
  openKundeForm(0);
}

function confirmAddBaustelleDesktop() {
  const nameInput = document.getElementById('newBaustelleNameInput');
  const kundeSelect = document.getElementById('newBaustelleKunde');
  const name = (nameInput?.value || '').trim();
  if (!name) { showNotification('Bitte Projektname eingeben.', 'error'); nameInput?.focus(); return; }
  const kundeId = parseInt(kundeSelect?.value) || null;
  const projektNr = generateProjektNr();
  const b = {
    id:                  appData.nextBaustelleId++,
    projektNr:           projektNr,
    name:                name,
    material:            [],
    arbeitszeit:         [],
    pauschalen:          [],
    nextMatId:           1,
    nextAzId:            1,
    abschlaege:          [],
    nextAbschlagId:      1,
    matKategorien:       [],
    nextMatKatId:        1,
    bautagebuch:         [],
    nextTagebuchId:      1,
    fehlendesMaterial:   [],
    nextFehlendesMatId:  1,
    materialAufschlagGlobal: 0,
    kundeId:             kundeId
  };
  appData.baustellen.push(b);
  saveData();
  document.getElementById('addBaustelleOverlay')?.remove();
  renderSidebar();
  selectBaustelle(b.id);
  showNotification('Projekt —' + name + '" erstellt!', 'success');
}

function deleteBaustelle(id) {
  if (!canDo('canDeleteBaustelle')) { showNotification('Keine Berechtigung.'); return; }
  confirmDelete('Baustelle wirklich löschen?\n\nAlle Positionen, Stunden und Anhänge werden unwiderruflich entfernt.', () => {
    appData.baustellen = appData.baustellen.filter(b => b.id !== id);
    saveData();
    if (selectedId === id) {
      selectedId = null;
      if (appData.baustellen.length > 0) {
        selectBaustelle(appData.baustellen[0].id);
      } else {
        showEmptyState();
      }
    }
    renderSidebar();
  }, { requireTyping: true });
}

async function selectBaustelle(id) {
  selectedId = id;
  document.getElementById('btnUebersicht')?.classList.remove('active');
  document.getElementById('btnMaterialKatalog')?.classList.remove('active');
  document.getElementById('btnStundenKatalog')?.classList.remove('active');
  document.getElementById('btnOffenesMaterial')?.classList.remove('active');
  document.getElementById('btnWhatsApp')?.classList.remove('active');
  document.getElementById('btnSchnellnotizenSidebar')?.classList.remove('active');
  document.getElementById('btnKundenstamm')?.classList.remove('active');
  hide('whatsappView');
  hide('schnellnotizenView');
  hide('kundenstammView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('dashboardView'); hide('vde0100View');
  renderSidebar();
  // Ensure rechnungenData is loaded for Abschlagsrechnungen integration
  if (rechnungenData.length === 0) {
    try {
      const r = await fetch('api.php?action=list_rechnungen');
      const j = await r.json();
      rechnungenData = j.rechnungen || [];
    } catch(e) {}
  }
  _startProjectPresence(id);
  renderDetail();
}

// -- Projekt-Presence: zeigt an, wer gerade dasselbe Projekt offen hat ----
function _startProjectPresence(baustelleId) {
  _stopProjectPresence();
  if (!baustelleId) return;
  _sendPresenceHeartbeat(baustelleId);
  _checkProjectPresence(baustelleId);
  _presenceTimer = setInterval(() => {
    _sendPresenceHeartbeat(baustelleId);
    _checkProjectPresence(baustelleId);
  }, 60000);
}
function _stopProjectPresence() {
  if (_presenceTimer) { clearInterval(_presenceTimer); _presenceTimer = null; }
  // Abmelden (baustelleId=0 = kein Projekt offen)
  fetch('api.php?action=project_heartbeat&_idle=1', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ baustelleId: 0 })
  }).catch(() => {});
}
function _sendPresenceHeartbeat(baustelleId) {
  fetch('api.php?action=project_heartbeat&_idle=1', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ baustelleId })
  }).catch(() => {});
}
async function _checkProjectPresence(baustelleId) {
  try {
    const r = await fetch('api.php?action=project_presence&_idle=1');
    const j = await r.json();
    if (!j.ok) return;
    const others = (j.presence || []).filter(p => p.baustelleId === baustelleId && p.username !== currentUser);
    const badge = document.getElementById('presenceBadge');
    if (badge) {
      if (others.length) {
        badge.textContent = '🔒 ' + others.map(p => p.username).join(', ') + ' bearbeitet gerade';
        badge.style.display = '';
      } else {
        badge.style.display = 'none';
      }
    }
  } catch (_) {}
}

function toggleBaustelleExclude(id, checked) {
  const b = appData.baustellen.find(x => x.id === id);
  if (!b) return;
  b.excludeFromOverview = !!checked;
  saveData();
}

function toggleBaustelleAuswertung(id, checked) {
  const b = appData.baustellen.find(x => x.id === id);
  if (!b) return;
  b.includeInAuswertung = !!checked;
  saveData();
  // Also persist flag for archive survival
  fetch('api.php?action=toggle_auswertung_flag', {
    method: 'POST', headers: {'Content-Type':'application/json'},
    body: JSON.stringify({baustelleId: id, include: !!checked})
  }).catch(() => {});
}

// -- Rename --------------------------------------------------
function openRenameModal(id) {
  renamingId = id;
  const b = appData.baustellen.find(b => b.id === id);
  const inp = document.getElementById('renameInput');
  inp.value = b.name;
  show('renameModal');
  setTimeout(() => { inp.focus(); inp.select(); }, 50);
}

function closeRenameModal() {
  hide('renameModal');
  renamingId = null;
}

function closeRenameModalOverlay(e) {
  if (e.target === e.currentTarget) closeRenameModal();
}

function confirmRename() {
  if (!renamingId) return;
  const name = document.getElementById('renameInput').value.trim();
  if (!name) return;
  const b = appData.baustellen.find(b => b.id === renamingId);
  if (b) {
    b.name = name;
    saveData();
    renderSidebar();
    const h = document.getElementById('baustelleName');
    if (h) h.textContent = name;
  }
  closeRenameModal();
}

// -- Sidebar collapse/expand helpers --------------------------
function toggleSidebarSection(id) {
  const body = document.getElementById(id);
  const arrow = document.getElementById('arrow' + id.replace('sec',''));
  if (!body) return;
  const isCollapsed = body.classList.toggle('collapsed');
  if (arrow) arrow.classList.toggle('collapsed', isCollapsed);
  collapsedSidebarSecs[id] = isCollapsed;
  localStorage.setItem('collapsedSidebarSecs', JSON.stringify(collapsedSidebarSecs));
}

function restoreSidebarSections() {
  Object.entries(collapsedSidebarSecs).forEach(([id, collapsed]) => {
    if (collapsed) {
      const body = document.getElementById(id);
      const arrow = document.getElementById('arrow' + id.replace('sec',''));
      if (body) body.classList.add('collapsed');
      if (arrow) arrow.classList.add('collapsed');
    }
  });
}

function toggleKundeGroup(kundeId) {
  collapsedKundeGroups[kundeId] = !collapsedKundeGroups[kundeId];
  localStorage.setItem('collapsedKundeGroups', JSON.stringify(collapsedKundeGroups));
  renderSidebar();
}

function toggleBaustelleSubs(baustelleId) {
  const isExpanded = expandedBaustellen[baustelleId] !== false;
  expandedBaustellen[baustelleId] = !isExpanded;
  localStorage.setItem('expandedBaustellen', JSON.stringify(expandedBaustellen));
  renderSidebar();
}

function getSubprojects(parentId) {
  return (appData.baustellen || []).filter(b => b.parentId === parentId);
}

function hasSubprojects(projectId) {
  return getSubprojects(projectId).length > 0;
}

function getProjectsForAggregation(selectedProject) {
  if (!selectedProject) return [];
  const subs = getSubprojects(selectedProject.id);
  if (subs.length === 0) return [selectedProject];
  // Hauptprojekt zeigt eigene Werte plus alle Unterprojekte.
  return [selectedProject, ...subs];
}

// -- Add Unterprojekt -----------------------------------------
function addUnterprojekt(parentId) {
  if (!canDo('canCreateBaustelle')) { showNotification('Keine Berechtigung.'); return; }
  const parent = appData.baustellen.find(b => b.id === parentId);
  if (!parent) return;
  const projektNr = generateUnterprojektNr(parent);
  const sub = {
    id:                  appData.nextBaustelleId++,
    projektNr:           projektNr,
    name:                `Unterprojekt ${appData.nextBaustelleId - 1}`,
    parentId:            parentId,
    material:            [],
    arbeitszeit:         [],
    pauschalen:          [],
    nextMatId:           1,
    nextAzId:            1,
    abschlaege:          [],
    nextAbschlagId:      1,
    matKategorien:       [],
    nextMatKatId:        1,
    bautagebuch:         [],
    nextTagebuchId:      1,
    fehlendesMaterial:   [],
    nextFehlendesMatId:  1,
    materialAufschlagGlobal: 0,
    kundeId:             parent.kundeId || null
  };
  appData.baustellen.push(sub);
  expandedBaustellen[parentId] = true;
  localStorage.setItem('expandedBaustellen', JSON.stringify(expandedBaustellen));
  saveData();
  renderSidebar();
  selectBaustelle(sub.id);
}

// -- Sidebar render -------------------------------------------
// Umschalter Projektsuche <-> Globale Suche für die Sidebar-Suchleiste.
let sidebarSearchMode = localStorage.getItem('bk_sidebarSearchMode') || 'projekt';

function _applySidebarSearchModeUI() {
  const bP = document.getElementById('searchModeProjekt');
  const bG = document.getElementById('searchModeGlobal');
  if (bP && bG) {
    bP.className = 'btn btn-sm ' + (sidebarSearchMode === 'projekt' ? 'btn-primary' : 'btn-secondary');
    bG.className = 'btn btn-sm ' + (sidebarSearchMode === 'global'  ? 'btn-primary' : 'btn-secondary');
  }
  const inp = document.getElementById('baustellenSearch');
  if (inp) inp.placeholder = sidebarSearchMode === 'global' ? 'Global suchen…' : 'Projekt suchen…';
}

function setSidebarSearchMode(mode) {
  sidebarSearchMode = (mode === 'global') ? 'global' : 'projekt';
  localStorage.setItem('bk_sidebarSearchMode', sidebarSearchMode);
  _applySidebarSearchModeUI();
  const inp = document.getElementById('baustellenSearch');
  if (sidebarSearchMode === 'projekt') {
    renderSidebar();
  } else {
    const v = (inp?.value || '').trim();
    if (v.length >= 2) openGlobalSearchModal(v);
  }
  if (inp) inp.focus();
}

function onSidebarSearchInput() {
  if (sidebarSearchMode === 'global') {
    const v = (document.getElementById('baustellenSearch')?.value || '').trim();
    const modal = document.getElementById('globalSearchModal');
    const open = modal && !modal.classList.contains('hidden');
    if (open) {
      const gi = document.getElementById('globalSearchInput');
      if (gi) { gi.value = v; debounceGlobalSearch(); }
    } else if (v.length >= 2) {
      openGlobalSearchModal(v);
    }
    return;
  }
  renderSidebar();
}

function onSidebarSearchEnter() {
  if (sidebarSearchMode === 'global') {
    openGlobalSearchModal((document.getElementById('baustellenSearch')?.value || '').trim());
  }
}

function renderSidebar() {
  const ul = document.getElementById('baustellenList');
  ul.innerHTML = '';
  _applySidebarSearchModeUI();
  // Im Globale-Suche-Modus filtert die Suchleiste NICHT die Projektliste.
  const searchTerm = (sidebarSearchMode === 'global') ? '' : (document.getElementById('baustellenSearch')?.value || '').trim().toLowerCase();
  const allVisible = getVisibleBaustellen().slice().sort((a, b) => a.name.localeCompare(b.name, 'de'));

  // v2.0.1: Multi-Token-AND-Suche über Name + ProjektNr + Kunden-Name + Firma
  const tokens = searchTerm ? searchTerm.split(/\s+/).filter(Boolean) : [];
  const kundeHayById = {};
  if (kundenData.length) {
    kundenData.forEach(k => {
      kundeHayById[k.id] = [k.firma, k.vorname, k.nachname, k.kundennummer]
        .filter(Boolean).join(' ').toLowerCase();
    });
  }
  // Set der Kunden-IDs, deren Kundendaten selbst zu allen Tokens passen
  // (für "Kunde"-Badge im Gruppen-Header).
  const kundeMatchIds = new Set();
  if (tokens.length) {
    Object.keys(kundeHayById).forEach(kid => {
      const hay = kundeHayById[kid];
      if (tokens.every(t => hay.includes(t))) kundeMatchIds.add(parseInt(kid));
    });
  }

  // Für Unterprojekte werden Eltern-Name/Projektnr in den Suchindex aufgenommen,
  // damit z.B. "Lidl Dachau" ein Unterprojekt "Dachau" unter Parent "Lidl" findet.
  const _byId = {};
  allVisible.forEach(b => { _byId[b.id] = b; });
  const hayFor = (b) => {
    const kHay = (b.kundeId && kundeHayById[b.kundeId]) ? kundeHayById[b.kundeId] : '';
    let h = (b.name || '') + ' ' + (b.projektNr || '') + ' ' + kHay;
    if (b.parentId && _byId[b.parentId]) {
      const p = _byId[b.parentId];
      h += ' ' + (p.name || '') + ' ' + (p.projektNr || '');
    }
    return h.toLowerCase();
  };
  const matchedIds = new Set();
  allVisible.forEach(b => {
    if (!tokens.length) { matchedIds.add(b.id); return; }
    if (b.kundeId && kundeMatchIds.has(b.kundeId)) { matchedIds.add(b.id); return; }
    if (tokens.every(t => hayFor(b).includes(t))) matchedIds.add(b.id);
  });
  // Passt ein Unterprojekt, bleibt sein Oberprojekt als Container sichtbar.
  const showIds = new Set(matchedIds);
  if (tokens.length) {
    matchedIds.forEach(id => { const b = _byId[id]; if (b && b.parentId) showIds.add(b.parentId); });
  }
  const filtered = allVisible.filter(b => !tokens.length || showIds.has(b.id));

  // Separate top-level and sub-projects
  const topLevel = filtered.filter(b => !b.parentId);
  const subMap = {};
  filtered.filter(b => b.parentId).forEach(b => {
    if (!subMap[b.parentId]) subMap[b.parentId] = [];
    subMap[b.parentId].push(b);
  });
  Object.keys(subMap).forEach(pid => {
    subMap[pid].sort((a, b) =>
      (a.sortPos != null && b.sortPos != null)
        ? (a.sortPos - b.sortPos || (a.projektNr || '').localeCompare((b.projektNr || ''), 'de'))
        : (a.projektNr || '').localeCompare((b.projektNr || ''), 'de')
    );
  });
  // Group by Kunde
  const grouped = {};
  const noKunde = [];
  topLevel.forEach(b => {
    const kid = b.kundeId;
    if (kid && kundenData.length) {
      if (!grouped[kid]) grouped[kid] = [];
      grouped[kid].push(b);
    } else {
      noKunde.push(b);
    }
  });
  const canArchive = canDo('canArchive');
  const canDelete  = canDo('canDeleteBaustelle');
  const canCreate  = canDo('canCreateBaustelle');
  // Helper: render single baustelle item
  let _dndDragId = null;
  function renderItem(b, isSub) {
    const hasSubs = !isSub && (subMap[b.id] || []).length > 0;
    const isExpanded = hasSubs ? (tokens.length ? true : (expandedBaustellen[b.id] !== false)) : false;
    const li = document.createElement('li');
    li.className = 'baustelle-item' + (b.id === selectedId ? ' active' : '') + (isSub ? ' sub-projekt' : '');
    if (isSub) {
      li.draggable = true;
      li.dataset.subId    = b.id;
      li.dataset.parentId = b.parentId;
      li.addEventListener('dragstart', e => {
        _dndDragId = b.id;
        li.classList.add('dnd-dragging');
        e.dataTransfer.effectAllowed = 'move';
      });
      li.addEventListener('dragend', () => {
        _dndDragId = null;
        li.classList.remove('dnd-dragging');
        document.querySelectorAll('.dnd-over').forEach(el => el.classList.remove('dnd-over'));
      });
      li.addEventListener('dragover', e => {
        if (_dndDragId === b.id) return;
        e.preventDefault();
        document.querySelectorAll('.dnd-over').forEach(el => el.classList.remove('dnd-over'));
        li.classList.add('dnd-over');
        e.dataTransfer.dropEffect = 'move';
      });
      li.addEventListener('dragleave', () => li.classList.remove('dnd-over'));
      li.addEventListener('drop', async e => {
        e.preventDefault();
        li.classList.remove('dnd-over');
        if (!_dndDragId || _dndDragId === b.id) return;
        // Neue Reihenfolge aus DOM ermitteln
        const parent = li.parentElement;
        const subs = Array.from(parent.querySelectorAll('li.sub-projekt[data-parent-id="' + b.parentId + '"]'));
        const draggedEl = parent.querySelector('li.sub-projekt[data-sub-id="' + _dndDragId + '"]');
        if (!draggedEl) return;
        // draggedEl vor das Ziel-li einfügen
        parent.insertBefore(draggedEl, li);
        const newOrder = Array.from(parent.querySelectorAll('li.sub-projekt[data-parent-id="' + b.parentId + '"]'))
          .map(el => parseInt(el.dataset.subId));
        try {
          const res = await fetch('api.php?action=save_sub_sort_order', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ parentId: b.parentId, order: newOrder }),
          });
          const j = await res.json();
          if (!j.ok) throw new Error(j.error || 'Fehler');
          // appData lokal aktualisieren
          newOrder.forEach((id, pos) => {
            const bs = appData.baustellen.find(x => x.id === id);
            if (bs) bs.sortPos = pos;
          });
        } catch (err) {
          notify('Sortierung konnte nicht gespeichert werden: ' + err.message);
          renderSidebar(); // DOM-Zustand zurücksetzen
        }
      });
    }
    li.innerHTML = `
      <span class="baustelle-name" onclick="selectBaustelle(${b.id})" style="display:flex;align-items:center;gap:4px">
        ${isSub ? '<span class="dnd-handle" title="Ziehen zum Sortieren">⠿</span>' : ''}
        ${!isSub && canCreate ? `<button class="sub-toggle ${hasSubs && isExpanded ? 'open' : ''}" onclick="event.stopPropagation();toggleBaustelleSubs(${b.id})" title="Unterprojekte">${hasSubs ? '\u25b8' : '\u00b7'}</button>` : ''}
        <span><span class="baustelle-pnr">${esc(b.projektNr || '')}</span> ${esc(b.name)}</span>
      </span>
      <div class="baustelle-actions">
        ${!isSub && canCreate ? `<button class="icon-btn" onclick="addUnterprojekt(${b.id})" title="Unterprojekt hinzuf\u00fcgen">${ico('plus')}</button>` : ''}
        <button class="icon-btn" onclick="openRenameModal(${b.id})" title="Umbenennen">${ico('edit')}</button>
        ${canArchive ? `<button class="icon-btn" onclick="archiveBaustelle(${b.id})" title="${(!isSub && (subMap[b.id] || []).length > 0) ? 'Archivieren (Hauptprojekt + Unterprojekte)' : 'Archivieren'}">${ico('box')}</button>` : ''}
        ${canDelete ? `<button class="icon-btn danger" onclick="deleteBaustelle(${b.id})" title="L\u00f6schen">${ico('trash')}</button>` : ''}
      </div>`;
    // A.1: Sidebar-Eintrag als Drop-Ziel für Positions-Verschiebung (Arbeitszeit/Material)
    attachPosDropTarget(li, b.id);
    ul.appendChild(li);
    if (!isSub && isExpanded && subMap[b.id]) {
      subMap[b.id].forEach(sub => renderItem(sub, true));
    }
  }
  // Render Kunde groups
  const kundeIds = Object.keys(grouped).sort((a,b) => {
    const ka = kundenData.find(k => k.id === parseInt(a));
    const kb = kundenData.find(k => k.id === parseInt(b));
    return (ka?.firma || ka?.nachname || '').localeCompare(kb?.firma || kb?.nachname || '', 'de');
  });
  kundeIds.forEach(kid => {
    const kunde = kundenData.find(k => k.id === parseInt(kid));
    const label = kunde ? (kunde.firma || `${kunde.vorname || ''} ${kunde.nachname || ''}`.trim()) : `Kunde #${kid}`;
    const isKundeMatch = searchTerm && kundeMatchIds.has(parseInt(kid));
    const isCollapsed = collapsedKundeGroups[kid];
    const header = document.createElement('li');
    header.className = 'sidebar-kunde-group';
    const matchBadge = isKundeMatch ? ' <span style="font-size:.65rem;background:var(--primary,#00B4D8);color:#fff;padding:1px 5px;border-radius:4px;margin-left:4px;font-weight:600">Kunde</span>' : '';
    header.innerHTML = `<span style="margin-right:4px">${isCollapsed ? '\u25b8' : '\u25be'}</span> ${ico('users')} ${esc(label)}${matchBadge} <span style="opacity:.5;font-weight:400">(${grouped[kid].length})</span>`;
    header.onclick = () => toggleKundeGroup(kid);
    ul.appendChild(header);
    if (!isCollapsed) {
      grouped[kid].forEach(b => renderItem(b, false));
    }
  });
  // Ungrouped projects
  if (noKunde.length > 0 && kundeIds.length > 0) {
    const sep = document.createElement('li');
    sep.className = 'sidebar-kunde-group';
    sep.style.color = 'var(--grey-400)';
    sep.textContent = 'Ohne Kunde';
    ul.appendChild(sep);
  }
  noKunde.forEach(b => renderItem(b, false));
  restoreSidebarSections();
}

// ============================================================
// A.1/A.2: Position (Arbeitszeit/Material) per Drag&Drop zwischen
// Baustellen verschieben. Drop-Ziel = Sidebar-Eintrag.
// ============================================================
function attachPosDropTarget(li, baustelleId) {
  li.addEventListener('dragover', e => {
    if (!_posDrag || _posDrag.srcBaustelleId === baustelleId) return;
    e.preventDefault();
    li.classList.add('dnd-pos-over');
    e.dataTransfer.dropEffect = 'move';
  });
  li.addEventListener('dragleave', () => li.classList.remove('dnd-pos-over'));
  li.addEventListener('drop', async e => {
    if (!_posDrag) return;
    e.preventDefault();
    e.stopPropagation();
    li.classList.remove('dnd-pos-over');
    const drag = _posDrag;
    _posDrag = null;
    if (drag.srcBaustelleId === baustelleId) return;
    await movePositionToBaustelle(drag, baustelleId);
  });
}

async function movePositionToBaustelle(drag, destId) {
  const src  = appData.baustellen.find(b => b.id === drag.srcBaustelleId);
  const dest = appData.baustellen.find(b => b.id === destId);
  if (!src || !dest) return;
  const key  = drag.category === 'material' ? 'material' : 'arbeitszeit';
  const list = src[key] || [];
  const idx  = list.findIndex(x => x.id === drag.itemId);
  if (idx < 0) return;
  const item = list[idx];
  const label = drag.category === 'material'
    ? (item.bezeichnung || 'Materialposition')
    : (item.beschreibung || 'Arbeitszeit-Eintrag');
  if (!confirm(`„${label}" nach „${dest.name}" verschieben?`)) return;

  // Aus Quelle entfernen, in Ziel mit neuer lokaler ID einfügen
  list.splice(idx, 1);
  if (key === 'arbeitszeit') {
    if (!dest.arbeitszeit) dest.arbeitszeit = [];
    if (!dest.nextAzId) dest.nextAzId = 1;
    item.id = dest.nextAzId++;
    dest.arbeitszeit.unshift(item);
  } else {
    if (!dest.material) dest.material = [];
    if (!dest.nextMatId) dest.nextMatId = 1;
    item.id = dest.nextMatId++;
    dest.material.unshift(item);
  }
  saveData();

  // A.2: Zeiterfassungs-Kaskade für auto-importierte Arbeitszeit-Einträge
  if (key === 'arbeitszeit' && item.autoImport && item.zeitEntryId) {
    try {
      const res = await fetch('api.php?action=move_position', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ zeitEntryId: item.zeitEntryId, zeitUser: item.zeitUser || null, destBaustelleId: destId })
      });
      const j = await res.json();
      if (!j || !j.ok) console.warn('move_position:', j && j.error);
    } catch (err) {
      console.warn('move_position fehlgeschlagen:', err);
    }
    // Lokalen Zeiterfassungs-Cache mitziehen, damit ein nachfolgender
    // Full-Replace-Save die Kaskade nicht wieder überschreibt.
    if (Array.isArray(zeitEntriesDesktop)) {
      const ze = zeitEntriesDesktop.find(e => e.id === item.zeitEntryId);
      if (ze) { ze.baustelleId = destId; ze.baustelleName = dest.name || ''; }
    }
  }

  showNotification(`„${label}" nach „${dest.name}" verschoben.`, 'success');
  renderSidebar();
  renderDetail();
}

// -- Helper: VK mit globalem Materialaufschlag + Positions-Rabatt --
// vkDirekt=true: gespeicherter ek ist bereits der (Netto-)VK, kein Aufschlag/Global.
// rabatt (%): Kundenrabatt, reduziert den VK. Negative ek/anzahl (Gutschriften) erlaubt.
function matVk(r, b) {
  const ek = parseFloat(r?.ek) || 0;
  const rabatt = parseFloat(r?.rabatt) || 0;
  const rabattFactor = 1 - rabatt / 100;
  if (r?.vkDirekt) {
    return ek * rabattFactor;
  }
  const aufschlag = parseFloat(r?.aufschlag) || 0;
  const ga = parseFloat(b?.materialAufschlagGlobal) || 0;
  return ek * (1 + aufschlag / 100) * (1 + ga / 100) * rabattFactor;
}

