// ============================================================
// SIDEBAR TOGGLE (Tablet / small screens)
// ============================================================
function toggleSidebar() {
  sidebarOpen = !sidebarOpen;
  document.body.classList.toggle('sidebar-collapsed', !sidebarOpen);
  const overlay = document.getElementById('sidebarOverlay');
  if (overlay) overlay.style.display = sidebarOpen ? 'block' : 'none';
  // On wide screens, just toggle; on narrow, show/hide overlay
  if (window.innerWidth <= 1024 && sidebarOpen) {
    if (!document.getElementById('sidebarOverlay')) {
      const ov = document.createElement('div');
      ov.id = 'sidebarOverlay';
      ov.className = 'sidebar-overlay';
      ov.onclick = () => toggleSidebar();
      document.body.appendChild(ov);
    }
    document.getElementById('sidebarOverlay').style.display = 'block';
  } else {
    const ov = document.getElementById('sidebarOverlay');
    if (ov) ov.style.display = 'none';
  }
}

// Auto-collapse sidebar on narrow screens
function checkSidebarResponsive() {
  if (window.innerWidth <= 1024 && sidebarOpen) {
    sidebarOpen = false;
    document.body.classList.add('sidebar-collapsed');
  }
}
window.addEventListener('resize', () => {
  const ov = document.getElementById('sidebarOverlay');
  if (window.innerWidth > 1024) {
    if (ov) ov.style.display = 'none';
    document.body.classList.remove('sidebar-collapsed');
    sidebarOpen = true;
  }
});

// ============================================================
// v2.0.1: Sidebar resizable (Drag-Handle, persist localStorage)
// ============================================================
function initSidebarResize() {
  const sb = document.getElementById('appSidebar');
  if (!sb || sb.querySelector('.sidebar-resize-handle')) return;
  try {
    const saved = parseInt(localStorage.getItem('bk_sidebarWidth') || '0', 10);
    if (saved >= 220 && saved <= 520) {
      document.documentElement.style.setProperty('--sidebar-width', saved + 'px');
    }
  } catch (e) {}
  const handle = document.createElement('div');
  handle.className = 'sidebar-resize-handle';
  handle.title = 'Breite ziehen (Doppelklick = Reset)';
  sb.appendChild(handle);

  let dragging = false, startX = 0, startW = 0;
  const MIN = 220, MAX = 520;

  handle.addEventListener('mousedown', (e) => {
    if (window.innerWidth <= 1024) return;
    dragging = true;
    startX = e.clientX;
    startW = sb.getBoundingClientRect().width;
    handle.classList.add('active');
    document.body.classList.add('sidebar-resizing');
    e.preventDefault();
  });
  window.addEventListener('mousemove', (e) => {
    if (!dragging) return;
    let w = startW + (e.clientX - startX);
    if (w < MIN) w = MIN;
    if (w > MAX) w = MAX;
    document.documentElement.style.setProperty('--sidebar-width', w + 'px');
  });
  window.addEventListener('mouseup', () => {
    if (!dragging) return;
    dragging = false;
    handle.classList.remove('active');
    document.body.classList.remove('sidebar-resizing');
    try {
      const w = sb.getBoundingClientRect().width;
      localStorage.setItem('bk_sidebarWidth', String(Math.round(w)));
    } catch (e) {}
  });
  handle.addEventListener('dblclick', () => {
    document.documentElement.style.setProperty('--sidebar-width', '280px');
    try { localStorage.removeItem('bk_sidebarWidth'); } catch (e) {}
  });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSidebarResize);
} else {
  initSidebarResize();
}

// ============================================================
// v2.0.1: Action-Menu (Drei-Punkte-Dropdown) Helper
// items: [{label, icon, onclick (string), danger?, active?, hidden?, divider?}]
// ============================================================
function actionMenuHtml(items, opts) {
  opts = opts || {};
  const id = 'am_' + Math.random().toString(36).slice(2, 9);
  const visible = (items || []).filter(it => it && !it.hidden);
  if (!visible.length) return '';
  const inner = visible.map(it => {
    if (it.divider) return '<div class="action-menu-divider"></div>';
    const cls = 'action-menu-item' + (it.danger ? ' am-danger' : '') + (it.active ? ' am-active' : '');
    const icon = it.icon || '';
    const title = it.title ? ` title="${String(it.title).replace(/"/g, '&quot;')}"` : '';
    return `<button type="button" class="${cls}"${title} onclick="closeActionMenus();${it.onclick}">${icon} ${typeof esc === 'function' ? esc(it.label) : it.label}</button>`;
  }).join('');
  const triggerCls = opts.triggerClass || 'btn btn-secondary btn-sm';
  const triggerLabel = opts.triggerLabel || '⋯';
  return `<div class="action-menu-wrap"><button type="button" class="${triggerCls} action-menu-trigger" onclick="toggleActionMenu('${id}',event)" title="Weitere Aktionen" aria-label="Weitere Aktionen">${triggerLabel}</button><div class="action-menu-pop" id="${id}">${inner}</div></div>`;
}
function toggleActionMenu(id, ev) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  const pop = document.getElementById(id);
  if (!pop) return;
  const wasOpen = pop.classList.contains('open');
  closeActionMenus();
  if (!wasOpen) pop.classList.add('open');
}
function closeActionMenus() {
  document.querySelectorAll('.action-menu-pop.open').forEach(el => el.classList.remove('open'));
}
document.addEventListener('click', (e) => {
  if (!e.target.closest('.action-menu-wrap')) closeActionMenus();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closeActionMenus();
});

