// ============================================================
// GESAMTÜBERSICHT
// ============================================================
function showDin1090() {
  if (typeof renderDin1090 !== 'function') return;
  selectedId = null;
  document.querySelectorAll('.sidebar-overview-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('btnDin1090')?.classList.add('active');
  renderSidebar();
  hide('emptyState');
  hide('baustelleDetail');
  hide('materialKatalogView');
  hide('stundenKatalogView');
  hide('offenesMaterialView');
  hide('whatsappView');
  hide('schnellnotizenView');
  hide('kundenstammView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('uebersichtView');
  hide('lagerView');
  hide('aufmassView');
  hide('vde0100View');
  hide('dashboardView');
  show('din1090View');
  renderDin1090();
}

function showUebersicht() {
  selectedId = null;
  document.getElementById('btnUebersicht')?.classList.add('active');
  document.getElementById('btnMaterialKatalog')?.classList.remove('active');
  document.getElementById('btnStundenKatalog')?.classList.remove('active');
  document.getElementById('btnOffenesMaterial')?.classList.remove('active');
  document.getElementById('btnWhatsApp')?.classList.remove('active');
  document.getElementById('btnSchnellnotizenSidebar')?.classList.remove('active');
  document.getElementById('btnKundenstamm')?.classList.remove('active');
  document.getElementById('btnDin1090')?.classList.remove('active');
  renderSidebar();
  hide('emptyState');
  hide('baustelleDetail');
  hide('materialKatalogView');
  hide('stundenKatalogView');
  hide('offenesMaterialView');
  hide('whatsappView');
  hide('schnellnotizenView');
  hide('kundenstammView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('dashboardView'); hide('vde0100View');
  show('uebersichtView');
  renderUebersicht();
}

function renderUebersicht() {
  const el = document.getElementById('uebersichtView');
  if (!el) return;

  if (appData.baustellen.length === 0) {
    el.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">${ico('chart','ico-2xl')}</div>
        <h2>Keine Baustellen vorhanden</h2>
        <p>Erstellen Sie eine neue Baustelle oder importieren Sie eine Excel-Datei.</p>
        ${canDo('canCreateBaustelle') ? '<button class="btn btn-primary" onclick="addBaustelle()">+ Neue Baustelle erstellen</button>' : ''}
      </div>`;
    return;
  }

  let totalMat = 0, totalAz = 0, totalP = 0, totalAbschlag = 0, totalGewinn = 0;
  const parentMap = Object.fromEntries((appData.baustellen || []).map(b => [b.id, b]));
  const rows = appData.baustellen.map(b => {
    const excluded = !!b.excludeFromOverview;
    let ms = 0, mek = 0, as = 0, afk = 0, ps = 0, abs = 0;
    (b.material   || []).forEach(r  => { ms += matVk(r, b) * (r.anzahl || 0); mek += (r.ek || 0) * (r.anzahl || 0); });
    (b.arbeitszeit || []).forEach(r => { as += (r.stunden || 0) * (r.stundenpreis || 0); afk += (r.stunden || 0) * (r.fixkosten || 0); });
    (b.pauschalen  || []).forEach(entry => {
      const p = appData.pauschalen.find(p => p.id === entry.id);
      if (p) ps += p.preis * (entry.anzahl || 1);
    });
    (b.abschlaege || []).forEach(r => { abs += r.betrag; });
    const g = ms + as + ps;
    const gw = (ms - mek) + (as - afk) + ps;
    const parent = b.parentId ? parentMap[b.parentId] : null;
    return {
      name: b.name,
      id: b.id,
      parentId: b.parentId || null,
      projektNr: b.projektNr || '',
      ms,
      as,
      ps,
      abs,
      g,
      offen: g - abs,
      gewinn: gw,
      excluded,
      isSub: !!b.parentId,
      parentName: parent?.name || '',
      parentProjektNr: parent?.projektNr || '',
      hasSubs: false, // wird unten gesetzt
    };
  });
  // Oberprojekt-Aggregation: Unterprojekte-Werte zum Parent addieren
  const rowById = Object.fromEntries(rows.map(r => [r.id, r]));
  rows.forEach(r => {
    if (r.isSub && r.parentId && rowById[r.parentId]) {
      const p = rowById[r.parentId];
      p.ms      += r.ms;
      p.as      += r.as;
      p.ps      += r.ps;
      p.abs     += r.abs;
      p.g       += r.g;
      p.gewinn  += r.gewinn;
      p.hasSubs  = true;
    }
  });
  // offen nach Aggregation neu berechnen
  rows.forEach(r => { if (!r.isSub) r.offen = r.g - r.abs; });
  // Gesamtsummen: nur Oberprojekte + eigenständige Baustellen (keine Unterprojekte), um Doppelzählung zu vermeiden
  rows.filter(r => !r.isSub && !r.excluded).forEach(r => {
    totalMat      += r.ms;
    totalAz       += r.as;
    totalP        += r.ps;
    totalAbschlag += r.abs;
    totalGewinn   += r.gewinn;
  });
  // Sortiere: Hauptprojekte alphabetisch nach Projekt-Nr, Unterprojekte direkt unter ihrem Parent
  const subsByParent = {};
  rows.forEach(r => { if (r.isSub) (subsByParent[r.parentId] ||= []).push(r); });
  Object.keys(subsByParent).forEach(pid => {
    subsByParent[pid].sort((a, b) => (a.sortPos != null && b.sortPos != null)
      ? (a.sortPos - b.sortPos || (a.projektNr || '').localeCompare((b.projektNr || ''), 'de'))
      : (a.projektNr || '').localeCompare((b.projektNr || ''), 'de'));
  });
  const topRows = rows.filter(r => !r.isSub).sort((a, b) => (a.projektNr || '').localeCompare((b.projektNr || ''), 'de'));
  const sortedRows = [];
  topRows.forEach(r => {
    sortedRows.push(r);
    (subsByParent[r.id] || []).forEach(s => sortedRows.push(s));
  });
  // Verwaiste Unterprojekte (Parent ausgefiltert) ans Ende
  rows.forEach(r => { if (r.isSub && !topRows.find(t => t.id === r.parentId)) sortedRows.push(r); });
  rows.length = 0;
  rows.push(...sortedRows);
  const grand = totalMat + totalAz + totalP;
  const grandOffen = grand - totalAbschlag;
  const maxG = Math.max(...rows.map(r => r.g), 1);

  el.innerHTML = `
    <div class="ov-header">
      <h2>${ico('chart')} Gesamtübersicht Baustellen</h2>
      <div style="display:flex;gap:8px;">
        <button class="btn btn-secondary btn-sm" onclick="openUebersichtExportModal()" style="white-space:nowrap;">${ico('download')} PDF Export</button>
      </div>
    </div>

    <div class="kpi-grid">
      <div class="kpi-card">
        <span class="kpi-icon">${ico('building')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Baustellen</span>
          <span class="kpi-value">${appData.baustellen.length}</span>
        </div>
      </div>
      <div class="kpi-card price-sensitive">
        <span class="kpi-icon">${ico('wrench')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Material gesamt</span>
          <span class="kpi-value">${fmt(totalMat)}</span>
        </div>
      </div>
      <div class="kpi-card price-sensitive">
        <span class="kpi-icon">${ico('clock')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Arbeitszeit gesamt</span>
          <span class="kpi-value">${fmt(totalAz)}</span>
        </div>
      </div>
      <div class="kpi-card price-sensitive">
        <span class="kpi-icon">${ico('clipboard')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Pauschalen gesamt</span>
          <span class="kpi-value">${fmt(totalP)}</span>
        </div>
      </div>
      <div class="kpi-card kpi-grand price-sensitive">
        <span class="kpi-icon">${ico('coins')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Gesamtsumme</span>
          <span class="kpi-value">${fmt(grand)}</span>
        </div>
      </div>
      <div class="kpi-card kpi-abschlag price-sensitive">
        <span class="kpi-icon">${ico('creditCard')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Abschläge gesamt</span>
          <span class="kpi-value">${fmt(totalAbschlag)}</span>
        </div>
      </div>
      <div class="kpi-card kpi-offen price-sensitive">
        <span class="kpi-icon">${ico('alert')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Offener Betrag</span>
          <span class="kpi-value">${fmt(grandOffen)}</span>
        </div>
      </div>
      <div class="kpi-card price-sensitive gewinn-sensitive" style="border-left:3px solid var(--success,#198754);">
        <span class="kpi-icon">${ico('coins')}</span>
        <div class="kpi-body">
          <span class="kpi-label">Gewinn gesamt</span>
          <span class="kpi-value" style="color:${totalGewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmt(totalGewinn)}</span>
        </div>
      </div>
    </div>

    <div class="section-card">
      <div class="section-header" style="flex-wrap:wrap;gap:8px;">
        <h3>Alle Baustellen im überblick</h3>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <input type="text" id="ovFilterInput" class="form-input" placeholder="Filtern..."
            oninput="_debouncedFilterOv(this.value)"
            style="width:200px;padding:5px 10px;font-size:.82rem;">
          <select id="ovSortSelect" class="form-select" onchange="sortUebersichtRows(this.value)"
            style="padding:5px 8px;font-size:.82rem;">
            <option value="projektNr">Projekt-Nr.</option>
            <option value="name">Name</option>
            <option value="g-desc">Gesamt ?</option>
            <option value="g-asc">Gesamt ?</option>
            <option value="offen-desc">Offen ?</option>
            <option value="offen-asc">Offen ?</option>
          </select>
        </div>
      </div>
      <div class="table-wrapper">
        <table class="data-table" id="ovTable">
          <thead>
            <tr>
              <th style="width:100px">Projekt-Nr.</th>
              <th>Baustelle</th>
              <th class="text-right price-sensitive" style="width:130px">Material (€)</th>
              <th class="text-right price-sensitive" style="width:130px">Arbeitszeit (€)</th>
              <th class="text-right price-sensitive" style="width:120px">Pauschalen (€)</th>
              <th class="text-right price-sensitive" style="width:120px">Gesamt (€)</th>
              <th class="text-right price-sensitive" style="width:120px">Abschläge (€)</th>
              <th class="text-right price-sensitive" style="width:120px">Offen (€)</th>
              <th class="text-right price-sensitive gewinn-sensitive" style="width:120px">Gewinn (€)</th>
              <th class="price-sensitive" style="width:160px">Abschlag / Gesamt</th>
            </tr>
          </thead>
          <tbody id="ovBody">
            ${rows.map(r => `
              <tr class="ov-row${r.excluded ? ' ov-excluded' : ''}${r.isSub ? ' ov-sub' : ''}" onclick="selectBaustelle(${r.id})" title="${r.excluded ? 'Ausgeschlossen - ' : ''}${r.isSub ? `Unterprojekt von ${r.parentProjektNr || ''} ${r.parentName || ''} - ` : ''}Baustelle öffnen" style="${r.excluded ? 'opacity:.45;' : ''}">
                <td class="ov-pnr" style="font-weight:600;font-size:.82rem;color:var(--primary);">${esc(r.projektNr)}</td>
                <td class="ov-name">${r.isSub ? '<span class="ov-sub-marker">↳</span>' : '<span class="ov-dot"></span>'}${esc(r.name)}${r.isSub && r.parentProjektNr ? `<span class="ov-sub-badge" title="Unterprojekt von ${esc(r.parentName || '')}">UP · ${esc(r.parentProjektNr)}</span>` : ''}${!r.isSub && r.hasSubs ? '<span class="ov-agg-badge" title="Summe inkl. aller Unterprojekte">∑ Gruppe</span>' : ''}${r.excluded ? ' <small style="color:var(--grey-400);font-weight:400">(ausgeschl.)</small>' : ''}</td>
                <td class="text-right price-sensitive">${fmt(r.ms)}</td>
                <td class="text-right price-sensitive">${fmt(r.as)}</td>
                <td class="text-right price-sensitive">${fmt(r.ps)}</td>
                <td class="text-right ov-total price-sensitive">${fmt(r.g)}</td>
                <td class="text-right ov-abschlag price-sensitive">${fmt(r.abs)}</td>
                <td class="text-right ov-offen price-sensitive">${fmt(r.offen)}</td>
                <td class="text-right price-sensitive gewinn-sensitive" style="color:${r.gewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmt(r.gewinn)}</td>
                <td class="price-sensitive">
                  <div class="ov-bar-wrap">
                    <div class="ov-bar ${r.g > 0 && r.abs >= r.g ? 'ov-bar-paid' : ''}" style="width:${r.g > 0 ? Math.min(Math.round(r.abs / r.g * 100), 100) : 0}%"></div>
                    <span class="ov-bar-pct">${r.g > 0 ? Math.min(Math.round(r.abs / r.g * 100), 100) : 0} %</span>
                  </div>
                </td>
              </tr>`).join('')}
          </tbody>
          <tfoot>
            <tr class="total-row">
              <td></td>
              <td><strong>Gesamt</strong></td>
              <td class="text-right calc-cell price-sensitive">${fmt(totalMat)}</td>
              <td class="text-right calc-cell price-sensitive">${fmt(totalAz)}</td>
              <td class="text-right calc-cell price-sensitive">${fmt(totalP)}</td>
              <td class="text-right calc-cell price-sensitive">${fmt(grand)}</td>
              <td class="text-right calc-cell price-sensitive">${fmt(totalAbschlag)}</td>
              <td class="text-right calc-cell ov-offen price-sensitive">${fmt(grandOffen)}</td>
              <td class="text-right calc-cell price-sensitive gewinn-sensitive" style="color:${totalGewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmt(totalGewinn)}</td>
              <td class="price-sensitive">
                <div class="ov-bar-wrap">
                  <div class="ov-bar ${grand > 0 && totalAbschlag >= grand ? 'ov-bar-paid' : ''}" style="width:${grand > 0 ? Math.min(Math.round(totalAbschlag / grand * 100), 100) : 0}%"></div>
                  <span class="ov-bar-pct">${grand > 0 ? Math.min(Math.round(totalAbschlag / grand * 100), 100) : 0} %</span>
                </div>
              </td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>`;
}

function filterUebersichtRows(q) {
  const terms = q.trim().toLowerCase().split(/\s+/).filter(t => t);
  const rows = document.querySelectorAll('#ovBody tr.ov-row');
  rows.forEach(tr => {
    if (terms.length === 0) { tr.style.display = ''; return; }
    const text = tr.textContent.toLowerCase();
    tr.style.display = terms.every(t => text.includes(t)) ? '' : 'none';
  });
}

function sortUebersichtRows(mode) {
  const tbody = document.getElementById('ovBody');
  if (!tbody) return;
  const rows = Array.from(tbody.querySelectorAll('tr.ov-row'));
  rows.sort((a, b) => {
    switch (mode) {
      case 'name': return a.querySelector('.ov-name').textContent.localeCompare(b.querySelector('.ov-name').textContent, 'de');
      case 'projektNr': return (a.querySelector('.ov-pnr')?.textContent || '').localeCompare(b.querySelector('.ov-pnr')?.textContent || '', 'de');
      case 'g-desc': return parseNum(b, 5) - parseNum(a, 5);
      case 'g-asc':  return parseNum(a, 5) - parseNum(b, 5);
      case 'offen-desc': return parseNum(b, 7) - parseNum(a, 7);
      case 'offen-asc':  return parseNum(a, 7) - parseNum(b, 7);
      default: return 0;
    }
  });
  rows.forEach(r => tbody.appendChild(r));
  function parseNum(tr, col) {
    const text = tr.children[col]?.textContent || '0';
    return parseFloat(text.replace(/[^\d,.-]/g, '').replace(',', '.')) || 0;
  }
}

