function addMatRow() {
  const b = getBaustelle();
  if (!b) return;
  b.material.unshift({ id: b.nextMatId++, bezeichnung: '', anzahl: 1, einheit: 'Stk.', ek: 0, aufschlag: 0, kategorieId: null, erstelltVon: currentKuerzel, datum: new Date().toISOString().split('T')[0] });
  openMatCategory('__none__', b);
  saveData();
  renderMatRows();
  recalc();
}

// ── KI Materialscan (v2.9.21) ────────────────────────────────
// Lieferscheine, Rechnungen oder Fotos per Gemini-API analysieren
// und erkannte Positionen direkt ins Projektmaterial importieren.

function openKiScanModal(globalMode = false) {
  window._kiScanGlobal = !!globalMode;
  document.getElementById('kiScanOverlay')?.remove();
  const ov = document.createElement('div');
  ov.className = 'modal-overlay';
  ov.id = 'kiScanOverlay';
  ov.onclick = (e) => { if (e.target === ov) ov.remove(); };
  ov.innerHTML = `
    <div class="modal-box" style="max-width:480px">
      <div class="modal-header">
        <h2>🤖 ${globalMode ? 'KI Beleg-Scan' : 'KI Materialscan'}</h2>
        <button class="close-btn" onclick="document.getElementById('kiScanOverlay')?.remove()">✕</button>
      </div>
      <div class="modal-body">
        <p style="margin-bottom:12px;font-size:.9rem;color:var(--text-muted)">
          Lade einen Lieferschein, eine Rechnung, ein Angebot oder ein Foto hoch.
          ${globalMode
            ? 'Die KI erkennt die Positionen – anschließend kannst du jede Position einer Baustelle und der Zuweisung (Material oder Arbeitszeit) zuordnen.'
            : 'Die KI erkennt die Materialpositionen und schlägt sie zum Import vor.'}
        </p>
        <div id="kiScanDropzone"
          style="border:2px dashed var(--border);border-radius:8px;padding:24px 16px;text-align:center;cursor:pointer;transition:border-color .2s;margin-bottom:12px;"
          onclick="document.getElementById('kiScanFileInput').click()"
          ondragover="event.preventDefault();this.style.borderColor='var(--primary)'"
          ondragleave="this.style.borderColor='var(--border)'"
          ondrop="_kiScanDrop(event)">
          <div style="font-size:2rem;margin-bottom:6px;">📄</div>
          <div style="font-size:.9rem;color:var(--text-muted)">Klicken oder Datei hierher ziehen</div>
          <div style="font-size:.75rem;color:var(--grey-400);margin-top:4px">JPG, PNG, WEBP, GIF, PDF · max. 10 MB</div>
        </div>
        <input type="file" id="kiScanFileInput" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf"
          style="display:none" onchange="_kiScanFileChosen(this.files[0])">
        <div id="kiScanPreview" style="display:none;margin-bottom:12px;text-align:center;">
          <img id="kiScanPreviewImg" style="max-width:100%;max-height:180px;border-radius:6px;border:1px solid var(--border);" alt="">
          <div id="kiScanFileName" style="font-size:.8rem;color:var(--text-muted);margin-top:4px;"></div>
        </div>
        <div id="kiScanStatus" style="display:none;text-align:center;padding:12px;color:var(--text-muted);font-size:.9rem;">
          <span style="display:inline-block;animation:spin 1s linear infinite;margin-right:6px;">⏳</span>
          KI analysiert Dokument…
        </div>
        <div id="kiScanError" style="display:none;padding:10px 12px;background:#ffebee;border-radius:6px;color:#b71c1c;font-size:.85rem;margin-bottom:10px;"></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:4px;">
          <button class="btn btn-secondary" onclick="document.getElementById('kiScanOverlay')?.remove()">Abbrechen</button>
          <button id="kiScanAnalyzeBtn" class="btn btn-primary" onclick="_kiScanRun()" disabled>Analysieren</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
}

function _kiScanDrop(event) {
  event.preventDefault();
  document.getElementById('kiScanDropzone').style.borderColor = 'var(--border)';
  const file = event.dataTransfer?.files?.[0];
  if (file) _kiScanFileChosen(file);
}

async function _kiScanFileChosen(file) {
  if (!file) return;
  const errEl = document.getElementById('kiScanError');
  const btn = document.getElementById('kiScanAnalyzeBtn');
  errEl.style.display = 'none';
  btn.disabled = true;
  window._kiScanPendingFile = null;
  if (file.size > 10 * 1024 * 1024) {
    errEl.textContent = 'Datei zu groß (max. 10 MB). Bitte eine kleinere Datei wählen.';
    errEl.style.display = 'block';
    return;
  }
  // Sofort in den Speicher kopieren: spätere Lesezugriffe (Scan, Vorschau, Beleg) hängen dann nicht mehr an der Datei auf dem Datenträger.
  try {
    file = new File([await file.arrayBuffer()], file.name, { type: file.type, lastModified: file.lastModified });
  } catch (e) {
    errEl.textContent = 'Datei konnte nicht gelesen werden (' + (e.name || 'Fehler') + '). Ist sie noch in einem anderen Programm geöffnet, wurde sie verschoben/geändert oder liegt sie nur in der Cloud (OneDrive)? Bitte Datei schließen bzw. lokal speichern und erneut auswählen.';
    errEl.style.display = 'block';
    return;
  }
  window._kiScanPendingFile = file;
  document.getElementById('kiScanFileName').textContent = file.name + ' (' + (file.size / 1024).toFixed(0) + ' KB)';
  const preview = document.getElementById('kiScanPreview');
  const img = document.getElementById('kiScanPreviewImg');
  if (file.type.startsWith('image/')) {
    img.src = URL.createObjectURL(file);
    img.style.display = '';
    preview.style.display = '';
  } else {
    img.style.display = 'none';
    preview.style.display = '';
  }
  btn.disabled = false;
}

async function _kiScanRun() {
  const file = window._kiScanPendingFile;
  if (!file) return;
  const errEl   = document.getElementById('kiScanError');
  const statusEl = document.getElementById('kiScanStatus');
  const btn     = document.getElementById('kiScanAnalyzeBtn');
  errEl.style.display   = 'none';
  statusEl.style.display = 'block';
  btn.disabled = true;
  try {
    const b64 = await new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onload  = () => resolve(fr.result.split(',')[1]);
      fr.onerror = () => reject(new Error('Datei konnte nicht gelesen werden (' + (fr.error?.name || 'Lesefehler') + '). Bitte Datei erneut auswählen.'));
      fr.readAsDataURL(file);
    });
    const resp = await fetch('api.php?action=ai_scan_material', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mimeType: file.type, data: b64 }),
    });
    const j = await resp.json();
    if (!resp.ok || !j.ok) throw new Error(j.error || 'Unbekannter Fehler');
    document.getElementById('kiScanOverlay')?.remove();
    window._kiScanAbsender = j.absender || null;
    if (!j.items || j.items.length === 0) {
      showNotification(j.hint || 'Keine Materialpositionen erkannt.');
      return;
    }
    if (window._kiScanGlobal) {
      showKiScanResultsGlobal(j.items, j.hint, j.preisbasis || 'unbekannt', parseFloat(j.mwstSatz) || 0);
    } else {
      showKiScanResults(j.items, j.hint, j.preisbasis || 'unbekannt', parseFloat(j.mwstSatz) || 0);
    }
  } catch (e) {
    statusEl.style.display = 'none';
    errEl.textContent = 'Fehler: ' + (e.message || String(e));
    errEl.style.display = 'block';
    btn.disabled = false;
  }
}

// ── Gemeinsame Helfer für die KI-Scan-Ergebnisansicht ──────
// Baut die Dokument-Vorschau (links) aus der hochgeladenen Datei.
function _kiScanDocPreviewHtml() {
  const f = window._kiScanPendingFile;
  window._kiScanDocIsPdf = false;
  if (!f) {
    return '<div style="flex:1;display:flex;align-items:center;justify-content:center;color:#999;font-size:.85rem;padding:20px;text-align:center;">Kein Dokument zur Vorschau vorhanden.</div>';
  }
  try { if (window._kiScanDocUrl) URL.revokeObjectURL(window._kiScanDocUrl); } catch (_) {}
  const url = URL.createObjectURL(f);
  window._kiScanDocUrl = url;
  const isPdf = (f.type === 'application/pdf') || /\.pdf$/i.test(f.name || '');
  const bar = `<div style="flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:5px 8px;background:#1f1f1f;color:#ddd;font-size:.75rem;">
      <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(f.name || 'Dokument')}</span>
      <a href="${url}" target="_blank" rel="noopener" style="color:#8ec5ff;text-decoration:none;">↗ In neuem Tab öffnen</a>
    </div>`;
  if (isPdf) {
    // PDF wird per PDF.js auf Canvas gezeichnet (native Einbettung wird von Edge/Browsern oft blockiert).
    window._kiScanDocIsPdf = true;
    return bar + `<div id="kiScanPdfHost" style="flex:1;min-height:0;width:100%;overflow:auto;background:#525659;padding:8px 0;text-align:center;">
      <div style="color:#ccc;font-size:.82rem;padding:20px;">PDF wird geladen…</div>
    </div>`;
  }
  return bar + `<div style="flex:1;min-height:0;width:100%;overflow:auto;background:#2b2b2b;display:flex;align-items:flex-start;justify-content:center;">
    <img src="${url}" alt="Gescanntes Dokument" style="max-width:100%;height:auto;display:block;">
  </div>`;
}

// PDF.js bei Bedarf nachladen (lokal gebündelt, funktioniert offline im LAN).
function _kiScanEnsurePdfJs() {
  if (window._pdfJsLoading) return window._pdfJsLoading;
  if (window.pdfjsLib) {
    try { window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'lib/pdfjs/pdf.worker.min.js'; } catch (_) {}
    return Promise.resolve();
  }
  window._pdfJsLoading = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'lib/pdfjs/pdf.min.js';
    s.onload = () => {
      try { window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'lib/pdfjs/pdf.worker.min.js'; } catch (_) {}
      resolve();
    };
    s.onerror = () => { window._pdfJsLoading = null; reject(new Error('PDF.js konnte nicht geladen werden')); };
    document.head.appendChild(s);
  });
  return window._pdfJsLoading;
}

// Rendert alle Seiten des PDFs in den Vorschau-Container.
// Übergabe der Rohbytes (nicht der Blob-URL): PDF.js kann Blob-URLs im Worker
// nicht zuverlässig laden ("Unexpected server response (0)").
async function _kiScanRenderPdf(file, host) {
  try {
    await _kiScanEnsurePdfJs();
    const lib = window.pdfjsLib;
    if (!lib) throw new Error('PDF.js nicht verfügbar');
    const buf = await file.arrayBuffer();
    const pdf = await lib.getDocument({ data: new Uint8Array(buf) }).promise;
    host.innerHTML = '';
    for (let n = 1; n <= pdf.numPages; n++) {
      const page = await pdf.getPage(n);
      const viewport = page.getViewport({ scale: 1.5 });
      const canvas = document.createElement('canvas');
      canvas.width = viewport.width;
      canvas.height = viewport.height;
      canvas.style.cssText = 'max-width:98%;height:auto;margin:0 auto 10px;display:block;box-shadow:0 1px 6px rgba(0,0,0,.5);background:#fff;';
      host.appendChild(canvas);
      await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
    }
  } catch (e) {
    const link = window._kiScanDocUrl ? `<br><a href="${esc(window._kiScanDocUrl)}" target="_blank" rel="noopener" style="color:#8ec5ff;">↗ In neuem Tab öffnen</a>` : '';
    host.innerHTML = `<div style="color:#f88;font-size:.82rem;padding:16px;text-align:center;">PDF-Vorschau nicht möglich: ${esc(e.message || String(e))}${link}</div>`;
  }
}

// Startet die PDF-Darstellung, nachdem das Modal im DOM ist.
function _kiScanInitDocPreview() {
  if (!window._kiScanDocIsPdf) return;
  const host = document.getElementById('kiScanPdfHost');
  if (host && window._kiScanPendingFile) _kiScanRenderPdf(window._kiScanPendingFile, host);
}

// Gibt die Object-URL der Dokument-Vorschau wieder frei (beim Schließen).
function _kiScanRevokeDoc() {
  try { if (window._kiScanDocUrl) { URL.revokeObjectURL(window._kiScanDocUrl); window._kiScanDocUrl = null; } } catch (_) {}
}

// Schließt die Ergebnis-Overlays (projekt-/global) inkl. Freigabe der Vorschau-URL.
function _kiScanCloseResults() { _kiScanRevokeDoc(); document.getElementById('kiScanResultOverlay')?.remove(); }
function _kigClose()          { _kiScanRevokeDoc(); document.getElementById('kiScanGlobalOverlay')?.remove(); }

// Baut den optionalen Absender-Block (Briefkopf → Kundenstamm).
// prefix macht die Feld-IDs eindeutig (proj = projektbezogen, glob = global).
function _kiScanAbsenderHtml(prefix) {
  const a = window._kiScanAbsender || {};
  const has = ['firma', 'ansprechpartner', 'strasse', 'plz', 'ort', 'telefon', 'email'].some(k => (a[k] || '').trim());
  if (!has) return '';
  const v = (s) => esc(s || '');
  const inp = (id, val, ph, w) => `<input type="text" id="${prefix}${id}" class="form-control" value="${v(val)}" placeholder="${ph}" style="width:${w||'100%'};font-size:.84rem;padding:4px 6px;">`;
  return `
  <details class="kiscan-absender" style="margin-bottom:10px;border:1px solid #B3D8FF;border-radius:6px;background:#F5FAFF;">
    <summary style="cursor:pointer;padding:8px 12px;font-size:.85rem;font-weight:600;color:#0B5394;">📇 Absender / Briefkopf erkannt – optional in den Kundenstamm übernehmen</summary>
    <div style="padding:10px 12px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
        <label style="grid-column:1/3;font-size:.76rem;color:#555;">Firma${inp('AbsFirma', a.firma, 'Firmenname')}</label>
        <label style="font-size:.76rem;color:#555;">Ansprechpartner${inp('AbsName', a.ansprechpartner, 'Name')}</label>
        <label style="font-size:.76rem;color:#555;">Straße${inp('AbsStrasse', a.strasse, 'Straße + Nr.')}</label>
        <label style="font-size:.76rem;color:#555;">PLZ / Ort<span style="display:flex;gap:6px;">${inp('AbsPlz', a.plz, 'PLZ', '80px')}${inp('AbsOrt', a.ort, 'Ort')}</span></label>
        <label style="font-size:.76rem;color:#555;">Telefon${inp('AbsTel', a.telefon, 'Telefon')}</label>
        <label style="font-size:.76rem;color:#555;">E-Mail${inp('AbsEmail', a.email, 'E-Mail')}</label>
        <span></span>
      </div>
      <div style="display:flex;justify-content:flex-end;margin-top:8px;">
        <button type="button" class="btn btn-primary btn-sm" id="${prefix}AbsBtn" onclick="_kiScanSaveKundeFromScan('${prefix}', this)">In Kundenstamm übernehmen</button>
      </div>
    </div>
  </details>`;
}

// Legt aus den Absender-Feldern einen Kunden im Kundenstamm an (nur auf Klick).
async function _kiScanSaveKundeFromScan(prefix, btn) {
  const g = (id) => document.getElementById(prefix + id)?.value?.trim() || '';
  const data = {
    firma:    g('AbsFirma'),
    nachname: g('AbsName'),
    strasse:  g('AbsStrasse'),
    plz:      g('AbsPlz'),
    ort:      g('AbsOrt'),
    telefon:  g('AbsTel'),
    email:    g('AbsEmail'),
    notizen:  'Automatisch aus KI-Beleg-Scan übernommen.',
  };
  if (!data.firma && !data.nachname) { showNotification('Bitte Firma oder Ansprechpartner angeben.', 'error'); return; }
  if (btn) btn.disabled = true;
  try {
    const r = await fetch('api.php?action=save_kunde', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    const j = await r.json();
    if (!r.ok || j.error) throw new Error(j.error || 'Speichern fehlgeschlagen');
    if (typeof loadKundenData === 'function') { try { await loadKundenData(); } catch (_) {} }
    showNotification('In Kundenstamm gespeichert ✓', 'success');
    if (btn) { btn.textContent = '✓ Gespeichert'; btn.classList.remove('btn-primary'); btn.classList.add('btn-secondary'); }
  } catch (e) {
    if (btn) btn.disabled = false;
    showNotification('Fehler: ' + (e.message || String(e)), 'error');
  }
}

function showKiScanResults(items, hint, preisbasis, mwstSatz) {
  document.getElementById('kiScanResultOverlay')?.remove();
  const ov = document.createElement('div');
  ov.className = 'modal-overlay';
  ov.id = 'kiScanResultOverlay';
  ov.onclick = (e) => { if (e.target === ov) _kiScanCloseResults(); };
  // MwSt-Behandlung: Baustellen führen ausschließlich NETTO-Preise.
  // preisbasis von der KI: 'netto' | 'brutto' | 'unbekannt'. Default-Satz aus Firma.
  preisbasis = (preisbasis === 'netto' || preisbasis === 'brutto') ? preisbasis : 'unbekannt';
  const firmaSatz = parseFloat(appSettings?.firma_mwst_satz) || 19;
  const satz = (mwstSatz && mwstSatz > 0) ? mwstSatz : firmaSatz;
  // Default-Modus: erkannte Basis; bei 'unbekannt' konservativ 'netto' (keine ungewollte Reduktion),
  // der Nutzer wird per Warnbanner zur Prüfung aufgefordert.
  const startModus = preisbasis === 'brutto' ? 'brutto' : 'netto';

  const rows = items.map((it, i) => {
    const menge   = parseFloat(it.anzahl) || 1;
    const rawEk   = parseFloat(it.ek) || 0;            // gedruckter Einzelpreis (netto ODER brutto)
    const rawGes  = parseFloat(it.gesamtpreis) || 0;   // gedruckter Positions-Gesamtpreis (Beleg)
    const netEk   = startModus === 'brutto' ? rawEk / (1 + satz / 100) : rawEk;
    const gesamt  = (menge * netEk).toFixed(2);
    return `
    <tr data-raw-ek="${rawEk}" data-raw-ges="${rawGes}">
      <td style="text-align:center;"><input type="checkbox" class="ki-scan-cb" data-idx="${i}" checked></td>
      <td><input type="text" class="form-control ki-scan-artnr" data-idx="${i}" value="${(it.artikelnummer||'').replace(/"/g,'&quot;')}" style="width:90px;font-size:.82rem;padding:3px 6px;" placeholder="—"></td>
      <td><input type="text" class="form-control ki-scan-bez" data-idx="${i}" value="${(it.bezeichnung||'').replace(/"/g,'&quot;')}" style="width:100%;min-width:130px;font-size:.85rem;padding:3px 6px;"></td>
      <td><input type="number" class="form-control ki-scan-menge" data-idx="${i}" value="${menge}" min="0" step="any" style="width:60px;font-size:.85rem;padding:3px 6px;text-align:right;" oninput="_kiScanCalcTotals()"></td>
      <td><input type="text" class="form-control ki-scan-einheit" data-idx="${i}" value="${(it.einheit||'Stk.').replace(/"/g,'&quot;')}" style="width:55px;font-size:.85rem;padding:3px 6px;"></td>
      <td><input type="number" class="form-control ki-scan-ek" data-idx="${i}" value="${netEk.toFixed(2)}" min="0" step="0.01" style="width:80px;font-size:.85rem;padding:3px 6px;text-align:right;" oninput="_kiScanCalcTotals()"></td>
      <td class="ki-scan-gesamt" data-idx="${i}" style="text-align:right;font-weight:600;padding:3px 6px;white-space:nowrap;">${gesamt}</td>
      <td class="ki-scan-beleg" data-idx="${i}" style="text-align:right;color:#888;font-size:.78rem;padding:3px 6px;white-space:nowrap;" title="Gesamtpreis laut Beleg (zur Kontrolle)">${rawGes > 0 ? rawGes.toFixed(2) : '—'}</td>
    </tr>`;
  }).join('');

  const initialTotal = items.reduce((s, it) => {
    const rawEk = parseFloat(it.ek) || 0;
    const netEk = startModus === 'brutto' ? rawEk / (1 + satz / 100) : rawEk;
    return s + netEk * (parseFloat(it.anzahl) || 1);
  }, 0).toFixed(2);

  // Warnbanner je nach erkannter Preisbasis
  let warnBanner = '';
  if (preisbasis === 'brutto') {
    warnBanner = `<div style="padding:9px 12px;background:#FFF3E0;border:1px solid #FFB74D;border-radius:6px;font-size:.83rem;color:#E65100;margin-bottom:10px;">
      ⚠️ <strong>Bruttopreise erkannt</strong> – die Belegpreise enthalten ${satz.toLocaleString('de-DE')}% MwSt. Sie wurden auf <strong>Netto</strong> umgerechnet (Baustellen führen nur Nettopreise). Bitte prüfen.</div>`;
  } else if (preisbasis === 'netto') {
    warnBanner = `<div style="padding:9px 12px;background:#E8F5E9;border:1px solid #A5D6A7;border-radius:6px;font-size:.83rem;color:#1B5E20;margin-bottom:10px;">
      ✓ <strong>Nettopreise erkannt</strong> – die Belegpreise wurden ohne MwSt übernommen.</div>`;
  } else {
    warnBanner = `<div style="padding:9px 12px;background:#FFEBEE;border:1px solid #EF9A9A;border-radius:6px;font-size:.83rem;color:#B71C1C;margin-bottom:10px;">
      ⚠️ <strong>MwSt-Behandlung unklar</strong> – bitte unten festlegen, ob die Belegpreise <strong>netto</strong> oder <strong>brutto (inkl. MwSt)</strong> sind. Baustellen führen ausschließlich Nettopreise.</div>`;
  }

  ov.innerHTML = `
    <div class="modal-box" style="width:98vw;max-width:none;height:96vh;display:flex;flex-direction:column;padding:0;overflow:hidden;">
      <div class="modal-header" style="flex:0 0 auto;">
        <h2>🤖 Erkannte Positionen (${items.length})</h2>
        <button class="close-btn" onclick="_kiScanCloseResults()">✕</button>
      </div>
      <div style="display:flex;flex:1;min-height:0;">
        <div class="kiscan-doc-pane" style="flex:0 0 44%;min-width:0;display:flex;flex-direction:column;border-right:1px solid var(--border);background:#2b2b2b;">
          ${_kiScanDocPreviewHtml()}
        </div>
        <div class="modal-body" style="flex:1;min-width:0;overflow-y:auto;">
        ${hint ? `<div style="padding:8px 12px;background:#FFF8E1;border-radius:6px;font-size:.85rem;color:#5D4037;margin-bottom:10px;">${hint}</div>` : ''}
        ${warnBanner}
        ${_kiScanAbsenderHtml('proj')}
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;padding:8px 10px;background:var(--bg-light,#f5f7fa);border-radius:6px;">
          <span style="font-size:.82rem;font-weight:600;color:#555;">Belegpreise sind:</span>
          <select id="kiScanModus" class="form-input" style="padding:3px 8px;font-size:.82rem;width:auto;" onchange="_kiScanApplyMode()">
            <option value="netto" ${startModus==='netto'?'selected':''}>Netto (ohne MwSt)</option>
            <option value="brutto" ${startModus==='brutto'?'selected':''}>Brutto (inkl. MwSt)</option>
          </select>
          <label style="font-size:.82rem;color:#555;display:flex;align-items:center;gap:4px;">MwSt-Satz
            <input type="number" id="kiScanMwst" value="${satz}" min="0" max="100" step="0.1" style="width:62px;padding:3px 6px;font-size:.82rem;text-align:right;" onchange="_kiScanApplyMode()" oninput="_kiScanApplyMode()"> %
          </label>
          <span style="flex:1"></span>
          <span style="font-size:.75rem;color:#999;">EK wird stets als Netto gespeichert</span>
        </div>
        <div style="margin-bottom:10px;">
          <label style="font-size:.8rem;color:#666;display:block;margin-bottom:3px;">📋 Lieferschein / Bezeichnung <span style="font-size:.75rem;color:#aaa;">(optional – alle Positionen erhalten diese Kategorie)</span></label>
          <input type="text" id="kiScanLieferschein" class="form-control" placeholder="z.B. LS-2025-001 oder Lieferschein Elektro AG" style="width:100%;font-size:.9rem;">
        </div>
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;font-size:.85rem;">
          <a href="#" onclick="event.preventDefault();document.querySelectorAll('.ki-scan-cb').forEach(c=>c.checked=true);_kiScanUpdateBtn();_kiScanCalcTotals()">Alle</a>
          <a href="#" onclick="event.preventDefault();document.querySelectorAll('.ki-scan-cb').forEach(c=>c.checked=false);_kiScanUpdateBtn();_kiScanCalcTotals()">Keine</a>
          <span style="flex:1"></span>
          <span id="kiScanSelCount" style="color:var(--text-muted)">${items.length} ausgewählt</span>
        </div>
        <div style="overflow-x:auto;">
          <table class="data-table" style="font-size:.85rem;width:100%">
            <thead><tr>
              <th style="width:32px;text-align:center;">✓</th>
              <th>Art.-Nr.</th>
              <th>Bezeichnung</th>
              <th style="text-align:right;">Menge</th>
              <th>Einheit</th>
              <th style="text-align:right;">EK netto (€)</th>
              <th style="text-align:right;">Gesamt netto (€)</th>
              <th style="text-align:right;" title="Gesamtpreis laut Beleg">Beleg (€)</th>
            </tr></thead>
            <tbody>${rows}</tbody>
            <tfoot>
              <tr>
                <td colspan="6" style="text-align:right;font-weight:700;font-size:.85rem;padding:5px 6px;border-top:2px solid var(--border);">Gesamt netto (Auswahl):</td>
                <td id="kiScanTotal" style="text-align:right;font-weight:700;font-size:.85rem;padding:5px 6px;border-top:2px solid var(--border);white-space:nowrap;">${initialTotal} €</td>
                <td style="border-top:2px solid var(--border);"></td>
              </tr>
            </tfoot>
          </table>
        </div>
        <div style="display:flex;align-items:center;gap:8px;margin-top:14px;padding-top:10px;border-top:1px solid var(--border);">
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;flex:1;">
            <input type="checkbox" id="kiScanSaveFileCb" checked>
            Originaldokument ablegen in
          </label>
          <select id="kiScanFileCat" class="form-input" style="padding:3px 7px;font-size:.82rem;width:auto;">
            <option value="Eingangsbelege" selected>Eingangsbelege</option>
            <option value="Ausgangsbelege">Ausgangsbelege</option>
            <option value="Angebote">Angebote</option>
            <option value="Dateien">Dateien</option>
            <option value="Sonstiges">Sonstiges</option>
          </select>
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px;">
          <button class="btn btn-secondary" onclick="_kiScanCloseResults()">Abbrechen</button>
          <button id="kiScanImportBtn" class="btn btn-primary" onclick="_kiScanImport()">
            ${items.length} Position${items.length !== 1 ? 'en' : ''} importieren
          </button>
        </div>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
  _kiScanInitDocPreview();
  // Zähler + Gesamtsumme bei Checkbox-Änderung aktualisieren
  ov.querySelectorAll('.ki-scan-cb').forEach(cb => cb.addEventListener('change', () => { _kiScanUpdateBtn(); _kiScanCalcTotals(); }));
}

// Wendet den Netto/Brutto-Modus an: rechnet die EK-Felder aus den gedruckten
// Roh-Einzelpreisen (data-raw-ek) zurück auf Netto, falls "brutto" gewählt ist.
function _kiScanApplyMode() {
  const modus = document.getElementById('kiScanModus')?.value || 'netto';
  const satz  = parseFloat(document.getElementById('kiScanMwst')?.value) || 0;
  document.querySelectorAll('#kiScanResultOverlay tbody tr').forEach(tr => {
    const rawEk = parseFloat(tr.getAttribute('data-raw-ek')) || 0;
    const netEk = (modus === 'brutto' && satz > 0) ? rawEk / (1 + satz / 100) : rawEk;
    const ekInput = tr.querySelector('.ki-scan-ek');
    if (ekInput) ekInput.value = netEk.toFixed(2);
  });
  _kiScanCalcTotals();
}

function _kiScanCalcTotals() {
  let total = 0;
  document.querySelectorAll('.ki-scan-cb').forEach(cb => {
    const i     = cb.dataset.idx;
    const menge = parseFloat(document.querySelector(`.ki-scan-menge[data-idx="${i}"]`)?.value) || 0;
    const ek    = parseFloat(document.querySelector(`.ki-scan-ek[data-idx="${i}"]`)?.value) || 0;
    const pos   = menge * ek;
    const cell  = document.querySelector(`.ki-scan-gesamt[data-idx="${i}"]`);
    if (cell) cell.textContent = pos.toFixed(2);
    if (cb.checked) total += pos;
  });
  const totalEl = document.getElementById('kiScanTotal');
  if (totalEl) totalEl.textContent = total.toFixed(2) + ' €';
}

function _kiScanUpdateBtn() {
  const checked = document.querySelectorAll('.ki-scan-cb:checked').length;
  const btn = document.getElementById('kiScanImportBtn');
  const cnt = document.getElementById('kiScanSelCount');
  if (btn) btn.textContent = checked + ' Position' + (checked !== 1 ? 'en' : '') + ' importieren';
  if (cnt) cnt.textContent = checked + ' ausgewählt';
}

async function _kiScanImport() {
  const b = getBaustelle();
  if (!b) return;
  const checkboxes = document.querySelectorAll('.ki-scan-cb:checked');
  if (checkboxes.length === 0) { showNotification('Keine Positionen ausgewählt.'); return; }
  const today = new Date().toISOString().split('T')[0];
  let count = 0;

  // Lieferschein-Kategorie ermitteln oder anlegen
  const lieferscheinName = document.getElementById('kiScanLieferschein')?.value?.trim() || '';
  let lieferscheinKatId = null;
  if (lieferscheinName) {
    if (!b.matKategorien) b.matKategorien = [];
    if (!b.nextMatKatId) b.nextMatKatId = 1;
    const existing = b.matKategorien.find(k => k.name.toLowerCase() === lieferscheinName.toLowerCase());
    if (existing) {
      lieferscheinKatId = existing.id;
    } else {
      lieferscheinKatId = b.nextMatKatId++;
      b.matKategorien.push({ id: lieferscheinKatId, name: lieferscheinName });
    }
  }

  // Rückwärts iterieren damit unshift() die Reihenfolge erhält
  const idxList = Array.from(checkboxes).map(cb => parseInt(cb.dataset.idx)).sort((a, b) => b - a);
  idxList.forEach(i => {
    const bez    = document.querySelector(`.ki-scan-bez[data-idx="${i}"]`)?.value?.trim() || '';
    const artnr  = document.querySelector(`.ki-scan-artnr[data-idx="${i}"]`)?.value?.trim() || '';
    const menge  = parseFloat(document.querySelector(`.ki-scan-menge[data-idx="${i}"]`)?.value) || 1;
    const einh   = document.querySelector(`.ki-scan-einheit[data-idx="${i}"]`)?.value?.trim() || 'Stk.';
    const ek     = parseFloat(document.querySelector(`.ki-scan-ek[data-idx="${i}"]`)?.value) || 0;
    if (!bez) return;
    b.material.unshift({ id: b.nextMatId++, bezeichnung: bez, artikelnr: artnr, anzahl: menge, einheit: einh, ek: ek, aufschlag: 0, kategorieId: lieferscheinKatId, erstelltVon: currentKuerzel, datum: today });
    count++;
  });
  if (count > 0) {
    openMatCategory('__none__', b);
    saveData();
    renderMatRows();
    recalc();
    // Originaldokument in Dateien ablegen
    const saveCb = document.getElementById('kiScanSaveFileCb');
    if (saveCb && saveCb.checked && window._kiScanPendingFile) {
      const cat = document.getElementById('kiScanFileCat')?.value || 'Eingangsbelege';
      const fd = new FormData();
      fd.append('file', window._kiScanPendingFile);
      fd.append('baustelleId', b.id);
      fd.append('category', cat);
      try {
        await fetch('api.php?action=upload_file', { method: 'POST', body: fd });
        loadBaustelleFiles();
      } catch(_) {}
    }
    document.getElementById('kiScanResultOverlay') && _kiScanCloseResults();
    showNotification(count + ' Position' + (count !== 1 ? 'en' : '') + ' importiert ✓');
  }
}

// ── Allgemeiner KI-Scan: Positionen frei Baustellen/Projekten zuweisen ──
// Wird über openKiScanModal(true) gestartet. Jede erkannte Position erhält eine
// eigene Baustelle (durchsuchbares Feld) und eine Zuweisung (Material/Arbeitszeit).
function showKiScanResultsGlobal(items, hint, preisbasis, mwstSatz) {
  document.getElementById('kiScanGlobalOverlay')?.remove();
  const ov = document.createElement('div');
  ov.className = 'modal-overlay';
  ov.id = 'kiScanGlobalOverlay';
  ov.onclick = (e) => { if (e.target === ov) _kigClose(); };

  preisbasis = (preisbasis === 'netto' || preisbasis === 'brutto') ? preisbasis : 'unbekannt';
  const firmaSatz = parseFloat(appSettings?.firma_mwst_satz) || 19;
  const satz = (mwstSatz && mwstSatz > 0) ? mwstSatz : firmaSatz;
  const startModus = preisbasis === 'brutto' ? 'brutto' : 'netto';

  // Sichtbare Baustellen + Lookup-Map für die Auflösung der Eingabe
  const bsList = getVisibleBaustellen().slice().sort((a, b) => (a.name || '').localeCompare(b.name || '', 'de'));
  const bsLabel = (b) => `${b.projektNr ? b.projektNr + ' · ' : ''}${b.name || ''}`;
  window._kigBsMap = {};
  bsList.forEach(b => {
    window._kigBsMap[bsLabel(b).toLowerCase()] = b.id;
    if (b.name) window._kigBsMap[b.name.toLowerCase()] = b.id;
  });
  const datalistOpts = bsList.map(b => `<option value="${esc(bsLabel(b))}"></option>`).join('');

  window._kigRid = 0;
  const rows = (items || []).map((it) => {
    const rawEk = parseFloat(it.ek) || 0;
    const netEk = startModus === 'brutto' ? rawEk / (1 + satz / 100) : rawEk;
    return _kigRowHtml(++window._kigRid, {
      artnr: it.artikelnummer || '', bez: it.bezeichnung || '',
      menge: parseFloat(it.anzahl) || 1, einheit: it.einheit || 'Stk.',
      ek: netEk, typ: 'material', baustelle: '', manual: false, rawEk: rawEk,
    });
  }).join('');

  const initialTotal = (items || []).reduce((s, it) => {
    const rawEk = parseFloat(it.ek) || 0;
    const netEk = startModus === 'brutto' ? rawEk / (1 + satz / 100) : rawEk;
    return s + netEk * (parseFloat(it.anzahl) || 1);
  }, 0).toFixed(2);

  let warnBanner = '';
  if (preisbasis === 'brutto') {
    warnBanner = `<div style="padding:9px 12px;background:#FFF3E0;border:1px solid #FFB74D;border-radius:6px;font-size:.83rem;color:#E65100;margin-bottom:10px;">⚠️ <strong>Bruttopreise erkannt</strong> – auf Netto umgerechnet (${satz.toLocaleString('de-DE')}% MwSt). Bitte prüfen.</div>`;
  } else if (preisbasis === 'netto') {
    warnBanner = `<div style="padding:9px 12px;background:#E8F5E9;border:1px solid #A5D6A7;border-radius:6px;font-size:.83rem;color:#1B5E20;margin-bottom:10px;">✓ <strong>Nettopreise erkannt</strong> – ohne MwSt übernommen.</div>`;
  } else {
    warnBanner = `<div style="padding:9px 12px;background:#FFEBEE;border:1px solid #EF9A9A;border-radius:6px;font-size:.83rem;color:#B71C1C;margin-bottom:10px;">⚠️ <strong>MwSt-Behandlung unklar</strong> – bitte unten festlegen (netto/brutto).</div>`;
  }

  ov.innerHTML = `
    <datalist id="kigBsList">${datalistOpts}</datalist>
    <div class="modal-box" style="width:98vw;max-width:none;height:96vh;display:flex;flex-direction:column;padding:0;overflow:hidden;">
      <div class="modal-header" style="flex:0 0 auto;">
        <h2>🤖 Beleg-Positionen zuweisen</h2>
        <button class="close-btn" onclick="_kigClose()">✕</button>
      </div>
      <div style="display:flex;flex:1;min-height:0;">
        <div class="kiscan-doc-pane" style="flex:0 0 40%;min-width:0;display:flex;flex-direction:column;border-right:1px solid var(--border);background:#2b2b2b;">
          ${_kiScanDocPreviewHtml()}
        </div>
        <div class="modal-body" style="flex:1;min-width:0;overflow-y:auto;">
        ${hint ? `<div style="padding:8px 12px;background:#FFF8E1;border-radius:6px;font-size:.85rem;color:#5D4037;margin-bottom:10px;">${hint}</div>` : ''}
        ${warnBanner}
        ${_kiScanAbsenderHtml('glob')}
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;padding:8px 10px;background:var(--bg-light,#f5f7fa);border-radius:6px;">
          <span style="font-size:.82rem;font-weight:600;color:#555;">Belegpreise sind:</span>
          <select id="kigModus" class="form-input" style="padding:3px 8px;font-size:.82rem;width:auto;" onchange="_kigApplyMode()">
            <option value="netto" ${startModus==='netto'?'selected':''}>Netto (ohne MwSt)</option>
            <option value="brutto" ${startModus==='brutto'?'selected':''}>Brutto (inkl. MwSt)</option>
          </select>
          <label style="font-size:.82rem;color:#555;display:flex;align-items:center;gap:4px;">MwSt-Satz
            <input type="number" id="kigMwst" value="${satz}" min="0" max="100" step="0.1" style="width:62px;padding:3px 6px;font-size:.82rem;text-align:right;" onchange="_kigApplyMode()" oninput="_kigApplyMode()"> %
          </label>
          <span style="flex:1"></span>
          <span style="font-size:.75rem;color:#999;">EK/Preis wird stets als Netto gespeichert · manuell ergänzte Zeilen bleiben unverändert</span>
        </div>
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px;padding:8px 10px;background:#EAF4FF;border:1px solid #B3D8FF;border-radius:6px;">
          <span style="font-size:.82rem;font-weight:600;color:#0B5394;">Für alle Positionen:</span>
          <input type="text" id="kigAllBs" list="kigBsList" placeholder="Baustelle suchen…" class="form-input" style="padding:3px 8px;font-size:.82rem;min-width:200px;">
          <select id="kigAllTyp" class="form-input" style="padding:3px 8px;font-size:.82rem;width:auto;">
            <option value="">— Zuweisung —</option>
            <option value="material">Material</option>
            <option value="arbeitszeit">Arbeitszeit</option>
          </select>
          <button class="btn btn-secondary btn-sm" onclick="_kigApplyAll()">Übernehmen</button>
        </div>
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;font-size:.85rem;flex-wrap:wrap;">
          <a href="#" onclick="event.preventDefault();document.querySelectorAll('#kigTbody .kig-cb').forEach(c=>c.checked=true);_kigCalcTotals()">Alle</a>
          <a href="#" onclick="event.preventDefault();document.querySelectorAll('#kigTbody .kig-cb').forEach(c=>c.checked=false);_kigCalcTotals()">Keine</a>
          <button class="btn btn-secondary btn-sm" onclick="_kigAddRow()" style="padding:2px 10px;" title="Position manuell anlegen (z.B. falls nicht erkannt)">➕ Position hinzufügen</button>
          <span style="font-size:.75rem;color:#999;">Tipp: ➗ teilt eine Position anteilig auf mehrere Projekte auf.</span>
          <span style="flex:1"></span>
          <span id="kigSelCount" style="color:var(--text-muted)">${(items||[]).length} ausgewählt</span>
        </div>
        <div style="overflow-x:auto;">
          <table class="data-table" style="font-size:.85rem;width:100%">
            <thead><tr>
              <th style="width:32px;text-align:center;">✓</th>
              <th>Art.-Nr.</th>
              <th>Bezeichnung</th>
              <th style="text-align:right;">Menge</th>
              <th>Einheit</th>
              <th style="text-align:right;">EK netto (€)</th>
              <th style="text-align:right;">Gesamt netto (€)</th>
              <th>Baustelle</th>
              <th>Zuweisung</th>
              <th style="width:74px;"></th>
            </tr></thead>
            <tbody id="kigTbody">${rows}</tbody>
            <tfoot><tr>
              <td colspan="6" style="text-align:right;font-weight:700;padding:5px 6px;border-top:2px solid var(--border);">Gesamt netto (Auswahl):</td>
              <td id="kigTotal" style="text-align:right;font-weight:700;padding:5px 6px;border-top:2px solid var(--border);white-space:nowrap;">${initialTotal} €</td>
              <td colspan="3" style="border-top:2px solid var(--border);"></td>
            </tr></tfoot>
          </table>
        </div>
        <div style="display:flex;align-items:center;gap:8px;margin-top:14px;padding-top:10px;border-top:1px solid var(--border);flex-wrap:wrap;">
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;">
            <input type="checkbox" id="kigSaveAllCb" checked> Beleg bei <strong>allen zugewiesenen</strong> Baustellen ablegen
          </label>
          <span style="font-size:.82rem;color:#666;">in</span>
          <select id="kigFileCat" class="form-input" style="padding:3px 7px;font-size:.82rem;width:auto;">
            <option value="Eingangsbelege" selected>Eingangsbelege</option>
            <option value="Ausgangsbelege">Ausgangsbelege</option>
            <option value="Angebote">Angebote</option>
            <option value="Dateien">Dateien</option>
            <option value="Sonstiges">Sonstiges</option>
          </select>
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px;">
          <button class="btn btn-secondary" onclick="_kigClose()">Abbrechen</button>
          <button id="kigImportBtn" class="btn btn-primary" onclick="_kigImport()">${(items||[]).length} Position${(items||[]).length!==1?'en':''} zuweisen</button>
        </div>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
  _kiScanInitDocPreview();
  _kigCalcTotals();
}

// Baut eine Tabellenzeile für den globalen KI-Scan.
function _kigRowHtml(rid, d) {
  d = d || {};
  const q = (s) => String(s == null ? '' : s).replace(/"/g, '&quot;');
  const menge  = (d.menge != null ? d.menge : 1);
  const ek     = parseFloat(d.ek) || 0;
  const manual = d.manual ? 1 : 0;
  const rawEk  = (d.rawEk != null ? d.rawEk : ek);
  const gesamt = ((parseFloat(menge) || 0) * ek).toFixed(2);
  return `
    <tr data-rid="${rid}" data-raw-ek="${rawEk}"${manual ? ' data-manual="1"' : ''}>
      <td style="text-align:center;"><input type="checkbox" class="kig-cb" checked onchange="_kigCalcTotals()"></td>
      <td><input type="text" class="form-control kig-artnr" value="${q(d.artnr)}" style="width:80px;font-size:.82rem;padding:3px 6px;" placeholder="—"></td>
      <td><input type="text" class="form-control kig-bez" value="${q(d.bez)}" style="width:100%;min-width:160px;font-size:.85rem;padding:3px 6px;" placeholder="Bezeichnung"></td>
      <td><input type="number" class="form-control kig-menge" value="${menge}" min="0" step="any" style="width:60px;font-size:.85rem;padding:3px 6px;text-align:right;" oninput="_kigCalcTotals()"></td>
      <td><input type="text" class="form-control kig-einheit" value="${q(d.einheit || 'Stk.')}" style="width:55px;font-size:.85rem;padding:3px 6px;"></td>
      <td><input type="number" class="form-control kig-ek" value="${ek.toFixed(2)}" min="0" step="0.01" style="width:80px;font-size:.85rem;padding:3px 6px;text-align:right;" oninput="_kigCalcTotals()"></td>
      <td class="kig-gesamt" style="text-align:right;font-weight:600;padding:3px 6px;white-space:nowrap;">${gesamt}</td>
      <td><input type="text" class="form-control kig-bs" list="kigBsList" value="${q(d.baustelle)}" placeholder="Baustelle suchen…" style="width:100%;min-width:170px;font-size:.85rem;padding:3px 6px;"></td>
      <td><select class="form-control kig-typ" style="width:120px;font-size:.85rem;padding:3px 6px;">
            <option value="material"${d.typ !== 'arbeitszeit' ? ' selected' : ''}>Material</option>
            <option value="arbeitszeit"${d.typ === 'arbeitszeit' ? ' selected' : ''}>Arbeitszeit</option>
          </select></td>
      <td style="white-space:nowrap;text-align:center;">
        <button type="button" class="btn btn-sm" title="Position splitten (anteilig auf mehrere Projekte)" onclick="_kigSplitRow(this)" style="padding:2px 6px;background:#EAF4FF;border:1px solid #B3D8FF;color:#0B5394;">➗</button>
        <button type="button" class="btn btn-sm" title="Zeile entfernen" onclick="_kigDelRow(this)" style="padding:2px 6px;background:#FFEBEE;border:1px solid #EF9A9A;color:#B71C1C;">✕</button>
      </td>
    </tr>`;
}

// Liest die Werte einer Zeile aus.
function _kigReadRow(tr) {
  return {
    artnr:     tr.querySelector('.kig-artnr')?.value || '',
    bez:       tr.querySelector('.kig-bez')?.value || '',
    menge:     parseFloat(tr.querySelector('.kig-menge')?.value) || 0,
    einheit:   tr.querySelector('.kig-einheit')?.value || 'Stk.',
    ek:        parseFloat(tr.querySelector('.kig-ek')?.value) || 0,
    typ:       tr.querySelector('.kig-typ')?.value || 'material',
    baustelle: tr.querySelector('.kig-bs')?.value || '',
    manual:    tr.dataset.manual === '1',
    rawEk:     parseFloat(tr.getAttribute('data-raw-ek')) || 0,
  };
}

// Neue, leere Position anlegen (z.B. falls nicht erkannt).
function _kigAddRow() {
  const tb = document.getElementById('kigTbody');
  if (!tb) return;
  tb.insertAdjacentHTML('beforeend', _kigRowHtml(++window._kigRid, { artnr: '', bez: '', menge: 1, einheit: 'Stk.', ek: 0, typ: 'material', baustelle: '', manual: true, rawEk: 0 }));
  _kigCalcTotals();
  tb.lastElementChild?.querySelector('.kig-bez')?.focus();
}

// Zeile entfernen.
function _kigDelRow(btn) {
  btn.closest('tr')?.remove();
  _kigCalcTotals();
}

// Position anteilig aufteilen: kopiert die Zeile (Menge 0, ohne Baustelle),
// sodass Teilmengen verschiedenen Projekten zugewiesen werden können.
function _kigSplitRow(btn) {
  const tr = btn.closest('tr');
  if (!tr) return;
  const d = _kigReadRow(tr);
  const html = _kigRowHtml(++window._kigRid, { ...d, menge: 0, baustelle: '' });
  tr.insertAdjacentHTML('afterend', html);
  _kigCalcTotals();
  tr.nextElementSibling?.querySelector('.kig-bs')?.focus();
}

function _kigResolveBs(str) {
  if (!str) return null;
  const id = window._kigBsMap?.[str.trim().toLowerCase()];
  return (id != null) ? (appData.baustellen || []).find(b => b.id === id) : null;
}

function _kigApplyMode() {
  const modus = document.getElementById('kigModus')?.value || 'netto';
  const satz  = parseFloat(document.getElementById('kigMwst')?.value) || 0;
  document.querySelectorAll('#kigTbody tr').forEach(tr => {
    if (tr.dataset.manual === '1') return; // manuell ergänzte Zeilen nicht umrechnen
    const rawEk = parseFloat(tr.getAttribute('data-raw-ek')) || 0;
    const netEk = (modus === 'brutto' && satz > 0) ? rawEk / (1 + satz / 100) : rawEk;
    const ekInput = tr.querySelector('.kig-ek');
    if (ekInput) ekInput.value = netEk.toFixed(2);
  });
  _kigCalcTotals();
}

function _kigCalcTotals() {
  let total = 0, count = 0;
  document.querySelectorAll('#kigTbody tr').forEach(tr => {
    const menge = parseFloat(tr.querySelector('.kig-menge')?.value) || 0;
    const ek    = parseFloat(tr.querySelector('.kig-ek')?.value) || 0;
    const pos = menge * ek;
    const cell = tr.querySelector('.kig-gesamt');
    if (cell) cell.textContent = pos.toFixed(2);
    if (tr.querySelector('.kig-cb')?.checked) { total += pos; count++; }
  });
  const el = document.getElementById('kigTotal');
  if (el) el.textContent = total.toFixed(2) + ' €';
  const cnt = document.getElementById('kigSelCount');
  if (cnt) cnt.textContent = count + ' ausgewählt';
  const btn = document.getElementById('kigImportBtn');
  if (btn) btn.textContent = count + ' Position' + (count !== 1 ? 'en' : '') + ' zuweisen';
}

function _kigApplyAll() {
  const bs  = document.getElementById('kigAllBs')?.value || '';
  const typ = document.getElementById('kigAllTyp')?.value || '';
  document.querySelectorAll('#kigTbody tr').forEach(tr => {
    if (bs)  { const el = tr.querySelector('.kig-bs');  if (el) el.value = bs; }
    if (typ) { const el = tr.querySelector('.kig-typ'); if (el) el.value = typ; }
  });
}

async function _kigImport() {
  const rows = Array.from(document.querySelectorAll('#kigTbody tr')).filter(tr => tr.querySelector('.kig-cb')?.checked);
  if (rows.length === 0) { showNotification('Keine Positionen ausgewählt.'); return; }
  const today = new Date().toISOString().split('T')[0];
  const errors = [];
  const touched = new Set();
  const touchedBs = [];
  let matCount = 0, azCount = 0;

  rows.forEach(tr => {
    const d = _kigReadRow(tr);
    const bez = d.bez.trim();
    if (!bez) return;
    if (!(d.menge > 0)) { errors.push(`„${bez}": Menge 0`); return; }
    const bs = _kigResolveBs(d.baustelle);
    if (!bs) { errors.push(`„${bez}": keine gültige Baustelle`); return; }
    if (d.typ === 'arbeitszeit') {
      if (!canDo('canEditArbeitszeit')) { errors.push(`„${bez}": keine Berechtigung für Arbeitszeit`); return; }
      if (!bs.arbeitszeit) bs.arbeitszeit = [];
      if (!bs.nextAzId) bs.nextAzId = 1;
      bs.arbeitszeit.unshift({ id: bs.nextAzId++, beschreibung: bez, datum: today, stunden: d.menge, stundenpreis: d.ek || 0, fixkosten: 0, erstelltVon: currentKuerzel });
      azCount++;
    } else {
      if (!canDo('canEditMaterial')) { errors.push(`„${bez}": keine Berechtigung für Material`); return; }
      if (!bs.material) bs.material = [];
      if (!bs.nextMatId) bs.nextMatId = 1;
      bs.material.unshift({ id: bs.nextMatId++, bezeichnung: bez, artikelnr: d.artnr.trim(), anzahl: d.menge, einheit: d.einheit || 'Stk.', ek: d.ek || 0, aufschlag: 0, kategorieId: null, erstelltVon: currentKuerzel, datum: today });
      matCount++;
    }
    if (!touched.has(bs.id)) { touched.add(bs.id); touchedBs.push(bs); }
  });

  if (matCount + azCount === 0) { showNotification(errors[0] || 'Nichts importiert.', 'error'); return; }
  saveData();

  // Originaldokument optional bei ALLEN zugewiesenen Baustellen ablegen
  const saveAll = document.getElementById('kigSaveAllCb');
  if (saveAll && saveAll.checked && window._kiScanPendingFile && touchedBs.length) {
    const cat = document.getElementById('kigFileCat')?.value || 'Eingangsbelege';
    for (const bs of touchedBs) {
      const fd = new FormData();
      fd.append('file', window._kiScanPendingFile);
      fd.append('baustelleId', bs.id);
      fd.append('category', cat);
      try { await fetch('api.php?action=upload_file', { method: 'POST', body: fd }); } catch(_) {}
    }
    const cur0 = getBaustelle();
    if (cur0 && touched.has(cur0.id) && typeof loadBaustelleFiles === 'function') loadBaustelleFiles();
  }

  // Aktuell geöffnete Baustelle betroffen → Ansicht aktualisieren
  const cur = getBaustelle();
  if (cur && touched.has(cur.id)) {
    openMatCategory('__none__', cur);
    renderMatRows();
    if (typeof renderAzRows === 'function') renderAzRows();
    recalc();
  }

  document.getElementById('kiScanGlobalOverlay') && _kigClose();
  let msg = `${matCount + azCount} Position(en) zugewiesen (${matCount} Material`;
  msg += azCount ? `, ${azCount} Arbeitszeit)` : ')';
  msg += ` in ${touched.size} Baustelle(n).`;
  if (saveAll && saveAll.checked && window._kiScanPendingFile && touched.size) msg += ` Beleg in ${touched.size} Projekt(en) abgelegt.`;
  if (errors.length) msg += ` ${errors.length} übersprungen.`;
  showNotification(msg + ' ✓', errors.length ? 'warning' : 'success');
}

// Material aus Lagerbestand entnehmen → in Projektmaterial einfügen.
async function addMatRowFromLager() {
  const b = getBaustelle();
  if (!b) return;
  if (!window.lagerModul) { alert('Lager-Modul nicht geladen.'); return; }
  const r = await window.lagerModul.pickAndConsumeForProject({ baustelleId: b.id, baustelleName: b.name });
  if (!r) return;
  b.material.unshift({
    id: b.nextMatId++,
    bezeichnung: r.bezeichnung + (r.artikelnr ? ' (Art. ' + r.artikelnr + ')' : ''),
    anzahl: r.menge,
    einheit: r.einheit || 'Stk.',
    ek: r.ek_preis || 0,
    aufschlag: 0,
    kategorieId: null,
    erstelltVon: currentKuerzel,
    datum: new Date().toISOString().split('T')[0],
    quelleLagerArtikelId: r.artikelId,
  });
  openMatCategory('__none__', b);
  saveData();
  renderMatRows();
  recalc();
}

// Aufmaß-Liste aus Projektkontext öffnen (vorgefilterte Baustelle).
function openAufmassFromProject() {
  const b = getBaustelle();
  if (!b) return;
  if (typeof window.showAufmassForBaustelle === 'function') {
    window.showAufmassForBaustelle(b.id);
  } else if (typeof window.showAufmass === 'function') {
    window.showAufmass();
  } else {
    alert('Aufmaß-Modul wird noch geladen, bitte erneut versuchen.');
  }
}

function delMatRow(id) {
  const b = getBaustelle();
  if (!b) return;
  const idx = (b.material || []).findIndex(r => r.id === id);
  if (idx < 0) return;
  b.material.splice(idx, 1);
  saveData();
  renderMatRows();
  recalc();
}

function setMat(id, field, val) {
  const b = getBaustelle();
  if (!b) return;
  const r = b.material.find(r => r.id === id);
  if (!r) return;
  r[field] = ['anzahl','ek','aufschlag','rabatt'].includes(field) ? (parseFloat(val) || 0) : val;
  saveDataDebounced();
  // live update calculated cells
  const vk = matVk(r, b);
  setCell(`vk_${id}`,  fmt(vk));
  setCell(`mg_${id}`,  fmt(vk * r.anzahl));
  const filter = document.getElementById('matFilterInput');
  if (filter && filter.value.trim()) filterMatRows(filter.value);
  else updateMatFilterSummary(b);
  recalc();
}

function setMatAufschlagGlobal(val) {
  const b = getBaustelle();
  if (!b) return;
  b.materialAufschlagGlobal = parseFloat(val) || 0;
  saveDataDebounced();
  renderMatRows();
  recalc();
}

// -- Material-Tabelle filtern ---------------------------------
function filterMatRows(q) {
  const terms = q.trim().toLowerCase().split(/\s+/).filter(t => t);
  const b = getBaustelle();
  if (terms.length === 0) { renderMatRows(); return; }
  // If filter active but collapsed categories hide rows from DOM, re-render to expand all
  if (terms.length > 0) {
    if (b) {
      const renderedRows = document.querySelectorAll('#matBody tr.mat-data-row').length;
      if (renderedRows < b.material.length) { renderMatRows(); return; }
    }
  }
  const rows = document.querySelectorAll('#matBody tr.mat-data-row');
  rows.forEach(tr => {
    if (terms.length === 0) { tr.style.display = ''; return; }
    // Collect text from textContent AND input/select values (input.value is not in textContent)
    let text = tr.textContent.toLowerCase();
    tr.querySelectorAll('input, select').forEach(el => { text += ' ' + (el.value || '').toLowerCase(); });
    tr.style.display = terms.every(t => text.includes(t)) ? '' : 'none';
  });
  // Also show/hide category headers based on visible rows
  const catHeaders = document.querySelectorAll('#matBody tr.mat-cat-header');
  catHeaders.forEach(hdr => {
    if (terms.length === 0) { hdr.style.display = ''; return; }
    let next = hdr.nextElementSibling;
    let hasVisible = false;
    while (next && !next.classList.contains('mat-cat-header')) {
      if (next.classList.contains('mat-data-row') && next.style.display !== 'none') hasVisible = true;
      next = next.nextElementSibling;
    }
    hdr.style.display = hasVisible ? '' : 'none';
  });
  updateMatFilterSummary(b);
}

let _collapsedMatCats = new Set();
let _collapsedMatCatsBaustelleId = null;
function loadMatCategoryState(b) {
  if (_collapsedMatCatsBaustelleId === b.id) return _collapsedMatCats;
  let saved = [];
  try { saved = JSON.parse(localStorage.getItem(`matCollapsedCats_${b.id}`) || '[]'); } catch (e) {}
  _collapsedMatCats = new Set(Array.isArray(saved) ? saved.filter(key => typeof key === 'string') : []);
  _collapsedMatCatsBaustelleId = b.id;
  return _collapsedMatCats;
}

function saveMatCategoryState(b) {
  try { localStorage.setItem(`matCollapsedCats_${b.id}`, JSON.stringify([..._collapsedMatCats])); } catch (e) {}
}

function updateMatGroupControls(b) {
  const button = document.getElementById('matToggleAllBtn');
  if (!button) return;
  loadMatCategoryState(b);
  const keys = (b.matKategorien || []).map(category => String(category.id));
  if (keys.length) keys.unshift('__none__');
  button.textContent = keys.some(key => !_collapsedMatCats.has(key)) ? 'Alle zu' : 'Alle auf';
}

function updateMatFilterSummary(b = getBaustelle()) {
  const summary = document.getElementById('matFilterSummary');
  if (!summary || !b) return;
  const all = b.material || [];
  const active = !!document.getElementById('matFilterInput')?.value.trim();
  const visibleIds = active
    ? new Set([...document.querySelectorAll('#matBody tr.mat-data-row')]
      .filter(row => row.style.display !== 'none').map(row => row.dataset.itemId))
    : null;
  const matching = active ? all.filter(row => visibleIds.has(String(row.id))) : all;
  let text = `${matching.length} von ${all.length} Positionen`;
  if (canDo('canSeePrices')) {
    const total = matching.reduce((sum, row) => sum + matVk(row, b) * (Number(row.anzahl) || 0), 0);
    text += ` · Summe: ${fmt(total)}`;
  }
  summary.textContent = text;
}

function openMatCategory(catKey, b = getBaustelle()) {
  if (!b) return;
  loadMatCategoryState(b).delete(catKey);
  saveMatCategoryState(b);
}

function toggleAllMatCategories() {
  const b = getBaustelle();
  if (!b) return;
  loadMatCategoryState(b);
  const keys = (b.matKategorien || []).map(category => String(category.id));
  if (!keys.length) return;
  keys.unshift('__none__');
  if (keys.some(key => !_collapsedMatCats.has(key))) keys.forEach(key => _collapsedMatCats.add(key));
  else keys.forEach(key => _collapsedMatCats.delete(key));
  saveMatCategoryState(b);
  renderMatRows();
}

function toggleMatCategory(catKey) {
  const b = getBaustelle();
  if (!b) return;
  loadMatCategoryState(b);
  if (_collapsedMatCats.has(catKey)) {
    _collapsedMatCats.delete(catKey);
  } else {
    _collapsedMatCats.add(catKey);
  }
  saveMatCategoryState(b);
  renderMatRows();
}

function renderMatRows() {
  const b = getBaustelle();
  if (!b) return;
  loadMatCategoryState(b);
  const tbody = document.getElementById('matBody');
  if (!tbody) return;
  tbody.innerHTML = '';

  const kategorien  = b.matKategorien || [];
  const colCount    = 9;

  function calcCatTotal(catId) {
    return b.material
      .filter(r => (r.kategorieId || null) === (catId || null))
      .reduce((s, r) => s + matVk(r, b) * r.anzahl, 0);
  }

  function renderCatHeader(catId, catName) {
    const total = calcCatTotal(catId);
    const catKey = catId === null ? '__none__' : String(catId);
    const isCollapsed = _collapsedMatCats.has(catKey);
    const itemCount = b.material.filter(r => (r.kategorieId || null) === (catId || null)).length;
    const tr  = document.createElement('tr');
    tr.className = 'mat-cat-header';
    tr.addEventListener('dragover',  e  => { e.preventDefault(); tr.classList.add('drag-over'); });
    tr.addEventListener('dragleave', () => tr.classList.remove('drag-over'));
    tr.addEventListener('drop',      e  => { e.preventDefault(); tr.classList.remove('drag-over'); matDrop(catId); });
    const actions = catId !== null
      ? `<div class="mat-cat-actions">
           <button class="icon-btn" onclick="renameMatKategorie(${catId})" title="Umbenennen">${ico('edit')}</button>
           <button class="icon-btn danger" onclick="delMatKategorie(${catId})" title="Löschen">${ico('trash')}</button>
         </div>`
      : '';
    tr.innerHTML = `
      <td colspan="${colCount}" class="mat-cat-cell">
        <div class="mat-cat-inner" style="cursor:pointer;" onclick="toggleMatCategory('${catKey}')">
          <span class="mat-cat-chevron" style="font-size:.75rem;margin-right:4px;transition:transform .2s;display:inline-block;${isCollapsed ? 'transform:rotate(-90deg);' : ''}">▾</span>
          <span class="mat-cat-icon">${ico('folder')}</span>
          <span class="mat-cat-name">${esc(catName)}</span>
          <span style="font-size:.72rem;color:var(--grey-400);margin-left:4px;">(${itemCount})</span>
          <span class="mat-cat-total price-sensitive">${fmt(total)}</span>
          ${actions}
        </div>
      </td>`;
    tbody.appendChild(tr);
    return isCollapsed;
  }

  function renderMatRow(r) {
    const ga = b.materialAufschlagGlobal || 0;
    const vk = matVk(r, b);
    const tr = document.createElement('tr');
    tr.className  = 'mat-data-row';
    tr.dataset.itemId = String(r.id);
    tr.draggable  = true;
    tr.addEventListener('dragstart', e => {
      dragMatId = r.id;
      _posDrag = { srcBaustelleId: b.id, category: 'material', itemId: r.id };
      e.dataTransfer.effectAllowed = 'move';
      setTimeout(() => tr.classList.add('mat-row-dragging'), 0);
    });
    tr.addEventListener('dragend', () => { tr.classList.remove('mat-row-dragging'); _posDrag = null; document.querySelectorAll('.dnd-pos-over').forEach(el => el.classList.remove('dnd-pos-over')); });
    const gaBadge = ga > 0 ? `<span class="ga-badge" title="Globaler Aufschlag ${ga}%">+${ga}%</span>` : '';
    tr.innerHTML = `
      <td><input class="cell-input" value="${esc(r.bezeichnung)}"
            oninput="setMat(${r.id},'bezeichnung',this.value)" placeholder="Bezeichnung">${r.erstelltVon ? `<span class="creator-badge">${esc(r.erstelltVon)}</span>` : ''}</td>
      <td><input class="cell-input text-right" type="number" value="${r.anzahl}" step="0.01"
            oninput="setMat(${r.id},'anzahl',this.value)"></td>
      <td>${einheitSelect(r.id, r.einheit)}</td>
      <td class="col-ek"><input class="cell-input text-right" type="number" value="${r.ek}" step="0.01"
            oninput="setMat(${r.id},'ek',this.value)"></td>
      <td class="col-aufschlag"><input class="cell-input text-right" type="number" value="${r.aufschlag}" min="0" step="0.1"
            oninput="setMat(${r.id},'aufschlag',this.value)">${gaBadge}</td>
      <td class="col-aufschlag"><input class="cell-input text-right" type="number" value="${r.rabatt || 0}" min="0" max="100" step="0.1"
            oninput="setMat(${r.id},'rabatt',this.value)"${r.vkDirekt ? ' title="VK direkt (Listenpreis ohne Aufschlag)"' : ''}></td>
      <td id="vk_${r.id}" class="calc-cell price-sensitive">${fmt(vk)}${r.vkDirekt ? '<span class="ga-badge" title="VK direkt – kein Aufschlag">VK</span>' : ''}</td>
      <td id="mg_${r.id}" class="calc-cell price-sensitive">${fmt(vk * r.anzahl)}</td>
      <td class="row-actions">
        <button class="icon-btn" id="savebtn_${r.id}" onclick="saveMatRowToKatalog(${r.id})" title="In Katalog speichern">${ico('save')}</button>
        <button class="icon-btn" onclick="archiveMatRow(${r.id})" title="Position archivieren">${ico('box')}</button>
        <button class="icon-btn danger" onclick="delMatRow(${r.id})">${ico('trash')}</button>
      </td>`;
    tbody.appendChild(tr);
  }

  // Check if filter is active ? force-expand all categories so rows are in DOM
  const filterInput = document.getElementById('matFilterInput');
  const activeFilter = filterInput && filterInput.value.trim();

  // -- Uncategorized section --
  const uncategorized = b.material.filter(r => !r.kategorieId);
  if (kategorien.length > 0) {
    const collapsed = renderCatHeader(null, 'Ohne Kategorie');
    if (!collapsed || activeFilter) uncategorized.forEach(r => renderMatRow(r));
  } else {
    uncategorized.forEach(r => renderMatRow(r));
  }

  // -- Each category --
  kategorien.forEach(kat => {
    const collapsed = renderCatHeader(kat.id, kat.name);
    if (!collapsed || activeFilter) b.material.filter(r => r.kategorieId === kat.id).forEach(r => renderMatRow(r));
  });

  // Re-apply filter if active
  if (activeFilter) filterMatRows(activeFilter);
  updateMatGroupControls(b);
  updateMatFilterSummary(b);
}

// -- Material category management ----------------------------
function addMatKategorie() {
  const b = getBaustelle();
  if (!b) return;
  if (!b.matKategorien)  b.matKategorien  = [];
  if (!b.nextMatKatId)   b.nextMatKatId   = 1;
  const name = prompt('Name der neuen Kategorie:', `Kategorie ${b.matKategorien.length + 1}`);
  if (!name || !name.trim()) return;
  b.matKategorien.push({ id: b.nextMatKatId++, name: name.trim() });
  saveData();
  renderMatRows();
  recalc();
}

function delMatKategorie(katId) {
  const b = getBaustelle();
  if (!b) return;
  confirmDelete('Kategorie löschen? Positionen werden in "Ohne Kategorie" verschoben.', () => {
    b.matKategorien = (b.matKategorien || []).filter(k => k.id !== katId);
    b.material.forEach(r => { if (r.kategorieId === katId) r.kategorieId = null; });
    saveData();
    renderMatRows();
    recalc();
  });
}

function renameMatKategorie(katId) {
  const b = getBaustelle();
  if (!b) return;
  const kat = (b.matKategorien || []).find(k => k.id === katId);
  if (!kat) return;
  const name = prompt('Neuer Name:', kat.name);
  if (!name || !name.trim()) return;
  kat.name = name.trim();
  saveData();
  renderMatRows();
}

function matDrop(catId) {
  if (dragMatId === null) return;
  const b = getBaustelle();
  if (!b) return;
  const r = b.material.find(r => r.id === dragMatId);
  if (r) { r.kategorieId = catId || null; saveData(); renderMatRows(); recalc(); }
  dragMatId = null;
}

function einheitSelect(id, current) {
  const units = ['Stk.','m','m²','m²','kg','t','l','lfm','VE','Pkt.','Psch.','h'];
  const opts = units.map(u => `<option${u === current ? ' selected' : ''}>${u}</option>`).join('');
  return `<select class="cell-select" onchange="setMat(${id},'einheit',this.value)">${opts}</select>`;
}

// ============================================================
// ARBEITSZEIT
// ============================================================
function addAzRow() {
  const b = getBaustelle();
  if (!b) return;
  b.arbeitszeit.unshift({ id: b.nextAzId++, beschreibung: '', datum: new Date().toISOString().split('T')[0], stunden: 0, stundenpreis: 0, fixkosten: 0, erstelltVon: currentKuerzel });
  saveData();
  renderAzRows();
  recalc();
}

function delAzRow(id) {
  const b = getBaustelle();
  if (!b) return;
  const idx = (b.arbeitszeit || []).findIndex(x => x.id === id);
  if (idx < 0) return;
  const r = b.arbeitszeit[idx];
  if (r && r.autoImport) _blockAzImport(b, r);
  b.arbeitszeit.splice(idx, 1);
  saveData();
  renderAzRows();
  recalc();
}

function setAz(id, field, val) {
  const b = getBaustelle();
  if (!b) return;
  const r = b.arbeitszeit.find(r => r.id === id);
  if (!r) return;
  if (field === 'unproduktiv') {
    r[field] = !!val;
  } else {
    r[field] = ['stunden','stundenpreis'].includes(field) ? (parseFloat(val) || 0) : val;
  }
  saveDataDebounced();
  setCell(`azg_${id}`, fmt((r.stunden || 0) * (r.stundenpreis || 0)));
  const groupMode = getAzGroupState(b).mode;
  if (field === 'datum' && groupMode === 'month') renderAzRows();
  else if (['stunden', 'stundenpreis'].includes(field)) updateAzGroupTotals(b, groupMode);
  const filter = document.getElementById('azFilterInput');
  if (filter && filter.value.trim()) filterAzRows(filter.value);
  else updateAzFilterSummary(b);
  recalc();
}

function getAzGroupState(b) {
  const state = { mode: 'month', collapsed: { month: [], employee: [] }, expanded: { month: [], employee: [] } };
  try {
    const saved = JSON.parse(localStorage.getItem(`azGroupState_${b.id}`) || 'null');
    if (!saved || typeof saved !== 'object') return state;
    if (['month', 'employee', 'none'].includes(saved.mode)) state.mode = saved.mode;
    ['month', 'employee'].forEach(mode => {
      if (saved.collapsed && Array.isArray(saved.collapsed[mode])) state.collapsed[mode] = saved.collapsed[mode].filter(key => typeof key === 'string');
      if (saved.expanded && Array.isArray(saved.expanded[mode])) state.expanded[mode] = saved.expanded[mode].filter(key => typeof key === 'string');
    });
  } catch (e) {}
  return state;
}

function saveAzGroupState(b, state) {
  try { localStorage.setItem(`azGroupState_${b.id}`, JSON.stringify(state)); } catch (e) {}
}

function updateAzGroupControls(b) {
  const button = document.getElementById('azToggleAllBtn');
  if (!button) return;
  const state = getAzGroupState(b);
  const mode = state.mode;
  const keys = mode === 'none' ? [] : [...new Set((b.arbeitszeit || []).map(row => azGroupInfo(row, mode).key))];
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  button.hidden = keys.length === 0;
  button.textContent = keys.some(key => azGroupIsCollapsed(state, mode, key, currentMonth)) ? 'Alle auf' : 'Alle zu';
}

function toggleAllAzGroups() {
  const b = getBaustelle();
  if (!b) return;
  const state = getAzGroupState(b);
  const mode = state.mode;
  if (mode === 'none') return;
  const keys = [...new Set((b.arbeitszeit || []).map(row => azGroupInfo(row, mode).key))];
  if (!keys.length) return;
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  const hasCollapsed = keys.some(key => azGroupIsCollapsed(state, mode, key, currentMonth));
  state.collapsed[mode] = hasCollapsed ? [] : keys;
  state.expanded[mode] = hasCollapsed ? keys : [];
  saveAzGroupState(b, state);
  renderAzRows();
}

function setAzGroupMode(mode) {
  const b = getBaustelle();
  if (!b || !['month', 'employee', 'none'].includes(mode)) return;
  const state = getAzGroupState(b);
  state.mode = mode;
  saveAzGroupState(b, state);
  renderAzRows();
}

function azGroupInfo(row, mode) {
  if (mode === 'month') {
    const match = /^(\d{4})-(\d{2})/.exec(String(row.datum || ''));
    if (match && Number(match[2]) >= 1 && Number(match[2]) <= 12) {
      const year = Number(match[1]);
      const month = Number(match[2]);
      return {
        key: `date:${match[1]}-${match[2]}`,
        label: new Intl.DateTimeFormat('de-DE', { month: 'long', year: 'numeric' }).format(new Date(year, month - 1, 1))
      };
    }
    return { key: 'date:__none__', label: 'Ohne Datum' };
  }
  const employee = String(row.erstelltVon || row.zeitUser || '').trim();
  return { key: employee ? `employee:${employee}` : 'employee:__none__', label: employee || 'Ohne Mitarbeiter' };
}

function azGroupIsCollapsed(state, mode, key, currentMonth) {
  if (state.collapsed[mode].includes(key)) return true;
  if (state.expanded[mode].includes(key)) return false;
  return mode === 'month' && key !== `date:${currentMonth}`;
}

function toggleAzGroup(mode, key) {
  const b = getBaustelle();
  if (!b || !['month', 'employee'].includes(mode)) return;
  const state = getAzGroupState(b);
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  const wasCollapsed = azGroupIsCollapsed(state, mode, key, currentMonth);
  state.collapsed[mode] = state.collapsed[mode].filter(item => item !== key);
  state.expanded[mode] = state.expanded[mode].filter(item => item !== key);
  state[wasCollapsed ? 'expanded' : 'collapsed'][mode].push(key);
  saveAzGroupState(b, state);
  renderAzRows();
}

function updateAzGroupTotals(b, mode) {
  if (!['month', 'employee'].includes(mode)) return;
  document.querySelectorAll('#azBody tr.az-group-header').forEach(header => {
    const rows = b.arbeitszeit.filter(row => azGroupInfo(row, mode).key === header.dataset.groupKey);
    const hours = rows.reduce((sum, row) => sum + (Number(row.stunden) || 0), 0);
    const amount = rows.reduce((sum, row) => sum + (Number(row.stunden) || 0) * (Number(row.stundenpreis) || 0), 0);
    const count = header.querySelector('.az-group-count');
    const hoursLabel = header.querySelector('.az-group-hours');
    const price = header.querySelector('.az-group-price');
    if (count) count.textContent = `(${rows.length})`;
    if (hoursLabel) hoursLabel.textContent = `Σ ${hours.toLocaleString('de-DE', { maximumFractionDigits: 2 })} h`;
    if (price) price.textContent = fmt(amount);
  });
}

function renderAzRows() {
  const b = getBaustelle();
  if (!b) return;
  const tbody = document.getElementById('azBody');
  if (!tbody) return;
  const canEditAz = canDo('canEditArbeitszeit');
  tbody.innerHTML = '';
  // Sort by date descending (newest first)
  const sorted = [...b.arbeitszeit].sort((a, c) => (c.datum || '').localeCompare(a.datum || ''));
  const state = getAzGroupState(b);
  const mode = state.mode;
  const filterInput = document.getElementById('azFilterInput');
  const activeFilter = !!(filterInput && filterInput.value.trim());
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

  function renderAzRow(r, groupKey = '') {
    // Migration: stundenpreis aus stundenKatId nachfüllen wenn fehlt (z.B. alte Datensätze)
    if ((r.stundenpreis == null || r.stundenpreis === '') && r.stundenKatId) {
      const kat = (appData.stundenKatalog || []).find(k => k.id === r.stundenKatId);
      if (kat) { r.stundenpreis = kat.preis || 0; r.fixkosten = kat.fixkosten || 0; saveDataDebounced(); }
    }
    if (r.stundenpreis == null || r.stundenpreis === '') r.stundenpreis = 0;
    const gesamt = (r.stunden || 0) * (r.stundenpreis || 0);
    const tr = document.createElement('tr');
    tr.className = 'az-data-row';
    tr.dataset.groupKey = groupKey;
    tr.dataset.itemId = String(r.id);
    if (r.autoImport) tr.style.background = '#F1F8E9';
    if (canEditAz) {
      tr.draggable = true;
      tr.addEventListener('dragstart', e => {
        _posDrag = { srcBaustelleId: b.id, category: 'arbeitszeit', itemId: r.id };
        e.dataTransfer.effectAllowed = 'move';
        setTimeout(() => tr.classList.add('mat-row-dragging'), 0);
      });
      tr.addEventListener('dragend', () => { tr.classList.remove('mat-row-dragging'); _posDrag = null; document.querySelectorAll('.dnd-pos-over').forEach(el => el.classList.remove('dnd-pos-over')); });
    }
    tr.innerHTML = `
      <td><input class="cell-input" value="${esc(r.beschreibung)}"
            oninput="setAz(${r.id},'beschreibung',this.value)" placeholder="Beschreibung" ${canEditAz ? '' : 'disabled'}></td>
      <td>${(r.erstelltVon || r.zeitUser) ? `<span class="creator-badge">${esc(r.erstelltVon || r.zeitUser)}</span>` : '<span style="color:#bbb">—</span>'}${r.autoImport ? '<span style="background:#C8E6C9;color:#2E7D32;font-size:.65rem;padding:1px 5px;border-radius:3px;margin-left:4px;font-weight:600">Import</span>' : ''}</td>
      <td><input class="cell-input" type="date" value="${esc(r.datum || '')}"
            oninput="setAz(${r.id},'datum',this.value)" ${canEditAz ? '' : 'disabled'}></td>
      <td><input class="cell-input text-right" type="number" value="${r.stunden}" min="0" step="0.25"
            oninput="setAz(${r.id},'stunden',this.value)" ${canEditAz ? '' : 'disabled'}></td>
      <td>${stundenKategorieSelect(r.id, r.stundenKatId)}</td>
      <td class="price-sensitive"><input class="cell-input text-right" type="number" value="${r.stundenpreis || 0}" min="0" step="0.01"
            oninput="setAz(${r.id},'stundenpreis',this.value)" ${canEditAz ? '' : 'disabled'}></td>
      <td id="azg_${r.id}" class="calc-cell price-sensitive">${fmt(gesamt)}</td>
      <td style="text-align:center"><input type="checkbox" class="az-unp-cb" ${r.unproduktiv ? 'checked' : ''} onchange="setAz(${r.id},'unproduktiv',this.checked)" title="Unproduktiv" ${canEditAz ? '' : 'disabled'}></td>
      <td>${canEditAz ? `<button class="icon-btn" onclick="archiveAzRow(${r.id})" title="Position archivieren">${ico('box')}</button><button class="icon-btn danger" onclick="delAzRow(${r.id})">${ico('trash')}</button>` : ''}</td>`;
    tbody.appendChild(tr);
  }

  if (mode === 'none') {
    sorted.forEach(r => renderAzRow(r));
  } else {
    const groups = new Map();
    sorted.forEach(r => {
      const info = azGroupInfo(r, mode);
      if (!groups.has(info.key)) groups.set(info.key, { ...info, rows: [] });
      groups.get(info.key).rows.push(r);
    });
    groups.forEach(group => {
      const savedCollapsed = azGroupIsCollapsed(state, mode, group.key, currentMonth);
      const collapsed = savedCollapsed && !activeFilter;
      const hours = group.rows.reduce((sum, row) => sum + (Number(row.stunden) || 0), 0);
      const amount = group.rows.reduce((sum, row) => sum + (Number(row.stunden) || 0) * (Number(row.stundenpreis) || 0), 0);
      const header = document.createElement('tr');
      header.className = 'mat-cat-header az-group-header';
      header.dataset.groupKey = group.key;
      header.dataset.collapsed = savedCollapsed ? '1' : '0';
      const cell = document.createElement('td');
      cell.colSpan = 9;
      cell.className = 'mat-cat-cell';
      const inner = document.createElement('div');
      inner.className = 'mat-cat-inner';
      inner.style.cursor = 'pointer';
      inner.setAttribute('role', 'button');
      inner.tabIndex = 0;
      const chevron = document.createElement('span');
      chevron.className = 'mat-cat-chevron';
      chevron.style.cssText = 'font-size:.75rem;margin-right:4px;transition:transform .2s;display:inline-block;';
      chevron.textContent = '▾';
      if (collapsed) chevron.style.transform = 'rotate(-90deg)';
      const icon = document.createElement('span');
      icon.className = 'mat-cat-icon';
      icon.innerHTML = ico(mode === 'month' ? 'calendar' : 'users');
      const name = document.createElement('span');
      name.className = 'mat-cat-name';
      name.textContent = group.label;
      const count = document.createElement('span');
      count.className = 'az-group-count';
      count.style.cssText = 'font-size:.72rem;color:var(--grey-400);margin-left:4px;';
      count.textContent = `(${group.rows.length})`;
      const hoursLabel = document.createElement('span');
      hoursLabel.className = 'mat-cat-total az-group-hours';
      hoursLabel.textContent = `Σ ${hours.toLocaleString('de-DE', { maximumFractionDigits: 2 })} h`;
      inner.append(chevron, icon, name, count, hoursLabel);
      if (canDo('canSeePrices')) {
        const price = document.createElement('span');
        price.className = 'mat-cat-total az-group-price price-sensitive';
        price.textContent = fmt(amount);
        inner.appendChild(price);
      }
      const toggle = () => toggleAzGroup(mode, group.key);
      inner.addEventListener('click', toggle);
      inner.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(); }
      });
      cell.appendChild(inner);
      header.appendChild(cell);
      tbody.appendChild(header);
      if (!collapsed) group.rows.forEach(r => renderAzRow(r, group.key));
    });
  }
  // Aktiven Filter nach dem Neu-Rendern erneut anwenden
  const azF = document.getElementById('azFilterInput');
  if (azF && azF.value.trim()) filterAzRows(azF.value);
  updateAzGroupControls(b);
  updateAzFilterSummary(b);
}

// -- Arbeitszeit-Tabelle filtern ------------------------------
function filterAzRows(q) {
  const terms = (q || '').trim().toLowerCase().split(/\s+/).filter(t => t);
  const b = getBaustelle();
  const rows = document.querySelectorAll('#azBody tr.az-data-row');
  if (terms.length > 0 && b && rows.length < b.arbeitszeit.length) { renderAzRows(); return; }
  const headers = document.querySelectorAll('#azBody tr.az-group-header');
  if (terms.length === 0 && b && rows.length === b.arbeitszeit.length && [...headers].some(header => header.dataset.collapsed === '1')) {
    renderAzRows();
    return;
  }
  rows.forEach(tr => {
    if (terms.length === 0) { tr.style.display = ''; return; }
    let text = tr.textContent.toLowerCase();
    tr.querySelectorAll('input, select').forEach(el => { text += ' ' + (el.value || '').toLowerCase(); });
    tr.querySelectorAll('select').forEach(sel => { const o = sel.options[sel.selectedIndex]; if (o) text += ' ' + o.textContent.toLowerCase(); });
    tr.style.display = terms.every(t => text.includes(t)) ? '' : 'none';
  });
  headers.forEach(header => {
    if (terms.length === 0) { header.style.display = ''; return; }
    let next = header.nextElementSibling;
    let hasVisible = false;
    while (next && !next.classList.contains('az-group-header')) {
      if (next.classList.contains('az-data-row') && next.style.display !== 'none') hasVisible = true;
      next = next.nextElementSibling;
    }
    header.style.display = hasVisible ? '' : 'none';
  });
  updateAzFilterSummary(b);
}

function updateAzFilterSummary(b = getBaustelle()) {
  const summary = document.getElementById('azFilterSummary');
  if (!summary || !b) return;
  const all = b.arbeitszeit || [];
  const active = !!document.getElementById('azFilterInput')?.value.trim();
  const visibleIds = active
    ? new Set([...document.querySelectorAll('#azBody tr.az-data-row')]
      .filter(row => row.style.display !== 'none').map(row => row.dataset.itemId))
    : null;
  const matching = active ? all.filter(row => visibleIds.has(String(row.id))) : all;
  const hours = matching.reduce((sum, row) => sum + (Number(row.stunden) || 0), 0);
  let text = `${matching.length} von ${all.length} Positionen · Summe: ${hours.toLocaleString('de-DE', { maximumFractionDigits: 2 })} h`;
  if (canDo('canSeePrices')) {
    const amount = matching.reduce((sum, row) => sum + (Number(row.stunden) || 0) * (Number(row.stundenpreis) || 0), 0);
    text += ` · ${fmt(amount)}`;
  }
  summary.textContent = text;
}

function stundenKategorieSelect(azId, currentKatId) {
  const kat = appData.stundenKatalog || [];
  let opts = '<option value="">— wählen —</option>';
  kat.forEach(k => {
    opts += `<option value="${k.id}"${k.id === currentKatId ? ' selected' : ''}>${esc(k.kategorie)}${canDo('canSeePrices') ? ` (${fmt(k.preis)})` : ''}</option>`;
  });
  return `<select class="cell-select" onchange="setAzKategorie(${azId}, this.value)">${opts}</select>`;
}

function setAzKategorie(azId, katId) {
  const b = getBaustelle();
  if (!b) return;
  const r = b.arbeitszeit.find(r => r.id === azId);
  if (!r) return;
  const kid = parseInt(katId) || null;
  r.stundenKatId = kid;
  if (kid) {
    const k = (appData.stundenKatalog || []).find(k => k.id === kid);
    if (k) { r.stundenpreis = parseFloat(k.preis) || 0; r.fixkosten = parseFloat(k.fixkosten) || 0; }
    else    { r.stundenpreis = 0; r.fixkosten = 0; }
  } else {
    r.stundenpreis = 0; r.fixkosten = 0;
  }
  saveData();
  renderAzRows();
  recalc();
}

// ============================================================
// EINZELPOSITIONEN ARCHIVIEREN (Material / Arbeitszeit / Pauschalen)
// ============================================================
function _ensurePosArchiv(b) {
  if (!Array.isArray(b._posArchiv)) b._posArchiv = [];
  if (!b.nextPosArchivId) b.nextPosArchivId = 1;
}

// Sperr-Schlüssel einer auto-importierten Arbeitszeit-Position, damit sie nach dem
// Archivieren/Löschen NICHT erneut aus der Zeiterfassung gebucht wird (identisch
// zur serverseitigen Prüfung in ZeiterfassungActions::ensureProjectBooking).
function _azBookingKeys(pos) {
  if (!pos) return [];
  if (pos.zeitEntryId) return ['id:' + String(pos.zeitUser || '').toLowerCase() + ':' + pos.zeitEntryId];
  if (pos.erstelltVon) return ['fz:' + pos.erstelltVon + ':' + (pos.datum || '') + ':' + (Math.round((pos.stunden || 0) * 100) / 100)];
  return [];
}
function _blockAzImport(b, pos) {
  const keys = _azBookingKeys(pos);
  if (!keys.length) return;
  if (!Array.isArray(b.azImportBlocked)) b.azImportBlocked = [];
  keys.forEach(k => { if (!b.azImportBlocked.includes(k)) b.azImportBlocked.push(k); });
}
function _unblockAzImport(b, pos) {
  if (!Array.isArray(b.azImportBlocked)) return;
  const keys = _azBookingKeys(pos);
  b.azImportBlocked = b.azImportBlocked.filter(k => !keys.includes(k));
}

function archiveMatRow(id) {
  const b = getBaustelle(); if (!b) return;
  const idx = (b.material || []).findIndex(x => x.id === id); if (idx < 0) return;
  const r = b.material[idx];
  _ensurePosArchiv(b);
  b._posArchiv.unshift({ archId: b.nextPosArchivId++, kind: 'material', data: JSON.parse(JSON.stringify(r)), archiviertAm: new Date().toISOString().split('T')[0], archiviertVon: currentKuerzel });
  b.material.splice(idx, 1);
  saveData(); renderMatRows(); renderPosArchiv(); recalc();
  showNotification('Position archiviert.');
}
function archiveAzRow(id) {
  const b = getBaustelle(); if (!b) return;
  const idx = (b.arbeitszeit || []).findIndex(x => x.id === id); if (idx < 0) return;
  const r = b.arbeitszeit[idx];
  _ensurePosArchiv(b);
  b._posArchiv.unshift({ archId: b.nextPosArchivId++, kind: 'arbeitszeit', data: JSON.parse(JSON.stringify(r)), archiviertAm: new Date().toISOString().split('T')[0], archiviertVon: currentKuerzel });
  if (r.autoImport) _blockAzImport(b, r); // Zeiterfassung soll diese Position nicht erneut buchen
  b.arbeitszeit.splice(idx, 1);
  saveData(); renderAzRows(); renderPosArchiv(); recalc();
  showNotification('Position archiviert.');
}
function archivePauschaleRow(entryId) {
  const b = getBaustelle(); if (!b) return;
  const idx = (b.pauschalen || []).findIndex(x => x.entryId === entryId); if (idx < 0) return;
  const r = b.pauschalen[idx];
  _ensurePosArchiv(b);
  b._posArchiv.unshift({ archId: b.nextPosArchivId++, kind: 'pauschale', data: JSON.parse(JSON.stringify(r)), archiviertAm: new Date().toISOString().split('T')[0], archiviertVon: currentKuerzel });
  b.pauschalen.splice(idx, 1);
  saveData(); renderPauschalenCB(); renderPosArchiv(); recalc();
  showNotification('Position archiviert.');
}

function restorePosArchiv(archId) {
  const b = getBaustelle(); if (!b) return;
  _ensurePosArchiv(b);
  const idx = b._posArchiv.findIndex(a => a.archId === archId); if (idx < 0) return;
  const a = b._posArchiv[idx];
  const d = JSON.parse(JSON.stringify(a.data || {}));
  if (a.kind === 'material') {
    if (!Array.isArray(b.material)) b.material = [];
    if (!b.nextMatId) b.nextMatId = 1;
    d.id = b.nextMatId++;
    b.material.unshift(d);
  } else if (a.kind === 'arbeitszeit') {
    if (!Array.isArray(b.arbeitszeit)) b.arbeitszeit = [];
    if (!b.nextAzId) b.nextAzId = 1;
    _unblockAzImport(b, d); // Sperre aufheben – Position ist wieder aktiv
    d.id = b.nextAzId++;
    b.arbeitszeit.unshift(d);
  } else if (a.kind === 'pauschale') {
    if (!Array.isArray(b.pauschalen)) b.pauschalen = [];
    const maxE = b.pauschalen.reduce((m, x) => Math.max(m, x.entryId || 0), 0);
    d.entryId = maxE + 1;
    b.pauschalen.unshift(d);
  }
  b._posArchiv.splice(idx, 1);
  saveData(); renderMatRows(); renderAzRows(); renderPauschalenCB(); renderPosArchiv(); recalc();
  showNotification('Position wiederhergestellt.');
}
function deletePosArchiv(archId) {
  const b = getBaustelle(); if (!b) return;
  confirmDelete('Diese archivierte Position endgültig löschen?', () => {
    _ensurePosArchiv(b);
    b._posArchiv = b._posArchiv.filter(a => a.archId !== archId);
    saveData(); renderPosArchiv();
  });
}

function renderPosArchiv() {
  const b = getBaustelle(); if (!b) return;
  const body = document.getElementById('posArchivBody'); if (!body) return;
  const list = Array.isArray(b._posArchiv) ? b._posArchiv : [];
  const cnt = document.getElementById('posArchivCount');
  if (cnt) cnt.textContent = list.length ? '(' + list.length + ')' : '';
  if (!list.length) {
    body.innerHTML = '<p class="hint-text" style="padding:12px;text-align:center">Keine archivierten Positionen.</p>';
    return;
  }
  const kindLabel = { material: 'Material', arbeitszeit: 'Arbeitszeit', pauschale: 'Pauschale' };
  const canRestore = { material: canDo('canEditMaterial'), arbeitszeit: canDo('canEditArbeitszeit'), pauschale: canDo('canEditPauschalen') };
  body.innerHTML = list.map(a => {
    const d = a.data || {};
    let bez = '', detail = '';
    if (a.kind === 'material') { bez = d.bezeichnung || ''; detail = `${d.anzahl || 0} ${esc(d.einheit || '')} · EK ${fmt(d.ek || 0)}`; }
    else if (a.kind === 'arbeitszeit') { bez = d.beschreibung || ''; detail = `${d.stunden || 0} h · ${fmt(d.stundenpreis || 0)}/h`; }
    else if (a.kind === 'pauschale') { const p = (appData.pauschalen || []).find(p => p.id === d.id); bez = p ? p.name : ('#' + d.id); detail = `${d.anzahl || 1} × ${fmt(p ? p.preis : 0)}`; }
    const allow = !!canRestore[a.kind];
    return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border,#eee)">
      <div style="min-width:0">
        <span style="display:inline-block;font-size:.68rem;font-weight:700;padding:1px 6px;border-radius:3px;background:var(--grey-100,#eee);color:#555;margin-right:6px">${kindLabel[a.kind] || a.kind}</span>
        <strong>${esc(bez || '—')}</strong>
        <span class="price-sensitive" style="color:#888;font-size:.8rem"> · ${detail}</span>
        <div style="font-size:.72rem;color:#aaa">archiviert ${esc(a.archiviertAm || '')}${a.archiviertVon ? ' · ' + esc(a.archiviertVon) : ''}</div>
      </div>
      <div style="display:flex;gap:6px;white-space:nowrap">
        ${allow ? `<button class="btn btn-secondary btn-sm" onclick="restorePosArchiv(${a.archId})" title="Wiederherstellen">${ico('refresh')} Wiederherstellen</button>
        <button class="icon-btn danger" onclick="deletePosArchiv(${a.archId})" title="Endgültig löschen">${ico('trash')}</button>` : '<span style="font-size:.75rem;color:#bbb">nur Ansicht</span>'}
      </div>
    </div>`;
  }).join('');
}

// ============================================================
// PAUSCHALEN  -  Table rows (per Baustelle, multiple per day)
// ============================================================
function renderPauschalenCB() {
  const b = getBaustelle();
  if (!b) return;
  const tbody = document.getElementById('pauschalenBody');
  if (!tbody) return;
  const canEditP = canDo('canEditPauschalen');
  tbody.innerHTML = '';

  if (appData.pauschalen.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" class="hint-text" style="padding:12px;text-align:center">Noch keine Pauschalen vorhanden. Klicken Sie auf "Pauschalen verwalten", um Pauschalen anzulegen.</td></tr>';
    return;
  }

  if (b.pauschalen.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="padding:12px;text-align:center;color:#999;font-size:.82rem">Keine Pauschalen eingetragen. Klicken Sie auf "+ Pauschale hinzufügen".</td></tr>';
    return;
  }

  // Sort by date descending
  const sorted = [...b.pauschalen].sort((a, c) => (c.datum || '').localeCompare(a.datum || ''));
  sorted.forEach(entry => {
    const p = appData.pauschalen.find(p => p.id === entry.id);
    if (!p) return;
    const gesamt = p.preis * (entry.anzahl || 1);
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${pauschaleSelect(entry.entryId, entry.id, canEditP)}</td>
      <td><input class="cell-input" type="date" value="${esc(entry.datum || '')}"
            oninput="setPauschaleField(${entry.entryId},'datum',this.value)" ${canEditP ? '' : 'disabled'}></td>
      <td><input class="cell-input text-right" type="number" value="${entry.anzahl || 1}" min="0" step="0.01"
            oninput="setPauschaleField(${entry.entryId},'anzahl',this.value)" ${canEditP ? '' : 'disabled'}></td>
      <td id="pe_${entry.entryId}" class="calc-cell price-sensitive">${fmt(p.preis)}</td>
      <td id="pg_${entry.entryId}" class="calc-cell price-sensitive">${fmt(gesamt)}</td>
      <td>${canEditP ? `<button class="icon-btn" onclick="archivePauschaleRow(${entry.entryId})" title="Position archivieren">${ico('box')}</button><button class="icon-btn danger" onclick="delPauschaleRow(${entry.entryId})">${ico('trash')}</button>` : ''}</td>`;
    tbody.appendChild(tr);
  });
}

function pauschaleSelect(entryId, currentPid, canEdit) {
  const catalog = appData.pauschalen || [];
  let opts = '<option value="">— wählen —</option>';
  catalog.forEach(p => {
    opts += `<option value="${p.id}"${p.id === currentPid ? ' selected' : ''}>${esc(p.name)}${canDo('canSeePrices') ? ` (${fmt(p.preis)})` : ''}</option>`;
  });
  return `<select class="cell-select" onchange="setPauschaleField(${entryId},'id',this.value)" ${canEdit ? '' : 'disabled'}>${opts}</select>`;
}

function addPauschaleRow() {
  if (!canDo('canEditPauschalen')) return;
  const b = getBaustelle();
  if (!b) return;
  if (!b.nextPauschaleEntryId) b.nextPauschaleEntryId = 1;
  const today = new Date().toISOString().split('T')[0];
  const firstP = (appData.pauschalen || [])[0];
  b.pauschalen.push({ entryId: b.nextPauschaleEntryId++, id: firstP ? firstP.id : 0, anzahl: 1, datum: today });
  saveData();
  renderPauschalenCB();
  recalc();
}

function delPauschaleRow(entryId) {
  if (!canDo('canEditPauschalen')) return;
  const b = getBaustelle();
  if (!b) return;
  const idx = (b.pauschalen || []).findIndex(e => e.entryId === entryId);
  if (idx < 0) return;
  b.pauschalen.splice(idx, 1);
  saveData();
  renderPauschalenCB();
  recalc();
}

function setPauschaleField(entryId, field, val) {
  if (!canDo('canEditPauschalen')) return;
  const b = getBaustelle();
  if (!b) return;
  const entry = b.pauschalen.find(e => e.entryId === entryId);
  if (!entry) return;
  if (field === 'id') {
    entry.id = parseInt(val) || 0;
  } else if (field === 'anzahl') {
    const f = parseFloat(String(val).replace(',', '.'));
    entry.anzahl = (isNaN(f) || f < 0) ? 0 : f;
  } else if (field === 'datum') {
    entry.datum = val || '';
  }
  saveDataDebounced();
  // Update inline cells (Einzelpreis + Gesamt) – wichtig bei Auswahl-Wechsel
  const p = appData.pauschalen.find(p => p.id === entry.id);
  const cellEinzel = document.getElementById(`pe_${entryId}`);
  if (cellEinzel && p) cellEinzel.textContent = fmt(p.preis);
  const cell = document.getElementById(`pg_${entryId}`);
  if (cell && p) cell.textContent = fmt(p.preis * (entry.anzahl || 1));
  recalc();
}

// ============================================================
// PAUSCHALEN MODAL  -  Catalog Management
// ============================================================
function openPauschalenModal() {
  renderPauschalenMgmt();
  show('pauschalenModal');
}

function closePauschalenModal() {
  hide('pauschalenModal');
  if (selectedId) {
    renderPauschalenCB();
    recalc();
  }
}

function closePauschalenModalOverlay(e) {
  if (e.target === e.currentTarget) closePauschalenModal();
}

function savePauschalenAndClose() {
  saveData();
  closePauschalenModal();
}

function renderPauschalenMgmt() {
  const tbody = document.getElementById('pauschalenMgmtBody');
  tbody.innerHTML = '';
  appData.pauschalen.forEach(p => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><input class="cell-input" value="${esc(p.name)}"
            oninput="setPauschale(${p.id},'name',this.value)" placeholder="Bezeichnung"></td>
      <td class="price-sensitive"><input class="cell-input text-right" type="number" value="${p.preis}" min="0" step="0.01"
            oninput="setPauschale(${p.id},'preis',this.value)"></td>
      <td><button class="icon-btn danger" onclick="delPauschale(${p.id})">${ico('trash')}</button></td>`;
    tbody.appendChild(tr);
  });
}

function addPauschaleCatalogRow() {
  if (!canDo('canEditPauschalen')) return;
  appData.pauschalen.push({ id: appData.nextPauschaleId++, name: '', preis: 0 });
  saveData();
  renderPauschalenMgmt();
}

function delPauschale(id) {
  if (!canDo('canEditPauschalen')) return;
  appData.pauschalen = appData.pauschalen.filter(p => p.id !== id);
  appData.baustellen.forEach(b => {
    b.pauschalen = b.pauschalen.filter(e => e.id !== id);
  });
  saveData();
  renderPauschalenMgmt();
}

function setPauschale(id, field, val) {
  if (!canDo('canEditPauschalen')) return;
  const p = appData.pauschalen.find(p => p.id === id);
  if (!p) return;
  p[field] = field === 'preis' ? (parseFloat(val) || 0) : val;
  saveDataDebounced();
}

// ============================================================
// ABSCHLAGSRECHNUNGEN
// ============================================================
function addAbschlagRow() {
  const b = getBaustelle();
  if (!b) return;
  if (!b.abschlaege) b.abschlaege = [];
  if (!b.nextAbschlagId) b.nextAbschlagId = 1;
  if (_hasSchlussrechnung(b) &&
      !confirm('Für diese Baustelle existiert bereits eine Schlussrechnung.\n\nTrotzdem einen weiteren Eintrag hinzufügen?')) {
    return;
  }
  b.abschlaege.push({ id: b.nextAbschlagId++, bezeichnung: '', betrag: 0, art: 'abschlag', erstelltVon: currentKuerzel });
  saveData();
  renderAbschlagRows();
  recalc();
}

// A.3: true, wenn mindestens ein Eintrag als Schlussrechnung markiert ist
function _hasSchlussrechnung(b) {
  return (b?.abschlaege || []).some(r => r.art === 'schluss');
}

function delAbschlagRow(id) {
  const b = getBaustelle();
  if (!b) return;
  const idx = (b.abschlaege || []).findIndex(r => r.id === id);
  if (idx < 0) return;
  b.abschlaege.splice(idx, 1);
  saveData();
  renderAbschlagRows();
  recalc();
}

function setAbschlag(id, field, val) {
  const b = getBaustelle();
  if (!b) return;
  const r = (b.abschlaege || []).find(r => r.id === id);
  if (!r) return;
  r[field] = field === 'betrag' ? (parseFloat(val) || 0) : val;
  saveData();
  if (field === 'art') renderAbschlagRows(); // Banner-Zustand aktualisieren
  recalc();
}

function renderAbschlagRows() {
  const b = getBaustelle();
  if (!b) return;
  const tbody = document.getElementById('abschlagBody');
  if (!tbody) return;
  tbody.innerHTML = '';
  // A.3: Warn-Banner, wenn eine Schlussrechnung existiert
  const banner = document.getElementById('abschlagWarnBanner');
  if (banner) {
    banner.innerHTML = _hasSchlussrechnung(b)
      ? `<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;margin-bottom:8px;background:#FFF3E0;border:1px solid #FFB74D;border-radius:6px;color:#E65100;font-size:.85rem;font-weight:600;">
           ⚠️ Für diese Baustelle ist eine <u>Schlussrechnung</u> gestellt. Weitere Änderungen an Abschlägen sollten nur mit Bedacht erfolgen.
         </div>`
      : '';
  }
  // Manual Abschlagsrechnungen
  (b.abschlaege || []).forEach(r => {
    const art = r.art === 'schluss' ? 'schluss' : 'abschlag';
    const tr = document.createElement('tr');
    if (art === 'schluss') tr.style.background = '#FFF8E1';
    tr.innerHTML = `
      <td><input class="cell-input" value="${esc(r.bezeichnung)}"
            oninput="setAbschlag(${r.id},'bezeichnung',this.value)" placeholder="z.B. Abschlagsrechnung Nr. 1">${r.erstelltVon ? `<span class="creator-badge">${esc(r.erstelltVon)}</span>` : ''}</td>
      <td>
        <select class="cell-select" onchange="setAbschlag(${r.id},'art',this.value)">
          <option value="abschlag"${art === 'abschlag' ? ' selected' : ''}>Abschlag</option>
          <option value="schluss"${art === 'schluss' ? ' selected' : ''}>Schlussrechnung</option>
        </select>
      </td>
      <td class="price-sensitive"><input class="cell-input text-right" type="number" value="${r.betrag}" min="0" step="0.01"
            oninput="setAbschlag(${r.id},'betrag',this.value)"></td>
      <td><button class="icon-btn danger" onclick="delAbschlagRow(${r.id})">${ico('trash')}</button></td>`;
    tbody.appendChild(tr);
  });
  // Linked Rechnungen (from rechnungenData)
  const linkedRe = (rechnungenData || []).filter(r => r.typ === 'rechnung' && r.baustelleId === b.id);
  linkedRe.forEach(re => {
    const brutto = rechnungBrutto(re);
    const isBezahlt = re.status === 'bezahlt';
    const tr = document.createElement('tr');
    tr.style.background = isBezahlt ? '#E8F5E9' : '#FFF3E0';
    tr.innerHTML = `
      <td>
        <span style="font-weight:600">${esc(re.nummer || '')}</span>
        ${re.kundeName ? ` - ${esc(re.kundeName)}` : ''}
        <span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:.7rem;font-weight:600;margin-left:6px;${isBezahlt ? 'background:#C8E6C9;color:#2E7D32' : 'background:#FFE0B2;color:#E65100'}">${isBezahlt ? 'bezahlt' : 'offen'}</span>
      </td>
      <td style="font-size:.75rem;color:var(--text-muted)">Rechnung</td>
      <td class="price-sensitive text-right" style="font-weight:600">${fmt(brutto)}</td>
      <td><button class="btn btn-secondary btn-sm" style="font-size:.7rem;padding:2px 6px" onclick="openRechnungForm('rechnung',${JSON.stringify(re.id).replace(/"/g,'&quot;')})">öffnen</button></td>`;
    tbody.appendChild(tr);
  });
}

// ============================================================
// VERKNÜPFTE ANGEBOTE & RECHNUNGEN (Baustellen-Detailansicht)
// ============================================================
function renderLinkedDocs() {
  const b = getBaustelle();
  if (!b) return;
  const tbody = document.getElementById('linkedDocsBody');
  if (!tbody) return;
  tbody.innerHTML = '';

  const mwstSatz = (appSettings?.firma_kleinunternehmer || appSettings?.firma_reverse_charge)
    ? 0 : (parseFloat(appSettings?.firma_mwst_satz) || 19);

  // Statuslabel + Farbe je Typ/Status
  const statusBadge = (typ, status) => {
    const map = {
      offen:      ['offen',      '#FFE0B2', '#E65100'],
      bezahlt:    ['bezahlt',    '#C8E6C9', '#2E7D32'],
      storniert:  ['storniert',  '#FFCDD2', '#C62828'],
      angenommen: ['angenommen', '#C8E6C9', '#2E7D32'],
      abgelehnt:  ['abgelehnt',  '#FFCDD2', '#C62828']
    };
    const [label, bg, fg] = map[status] || [status || '—', '#ECEFF1', '#546E7A'];
    return `<span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:.7rem;font-weight:600;background:${bg};color:${fg}">${label}</span>`;
  };

  const docs = (rechnungenData || [])
    .filter(r => r.baustelleId === b.id)
    .sort((a, c) => (c.datum || '').localeCompare(a.datum || ''));

  if (docs.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" style="padding:12px;text-align:center;color:#999;font-size:.82rem">Noch keine Angebote oder Rechnungen mit dieser Baustelle verknüpft.</td></tr>';
    return;
  }

  docs.forEach(doc => {
    const isAngebot = doc.typ === 'angebot';
    const netto = (doc.positionen || [])
      .filter(p => (p.posTyp || 'normal') === 'normal')
      .reduce((s, p) => s + (parseFloat(p.menge) || 0) * (parseFloat(p.einzelpreis) || 0)
        * (1 - (parseFloat(p.rabatt) || 0) / 100), 0);
    const brutto = netto * (1 + mwstSatz / 100);
    const datumDE = doc.datum ? doc.datum.split('-').reverse().join('.') : '';
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><span style="display:inline-block;padding:1px 8px;border-radius:4px;font-size:.72rem;font-weight:600;${isAngebot ? 'background:#E3F2FD;color:#1565C0' : 'background:#F3E5F5;color:#6A1B9A'}">${isAngebot ? 'Angebot' : 'Rechnung'}</span></td>
      <td><span style="font-weight:600">${esc(doc.nummer || '(ohne Nr.)')}</span>${doc.kundeName ? ` – ${esc(doc.kundeName)}` : ''}</td>
      <td style="font-size:.82rem">${datumDE}</td>
      <td>${statusBadge(doc.typ, doc.status)}</td>
      <td class="price-sensitive text-right" style="font-weight:600">${fmt(brutto)}</td>
      <td><button class="btn btn-secondary btn-sm" style="font-size:.7rem;padding:2px 6px" onclick="openRechnungForm('${isAngebot ? 'angebot' : 'rechnung'}',${JSON.stringify(doc.id).replace(/"/g, '&quot;')})">öffnen</button></td>`;
    tbody.appendChild(tr);
  });
}

// ============================================================
// BAUTAGEBUCH
// ============================================================
function addTagebuchRow() {
  const b = getBaustelle();
  if (!b) return;
  if (!b.bautagebuch)    b.bautagebuch    = [];
  if (!b.nextTagebuchId) b.nextTagebuchId = 1;
  const today = new Date().toISOString().split('T')[0];
  b.bautagebuch.push({ id: b.nextTagebuchId++, datum: today, eintrag: '', erstelltVon: currentKuerzel });
  saveData();
  renderTagebuchRows();
}

function delTagebuchRow(id) {
  const b = getBaustelle();
  if (!b) return;
  b.bautagebuch = (b.bautagebuch || []).filter(r => r.id !== id);
  saveData();
  renderTagebuchRows();
}

function setTagebuch(id, field, val) {
  const b = getBaustelle();
  if (!b) return;
  const r = (b.bautagebuch || []).find(r => r.id === id);
  if (!r) return;
  r[field] = val;
  saveData();
}

function renderTagebuchRows() {
  const b = getBaustelle();
  if (!b) return;
  const tbody = document.getElementById('tagebuchBody');
  if (!tbody) return;
  tbody.innerHTML = '';
  const sorted = [...(b.bautagebuch || [])].sort((a, c) => (c.datum||'').localeCompare(a.datum||''));
  sorted.forEach(r => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><input class="cell-input" type="date" value="${esc(r.datum)}"
            onchange="setTagebuch(${r.id},'datum',this.value)">${r.erstelltVon ? `<span class="creator-badge">${esc(r.erstelltVon)}</span>` : ''}</td>
      <td><textarea class="cell-input" rows="2" style="width:100%;resize:vertical"
            oninput="setTagebuch(${r.id},'eintrag',this.value)"
            placeholder="Tagesablauf, Besonderheiten, Lieferungen —">${esc(r.eintrag)}</textarea></td>
      <td><button class="icon-btn danger" onclick="delTagebuchRow(${r.id})">${ico('trash')}</button></td>`;
    tbody.appendChild(tr);
  });
}

// ============================================================
// TOTALS  -  recalculate & update display
// ============================================================
// Effektiver MwSt-Satz der Firma (Kleinunternehmer/Reverse-Charge => 0%).
function _firmaMwstSatz() {
  return (appSettings?.firma_kleinunternehmer || appSettings?.firma_reverse_charge)
    ? 0 : (parseFloat(appSettings?.firma_mwst_satz) || 19);
}
// Netto-Summe einer Rechnung/eines Angebots (nur normale Positionen, inkl. Rabatt).
function rechnungNetto(re) {
  return (re && Array.isArray(re.positionen) ? re.positionen : [])
    .filter(p => (p.posTyp || 'normal') === 'normal')
    .reduce((s, p) => s + (parseFloat(p.menge) || 0) * (parseFloat(p.einzelpreis) || 0)
      * (1 - (parseFloat(p.rabatt) || 0) / 100), 0);
}
// Brutto-Summe: Netto zzgl. effektivem MwSt-Satz der Firma.
function rechnungBrutto(re) {
  return rechnungNetto(re) * (1 + _firmaMwstSatz() / 100);
}

function recalc() {
  const b = getBaustelle();
  if (!b) return;

  const calcProjects = getProjectsForAggregation(b);
  const calcProjectIds = new Set(calcProjects.map(p => p.id));

  let matSum = 0, matEkSum = 0;
  calcProjects.forEach(project => {
    (project.material || []).forEach(r => {
      matSum += matVk(r, project) * (r.anzahl || 0);
      matEkSum += (r.ek || 0) * (r.anzahl || 0);
    });
  });

  let azSum = 0, azFixkosten = 0, azHoursTotal = 0, azHoursProduktiv = 0;
  calcProjects.forEach(project => {
    (project.arbeitszeit || []).forEach(r => {
      azSum += (r.stunden || 0) * (r.stundenpreis || 0);
      azFixkosten += (r.stunden || 0) * (r.fixkosten || 0);
      azHoursTotal += (r.stunden || 0);
      if (!r.unproduktiv) azHoursProduktiv += (r.stunden || 0);
    });
  });

  let pSum = 0;
  calcProjects.forEach(project => {
    (project.pauschalen || []).forEach(entry => {
      const p = appData.pauschalen.find(p => p.id === entry.id);
      if (p) pSum += p.preis * (entry.anzahl || 1);
    });
  });

  const grand = matSum + azSum + pSum;
  const gewinn = (matSum - matEkSum) + (azSum - azFixkosten) + pSum;

  let abschlagSum = 0;
  calcProjects.forEach(project => {
    (project.abschlaege || []).forEach(r => { abschlagSum += (r.betrag || 0); });
  });
  // Include paid invoices linked to selected project and subprojects.
  (rechnungenData || []).filter(r => r.typ === 'rechnung' && calcProjectIds.has(r.baustelleId) && r.status === 'bezahlt').forEach(re => {
    abschlagSum += rechnungBrutto(re);
  });
  const offenBetrag = grand - abschlagSum;

  setCell('matTotal',     fmt(matSum));
  setCell('azTotal',      fmt(azSum));
  setCell('azTotalHours', azHoursTotal.toFixed(2));
  setCell('azProdHours',  azHoursProduktiv.toFixed(2));
  setCell('pTotal',       fmt(pSum));
  setCell('grandTotal',   fmt(grand));
  setCell('sumMat',       fmt(matSum));
  setCell('sumAz',        fmt(azSum));
  setCell('sumP',         fmt(pSum));
  setCell('sumGrand',     fmt(grand));
  setCell('sumGewinn',    fmt(gewinn));
  setCell('sumAbschlag',  fmt(abschlagSum));
  setCell('sumOffen',     fmt(offenBetrag));
  setCell('abschlagTotal',fmt(abschlagSum));
  setCell('obGesamt',     fmt(grand));
  setCell('obAbschlaege', fmt(abschlagSum));
  setCell('obOffen',      fmt(offenBetrag));
  setCell('offenTotal',   fmt(offenBetrag));
  setCell('gewinnTotal',  fmt(gewinn));
  // Collapsed section totals
  setCell('matCollapsedTotal', fmt(matSum));
  setCell('azCollapsedTotal',  fmt(azSum));
  setCell('azCollapsedHours', azHoursProduktiv.toFixed(2) + ' h');
  setCell('pCollapsedTotal',   fmt(pSum));
  // Color-code offener Betrag
  const obEl = document.getElementById('obOffen');
  if (obEl) obEl.className = 'ob-value' + (offenBetrag > 0.005 ? ' ob-positive' : (grand > 0.005 ? ' ob-zero' : ''));
  const offenBadgeEl = document.getElementById('offenTotal');
  if (offenBadgeEl && offenBadgeEl.parentElement) {
    const isPaid = grand > 0.005 && offenBetrag <= 0.005;
    offenBadgeEl.parentElement.className = 'offen-badge price-sensitive' + (isPaid ? ' offen-badge-paid' : '');
  }
  // Color-code Gewinn
  const gewinnEl = document.getElementById('gewinnTotal');
  if (gewinnEl) gewinnEl.style.color = gewinn >= 0 ? 'var(--success, #198754)' : 'var(--danger, #dc3545)';

  renderUnterprojektAggregateBlocks(b);
}

function renderUnterprojektAggregateBlocks(parentProject) {
  const subs = getSubprojects(parentProject.id);
  const matEl = document.getElementById('matUnterprojektAgg');
  const azEl = document.getElementById('azUnterprojektAgg');
  const pEl = document.getElementById('pUnterprojektAgg');
  if (!matEl || !azEl || !pEl) return;

  if (subs.length === 0) {
    matEl.style.display = 'none';
    azEl.style.display = 'none';
    pEl.style.display = 'none';
    return;
  }

  const rows = subs.map(sp => {
    const mat = (sp.material || []).reduce((sum, r) => sum + matVk(r, sp) * (r.anzahl || 0), 0);
    const az = (sp.arbeitszeit || []).reduce((sum, r) => sum + (r.stunden || 0) * (r.stundenpreis || 0), 0);
    const p = (sp.pauschalen || []).reduce((sum, entry) => {
      const pd = (appData.pauschalen || []).find(x => x.id === entry.id);
      return sum + (pd ? pd.preis * (entry.anzahl || 1) : 0);
    }, 0);
    return { name: sp.name || `Unterprojekt ${sp.id}`, mat, az, p };
  });

  const renderBlock = (title, key) => {
    const total = rows.reduce((sum, r) => sum + (r[key] || 0), 0);
    if (total <= 0) return `<div style="font-size:.8rem;color:var(--grey-400)">Keine Unterprojektwerte vorhanden.</div>`;
    return `<div style="border:1px dashed var(--border);border-radius:8px;padding:10px;background:var(--bg-light,#f7fbfc)">
      <div style="font-size:.82rem;font-weight:700;margin-bottom:6px">${title} nach Unterprojekten</div>
      <table class="data-table" style="margin:0">
        <thead><tr><th>Unterprojekt</th><th style="width:160px;text-align:right">Wert (€)</th></tr></thead>
        <tbody>${rows.map(r => `<tr><td>${esc(r.name)}</td><td style="text-align:right">${fmt(r[key] || 0)}</td></tr>`).join('')}</tbody>
        <tfoot><tr class="total-row"><td style="text-align:right">Gesamt Unterprojekte:</td><td style="text-align:right">${fmt(total)}</td></tr></tfoot>
      </table>
    </div>`;
  };

  matEl.style.display = '';
  matEl.innerHTML = renderBlock('Material', 'mat');
  azEl.style.display = '';
  azEl.innerHTML = renderBlock('Arbeitszeit', 'az');
  pEl.style.display = '';
  pEl.innerHTML = renderBlock('Pauschalen', 'p');
}

