function katalogEinheitSelect(id, current) {
  const units = ['Stk.','m','m²','m²','kg','t','l','lfm','VE','Pkt.','Psch.','h'];
  const opts = units.map(u => `<option${u === current ? ' selected' : ''}>${u}</option>`).join('');
  return `<select class="cell-select" onchange="setKatalog(${id},'einheit',this.value)">${opts}</select>`;
}

// -- KATALOG CRUD ---------------------------------------------
function addKatalogRow() {
  if (!appData.materialKatalog) appData.materialKatalog = [];
  if (!appData.nextKatalogId) appData.nextKatalogId = 1;
  appData.materialKatalog.push({ id: appData.nextKatalogId++, bezeichnung: '', einheit: 'Stk.', ek: 0, aufschlag: 0 });
  saveData();
  renderKatalogRows();
  // show hint if empty was shown
  const el = document.getElementById('materialKatalogView');
  if (el) renderMaterialKatalog();
}

function delKatalogRow(id) {
  appData.materialKatalog = (appData.materialKatalog || []).filter(k => k.id !== id);
  saveData();
  renderMaterialKatalog();
}

function setKatalog(id, field, val) {
  const k = (appData.materialKatalog || []).find(k => k.id === id);
  if (!k) return;
  k[field] = ['ek','aufschlag'].includes(field) ? (parseFloat(val) || 0) : val;
  saveData();
  setCell(`kvk_${id}`, fmt(k.ek * (1 + k.aufschlag / 100)));
}

// -- Datanorm Server-Reindex ----------------------------------
async function datanormReindex() {
  const btn = document.getElementById('btnDnReindex');
  const status = document.getElementById('dnIndexStatus');
  if (btn) btn.disabled = true;
  if (status) status.textContent = 'Indexierung läuft - bitte warten...';
  try {
    const res = await fetch('api.php?action=datanorm_reindex', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const data = await res.json();
    if (data.ok) {
      if (status) status.innerHTML = `<strong style="color:var(--success)"> ${data.count.toLocaleString('de-DE')} Artikel indexiert.</strong> Die Datanorm-Suche steht jetzt in "Aus Katalog" zur Verfügung.`;
      showNotification(`Datanorm: ${data.count.toLocaleString('de-DE')} Artikel indexiert.`);
      datanormStatus();
    } else {
      if (status) status.textContent = 'Fehler: ' + (data.error || 'Unbekannt');
    }
  } catch (err) {
    console.error(err);
    if (status) status.textContent = 'Fehler: ' + err.message;
  }
  if (btn) btn.disabled = false;
}

// v2.0.1: Status der Datanorm-Quelldateien laden + Karten aktualisieren
async function datanormStatus() {
  const grid = document.getElementById('dnFileGrid');
  if (!grid) return;
  try {
    const r = await fetch('api.php?action=datanorm_status');
    const j = await r.json();
    if (!j.ok) return;
    const dirInfo = document.getElementById('dnDirInfo');
    if (dirInfo) dirInfo.textContent = (j.writable ? '' : '⚠ nicht beschreibbar · ') + (j.directory || '');
    ['datanorm.001','datanorm.wrg','datpreis.001'].forEach(name => {
      const card = grid.querySelector(`.dn-file-card[data-dnfile="${name}"]`);
      if (!card) return;
      const badge = card.querySelector('.dn-file-badge');
      const meta  = card.querySelector('.dn-file-meta');
      const info  = j.files?.[name];
      if (info && info.present) {
        if (badge) { badge.textContent = '✓'; badge.style.background = '#d4edda'; badge.style.color = '#155724'; }
        const sz = info.size > 1048576 ? (info.size/1048576).toFixed(1)+' MB' : Math.max(1, Math.round(info.size/1024))+' KB';
        const dt = info.mtime ? new Date(info.mtime*1000).toLocaleString('de-DE') : '';
        if (meta) meta.textContent = `${sz} · ${dt}`;
      } else {
        if (badge) { badge.textContent = '–'; badge.style.background = '#eee'; badge.style.color = '#666'; }
        if (meta)  meta.textContent = 'noch nicht hochgeladen';
      }
    });
    const status = document.getElementById('dnIndexStatus');
    if (status && j.index) {
      if (j.index.present) {
        const lines = (j.index.lines||0).toLocaleString('de-DE');
        const dt = j.index.mtime ? new Date(j.index.mtime*1000).toLocaleString('de-DE') : '';
        status.innerHTML = `Index vorhanden: <strong>${lines}</strong> Artikel · ${dt}`;
      } else {
        status.textContent = 'Noch kein Index. Dateien hochladen und "Datanorm indexieren" klicken.';
      }
    }
  } catch (e) { console.warn('datanormStatus:', e); }
}

// v2.0.1: Eine Datanorm-Datei hochladen
async function datanormUpload(name) {
  const inp = document.querySelector(`.dn-file-input[data-dnname="${name}"]`);
  if (!inp || !inp.files || !inp.files[0]) { showNotification('Bitte zuerst eine Datei wählen.', 'error'); return; }
  const file = inp.files[0];
  const fd = new FormData();
  fd.append(name, file, name);
  const status = document.getElementById('dnIndexStatus');
  if (status) status.textContent = `Lade "${name}" hoch …`;
  try {
    const r = await fetch('api.php?action=datanorm_upload', { method: 'POST', body: fd });
    const j = await r.json();
    if (j.ok) {
      showNotification(`${name} hochgeladen.`);
      inp.value = '';
      datanormStatus();
    } else {
      showNotification(j.error || 'Upload fehlgeschlagen.', 'error');
      if (status) status.textContent = 'Fehler: ' + (j.error || 'Unbekannt');
    }
  } catch (e) {
    showNotification('Netzwerkfehler: ' + e.message, 'error');
  }
}

// v2.0.1: Datanorm-Quelldateien + Index löschen
async function datanormClear() {
  confirmDelete('Datanorm-Quelldateien (datanorm.001, .wrg, datpreis.001) und den Index wirklich löschen?', async () => {
    try {
      const r = await fetch('api.php?action=datanorm_clear', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
      const j = await r.json();
      if (j.ok) {
        showNotification('Datanorm zurückgesetzt (' + (j.deleted?.length || 0) + ' Dateien gelöscht).');
        datanormStatus();
      } else showNotification(j.error || 'Fehler beim Löschen.', 'error');
    } catch (e) { showNotification('Netzwerkfehler: ' + e.message, 'error'); }
  });
}

// -- Save material row ? Katalog ------------------------------
function saveMatRowToKatalog(matId) {
  const b = getBaustelle();
  if (!b) return;
  const r = b.material.find(r => r.id === matId);
  if (!r) return;
  if (!appData.materialKatalog) appData.materialKatalog = [];
  if (!appData.nextKatalogId) appData.nextKatalogId = 1;
  // avoid exact duplicates (same bezeichnung + einheit + ek + aufschlag)
  const dup = appData.materialKatalog.find(k =>
    k.bezeichnung === r.bezeichnung && k.einheit === r.einheit &&
    k.ek === r.ek && k.aufschlag === r.aufschlag);
  if (dup) {
    const btn = document.getElementById(`savebtn_${matId}`);
    if (btn) { btn.innerHTML = ico('check'); setTimeout(() => btn.innerHTML = ico('save'), 1200); }
    return;
  }
  appData.materialKatalog.push({ id: appData.nextKatalogId++, bezeichnung: r.bezeichnung, einheit: r.einheit, ek: r.ek, aufschlag: r.aufschlag });
  saveData();
  const btn = document.getElementById(`savebtn_${matId}`);
  if (btn) { btn.innerHTML = ico('check'); setTimeout(() => btn.innerHTML = ico('save'), 1200); }
}

// -- Metallzuschlag (Kupfer-DEL-Notierung) --------------------
const CABLE_RE = /\b(NYM|NYY|NHXMH|NYCWY|NYCY|NAYY|H07V|H05V|H03V|LIYCY|ÖLFLEX|J-Y\(ST\)|YSLY|NSGAFÖU|NSHTÖU)/i;
const CABLE_SPEC_RE = /(\d+)\s*[x×]\s*(\d+[,.]?\d*)/i;

let _currentMetallzuschlag = null; // { delNotierung, basisNotierung, datum, quelle }

/** Detect whether an item name refers to a cable (Kabel/Leitung) */
function isCableItem(name) {
  return CABLE_RE.test(name);
}

/** Parse cable specification: returns { cores, crossSection } or null */
function parseCableSpec(name) {
  const m = name.match(CABLE_SPEC_RE);
  if (!m) return null;
  const cores = parseInt(m[1], 10);
  const cs = parseFloat(m[2].replace(',', '.'));
  if (!cores || !cs || cores > 100 || cs > 400) return null;
  return { cores, crossSection: cs };
}

/**
 * Calculate Metallzuschlag per unit (meter) for a cable.
 * - Copper density: 8.93 g/cm² ? 0.00893 kg per m per mm²
 * - Surcharge = copperWeight - (DEL - basis) / 100
 * @param {string} name        - Article name
 * @param {string} einheit     - Unit (m, lfm, Rolle, Ring, etc.)
 * @param {number} delNotierung - Current DEL-Notierung in EUR/100kg
 * @returns {{ zuschlag: number, cuKgPerM: number, spec: string }|null}
 */
function calcMetallzuschlag(name, einheit, delNotierung) {
  if (!delNotierung || delNotierung <= 0) return null;
  const spec = parseCableSpec(name);
  if (!spec) return null;
  const cuKgPerM = spec.cores * spec.crossSection * 0.00893;
  let zuschlag = cuKgPerM * delNotierung / 100;
  // Handle units: Ring/Rolle usually = 100m, Trommel varies
  const e = (einheit || '').toLowerCase();
  if (e.includes('ring') || e.includes('rolle') || e === 'bund') zuschlag *= 100;
  if (e.includes('trommel') || e.includes('500')) zuschlag *= 500;
  return {
    zuschlag: Math.round(zuschlag * 10000) / 10000,
    cuKgPerM,
    spec: spec.cores + '×' + spec.crossSection + 'mm²'
  };
}

/** Fetch current Metallzuschlag from server - fast: reads stored JSON first */
async function fetchMetallzuschlag() {
  // 1) Quick: get stored/cached value immediately
  try {
    const r = await fetch('api.php?action=metallzuschlag_get');
    const j = await r.json();
    if (j && 'delNotierung' in j) _currentMetallzuschlag = j.delNotierung > 0 ? j : null;
  } catch (e) { console.warn('Metallzuschlag fetch:', e); }
  // 2) Background: try auto-fetch to update for next time (non-blocking)
  fetch('api.php?action=metallzuschlag_auto_fetch').then(r => r.json()).then(j => {
    if (j && 'delNotierung' in j) _currentMetallzuschlag = j.delNotierung > 0 ? j : null;
  }).catch(() => {});
}

/** Render info bar showing current DEL-Notierung inside the picker modal */
function renderMzInfoBar() {
  const bar = document.getElementById('mzInfoBar');
  if (!bar) return;
  const mz = _currentMetallzuschlag;
  if (!mz || !mz.delNotierung || mz.delNotierung <= 0) {
    bar.innerHTML = `<div class="mz-info-bar mz-info-missing">
      <span> <strong>Metallzuschlag:</strong> Keine DEL-Notierung hinterlegt.</span>
      ${(currentRole === 'admin' || currentRole === 'master')
        ? '<span style="font-size:.78rem"> <a href="#" onclick="closeKatalogPickerModal();openMetallzuschlagModal();return false;">DEL-Notierung hinterlegen</a></span>'
        : '<span style="font-size:.78rem">Admin muss DEL-Notierung hinterlegen</span>'}
    </div>`;
    return;
  }
  bar.innerHTML = `<div class="mz-info-bar mz-info-active">
    <span> <strong>DEL-Notierung:</strong> ${fmt(mz.delNotierung)}/100 kg Cu</span>
    <span style="font-size:.72rem;color:var(--grey-500)">${mzStandText(mz)}</span>
  </div>${mzVeraltetHinweis(mz)}`;
}

/** „Stand der Notiz: TT.MM.JJJJ (manuell|automatisch)“ – Serverwerte escaped. */
function mzStandText(mz) {
  const roh = String(mz.stand || mz.datum || '');
  const m = roh.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const datum = m ? `${m[3]}.${m[2]}.${m[1]}` : roh;
  return `Stand der Notiz: ${esc(datum) || '-'} (${mz.quelle === 'manual' ? 'manuell' : 'automatisch'})`;
}

function mzVeraltetHinweis(mz) {
  if (!mz.veraltet && !mz.fetchError) return '';
  return `<div class="mz-veraltet" style="margin-top:4px;padding:4px 8px;background:#FFF8E1;border:1px solid #FFD54F;border-radius:4px;font-size:.75rem;color:#8D6E00;">
    <strong>Hinweis:</strong> DEL-Notierung möglicherweise veraltet${mz.fetchError ? ' - letzter Abruf fehlgeschlagen: ' + esc(mz.fetchError) : ''}
  </div>`;
}

async function loadMetallProfileCatalog(forceUpdate = false) {
  const action = forceUpdate ? 'metallprofile_auto_update' : 'metallprofile_catalog';
  const r = await fetch('api.php?action=' + action, {
    method: forceUpdate ? 'POST' : 'GET',
    headers: { 'Content-Type': 'application/json' },
    body: forceUpdate ? '{}' : undefined
  });
  const j = await r.json();
  if (!j.ok) throw new Error(j.error || 'Katalog konnte nicht geladen werden.');
  metallProfileCatalog = j.entries || [];
  metallProfileMeta = { updated: j.updated || '', quelle: j.quelle || '' };
  return j;
}

// ── HiCAD-Materialbibliothek (eigene Tabelle, Admin-Import) ──
let hicadProfileCatalog = [];
let hicadProfileMeta    = { updated: '', count: 0, matched: 0 };
let mpActiveSource      = 'standard'; // 'standard' | 'hicad'

async function loadHicadProfileCatalog() {
  const r = await fetch('api.php?action=hicad_list');
  const j = await r.json();
  if (!j.ok) throw new Error(j.error || 'HiCAD-Katalog konnte nicht geladen werden.');
  hicadProfileCatalog = (j.entries || []).map(e => ({
    typ:         e.typ || 'profil',
    kategorie:   e.kategorie || '',
    bezeichnung: e.bezeichnung || '',
    kgProM:      e.kgProM, // kann null sein
    material:    e.material || 'S235',
    kategoriePfad: e.kategoriePfad || '',
  }));
  hicadProfileMeta = {
    updated: j.updated || '',
    count:   j.count || 0,
    matched: j.matched || 0,
  };
  return j;
}

async function importHicadLibrary() {
  if (!(currentRole === 'admin' || currentRole === 'master')) {
    showNotification('Keine Berechtigung.');
    return;
  }
  const btn = document.getElementById('mpHicadImportBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Importiere...'; }
  try {
    const r = await fetch('api.php?action=hicad_import', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}'
    });
    const j = await r.json();
    if (!j.ok) throw new Error(j.error || 'Import fehlgeschlagen.');
    await loadHicadProfileCatalog();
    renderMetallProfileList();
    updateMpMetaLabel();
    showNotification(`HiCAD importiert: ${j.count} Einträge, ${j.matched} mit Gewicht.`);
  } catch (e) {
    showNotification(e.message || 'HiCAD-Import fehlgeschlagen.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'HiCAD importieren'; }
  }
}

function getActiveMetallProfileCatalog() {
  return mpActiveSource === 'hicad' ? hicadProfileCatalog : metallProfileCatalog;
}

function updateMpMetaLabel() {
  const meta = document.getElementById('mpMeta');
  if (!meta) return;
  if (mpActiveSource === 'hicad') {
    if (!hicadProfileMeta.updated && !hicadProfileCatalog.length) {
      meta.textContent = 'HiCAD-Bibliothek noch nicht importiert.';
    } else {
      const d = hicadProfileMeta.updated ? new Date(hicadProfileMeta.updated).toLocaleDateString('de-DE') : '-';
      meta.textContent = `HiCAD | ${hicadProfileMeta.count} Einträge (${hicadProfileMeta.matched} mit kg/m) | Stand: ${d}`;
    }
  } else {
    meta.textContent = `Quelle: ${metallProfileMeta.quelle || '-'} | Aktualisiert: ${metallProfileMeta.updated ? new Date(metallProfileMeta.updated).toLocaleDateString('de-DE') : '-'}`;
  }
  // Admin-Buttons nach Quelle ein-/ausblenden
  const importBtn = document.getElementById('mpHicadImportBtn');
  const updateBtn = document.getElementById('mpStandardUpdateBtn');
  if (importBtn) importBtn.style.display = (mpActiveSource === 'hicad') ? '' : 'none';
  if (updateBtn) updateBtn.style.display = (mpActiveSource === 'standard') ? '' : 'none';
}

async function switchMetallProfileSource(src) {
  mpActiveSource = (src === 'hicad') ? 'hicad' : 'standard';
  const list = document.getElementById('mpList');
  if (mpActiveSource === 'hicad' && !hicadProfileCatalog.length) {
    if (list) list.innerHTML = '<div style="padding:10px;color:var(--grey-400)">Lade HiCAD...</div>';
    try { await loadHicadProfileCatalog(); } catch (e) {
      if (list) list.innerHTML = `<div style="padding:10px;color:#c62828">${esc(e.message || 'HiCAD-Katalog nicht verfügbar.')}</div>`;
      updateMpMetaLabel();
      return;
    }
  }
  renderMetallProfileList();
  updateMpMetaLabel();
  const search = document.getElementById('mpSearch');
  if (search && search.value) filterMetallProfileRows(search.value);
}

function filterMetallProfileRows(q) {
  const query = (q || '').trim().toLowerCase();
  const rows = document.querySelectorAll('.mp-row');
  rows.forEach(row => {
    const text = (row.dataset.search || '').toLowerCase();
    row.style.display = !query || text.includes(query) ? '' : 'none';
  });
}

function applyMetallProfileSelection(index) {
  const entry = getActiveMetallProfileCatalog()[index];
  if (!entry) return;
  const typEl = document.getElementById('mpTyp');
  const catEl = document.getElementById('mpKategorie');
  const bezEl = document.getElementById('mpBezeichnung');
  const kgEl = document.getElementById('mpKgProM');
  if (typEl) typEl.value = entry.typ || 'profil';
  if (catEl) catEl.value = entry.kategorie || '';
  if (bezEl) bezEl.value = entry.bezeichnung || '';
  if (kgEl) kgEl.value = (entry.kgProM != null && entry.kgProM > 0) ? entry.kgProM.toString() : '';
  calcMetallProfilGewicht();
  if (entry.kgProM == null || entry.kgProM <= 0) {
    showNotification('Für dieses Profil ist kein Gewicht hinterlegt – bitte kg/m manuell eintragen.');
  }
}

function calcMetallProfilGewicht() {
  const kgProM = parseFloat(document.getElementById('mpKgProM')?.value || '0') || 0;
  const laenge = parseFloat(document.getElementById('mpLaenge')?.value || '0') || 0;
  const stueck = parseFloat(document.getElementById('mpStueck')?.value || '0') || 0;
  const gesamt = Math.max(0, kgProM * laenge * stueck);
  const out = document.getElementById('mpGewichtGesamt');
  if (out) out.textContent = gesamt.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 3 });
  return gesamt;
}

async function openMetallProfilModal() {
  const b = getBaustelle();
  if (!b) return;
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'metallProfilOverlay';
  overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `<div class="modal-box" style="max-width:920px;max-height:90vh;overflow-y:auto">
    <div class="modal-header"><h2>Profil / Halbzeug hinzufügen</h2><button class="close-btn" onclick="document.getElementById('metallProfilOverlay')?.remove()">✕</button></div>
    <div class="modal-body">
      <div style="display:grid;grid-template-columns:1.4fr 1fr;gap:12px;align-items:start">
        <div style="border:1px solid var(--border);border-radius:8px;padding:10px">
          <div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap">
            <select id="mpSourceSelect" class="form-control" style="width:auto;min-width:140px" onchange="switchMetallProfileSource(this.value)">
              <option value="standard">Standard</option>
              <option value="hicad">HiCAD-Bibliothek</option>
            </select>
            <input id="mpSearch" class="form-control" style="flex:1;min-width:160px" placeholder="Profil/Halbzeug suchen..." oninput="filterMetallProfileRows(this.value)">
            ${(currentRole === 'admin' || currentRole === 'master') ? '<button id="mpStandardUpdateBtn" class="btn btn-secondary btn-sm" onclick="refreshMetallProfileCatalog()">Update</button>' : ''}
            ${(currentRole === 'admin' || currentRole === 'master') ? '<button id="mpHicadImportBtn" class="btn btn-secondary btn-sm" style="display:none" onclick="importHicadLibrary()">HiCAD importieren</button>' : ''}
          </div>
          <div id="mpMeta" style="font-size:.75rem;color:var(--grey-400);margin-bottom:6px">Lade Katalog...</div>
          <div id="mpList" style="max-height:360px;overflow:auto;border:1px solid var(--grey-100);border-radius:6px"></div>
        </div>
        <div style="border:1px solid var(--border);border-radius:8px;padding:10px">
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
            <div><label class="form-label">Typ</label><select id="mpTyp" class="form-control"><option value="profil">Profil</option><option value="halbzeug">Halbzeug</option></select></div>
            <div><label class="form-label">Kategorie</label><input id="mpKategorie" class="form-control" placeholder="z.B. Vierkantrohr"></div>
            <div style="grid-column:1/-1"><label class="form-label">Abmessung / Bezeichnung</label><input id="mpBezeichnung" class="form-control" placeholder="z.B. 40x40x2"></div>
            <div><label class="form-label">kg pro m</label><input id="mpKgProM" type="number" min="0" step="0.0001" class="form-control" oninput="calcMetallProfilGewicht()"></div>
            <div><label class="form-label">Länge je Stück (m)</label><input id="mpLaenge" type="number" min="0" step="0.01" class="form-control" value="6" oninput="calcMetallProfilGewicht()"></div>
            <div><label class="form-label">Stückzahl</label><input id="mpStueck" type="number" min="0" step="1" class="form-control" value="1" oninput="calcMetallProfilGewicht()"></div>
            <div><label class="form-label">Gesamtgewicht (kg)</label><div style="height:36px;display:flex;align-items:center;padding:0 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg-light,#f7fbfc)"><strong id="mpGewichtGesamt">0,00</strong></div></div>
            <div><label class="form-label">EK €/kg (optional)</label><input id="mpEkKg" type="number" min="0" step="0.01" class="form-control" value="0"></div>
          </div>
          <p style="font-size:.75rem;color:var(--grey-400);margin-top:8px">Das Gesamtgewicht wird als Materialposition mit Einheit <strong>kg</strong> eingefügt.</p>
          <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px">
            <button class="btn btn-secondary" onclick="document.getElementById('metallProfilOverlay')?.remove()">Abbrechen</button>
            <button class="btn btn-primary" onclick="addMetallProfilToMaterial()">Übernehmen</button>
          </div>
        </div>
      </div>
    </div>
  </div>`;
  document.body.appendChild(overlay);

  try {
    // Quelle-Dropdown auf aktuell gewählten Zustand setzen
    const srcSel = document.getElementById('mpSourceSelect');
    if (srcSel) srcSel.value = mpActiveSource;
    const res = await loadMetallProfileCatalog(false);
    renderMetallProfileList();
    updateMpMetaLabel();
    if (res.autoUpdateDue && (currentRole === 'admin' || currentRole === 'master')) {
      refreshMetallProfileCatalog(true);
    }
  } catch (e) {
    const list = document.getElementById('mpList');
    if (list) list.innerHTML = `<div style="padding:10px;color:#c62828">${esc(e.message || 'Katalog konnte nicht geladen werden.')}</div>`;
  }
  calcMetallProfilGewicht();
}

function renderMetallProfileList() {
  const list = document.getElementById('mpList');
  if (!list) return;
  const catalog = getActiveMetallProfileCatalog();
  if (!catalog.length) {
    list.innerHTML = '<div style="padding:10px;color:var(--grey-400)">'
      + (mpActiveSource === 'hicad'
          ? 'HiCAD-Bibliothek leer. Bitte "HiCAD importieren" (Admin) ausführen.'
          : 'Keine Datensätze vorhanden.')
      + '</div>';
    return;
  }
  list.innerHTML = catalog.map((entry, idx) => {
    const search = `${entry.typ || ''} ${entry.kategorie || ''} ${entry.bezeichnung || ''} ${entry.material || ''} ${entry.kategoriePfad || ''}`;
    const kg = (entry.kgProM != null && entry.kgProM > 0)
      ? entry.kgProM.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 4 }) + ' kg/m'
      : '<span style="color:var(--grey-400)">— kg/m</span>';
    return `<div class="mp-row" data-search="${esc(search)}" style="padding:8px 10px;border-bottom:1px solid var(--grey-100);cursor:pointer" onclick="applyMetallProfileSelection(${idx})">
      <div style="display:flex;justify-content:space-between;gap:8px">
        <div><strong>${esc(entry.kategorie || 'Profil')}</strong> ${esc(entry.bezeichnung || '')}<div style="font-size:.75rem;color:var(--grey-400)">${esc(entry.typ || '')} ${entry.material ? '| ' + esc(entry.material) : ''}</div></div>
        <div style="font-size:.82rem;font-weight:700">${kg}</div>
      </div>
    </div>`;
  }).join('');
}

async function refreshMetallProfileCatalog(silent = false) {
  try {
    await loadMetallProfileCatalog(true);
    renderMetallProfileList();
    updateMpMetaLabel();
    if (!silent) showNotification('Metallprofil-Katalog aktualisiert.');
  } catch (e) {
    if (!silent) showNotification('Katalog-Update fehlgeschlagen.');
  }
}

function addMetallProfilToMaterial() {
  const b = getBaustelle();
  if (!b) return;
  const typ = document.getElementById('mpTyp')?.value || 'profil';
  const kat = (document.getElementById('mpKategorie')?.value || '').trim();
  const bez = (document.getElementById('mpBezeichnung')?.value || '').trim();
  const laenge = parseFloat(document.getElementById('mpLaenge')?.value || '0') || 0;
  const stueck = parseFloat(document.getElementById('mpStueck')?.value || '0') || 0;
  const ekKg = parseFloat(document.getElementById('mpEkKg')?.value || '0') || 0;
  const gewicht = calcMetallProfilGewicht();
  if (!bez || gewicht <= 0 || laenge <= 0 || stueck <= 0) {
    showNotification('Bitte Profil, Länge und Stückzahl korrekt eingeben.');
    return;
  }
  const bezeichnung = `[${typ}] ${kat ? kat + ' ' : ''}${bez} | ${stueck}x ${laenge}m`;
  b.material.unshift({
    id: b.nextMatId++,
    bezeichnung,
    anzahl: Math.round(gewicht * 1000) / 1000,
    einheit: 'kg',
    ek: ekKg,
    aufschlag: 0,
    kategorieId: null,
    erstelltVon: currentKuerzel,
    datum: new Date().toISOString().split('T')[0],
  });
  saveData();
  renderMatRows();
  recalc();
  document.getElementById('metallProfilOverlay')?.remove();
  showNotification('Profil/Halbzeug übernommen.');
}

// -- Katalog picker modal with search -------------------------
let _katalogSearchTimer = null;
let _pickerSelected = new Map(); // key => { src, data, anzahl }

function openKatalogPickerModal() {
  const inp = document.getElementById('katalogSearchInput');
  const tbody = document.getElementById('katalogPickerBody');
  const hint = document.getElementById('katalogSearchHint');
  const tbl = document.getElementById('katalogPickerTable');
  _pickerSelected.clear();
  if (inp) inp.value = '';
  if (tbody) tbody.innerHTML = '';
  if (hint) { hint.innerHTML = '<div style="text-align:center;padding:20px 0;"><div style="font-size:2rem;margin-bottom:8px;">Info</div><div>Suchbegriff eingeben - mindestens 2 Zeichen</div><div style="font-size:.78rem;color:var(--grey-400);margin-top:6px;">Tipp: Mehrere Begriffe eingeben für genauere Ergebnisse, z.B.<br><em>\"Leitungsschutzschalter B16\"</em> oder <em>\"NYM 3x1,5\"</em></div></div>'; hint.style.display = ''; }
  if (tbl) tbl.style.display = 'none';
  const countEl = document.getElementById('katalogPickerCount');
  if (countEl) countEl.textContent = '0 ausgewählt';
  renderPickerSelectedBar();
  show('katalogPickerModal');
  // v2.0.1: "Oft verbaut" laden und rendern
  loadAndRenderTopUsedMaterials();
  // Fetch current DEL-Notierung for Metallzuschlag display (async, non-blocking)
  fetchMetallzuschlag().then(() => { try { renderMzInfoBar(); } catch(e) { console.warn('MZ info bar:', e); } }).catch(() => {});
  setTimeout(() => inp?.focus(), 80);
}

// v2.0.1: "Oft verbaut" – Top-Materialien aus allen Baustellen
let _topUsedMatCache = null;
async function loadAndRenderTopUsedMaterials() {
  const tbody = document.getElementById('katalogPickerBody');
  const tbl = document.getElementById('katalogPickerTable');
  if (!tbody) return;
  try {
    if (!_topUsedMatCache) {
      const r = await fetch('api.php?action=material_top_used&limit=20');
      const j = await r.json();
      _topUsedMatCache = (j.ok && j.items) ? j.items : [];
    }
    const items = _topUsedMatCache;
    if (!items.length) return;
    // Nur anzeigen wenn Suche leer
    const inp = document.getElementById('katalogSearchInput');
    if (inp && inp.value.trim() !== '') return;
    if (tbl) tbl.style.display = '';
    const hdr = document.createElement('tr');
    hdr.innerHTML = `<td colspan="8" style="background:#FFF8E1;font-weight:600;padding:6px 12px;font-size:.85rem;">⭐ Oft verbaut (${items.length})</td>`;
    tbody.appendChild(hdr);
    items.forEach((it, idx) => {
      const key = 'top:' + idx;
      const tr = document.createElement('tr');
      tr.className = 'picker-row';
      tr.innerHTML = `
        <td><input type="checkbox" class="picker-cb" data-key="${key}" data-src="top" data-bez="${esc(it.bezeichnung)}" data-einheit="${esc(it.einheit)}" data-ek="${it.ek||0}" onchange="togglePickerSelection(this)"></td>
        <td style="font-size:.8rem;color:var(--text-muted);">${it.count}×</td>
        <td>${esc(it.bezeichnung)}</td>
        <td>${esc(it.einheit)}</td>
        <td class="text-right price-sensitive">${fmt(it.ek||0)}</td>
        <td class="text-right price-sensitive">${fmt(it.ek||0)}</td>
        <td><span style="display:inline-block;background:#FFF3E0;color:#E65100;padding:1px 6px;border-radius:4px;font-size:.72rem;font-weight:500;">Oft verbaut</span></td>
        <td><input type="number" class="cell-input text-right picker-qty" data-key="${key}" value="1" min="1" style="width:56px;" onchange="updatePickerQty(this)"></td>`;
      tbody.appendChild(tr);
    });
    const hint = document.getElementById('katalogSearchHint');
    if (hint) hint.style.display = 'none';
  } catch (e) { /* silent */ }
}

/* Highlight search terms in text */
function highlightTerms(text, terms) {
  if (!terms || terms.length === 0) return esc(text);
  let result = esc(text);
  terms.forEach(t => {
    const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    result = result.replace(new RegExp('(' + escaped + ')', 'gi'), '<mark style="background:#FFF3B0;padding:0 1px;border-radius:2px;">$1</mark>');
  });
  return result;
}

function closeKatalogPickerModal() { hide('katalogPickerModal'); }
function closeKatalogPickerOverlay(e) { if (e.target === e.currentTarget) closeKatalogPickerModal(); }

// ── OCI Punchout ─────────────────────────────────────────────

/** Wird aufgerufen, wenn der Benutzer auf "🏪 OCI" klickt. */
async function openOciSupplierPicker() {
  try {
    const r = await fetch('api.php?action=oci_list_lieferanten');
    const j = await r.json();
    if (!j.ok) { alert('OCI-Lieferanten konnten nicht geladen werden.'); return; }
    const aktive = (j.lieferanten || []).filter(l => l.aktiv);
    if (aktive.length === 0) {
      alert('Keine aktiven OCI-Lieferanten konfiguriert.\nBitte unter Einstellungen → OCI Großhandel einen Lieferanten anlegen.');
      return;
    }
    if (aktive.length === 1) {
      openOciPunchout(aktive[0].id);
      return;
    }
    // Mehrere Lieferanten → Auswahl anzeigen
    _showOciLieferantSelect(aktive);
  } catch (e) {
    alert('Netzwerkfehler beim Laden der OCI-Lieferanten.');
  }
}

/** Zeigt ein Mini-Overlay zur Lieferantenauswahl (bei mehreren aktiven). */
function _showOciLieferantSelect(lieferanten) {
  // Altes Overlay entfernen
  const old = document.getElementById('ociSelectOverlay');
  if (old) old.remove();

  const overlay = document.createElement('div');
  overlay.id = 'ociSelectOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };

  const box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:12px;padding:24px;max-width:360px;width:90%;box-shadow:0 4px 20px rgba(0,0,0,.25)';
  box.innerHTML = `<h3 style="margin:0 0 16px;font-size:1rem">&#x1F3EA; OCI-Lieferant wählen</h3>
    <div style="display:flex;flex-direction:column;gap:8px">
      ${lieferanten.map(l => `<button class="btn btn-secondary" style="text-align:left;font-size:.9rem" onclick="document.getElementById('ociSelectOverlay').remove();openOciPunchout(${l.id})">${esc(l.name)}</button>`).join('')}
    </div>
    <button class="btn btn-secondary btn-sm" style="margin-top:16px;width:100%" onclick="document.getElementById('ociSelectOverlay').remove()">Abbrechen</button>`;
  overlay.appendChild(box);
  document.body.appendChild(overlay);
}

/** Startet den OCI-Punchout-Flow für einen Lieferanten. */
async function openOciPunchout(lieferantId) {
  try {
    const r = await fetch('api.php?action=oci_prepare&lieferantId=' + lieferantId);
    const j = await r.json();
    if (!j.ok || !j.nonce) { alert(j.error || 'OCI-Sitzung konnte nicht gestartet werden.'); return; }

    const popup = window.open(
      'api.php?action=oci_start&t=' + encodeURIComponent(j.nonce),
      'oci-punchout',
      'width=1200,height=800,left=200,top=80,resizable=yes,scrollbars=yes'
    );
    if (!popup) {
      alert('Popup wurde blockiert. Bitte erlauben Sie Popups für diese Seite und versuchen Sie es erneut.');
      return;
    }

    // Hinweis-Banner im Modal
    const hint = document.getElementById('katalogSearchHint');
    if (hint) {
      hint.innerHTML = '<span style="color:#00897B;font-weight:600">&#x1F3EA; OCI-Fenster geöffnet – Artikel im Lieferanten-Shop auswählen und Warenkorb bestätigen.</span>';
      hint.style.display = 'block';
    }

    // Message-Listener registrieren
    window.addEventListener('message', _onOciMessage);
  } catch (e) {
    alert('Netzwerkfehler beim Starten des OCI-Punchout.');
  }
}

/** Empfängt Artikel vom OCI-Hook via postMessage. */
function _onOciMessage(event) {
  // Nur eigene Origin akzeptieren
  if (event.origin !== window.location.origin) return;
  if (!event.data || event.data.type !== 'oci_items') return;

  window.removeEventListener('message', _onOciMessage);

  const items = Array.isArray(event.data.items) ? event.data.items : [];
  if (items.length === 0) {
    const hint = document.getElementById('katalogSearchHint');
    if (hint) { hint.textContent = 'Keine Artikel vom Lieferanten empfangen.'; hint.style.display = 'block'; }
    return;
  }
  _insertOciItems(items);
}

/** Fügt OCI-Artikel in das aktuelle Baustellen-Materialdaten ein. */
function _insertOciItems(ociItems) {
  const b = getBaustelle();
  if (!b) {
    alert('Bitte zuerst ein Projekt öffnen, in das die OCI-Artikel eingefügt werden sollen.');
    return;
  }
  if (!Array.isArray(b.material)) b.material = [];
  if (typeof b.nextMatId !== 'number') b.nextMatId = (b.material.reduce((m, x) => Math.max(m, x.id || 0), 0) + 1);

  const heute = new Date().toISOString().split('T')[0];
  const inserted = [];
  ociItems.forEach(item => {
    const eintrag = {
      id:          b.nextMatId++,
      bezeichnung: String(item.bezeichnung || '').trim() || 'Unbekannt',
      anzahl:      parseFloat(item.anzahl) || 1,
      einheit:     String(item.einheit || 'Stk.'),
      ek:          parseFloat(item.ek) || 0,
      aufschlag:   0,
      kategorieId: null,
      erstelltVon: currentKuerzel || '',
      datum:       heute,
    };
    b.material.push(eintrag);
    inserted.push(eintrag);
  });

  saveData();
  renderMatRows();
  recalc();

  // Feedback
  const hint = document.getElementById('katalogSearchHint');
  if (hint) {
    hint.innerHTML = `<span style="color:#2e7d32;font-weight:600">&#x2713; ${inserted.length} Artikel aus OCI übernommen.</span>`;
    hint.style.display = 'block';
  }
  closeKatalogPickerModal();
}

function katalogSearch(q) {
  clearTimeout(_katalogSearchTimer);
  _katalogSearchTimer = setTimeout(() => doKatalogSearch(q), 300);
}

async function doKatalogSearch(q) {
  const tbody = document.getElementById('katalogPickerBody');
  const hint  = document.getElementById('katalogSearchHint');
  const tbl   = document.getElementById('katalogPickerTable');
  const src   = document.getElementById('katalogSearchSource')?.value || 'all';
  if (!tbody) return;
  tbody.innerHTML = '';

  const terms = q.trim().toLowerCase().split(/\s+/).filter(t => t.length > 0);

  // -- Local catalog results --
  let localResults = [];
  if (src === 'all' || src === 'katalog') {
    (appData.materialKatalog || []).forEach(k => {
      if (terms.length === 0) { localResults.push(k); return; }
      const hay = (k.bezeichnung + ' ' + k.einheit).toLowerCase();
      if (terms.every(t => hay.includes(t))) localResults.push(k);
    });
  }

  // -- Datanorm results (server) --
  let remoteResults = [];
  if ((src === 'all' || src === 'datanorm') && terms.length > 0 && q.trim().length >= 2) {
    if (hint) { hint.innerHTML = '<div style="text-align:center;padding:16px 0;"><div class="spinner" style="display:inline-block;width:20px;height:20px;border:2px solid var(--grey-200);border-top-color:var(--primary);border-radius:50%;animation:spin .6s linear infinite;margin-right:8px;vertical-align:middle;"></div> Suche läuft...</div>'; hint.style.display = ''; }
    try {
      const res = await fetch('api.php?action=datanorm_search&q=' + encodeURIComponent(q.trim()));
      const data = await res.json();
      remoteResults = data.results || [];
      if (data.hint && remoteResults.length === 0 && localResults.length === 0) {
        if (hint) { hint.textContent = data.hint; hint.style.display = ''; }
        if (tbl) tbl.style.display = 'none';
        return;
      }
    } catch (e) { console.error('Datanorm search:', e); }
  }

  const hasResults = localResults.length > 0 || remoteResults.length > 0;
  const totalCount = localResults.length + remoteResults.length;

  if (!hasResults) {
    if (tbl) tbl.style.display = 'none';
    if (hint) {
      hint.innerHTML = terms.length > 0
        ? '<div style="text-align:center;padding:20px 0;"><div style="font-size:2rem;margin-bottom:8px;">Hinweis</div><div>Keine Ergebnisse für <strong>"' + esc(q.trim()) + '"</strong></div><div style="font-size:.78rem;color:var(--grey-400);margin-top:6px;">Versuchen Sie andere Suchbegriffe oder weniger Wörter</div></div>'
        : '<div style="text-align:center;padding:20px 0;"><div style="font-size:2rem;margin-bottom:8px;">Hinweis</div><div>Suchbegriff eingeben - mindestens 2 Zeichen</div></div>';
      hint.style.display = '';
    }
    return;
  }

  if (tbl) tbl.style.display = '';
  if (hint) hint.style.display = 'none';

  // Result summary bar
  {
    const hdr = document.createElement('tr');
    hdr.innerHTML = `<td colspan="8" style="background:#FDE8EC;padding:6px 12px;font-size:.82rem;color:#1A1A1A;font-weight:500;">
      ${totalCount} Ergebnis${totalCount !== 1 ? 'se' : ''} für "${esc(q.trim())}"${remoteResults.length >= 50 ? ' <span style="color:#E65100;font-weight:600;">(max. 50 Datanorm-Treffer - Suche verfeinern)</span>' : ''}</td>`;
    tbody.appendChild(hdr);
  }

  // Render local
  if (localResults.length > 0) {
    const hdr = document.createElement('tr');
    hdr.innerHTML = `<td colspan="8" style="background:var(--bg-light,#f0f8fa);font-weight:600;padding:6px 12px;font-size:.85rem;">
      Eigener Katalog (${localResults.length})</td>`;
    tbody.appendChild(hdr);
    localResults.forEach(k => {
      const key = 'local:' + k.id;
      const wasSel = _pickerSelected.has(key);
      const qty = wasSel ? _pickerSelected.get(key).anzahl : 1;
      const tr = document.createElement('tr');
      tr.className = 'picker-row';
      tr.innerHTML = `
        <td><input type="checkbox" class="picker-cb" data-key="${key}" data-src="local" data-kid="${k.id}" ${wasSel ? 'checked' : ''} onchange="togglePickerSelection(this)"></td>
        <td style="font-size:.8rem;color:var(--text-muted);">—</td>
        <td>${highlightTerms(k.bezeichnung, terms)}</td>
        <td>${esc(k.einheit)}</td>
        <td class="text-right price-sensitive">${fmt(k.ek)}</td>
        <td class="text-right price-sensitive">${fmt(k.ek * (1 + k.aufschlag / 100))}</td>
        <td><span style="display:inline-block;background:#E8F5E9;color:#2E7D32;padding:1px 6px;border-radius:4px;font-size:.72rem;font-weight:500;">Eigener Katalog</span></td>
        <td><input type="number" class="cell-input text-right picker-qty" data-key="${key}" value="${qty}" min="1" style="width:56px;" onchange="updatePickerQty(this)"></td>`;
      tbody.appendChild(tr);
    });
  }

  // Render Datanorm
  if (remoteResults.length > 0) {
    const hdr = document.createElement('tr');
    hdr.innerHTML = `<td colspan="8" style="background:var(--bg-light,#f0f8fa);font-weight:600;padding:6px 12px;font-size:.85rem;">
      Datanorm / Großhandel (${remoteResults.length}${remoteResults.length >= 50 ? '+' : ''})</td>`;
    tbody.appendChild(hdr);
    remoteResults.forEach((r, i) => {
      const key = 'datanorm:' + r.artNr;
      const wasSel = _pickerSelected.has(key);
      const qty = wasSel ? _pickerSelected.get(key).anzahl : 1;
      // Metallzuschlag für Kabel berechnen (safe)
      let isCable = false, mzInfo = null, ekCell = `<td class="text-right price-sensitive">${fmt(r.ek)}</td>`;
      try {
        const mz = _currentMetallzuschlag;
        isCable = isCableItem(r.bezeichnung);
        if (isCable && mz && mz.delNotierung > 0) {
          mzInfo = calcMetallzuschlag(r.bezeichnung, r.einheit, mz.delNotierung);
        }
        if (mzInfo && mzInfo.zuschlag > 0) {
          const total = r.ek + mzInfo.zuschlag;
          ekCell = `<td class="text-right price-sensitive" style="position:relative;">
            <div style="font-size:.72rem;color:#E65100;text-decoration:line-through;opacity:.7">${fmt(r.ek)}</div>
            <div style="font-weight:600;">${fmt(total)}</div>
            <span class="mz-badge" title="Metallzuschlag ${mzInfo.spec}: +${fmt(mzInfo.zuschlag)} - (DEL ${fmt(mz.delNotierung)} €/100kg)"> +${fmt(mzInfo.zuschlag)}</span>
          </td>`;
        }
      } catch(e) { console.warn('MZ calc:', e); }
      const tr = document.createElement('tr');
      tr.className = 'picker-row' + (isCable && mzInfo && mzInfo.zuschlag > 0 ? ' picker-row-cable' : '');
      tr.innerHTML = `
        <td><input type="checkbox" class="picker-cb" data-key="${key}" data-src="datanorm" data-idx="${i}" ${wasSel ? 'checked' : ''} onchange="togglePickerSelection(this)"></td>
        <td style="font-size:.8rem;font-weight:600;color:#1565C0;">${highlightTerms(r.artNr, terms)}</td>
        <td>${highlightTerms(r.bezeichnung, terms)}${isCable && mzInfo ? '<span class="mz-cable-tag" title="' + mzInfo.spec + ' - Cu-Gewicht: ' + (mzInfo.cuKgPerM * 1000).toFixed(1) + ' g/m"> Kabel</span>' : ''}</td>
        <td>${esc(r.einheit)}</td>
        ${ekCell}
        <td class="text-right price-sensitive">${fmt(r.lp)}</td>
        <td><span style="display:inline-block;background:#E3F2FD;color:#1565C0;padding:1px 6px;border-radius:4px;font-size:.72rem;font-weight:500;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${esc(r.warengruppe)}">${esc(r.warengruppe)}</span></td>
        <td><input type="number" class="cell-input text-right picker-qty" data-key="${key}" value="${qty}" min="1" style="width:56px;" onchange="updatePickerQty(this)"></td>`;
      tr._dnData = r;   // stash for insert
      tbody.appendChild(tr);
    });
  }
  updatePickerCount();
  renderPickerSelectedBar();
}

function togglePickerSelection(cb) {
  const key = cb.dataset.key;
  if (cb.checked) {
    const tr = cb.closest('tr');
    const src = cb.dataset.src;
    const qtyInput = tr?.querySelector('.picker-qty');
    const anzahl = Math.max(1, parseInt(qtyInput?.value) || 1);
    if (src === 'local') {
      const kid = parseInt(cb.dataset.kid);
      const k = (appData.materialKatalog || []).find(k => k.id === kid);
      if (k) _pickerSelected.set(key, { src: 'local', data: k, anzahl, label: k.bezeichnung });
    } else if (src === 'datanorm') {
      const r = tr?._dnData;
      if (r) _pickerSelected.set(key, { src: 'datanorm', data: r, anzahl, label: r.bezeichnung + ' [' + r.artNr + ']' });
    } else if (src === 'top') {
      // v2.0.1: "Oft verbaut" – als plain Material-Eintrag behandeln (wie local ohne ID)
      const bez = cb.dataset.bez || '';
      const einheit = cb.dataset.einheit || 'Stk';
      const ek = parseFloat(cb.dataset.ek || '0') || 0;
      const fakeK = { id: null, bezeichnung: bez, einheit, ek, aufschlag: 0 };
      _pickerSelected.set(key, { src: 'local', data: fakeK, anzahl, label: bez });
    }
  } else {
    _pickerSelected.delete(key);
  }
  updatePickerCount();
  renderPickerSelectedBar();
}

function updatePickerQty(inp) {
  const key = inp.dataset.key;
  const val = Math.max(1, parseInt(inp.value) || 1);
  if (_pickerSelected.has(key)) {
    _pickerSelected.get(key).anzahl = val;
    renderPickerSelectedBar();
  }
}

function removePickerSelection(key) {
  _pickerSelected.delete(key);
  // Uncheck if visible
  const cb = document.querySelector(`.picker-cb[data-key="${key}"]`);
  if (cb) cb.checked = false;
  updatePickerCount();
  renderPickerSelectedBar();
}

function renderPickerSelectedBar() {
  const bar = document.getElementById('pickerSelectedBar');
  if (!bar) return;
  if (_pickerSelected.size === 0) {
    bar.style.display = 'none';
    return;
  }
  bar.style.display = '';
  let html = `<div style="background:#E8F5E9;border:1px solid #C8E6C9;border-radius:6px;padding:8px 12px;margin-bottom:8px;font-size:.82rem;">
    <strong>${_pickerSelected.size} ausgewählt:</strong><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">`;
  _pickerSelected.forEach((v, key) => {
    const label = v.label || '';
    const short = label.length > 35 ? label.substring(0, 32) + '—' : label;
    html += `<span style="display:inline-flex;align-items:center;gap:3px;background:#fff;border:1px solid #A5D6A7;border-radius:4px;padding:2px 6px;font-size:.78rem;">
      ${esc(short)}${v.anzahl > 1 ? ' —' + v.anzahl : ''}
      <button onclick="removePickerSelection('${key}')" style="background:none;border:none;cursor:pointer;color:#C62828;font-size:.9rem;padding:0 2px;line-height:1;" title="Entfernen">—</button>
    </span>`;
  });
  html += '</div></div>';
  bar.innerHTML = html;
}

function updatePickerCount() {
  const n = _pickerSelected.size;
  const el = document.getElementById('katalogPickerCount');
  if (el) el.textContent = n + ' ausgewählt';
}

function insertFromKatalog() {
  const b = getBaustelle();
  if (!b) return;
  if (_pickerSelected.size === 0) { alert('Bitte mindestens eine Position auswählen.'); return; }

  let mzCount = 0;
  const vkDirekt = document.getElementById('katalogImportVkDirekt')?.checked === true;
  _pickerSelected.forEach((item) => {
    if (item.src === 'local') {
      const k = item.data;
      // "Listenpreis als VK": Im lokalen Katalog ist k.ek der EK; der Listen-/Verkaufspreis
      // ist der kalkulierte VK (k.ek + Aufschlag). Bei aktivierter Checkbox wird dieser VK
      // direkt als VK übernommen (kein weiterer Auf-/Global-Aufschlag). Ohne Checkbox bleibt
      // k.ek der EK und der Aufschlag wird regulär angewandt.
      const kEk = parseFloat(k.ek) || 0;
      const kAuf = parseFloat(k.aufschlag) || 0;
      const kVk = kEk * (1 + kAuf / 100);
      b.material.unshift({ id: b.nextMatId++, bezeichnung: k.bezeichnung, anzahl: item.anzahl, einheit: k.einheit, ek: vkDirekt ? kVk : k.ek, aufschlag: vkDirekt ? 0 : k.aufschlag, rabatt: 0, vkDirekt: vkDirekt, kategorieId: null, erstelltVon: currentKuerzel, datum: new Date().toISOString().split('T')[0] });
    } else if (item.src === 'datanorm') {
      const r = item.data;
      let ek = r.ek;
      let bezSuffix = '';
      // Metallzuschlag für Kabel automatisch aufrechnen (safe)
      try {
        const mz = _currentMetallzuschlag;
        if (mz && mz.delNotierung > 0 && isCableItem(r.bezeichnung)) {
          const mzCalc = calcMetallzuschlag(r.bezeichnung, r.einheit, mz.delNotierung);
          if (mzCalc && mzCalc.zuschlag > 0) {
            ek = Math.round((ek + mzCalc.zuschlag) * 10000) / 10000;
            bezSuffix = ' [MZ+' + fmt(mzCalc.zuschlag) + ']';
            mzCount++;
          }
        }
      } catch(e) { console.warn('MZ insert:', e); }
      const bez = r.bezeichnung + ' [' + r.artNr + ']' + bezSuffix;
      b.material.unshift({ id: b.nextMatId++, bezeichnung: bez, anzahl: item.anzahl, einheit: r.einheit, ek: ek, aufschlag: 0, rabatt: 0, vkDirekt: vkDirekt, kategorieId: null, erstelltVon: currentKuerzel, datum: new Date().toISOString().split('T')[0] });
    }
  });

  const count = _pickerSelected.size;
  _pickerSelected.clear();
  openMatCategory('__none__', b);
  saveData();
  closeKatalogPickerModal();
  renderMatRows();
  recalc();
  const mzNote = mzCount > 0 ? ` (${mzCount}— inkl. Metallzuschlag)` : '';
  showNotification(count + ' Position(en) eingefügt.' + mzNote);
}

// ============================================================
// EXCEL EXPORT
// ============================================================
function exportToExcel() {
  if (appData.baustellen.length === 0) {
    alert('Keine Baustellen vorhanden zum Exportieren.');
    return;
  }

  const wb = XLSX.utils.book_new();
  const usedNames = new Set();

  appData.baustellen.forEach(b => {
    const rows = [];

    // -- Title --
    rows.push([b.name]);
    rows.push([]);

    // -- MATERIAL --
    rows.push(['MATERIAL']);
    if (b.materialAufschlagGlobal) rows.push(['Globaler Aufschlag:', b.materialAufschlagGlobal + ' %']);
    rows.push(['Bezeichnung', 'Anzahl', 'Einheit', 'EK-Preis (€)', 'Aufschlag (%)', 'VK-Preis (€)', 'Gesamt (€)']);

    let matSum = 0;
    b.material.forEach(r => {
      const vk = matVk(r, b);
      const g  = vk * r.anzahl;
      matSum  += g;
      rows.push([r.bezeichnung, r.anzahl, r.einheit, r.ek, r.aufschlag, vk, g]);
    });
    if (b.material.length === 0) rows.push(['— keine Positionen —']);
    rows.push(['', '', '', '', '', 'Material Gesamt (€)', matSum]);
    rows.push([]);

    // -- ARBEITSZEIT --
    rows.push(['ARBEITSZEIT']);
    rows.push(['Beschreibung', 'Datum', 'Stunden (h)', 'Stundenpreis (€)', 'Gesamt (€)']);

    let azSum = 0;
    b.arbeitszeit.forEach(r => {
      const g = r.stunden * r.stundenpreis;
      azSum  += g;
      rows.push([r.beschreibung, r.datum || '', r.stunden, r.stundenpreis, g]);
    });
    if (b.arbeitszeit.length === 0) rows.push(['— keine Positionen —']);
    rows.push(['', '', '', 'Arbeitszeit Gesamt (€)', azSum]);
    rows.push([]);

    // -- PAUSCHALEN --
    rows.push(['PAUSCHALEN']);
    rows.push(['Bezeichnung', 'Anzahl', 'Einzelpreis (€)', 'Gesamt (€)']);

    let pSum = 0;
    b.pauschalen.forEach(entry => {
      const p = appData.pauschalen.find(p => p.id === entry.id);
      if (p) { const g = p.preis * (entry.anzahl || 1); pSum += g; rows.push([p.name, entry.anzahl || 1, p.preis, g]); }
    });
    if (b.pauschalen.length === 0) rows.push(['— keine Pauschalen aktiviert —']);
    rows.push(['', '', 'Pauschalen Gesamt (€)', pSum]);
    rows.push([]);

    // -- GESAMT --
    rows.push(['GESAMTSUMME (€)', matSum + azSum + pSum]);
    rows.push([]);

    // -- ABSCHLAGSRECHNUNGEN --
    rows.push(['ABSCHLAGSRECHNUNGEN']);
    rows.push(['Bezeichnung / Rechnungsnummer', 'Betrag (€)']);
    let abschlagSum = 0;
    (b.abschlaege || []).forEach(r => {
      abschlagSum += r.betrag;
      rows.push([r.bezeichnung, r.betrag]);
    });
    if ((b.abschlaege || []).length === 0) rows.push(['— keine Abschlagsrechnungen —']);
    rows.push(['Abschläge Gesamt (€)', abschlagSum]);
    rows.push([]);
    rows.push(['OFFENER BETRAG (€)', (matSum + azSum + pSum) - abschlagSum]);

    // -- Build sheet --
    const ws = XLSX.utils.aoa_to_sheet(rows);
    ws['!cols'] = [
      { wch: 36 }, { wch: 10 }, { wch: 10 },
      { wch: 14 }, { wch: 14 }, { wch: 14 }, { wch: 14 }
    ];

    // Apply number format to numeric cells
    applyNumberFormat(ws, '#,##0.00');

    // Sheet name: max 31 chars, no special chars, unique
    let sn = b.name.substring(0, 31).replace(/[\\/*?:[\]]/g, '_');
    if (usedNames.has(sn)) {
      let i = 2;
      while (usedNames.has(sn.substring(0, 28) + '_' + i)) i++;
      sn = sn.substring(0, 28) + '_' + i;
    }
    usedNames.add(sn);
    XLSX.utils.book_append_sheet(wb, ws, sn);
  });

  // -- SUMMARY SHEET --
  const sumRows = [
    ['ZUSAMMENFASSUNG ALLE BAUSTELLEN'],
    [],
    ['Baustelle', 'Material (€)', 'Arbeitszeit (€)', 'Pauschalen (€)', 'Gesamt (€)', 'Abschläge (€)', 'Offener Betrag (€)']
  ];
  let grandGrand = 0, grandAbschlag = 0;

  appData.baustellen.forEach(b => {
    let ms = 0, as = 0, ps = 0, abs = 0;
    b.material.forEach(r => { ms += matVk(r, b) * r.anzahl; });
    b.arbeitszeit.forEach(r => { as += r.stunden * r.stundenpreis; });
    b.pauschalen.forEach(entry => {
      const p = appData.pauschalen.find(p => p.id === entry.id);
      if (p) ps += p.preis * (entry.anzahl || 1);
    });
    (b.abschlaege || []).forEach(r => { abs += r.betrag; });
    grandGrand   += ms + as + ps;
    grandAbschlag += abs;
    sumRows.push([b.name, ms, as, ps, ms + as + ps, abs, (ms + as + ps) - abs]);
  });

  sumRows.push([]);
  sumRows.push(['GESAMT ALLE BAUSTELLEN', '', '', '', grandGrand, grandAbschlag, grandGrand - grandAbschlag]);

  const sumWs = XLSX.utils.aoa_to_sheet(sumRows);
  sumWs['!cols'] = [{ wch: 36 }, { wch: 16 }, { wch: 16 }, { wch: 16 }, { wch: 16 }, { wch: 16 }, { wch: 18 }];
  applyNumberFormat(sumWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, sumWs, 'Zusammenfassung');

  // -- Download --
  const date = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(wb, `Baukalkulation_${date}.xlsx`);
}

