  const rows = [
    [`Material - ${b.name}`],
    [],
    ['Bezeichnung', 'Anzahl', 'Einheit', 'EK (€)', 'Aufschlag (%)', 'VK (€)', 'Gesamt (€)']
  ];
  let total = 0;
  b.material.forEach(r => {
    const vk = matVk(r, b); const g = vk * r.anzahl; total += g;
    rows.push([r.bezeichnung, r.anzahl, r.einheit, r.ek, r.aufschlag, vk, g]);
  });
  rows.push([]);
  rows.push(['', '', '', '', '', 'Material Gesamt (€)', total]);

