// ============================================================
// COMPLETE BAUSTELLE EXPORT  (Excel + PDF)
// ============================================================
async function exportBaustelleExcel() {
  const b = getBaustelle();
  if (!b) return;

  // Hat das aktuelle Projekt Unterprojekte? -> Auswahl anbieten.
  const subs = getSubprojectsRecursive(b.id);
  let bundleIds = null;
  if (subs.length > 0 && !b.parentId) {
    bundleIds = await showSubprojectSelectionModal(b, subs, {
      title: 'Excel-Export: Unterprojekte einbeziehen',
      intro: `"${b.name}" hat ${subs.length} Unterprojekt(e). Welche sollen mit exportiert werden?`,
      confirmLabel: 'Excel erstellen',
      parentLockedLabel: 'Hauptprojekt – wird immer exportiert'
    });
    if (!bundleIds) return;
  }

  const wb = XLSX.utils.book_new();

  if (bundleIds && bundleIds.length > 1) {
    // Bündel-Export: Übersicht + ein Sheet pro Baustelle (kompaktes Format)
    const ovRows = [['SAMMEL-EXPORT'], [],
      ['Hauptprojekt:', b.name + (b.projektNr ? '  (' + b.projektNr + ')' : '')],
      ['Anzahl Baustellen:', bundleIds.length],
      ['Exportiert am:', new Date().toLocaleString('de-DE')],
      [],
      ['Projekt-Nr.', 'Name', 'Typ', 'Material (€)', 'Arbeitszeit (€)', 'Pauschalen (€)', 'Gesamt (€)']
    ];
    let gMat = 0, gAz = 0, gP = 0;
    bundleIds.forEach(bid => {
      const x = appData.baustellen.find(z => z.id === bid);
      if (!x) return;
      const { matSum, azSum, pSum } = buildBaustelleArchiveRows(x);
      gMat += matSum; gAz += azSum; gP += pSum;
      ovRows.push([
        x.projektNr || '',
        x.name,
        x.parentId ? 'Unterprojekt' : 'Hauptprojekt',
        matSum, azSum, pSum, matSum + azSum + pSum
      ]);
      appendBaustelleSheet(wb, x);
    });
    ovRows.push([]);
    ovRows.push(['', '', 'GESAMT', gMat, gAz, gP, gMat + gAz + gP]);
    const ovWs = XLSX.utils.aoa_to_sheet(ovRows);
    ovWs['!cols'] = [{wch:14},{wch:30},{wch:14},{wch:16},{wch:16},{wch:16},{wch:16}];
    applyNumberFormat(ovWs, '#,##0.00');
    // Übersicht als erstes Sheet einfügen
    XLSX.utils.book_append_sheet(wb, ovWs, 'Übersicht');
    const sheetNames = wb.SheetNames;
    if (sheetNames.length > 1) {
      sheetNames.unshift(sheetNames.pop());
      wb.SheetNames = sheetNames;
    }
    XLSX.writeFile(wb, `Projekte_${b.name.replace(/[^a-zA-Z0-9_-]/g,'_')}_${new Date().toISOString().slice(0,10)}.xlsx`);
    return;
  }

  // ---- Einzel-Export (bestehendes Format, mehrere Kategorie-Sheets) ----
  const ga = b.materialAufschlagGlobal || 0;

  // -- Material Sheet --
  const matRows = [['MATERIAL - ' + b.name], [], ['Bezeichnung', 'Anzahl', 'Einheit', 'EK (€)', 'Aufschlag (%)', 'VK (€)', 'Gesamt (€)']];
  let matSum = 0;
  b.material.forEach(r => {
    const vk = matVk(r, b); const g = vk * r.anzahl; matSum += g;
    matRows.push([r.bezeichnung, r.anzahl, r.einheit, r.ek, r.aufschlag, vk, g]);
  });
  matRows.push([]); matRows.push(['', '', '', '', '', 'Material Gesamt (€)', matSum]);
  const matWs = XLSX.utils.aoa_to_sheet(matRows);
  matWs['!cols'] = [{ wch: 36 }, { wch: 10 }, { wch: 10 }, { wch: 12 }, { wch: 14 }, { wch: 12 }, { wch: 14 }];
  applyNumberFormat(matWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, matWs, 'Material');

  // -- Arbeitszeit Sheet --
  const azRows = [['ARBEITSZEIT - ' + b.name], [], ['Beschreibung', 'Datum', 'Stunden (h)', 'Stundenkategorie', 'Stundenpreis (€)', 'Gesamt (€)']];
  let azSum = 0;
  b.arbeitszeit.forEach(r => {
    const g = r.stunden * r.stundenpreis; azSum += g;
    const katName = r.stundenKatId ? ((appData.stundenKatalog || []).find(k => k.id === r.stundenKatId)?.kategorie || '') : '';
    azRows.push([r.beschreibung, r.datum || '', r.stunden, katName, r.stundenpreis, g]);
  });
  azRows.push([]); azRows.push(['', '', '', '', 'Arbeitszeit Gesamt (€)', azSum]);
  const azWs = XLSX.utils.aoa_to_sheet(azRows);
  azWs['!cols'] = [{ wch: 36 }, { wch: 14 }, { wch: 12 }, { wch: 18 }, { wch: 16 }, { wch: 14 }];
  applyNumberFormat(azWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, azWs, 'Arbeitszeit');

  // -- Pauschalen Sheet --
  const pRows = [['PAUSCHALEN - ' + b.name], [], ['Bezeichnung', 'Anzahl', 'Einzelpreis (€)', 'Gesamt (€)']];
  let pSum = 0;
  b.pauschalen.forEach(entry => {
    const p = appData.pauschalen.find(p => p.id === entry.id);
    if (p) { const g = p.preis * (entry.anzahl || 1); pSum += g; pRows.push([p.name, entry.anzahl || 1, p.preis, g]); }
  });
  pRows.push([]); pRows.push(['', '', 'Pauschalen Gesamt (€)', pSum]);
  const pWs = XLSX.utils.aoa_to_sheet(pRows);
  pWs['!cols'] = [{ wch: 36 }, { wch: 10 }, { wch: 16 }, { wch: 16 }];
  applyNumberFormat(pWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, pWs, 'Pauschalen');

  // -- Abschläge Sheet --
  const abRows = [['ABSCHLAGSRECHNUNGEN - ' + b.name], [], ['Bezeichnung', 'Betrag (€)']];
  let abSum = 0;
  (b.abschlaege || []).forEach(r => { abSum += r.betrag; abRows.push([r.bezeichnung, r.betrag]); });
  abRows.push([]); abRows.push(['Abschläge Gesamt (€)', abSum]);
  const abWs = XLSX.utils.aoa_to_sheet(abRows);
  abWs['!cols'] = [{ wch: 36 }, { wch: 16 }];
  applyNumberFormat(abWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, abWs, 'Abschläge');

  // -- Zusammenfassung Sheet --
  const grand = matSum + azSum + pSum;
  const offen = grand - abSum;
  const sumRows = [
    ['ZUSAMMENFASSUNG - ' + b.name], [],
    ['Position', 'Betrag (€)'],
    ['Material', matSum],
    ['Arbeitszeit', azSum],
    ['Pauschalen', pSum],
    [], ['Gesamtsumme', grand],
    [], ['Abschläge', abSum],
    ['Offener Betrag', offen]
  ];
  const sumWs = XLSX.utils.aoa_to_sheet(sumRows);
  sumWs['!cols'] = [{ wch: 24 }, { wch: 18 }];
  applyNumberFormat(sumWs, '#,##0.00');
  XLSX.utils.book_append_sheet(wb, sumWs, 'Zusammenfassung');

  XLSX.writeFile(wb, `Baustelle_${b.name.replace(/[^a-zA-Z0-9———————_-]/g,'_')}_${new Date().toISOString().slice(0,10)}.xlsx`);
}

function exportBaustellePDF() {
  const b = getBaustelle();
  if (!b) return;
  const subs = (!b.parentId) ? getSubprojectsRecursive(b.id) : [];

  const startSingle = (htmlFinal, fileName) => {
    if (typeof html2pdf === 'undefined') {
      const s = document.createElement('script');
      s.src = 'lib/html2pdf.bundle.min.js';
      s.onload = () => _generateBaustellePDF(htmlFinal, fileName);
      document.head.appendChild(s);
    } else {
      _generateBaustellePDF(htmlFinal, fileName);
    }
  };

  if (subs.length === 0) {
    startSingle(_buildBaustellePdfHtml(b, { wrap: true }), b.name);
    return;
  }

  showSubprojectSelectionModal(b, subs, {
    title: 'PDF-Export: Unterprojekte einbeziehen',
    intro: `"${b.name}" hat ${subs.length} Unterprojekt(e). Welche sollen mit ins PDF?`,
    confirmLabel: 'PDF erstellen',
    parentLockedLabel: 'Hauptprojekt – wird immer exportiert'
  }).then(ids => {
    if (!ids) return;
    if (ids.length === 1) {
      startSingle(_buildBaustellePdfHtml(b, { wrap: true }), b.name);
      return;
    }
    // Mehrere Baustellen: Sammel-PDF mit Übersicht + jeweils einer Sektion
    const baustellen = ids.map(id => appData.baustellen.find(x => x.id === id)).filter(Boolean);
    let totMat = 0, totAz = 0, totP = 0, totAb = 0;
    const blocks = baustellen.map((x, i) => {
      const block = _buildBaustellePdfHtml(x, { wrap: false });
      totMat += block.matSum; totAz += block.azSum; totP += block.pSum; totAb += block.abSum;
      const pageBreak = i > 0 ? 'page-break-before:always;' : '';
      return `<div style="${pageBreak}">${block.html}</div>`;
    }).join('');

    const totGrand = totMat + totAz + totP;
    const totOffen = totGrand - totAb;
    const overview = `
      <div style="font-family:Arial,sans-serif;font-size:12px;max-width:800px;margin:0 auto;padding:20px;">
        <style>tr{page-break-inside:avoid}table{page-break-inside:auto}h2{page-break-after:avoid}tfoot{page-break-inside:avoid}</style>
        <h1 style="font-size:18px;border-bottom:2px solid #00B4D8;padding-bottom:8px;color:#00B4D8;">Sammel-Export: ${esc(b.name)}</h1>
        <p style="color:#888;font-size:11px;">${baustellen.length} Baustellen · Exportiert am ${new Date().toLocaleDateString('de-DE')}</p>
        <table style="width:100%;border-collapse:collapse;font-size:11px;margin-top:12px">
          <thead><tr style="background:#FDE8EC;">
            <th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Projekt-Nr.</th>
            <th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Name</th>
            <th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Typ</th>
            <th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt (€)</th>
          </tr></thead><tbody>
          ${baustellen.map(x => {
            const blk = _buildBaustellePdfHtml(x, { wrap: false, sumOnly: true });
            return `<tr>
              <td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(x.projektNr || '')}</td>
              <td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(x.name)}</td>
              <td style="padding:3px 6px;border-bottom:1px solid #eee;">${x.parentId ? 'Unterprojekt' : 'Hauptprojekt'}</td>
              <td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(blk.matSum + blk.azSum + blk.pSum)}</td>
            </tr>`;
          }).join('')}
          </tbody>
          <tfoot><tr style="background:#FDE8EC;font-weight:700">
            <td colspan="3" style="text-align:right;padding:4px 6px;">GESAMT:</td>
            <td style="text-align:right;padding:4px 6px;">${fmtNum(totGrand)} €</td>
          </tr></tfoot>
        </table>
        <div style="margin-top:18px;padding:12px;background:#FDE8EC;border-radius:6px;">
          <table style="width:100%;font-size:13px;"><tbody>
            <tr><td style="padding:3px 0;font-weight:600;">Material gesamt:</td><td style="text-align:right;padding:3px 0;">${fmtNum(totMat)} €</td></tr>
            <tr><td style="padding:3px 0;font-weight:600;">Arbeitszeit gesamt:</td><td style="text-align:right;padding:3px 0;">${fmtNum(totAz)} €</td></tr>
            <tr><td style="padding:3px 0;font-weight:600;">Pauschalen gesamt:</td><td style="text-align:right;padding:3px 0;">${fmtNum(totP)} €</td></tr>
            <tr style="border-top:2px solid #00B4D8;"><td style="padding:6px 0 3px;font-weight:700;font-size:14px;">Summe:</td><td style="text-align:right;padding:6px 0 3px;font-weight:700;font-size:14px;">${fmtNum(totGrand)} €</td></tr>
            <tr><td style="padding:3px 0;font-weight:600;">Abschläge:</td><td style="text-align:right;padding:3px 0;">-${fmtNum(totAb)} €</td></tr>
            <tr style="border-top:1px solid #ccc;"><td style="padding:6px 0 3px;font-weight:700;font-size:14px;color:#00B4D8;">Offen gesamt:</td><td style="text-align:right;padding:6px 0 3px;font-weight:700;font-size:14px;color:#00B4D8;">${fmtNum(totOffen)} €</td></tr>
          </tbody></table>
        </div>
      </div>`;

    startSingle(overview + blocks, 'Projekte_' + b.name);
  });
}

// Liefert das HTML eines Baustellen-Blocks (ohne/mit äußerem Wrapper).
// opts.wrap=true hängt den vollständigen Container an. opts.sumOnly verzichtet
// auf das HTML und liefert nur die berechneten Summen.
function _buildBaustellePdfHtml(b, opts = {}) {
  let matSum = 0, azSum = 0, pSum = 0, abSum = 0;
  let inner = '';

  inner += `<h1 style="font-size:18px;border-bottom:2px solid #00B4D8;padding-bottom:8px;color:#00B4D8;">${esc(b.name)}${b.projektNr ? ` <small style="color:#888;font-size:12px">(${esc(b.projektNr)})</small>` : ''}</h1>
    <p style="color:#888;font-size:11px;">${b.parentId ? 'Unterprojekt · ' : ''}Exportiert am ${new Date().toLocaleDateString('de-DE')}</p>`;

  // Material
  inner += '<h2 style="font-size:14px;margin-top:18px;color:#333;">Material</h2>';
  if (b.material.length > 0) {
    inner += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Bezeichnung</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Anzahl</th><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Einheit</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">VK (€)</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt (€)</th></tr></thead><tbody>';
    b.material.forEach(r => {
      const vk = matVk(r, b); const g = vk * r.anzahl; matSum += g;
      inner += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.bezeichnung)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${r.anzahl}</td><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.einheit)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(vk)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(g)}</td></tr>`;
    });
    inner += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;font-weight:bold;padding:4px 6px;">Material Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(matSum)} €</td></tr></tfoot></table>`;
  } else { inner += '<p style="color:#999;">Keine Materialpositionen.</p>'; }

  // Arbeitszeit
  inner += '<h2 style="font-size:14px;margin-top:18px;color:#333;">Arbeitszeit</h2>';
  if (b.arbeitszeit.length > 0) {
    inner += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Beschreibung</th><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Datum</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Stunden</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">€/h</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt (€)</th></tr></thead><tbody>';
    b.arbeitszeit.forEach(r => {
      const g = r.stunden * r.stundenpreis; azSum += g;
      inner += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.beschreibung)}</td><td style="padding:3px 6px;border-bottom:1px solid #eee;">${r.datum || ''}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${r.stunden}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.stundenpreis)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(g)}</td></tr>`;
    });
    inner += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;font-weight:bold;padding:4px 6px;">Arbeitszeit Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(azSum)} €</td></tr></tfoot></table>`;
  } else { inner += '<p style="color:#999;">Keine Arbeitszeiten.</p>'; }

  // Pauschalen
  inner += '<h2 style="font-size:14px;margin-top:18px;color:#333;">Pauschalen</h2>';
  const pauschEntries = (b.pauschalen || []).map(entry => {
    const p = appData.pauschalen.find(p => p.id === entry.id);
    return p ? { name: p.name, preis: p.preis, anzahl: entry.anzahl || 1 } : null;
  }).filter(Boolean);
  if (pauschEntries.length > 0) {
    inner += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Bezeichnung</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Anzahl</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Einzelpreis (€)</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt (€)</th></tr></thead><tbody>';
    pauschEntries.forEach(p => {
      const g = p.preis * p.anzahl; pSum += g;
      inner += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(p.name)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${p.anzahl}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(p.preis)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(g)}</td></tr>`;
    });
    inner += `</tbody><tfoot><tr><td colspan="3" style="text-align:right;font-weight:bold;padding:4px 6px;">Pauschalen Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(pSum)} €</td></tr></tfoot></table>`;
  } else { inner += '<p style="color:#999;">Keine aktiven Pauschalen.</p>'; }

  // Abschläge
  inner += '<h2 style="font-size:14px;margin-top:18px;color:#333;">Abschlagsrechnungen</h2>';
  const abschlaege = b.abschlaege || [];
  if (abschlaege.length > 0) {
    inner += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Bezeichnung</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Betrag (€)</th></tr></thead><tbody>';
    abschlaege.forEach(r => { abSum += r.betrag; inner += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.bezeichnung)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.betrag)}</td></tr>`; });
    inner += `</tbody><tfoot><tr><td style="text-align:right;font-weight:bold;padding:4px 6px;">Abschläge Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(abSum)} €</td></tr></tfoot></table>`;
  } else { inner += '<p style="color:#999;">Keine Abschlagsrechnungen.</p>'; }

  if (opts.sumOnly) return { html: '', matSum, azSum, pSum, abSum };

  // Summary
  const grand = matSum + azSum + pSum;
  const offen = grand - abSum;
  inner += `<div style="margin-top:24px;padding:12px;background:#FDE8EC;border-radius:6px;">
    <table style="width:100%;font-size:13px;"><tbody>
      <tr><td style="padding:3px 0;font-weight:600;">Material:</td><td style="text-align:right;padding:3px 0;">${fmtNum(matSum)} €</td></tr>
      <tr><td style="padding:3px 0;font-weight:600;">Arbeitszeit:</td><td style="text-align:right;padding:3px 0;">${fmtNum(azSum)} €</td></tr>
      <tr><td style="padding:3px 0;font-weight:600;">Pauschalen:</td><td style="text-align:right;padding:3px 0;">${fmtNum(pSum)} €</td></tr>
      <tr style="border-top:2px solid #00B4D8;"><td style="padding:6px 0 3px;font-weight:700;font-size:14px;">Gesamtsumme:</td><td style="text-align:right;padding:6px 0 3px;font-weight:700;font-size:14px;">${fmtNum(grand)} €</td></tr>
      <tr><td style="padding:3px 0;font-weight:600;">Abschläge:</td><td style="text-align:right;padding:3px 0;">-${fmtNum(abSum)} €</td></tr>
      <tr style="border-top:1px solid #ccc;"><td style="padding:6px 0 3px;font-weight:700;font-size:14px;color:#00B4D8;">Offener Betrag:</td><td style="text-align:right;padding:6px 0 3px;font-weight:700;font-size:14px;color:#00B4D8;">${fmtNum(offen)} €</td></tr>
    </tbody></table>
  </div>`;

  if (opts.wrap) {
    return `<div style="font-family:Arial,sans-serif;font-size:12px;max-width:800px;margin:0 auto;padding:20px;">
      <style>tr{page-break-inside:avoid}table{page-break-inside:auto}h2{page-break-after:avoid}tfoot{page-break-inside:avoid}</style>
      ${inner}
    </div>`;
  }
  return { html: inner, matSum, azSum, pSum, abSum };
}

function _generateBaustellePDF(html, name) {
  const container = document.createElement('div');
  container.innerHTML = html;
  document.body.appendChild(container);
  html2pdf().set({
    margin: [15, 10, 15, 10],
    filename: `Baustelle_${name.replace(/[^a-zA-Z0-9———————_-]/g,'_')}_${new Date().toISOString().slice(0,10)}.pdf`,
    image: { type: 'jpeg', quality: 0.95 },
    html2canvas: { scale: 2 },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
    pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
  }).from(container).save().then(() => { document.body.removeChild(container); });
}

function fmtNum(v) {
  return (v || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// ============================================================
// GEWINN DETAIL MODAL
// ============================================================
function openGewinnDetailModal() {
  const b = getBaustelle();
  if (!b) return;

  let matVkSum = 0, matEkSum = 0;
  b.material.forEach(r => { matVkSum += matVk(r, b) * r.anzahl; matEkSum += r.ek * r.anzahl; });
  const matGewinn = matVkSum - matEkSum;

  let azSum = 0, azFk = 0;
  b.arbeitszeit.forEach(r => { azSum += r.stunden * r.stundenpreis; azFk += r.stunden * (r.fixkosten || 0); });
  const azGewinn = azSum - azFk;

  let pSum = 0;
  b.pauschalen.forEach(entry => {
    const p = appData.pauschalen.find(p => p.id === entry.id);
    if (p) pSum += p.preis * (entry.anzahl || 1);
  });

  const totalGewinn = matGewinn + azGewinn + pSum;

  // Detail per AZ row
  const azDetails = b.arbeitszeit.map(r => ({
    beschreibung: r.beschreibung || '(ohne)',
    datum: r.datum || '',
    stunden: r.stunden,
    einnahme: r.stunden * r.stundenpreis,
    fixkosten: r.stunden * (r.fixkosten || 0),
    gewinn: (r.stunden * r.stundenpreis) - (r.stunden * (r.fixkosten || 0))
  }));

  // Detail per Material row
  const matDetails = b.material.map(r => {
    const vk = matVk(r, b) * r.anzahl;
    const ek = r.ek * r.anzahl;
    return { bezeichnung: r.bezeichnung || '(ohne)', anzahl: r.anzahl, vkGesamt: vk, ekGesamt: ek, gewinn: vk - ek };
  });

  let m = document.getElementById('gewinnDetailModal');
  if (!m) {
    m = document.createElement('div');
    m.id = 'gewinnDetailModal';
    m.className = 'modal-overlay';
    document.body.appendChild(m);
  }

  m.innerHTML = `<div class="modal-box" style="max-width:900px;">
    <div class="modal-header"><h3>${ico('coins')} Gewinn-Aufstellung: ${esc(b.name)}</h3><button class="modal-close" onclick="hide('gewinnDetailModal')">&times;</button></div>
    <div class="modal-body" style="max-height:70vh;overflow-y:auto;">

      <!-- Summary KPI -->
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px;">
        <div style="flex:1;min-width:140px;padding:12px;background:var(--bg-light,#f0f8fa);border-radius:8px;border-left:3px solid var(--primary,#0071E3);">
          <div style="font-size:.75rem;color:var(--grey-400);">Material-Gewinn</div>
          <div style="font-size:1.1rem;font-weight:700;color:${matGewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmtNum(matGewinn)} €</div>
          <div style="font-size:.7rem;color:var(--grey-400);">VK ${fmtNum(matVkSum)} - EK ${fmtNum(matEkSum)} €</div>
        </div>
        <div style="flex:1;min-width:140px;padding:12px;background:var(--bg-light,#f0f8fa);border-radius:8px;border-left:3px solid var(--primary,#0071E3);">
          <div style="font-size:.75rem;color:var(--grey-400);">Arbeitszeit-Gewinn</div>
          <div style="font-size:1.1rem;font-weight:700;color:${azGewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmtNum(azGewinn)} €</div>
          <div style="font-size:.7rem;color:var(--grey-400);">Einnahmen ${fmtNum(azSum)} - Fixkosten ${fmtNum(azFk)} €</div>
        </div>
        <div style="flex:1;min-width:140px;padding:12px;background:var(--bg-light,#f0f8fa);border-radius:8px;border-left:3px solid var(--primary,#0071E3);">
          <div style="font-size:.75rem;color:var(--grey-400);">Pauschalen</div>
          <div style="font-size:1.1rem;font-weight:700;color:var(--success,#198754)">${fmtNum(pSum)} €</div>
          <div style="font-size:.7rem;color:var(--grey-400);">100% Gewinn</div>
        </div>
        <div style="flex:1;min-width:140px;padding:12px;background:#E8F5E9;border-radius:8px;border-left:3px solid var(--success,#198754);">
          <div style="font-size:.75rem;font-weight:600;">Gewinn Gesamt</div>
          <div style="font-size:1.3rem;font-weight:700;color:${totalGewinn >= 0 ? 'var(--success,#198754)' : 'var(--danger,#dc3545)'}">${fmtNum(totalGewinn)} €</div>
        </div>
      </div>

      <!-- Material Detail -->
      <h4 style="font-size:.9rem;margin:12px 0 6px;">Material-Positionen</h4>
      ${matDetails.length > 0 ? `<table style="width:100%;border-collapse:collapse;font-size:.8rem;">
        <thead><tr style="background:var(--grey-50,#F5F5F7);">
          <th style="text-align:left;padding:4px 8px;">Bezeichnung</th>
          <th style="text-align:right;padding:4px 8px;">Anz.</th>
          <th style="text-align:right;padding:4px 8px;">VK Ges.</th>
          <th style="text-align:right;padding:4px 8px;">EK Ges.</th>
          <th style="text-align:right;padding:4px 8px;">Gewinn</th>
        </tr></thead>
        <tbody>${matDetails.map(r => `<tr>
          <td style="padding:3px 8px;border-bottom:1px solid var(--grey-100);">${esc(r.bezeichnung)}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${r.anzahl}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${fmtNum(r.vkGesamt)}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${fmtNum(r.ekGesamt)}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);color:${r.gewinn >= 0 ? 'var(--success)' : 'var(--danger)'};font-weight:600;">${fmtNum(r.gewinn)}</td>
        </tr>`).join('')}</tbody>
        <tfoot><tr style="font-weight:700;border-top:2px solid var(--grey-200);"><td colspan="4" style="text-align:right;padding:4px 8px;">Gesamt:</td><td style="text-align:right;padding:4px 8px;color:${matGewinn >= 0 ? 'var(--success)' : 'var(--danger)'};">${fmtNum(matGewinn)} €</td></tr></tfoot>
      </table>` : '<p style="color:var(--grey-400);font-size:.82rem;">Keine Materialien.</p>'}

      <!-- Arbeitszeit Detail -->
      <h4 style="font-size:.9rem;margin:16px 0 6px;">Arbeitszeit-Positionen</h4>
      ${azDetails.length > 0 ? `<table style="width:100%;border-collapse:collapse;font-size:.8rem;">
        <thead><tr style="background:var(--grey-50,#F5F5F7);">
          <th style="text-align:left;padding:4px 8px;">Beschreibung</th>
          <th style="text-align:left;padding:4px 8px;">Datum</th>
          <th style="text-align:right;padding:4px 8px;">Std.</th>
          <th style="text-align:right;padding:4px 8px;">Einnahme</th>
          <th style="text-align:right;padding:4px 8px;">Fixkosten</th>
          <th style="text-align:right;padding:4px 8px;">Gewinn</th>
        </tr></thead>
        <tbody>${azDetails.map(r => `<tr>
          <td style="padding:3px 8px;border-bottom:1px solid var(--grey-100);">${esc(r.beschreibung)}</td>
          <td style="padding:3px 8px;border-bottom:1px solid var(--grey-100);">${r.datum}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${r.stunden}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${fmtNum(r.einnahme)}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);">${fmtNum(r.fixkosten)}</td>
          <td style="text-align:right;padding:3px 8px;border-bottom:1px solid var(--grey-100);color:${r.gewinn >= 0 ? 'var(--success)' : 'var(--danger)'};font-weight:600;">${fmtNum(r.gewinn)}</td>
        </tr>`).join('')}</tbody>
        <tfoot><tr style="font-weight:700;border-top:2px solid var(--grey-200);"><td colspan="5" style="text-align:right;padding:4px 8px;">Gesamt:</td><td style="text-align:right;padding:4px 8px;color:${azGewinn >= 0 ? 'var(--success)' : 'var(--danger)'};">${fmtNum(azGewinn)} €</td></tr></tfoot>
      </table>` : '<p style="color:var(--grey-400);font-size:.82rem;">Keine Arbeitszeiten.</p>'}

    </div>
    <div class="modal-footer" style="display:flex;gap:8px;justify-content:flex-end;padding:12px 20px;border-top:1px solid var(--grey-100);">
      <button class="btn btn-secondary btn-sm" onclick="exportGewinnDetailPDF()">${ico('download')} PDF Export</button>
      <button class="btn btn-primary btn-sm" onclick="hide('gewinnDetailModal')">Schließen</button>
    </div>
  </div>`;
  show('gewinnDetailModal');
}

function exportGewinnDetailPDF() {
  const b = getBaustelle();
  if (!b) return;

  let matVkSum = 0, matEkSum = 0;
  b.material.forEach(r => { matVkSum += matVk(r, b) * r.anzahl; matEkSum += r.ek * r.anzahl; });
  const matGewinn = matVkSum - matEkSum;
  let azSum = 0, azFk = 0;
  b.arbeitszeit.forEach(r => { azSum += r.stunden * r.stundenpreis; azFk += r.stunden * (r.fixkosten || 0); });
  const azGewinn = azSum - azFk;
  let pSum = 0;
  b.pauschalen.forEach(entry => { const p = appData.pauschalen.find(p => p.id === entry.id); if (p) pSum += p.preis * (entry.anzahl || 1); });
  const totalGewinn = matGewinn + azGewinn + pSum;

  let html = `<div style="font-family:Arial,sans-serif;font-size:12px;max-width:800px;margin:0 auto;padding:20px;">
    <h1 style="font-size:18px;border-bottom:2px solid #198754;padding-bottom:8px;color:#198754;">Gewinn-Aufstellung: ${esc(b.name)}</h1>
    <p style="color:#888;font-size:11px;">Exportiert am ${new Date().toLocaleDateString('de-DE')}</p>

    <table style="width:100%;border-collapse:collapse;font-size:12px;margin:16px 0;">
      <tr><td style="padding:6px 8px;font-weight:600;">Material-Gewinn:</td><td style="text-align:right;padding:6px 8px;">${fmtNum(matGewinn)} €</td><td style="padding:6px 8px;color:#888;font-size:11px;">(VK ${fmtNum(matVkSum)} - EK ${fmtNum(matEkSum)})</td></tr>
      <tr><td style="padding:6px 8px;font-weight:600;">Arbeitszeit-Gewinn:</td><td style="text-align:right;padding:6px 8px;">${fmtNum(azGewinn)} €</td><td style="padding:6px 8px;color:#888;font-size:11px;">(Einnahmen ${fmtNum(azSum)} - Fixkosten ${fmtNum(azFk)})</td></tr>
      <tr><td style="padding:6px 8px;font-weight:600;">Pauschalen:</td><td style="text-align:right;padding:6px 8px;">${fmtNum(pSum)} €</td><td style="padding:6px 8px;color:#888;font-size:11px;">(100% Gewinn)</td></tr>
      <tr style="border-top:2px solid #198754;"><td style="padding:8px;font-weight:700;font-size:14px;color:#198754;">Gewinn Gesamt:</td><td style="text-align:right;padding:8px;font-weight:700;font-size:14px;color:#198754;">${fmtNum(totalGewinn)} €</td><td></td></tr>
    </table>

    <h2 style="font-size:14px;margin-top:20px;color:#333;">Material-Positionen</h2>`;
  if (b.material.length > 0) {
    html += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Bezeichnung</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Anz.</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">VK Ges.</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">EK Ges.</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gewinn</th></tr></thead><tbody>';
    b.material.forEach(r => {
      const vk = matVk(r, b) * r.anzahl; const ek = r.ek * r.anzahl;
      html += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.bezeichnung)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${r.anzahl}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(vk)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(ek)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;color:${(vk-ek) >= 0 ? '#198754' : '#dc3545'}">${fmtNum(vk - ek)}</td></tr>`;
    });
    html += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;font-weight:bold;padding:4px 6px;">Material-Gewinn:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;color:#198754">${fmtNum(matGewinn)} €</td></tr></tfoot></table>`;
  }

  html += '<h2 style="font-size:14px;margin-top:20px;color:#333;">Arbeitszeit-Positionen</h2>';
  if (b.arbeitszeit.length > 0) {
    html += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><thead><tr style="background:#FDE8EC;"><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Beschreibung</th><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Datum</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Std.</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Einnahme</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Fixkosten</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gewinn</th></tr></thead><tbody>';
    b.arbeitszeit.forEach(r => {
      const ein = r.stunden * r.stundenpreis; const fk = r.stunden * (r.fixkosten || 0); const gw = ein - fk;
      html += `<tr><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.beschreibung)}</td><td style="padding:3px 6px;border-bottom:1px solid #eee;">${r.datum || ''}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${r.stunden}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(ein)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(fk)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;color:${gw >= 0 ? '#198754' : '#dc3545'}">${fmtNum(gw)}</td></tr>`;
    });
    html += `</tbody><tfoot><tr><td colspan="5" style="text-align:right;font-weight:bold;padding:4px 6px;">Arbeitszeit-Gewinn:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;color:#198754">${fmtNum(azGewinn)} €</td></tr></tfoot></table>`;
  }
  html += '</div>';

  if (typeof html2pdf === 'undefined') {
    const s = document.createElement('script');
    s.src = 'lib/html2pdf.bundle.min.js';
    s.onload = () => _generateBaustellePDF(html, `Gewinn_${b.name}`);
    document.head.appendChild(s);
  } else {
    _generateBaustellePDF(html, `Gewinn_${b.name}`);
  }
}

// ============================================================
// GESAMTÜBERSICHT PDF EXPORT MODAL
// ============================================================
function openUebersichtExportModal() {
  let m = document.getElementById('ovExportModal');
  if (!m) {
    m = document.createElement('div');
    m.id = 'ovExportModal';
    m.className = 'modal-overlay';
    document.body.appendChild(m);
  }

  const bList = appData.baustellen.map(b => `
    <label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;" onmouseover="this.style.background='var(--grey-50,#F5F5F7)'" onmouseout="this.style.background=''">
      <input type="checkbox" class="ov-export-cb" value="${b.id}" checked>
      <span style="font-weight:600;font-size:.85rem;">${b.projektNr ? esc(b.projektNr) + ' - ' : ''}${esc(b.name)}</span>
    </label>`).join('');

  m.innerHTML = `<div class="modal-box" style="max-width:550px;">
    <div class="modal-header"><h3>${ico('download')} Gesamtübersicht exportieren</h3><button class="modal-close" onclick="hide('ovExportModal')">&times;</button></div>
    <div class="modal-body" style="max-height:60vh;overflow-y:auto;">
      <div style="margin-bottom:16px;">
        <label style="font-size:.85rem;font-weight:600;display:block;margin-bottom:6px;">Ansicht:</label>
        <div style="display:flex;gap:12px;">
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;"><input type="radio" name="ovExportView" value="all" checked> Alle Details (intern)</label>
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;"><input type="radio" name="ovExportView" value="kunde"> Kundenansicht</label>
        </div>
      </div>
      <div style="margin-bottom:16px;">
        <label style="font-size:.85rem;font-weight:600;display:block;margin-bottom:6px;">Detailgrad:</label>
        <div style="display:flex;gap:12px;flex-wrap:wrap;">
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;"><input type="radio" name="ovExportDetail" value="summary" checked> Nur übersicht</label>
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;"><input type="radio" name="ovExportDetail" value="categories"> Oberkategorien</label>
          <label style="display:flex;align-items:center;gap:6px;font-size:.85rem;cursor:pointer;"><input type="radio" name="ovExportDetail" value="positions"> Einzelpositionen</label>
        </div>
      </div>
      <div style="margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;">
        <label style="font-size:.85rem;font-weight:600;">Baustellen auswählen:</label>
        <div style="display:flex;gap:6px;">
          <button class="btn btn-sm btn-secondary" onclick="document.querySelectorAll('.ov-export-cb').forEach(c=>c.checked=true)" style="font-size:.72rem;">Alle</button>
          <button class="btn btn-sm btn-secondary" onclick="document.querySelectorAll('.ov-export-cb').forEach(c=>c.checked=false)" style="font-size:.72rem;">Keine</button>
        </div>
      </div>
      <div style="border:1px solid var(--grey-100);border-radius:8px;padding:4px 0;max-height:300px;overflow-y:auto;">
        ${bList}
      </div>
    </div>
    <div class="modal-footer" style="display:flex;gap:8px;justify-content:flex-end;padding:12px 20px;border-top:1px solid var(--grey-100);">
      <button class="btn btn-secondary btn-sm" onclick="hide('ovExportModal')">Abbrechen</button>
      <button class="btn btn-primary btn-sm" onclick="doUebersichtPDFExport()">${ico('download')} PDF erzeugen</button>
    </div>
  </div>`;
  show('ovExportModal');
}

function doUebersichtPDFExport() {
  const selectedIds = new Set(
    Array.from(document.querySelectorAll('.ov-export-cb:checked')).map(c => parseInt(c.value))
  );
  const isKunde = document.querySelector('input[name="ovExportView"]:checked')?.value === 'kunde';
  const detailLevel = document.querySelector('input[name="ovExportDetail"]:checked')?.value || 'summary';
  if (selectedIds.size === 0) { showNotification('Bitte mindestens eine Baustelle auswählen.'); return; }
  hide('ovExportModal');

  const baustellen = appData.baustellen.filter(b => selectedIds.has(b.id));
  let totalMat = 0, totalAz = 0, totalP = 0, totalAbs = 0, totalGewinn = 0;

  // Collect per-Baustelle data with details
  const bData = baustellen.map(b => {
    let ms = 0, mek = 0, as = 0, afk = 0, ps = 0, abs = 0;
    const matRows = b.material.map(r => {
      const vk = matVk(r, b) * r.anzahl; const ek = r.ek * r.anzahl;
      ms += vk; mek += ek;
      return { bezeichnung: r.bezeichnung || '(ohne)', kategorie: r.kategorie || '', anzahl: r.anzahl, vk, ek, gewinn: vk - ek, ekSingle: r.ek, vkSingle: matVk(r, b) };
    });
    const azRows = b.arbeitszeit.map(r => {
      const ein = r.stunden * r.stundenpreis; const fk = r.stunden * (r.fixkosten || 0);
      as += ein; afk += fk;
      return { beschreibung: r.beschreibung || '(ohne)', datum: r.datum || '', stunden: r.stunden, stundenpreis: r.stundenpreis, einnahme: ein, fixkosten: fk, gewinn: ein - fk };
    });
    const pRows = [];
    b.pauschalen.forEach(entry => {
      const p = appData.pauschalen.find(p => p.id === entry.id);
      if (p) { const g = p.preis * (entry.anzahl || 1); ps += g; pRows.push({ name: p.name, anzahl: entry.anzahl || 1, preis: p.preis, gesamt: g }); }
    });
    (b.abschlaege || []).forEach(r => { abs += r.betrag; });
    const g = ms + as + ps;
    const gw = (ms - mek) + (as - afk) + ps;
    totalMat += ms; totalAz += as; totalP += ps; totalAbs += abs; totalGewinn += gw;
    return { name: b.name, projektNr: b.projektNr || '', ms, mek, as, afk, ps, g, abs, offen: g - abs, gewinn: gw, matRows, azRows, pRows };
  });

  const grand = totalMat + totalAz + totalP;
  const grandOffen = grand - totalAbs;

  // Build header columns based on view
  let thRow, tdFn, tfRow;
  if (isKunde) {
    thRow = '<th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Projekt</th><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Baustelle</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt (€)</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Abschläge (€)</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Offen (€)</th>';
    tdFn = r => `<td style="padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;color:#00B4D8;">${esc(r.projektNr)}</td><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.name)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.g)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.abs)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;">${fmtNum(r.offen)}</td>`;
    tfRow = `<td></td><td style="text-align:right;font-weight:bold;padding:4px 6px;">Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(grand)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(totalAbs)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(grandOffen)}</td>`;
  } else {
    thRow = '<th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Projekt</th><th style="text-align:left;padding:4px 6px;border-bottom:1px solid #ddd;">Baustelle</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Material</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Arbeitszeit</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Pausch.</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gesamt</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Abschläge</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Offen</th><th style="text-align:right;padding:4px 6px;border-bottom:1px solid #ddd;">Gewinn</th>';
    tdFn = r => `<td style="padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;color:#00B4D8;">${esc(r.projektNr)}</td><td style="padding:3px 6px;border-bottom:1px solid #eee;">${esc(r.name)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.ms)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.as)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.ps)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.g)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.abs)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;">${fmtNum(r.offen)}</td><td style="text-align:right;padding:3px 6px;border-bottom:1px solid #eee;font-weight:600;color:${r.gewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(r.gewinn)}</td>`;
    tfRow = `<td></td><td style="text-align:right;font-weight:bold;padding:4px 6px;">Gesamt:</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(totalMat)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(totalAz)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(totalP)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(grand)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(totalAbs)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;">${fmtNum(grandOffen)}</td><td style="text-align:right;font-weight:bold;padding:4px 6px;color:${totalGewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(totalGewinn)}</td>`;
  }

  let html = `<div style="font-family:Arial,sans-serif;font-size:12px;max-width:1000px;margin:0 auto;padding:20px;">
    <style>tr { page-break-inside: avoid; } table { page-break-inside: auto; } h2, h3 { page-break-after: avoid; } tfoot { page-break-inside: avoid; }</style>
    <h1 style="font-size:18px;border-bottom:2px solid #00B4D8;padding-bottom:8px;color:#00B4D8;">Gesamtübersicht Baustellen${isKunde ? ' (Kundenansicht)' : ''}</h1>
    <p style="color:#888;font-size:11px;">Exportiert am ${new Date().toLocaleDateString('de-DE')} - ${baustellen.length} Baustelle${baustellen.length !== 1 ? 'n' : ''}</p>

    ${!isKunde ? `<div style="display:flex;gap:16px;flex-wrap:wrap;margin:16px 0;">
      <div style="padding:8px 14px;background:#FDE8EC;border-radius:6px;"><span style="font-size:11px;color:#666;">Material gesamt</span><br><strong>${fmtNum(totalMat)} €</strong></div>
      <div style="padding:8px 14px;background:#FDE8EC;border-radius:6px;"><span style="font-size:11px;color:#666;">Arbeitszeit gesamt</span><br><strong>${fmtNum(totalAz)} €</strong></div>
      <div style="padding:8px 14px;background:#FDE8EC;border-radius:6px;"><span style="font-size:11px;color:#666;">Pauschalen gesamt</span><br><strong>${fmtNum(totalP)} €</strong></div>
      <div style="padding:8px 14px;background:#FDE8EC;border-radius:6px;border-left:3px solid #198754;"><span style="font-size:11px;color:#666;">Gewinn gesamt</span><br><strong style="color:${totalGewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(totalGewinn)} €</strong></div>
    </div>` : ''}

    <table style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead><tr style="background:#FDE8EC;">${thRow}</tr></thead>
      <tbody>${bData.map(r => `<tr>${tdFn(r)}</tr>`).join('')}</tbody>
      <tfoot><tr style="border-top:2px solid #00B4D8;">${tfRow}</tr></tfoot>
    </table>

    <div style="margin-top:20px;padding:10px;background:#FDE8EC;border-radius:6px;">
      <table style="width:100%;font-size:12px;">
        <tr><td style="padding:3px 0;font-weight:600;">Gesamtsumme:</td><td style="text-align:right;font-weight:700;font-size:14px;">${fmtNum(grand)} €</td></tr>
        <tr><td style="padding:3px 0;font-weight:600;">Abschläge:</td><td style="text-align:right;">-${fmtNum(totalAbs)} €</td></tr>
        <tr style="border-top:1px solid #ccc;"><td style="padding:6px 0 3px;font-weight:700;font-size:14px;color:#00B4D8;">Offener Betrag:</td><td style="text-align:right;font-weight:700;font-size:14px;color:#00B4D8;">${fmtNum(grandOffen)} €</td></tr>
      </table>
    </div>`;

  // Detail sections per Baustelle
  if (detailLevel !== 'summary') {
    bData.forEach(bd => {
      html += `<div style="page-break-before:always;margin-top:30px;border-top:3px solid #00B4D8;padding-top:16px;">
        <h2 style="font-size:15px;color:#00B4D8;margin-bottom:4px;">${bd.projektNr ? esc(bd.projektNr) + ' - ' : ''}${esc(bd.name)}</h2>`;

      if (detailLevel === 'categories') {
        // Oberkategorien: show subtotals per category
        html += `<table style="width:100%;border-collapse:collapse;font-size:12px;margin:10px 0;">
          <thead><tr style="background:#FDE8EC;">
            <th style="text-align:left;padding:5px 8px;border-bottom:1px solid #ddd;">Kategorie</th>
            ${!isKunde ? '<th style="text-align:right;padding:5px 8px;border-bottom:1px solid #ddd;">VK</th><th style="text-align:right;padding:5px 8px;border-bottom:1px solid #ddd;">EK</th><th style="text-align:right;padding:5px 8px;border-bottom:1px solid #ddd;">Gewinn</th>' : '<th style="text-align:right;padding:5px 8px;border-bottom:1px solid #ddd;">Summe</th>'}
          </tr></thead><tbody>`;
        // Material
        html += `<tr><td style="padding:4px 8px;border-bottom:1px solid #eee;font-weight:600;">Material</td>`;
        if (!isKunde) html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.ms)} €</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.mek)} €</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;color:${(bd.ms-bd.mek) >= 0 ? '#198754' : '#dc3545'};font-weight:600;">${fmtNum(bd.ms - bd.mek)} €</td>`;
        else html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.ms)} €</td>`;
        html += '</tr>';
        // Arbeitszeit
        html += `<tr><td style="padding:4px 8px;border-bottom:1px solid #eee;font-weight:600;">Arbeitszeit</td>`;
        if (!isKunde) html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.as)} €</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.afk)} €</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;color:${(bd.as-bd.afk) >= 0 ? '#198754' : '#dc3545'};font-weight:600;">${fmtNum(bd.as - bd.afk)} €</td>`;
        else html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.as)} €</td>`;
        html += '</tr>';
        // Pauschalen
        html += `<tr><td style="padding:4px 8px;border-bottom:1px solid #eee;font-weight:600;">Pauschalen</td>`;
        if (!isKunde) html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.ps)} €</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">—</td><td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;color:#198754;font-weight:600;">${fmtNum(bd.ps)} €</td>`;
        else html += `<td style="text-align:right;padding:4px 8px;border-bottom:1px solid #eee;">${fmtNum(bd.ps)} €</td>`;
        html += '</tr>';
        // Summe
        html += `<tr style="border-top:2px solid #00B4D8;font-weight:700;"><td style="padding:5px 8px;">Gesamt</td>`;
        if (!isKunde) html += `<td style="text-align:right;padding:5px 8px;">${fmtNum(bd.g)} €</td><td></td><td style="text-align:right;padding:5px 8px;color:${bd.gewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(bd.gewinn)} €</td>`;
        else html += `<td style="text-align:right;padding:5px 8px;">${fmtNum(bd.g)} €</td>`;
        html += '</tr></tbody></table>';

      } else if (detailLevel === 'positions') {
        // Einzelpositionen: full tables

        // Material
        html += '<h3 style="font-size:12px;margin:14px 0 4px;color:#555;">Material</h3>';
        if (bd.matRows.length > 0) {
          html += `<table style="width:100%;border-collapse:collapse;font-size:10px;"><thead><tr style="background:#f0f4f8;">
            <th style="text-align:left;padding:3px 5px;border-bottom:1px solid #ddd;">Bezeichnung</th>
            <th style="text-align:left;padding:3px 5px;border-bottom:1px solid #ddd;">Kategorie</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Anz.</th>
            ${!isKunde ? '<th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">EK/Stk</th>' : ''}
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">VK/Stk</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">VK Ges.</th>
            ${!isKunde ? '<th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">EK Ges.</th><th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Gewinn</th>' : ''}
          </tr></thead><tbody>`;
          bd.matRows.forEach(r => {
            html += `<tr>
              <td style="padding:2px 5px;border-bottom:1px solid #f0f0f0;">${esc(r.bezeichnung)}</td>
              <td style="padding:2px 5px;border-bottom:1px solid #f0f0f0;">${esc(r.kategorie)}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${r.anzahl}</td>
              ${!isKunde ? `<td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.ekSingle)}</td>` : ''}
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.vkSingle)}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.vk)}</td>
              ${!isKunde ? `<td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.ek)}</td><td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;font-weight:600;color:${r.gewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(r.gewinn)}</td>` : ''}
            </tr>`;
          });
          html += `</tbody><tfoot><tr style="font-weight:600;border-top:1px solid #bbb;">
            <td colspan="${!isKunde ? '5' : '4'}" style="text-align:right;padding:3px 5px;">Material Summe:</td>
            <td style="text-align:right;padding:3px 5px;">${fmtNum(bd.ms)} €</td>
            ${!isKunde ? `<td style="text-align:right;padding:3px 5px;">${fmtNum(bd.mek)} €</td><td style="text-align:right;padding:3px 5px;color:${(bd.ms-bd.mek)>=0?'#198754':'#dc3545'}">${fmtNum(bd.ms - bd.mek)} €</td>` : ''}
          </tr></tfoot></table>`;
        } else { html += '<p style="font-size:10px;color:#999;">Keine Materialien.</p>'; }

        // Arbeitszeit
        html += '<h3 style="font-size:12px;margin:14px 0 4px;color:#555;">Arbeitszeit</h3>';
        if (bd.azRows.length > 0) {
          html += `<table style="width:100%;border-collapse:collapse;font-size:10px;"><thead><tr style="background:#f0f4f8;">
            <th style="text-align:left;padding:3px 5px;border-bottom:1px solid #ddd;">Beschreibung</th>
            <th style="text-align:left;padding:3px 5px;border-bottom:1px solid #ddd;">Datum</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Std.</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">€/Std.</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Einnahme</th>
            ${!isKunde ? '<th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Fixkosten</th><th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Gewinn</th>' : ''}
          </tr></thead><tbody>`;
          bd.azRows.forEach(r => {
            html += `<tr>
              <td style="padding:2px 5px;border-bottom:1px solid #f0f0f0;">${esc(r.beschreibung)}</td>
              <td style="padding:2px 5px;border-bottom:1px solid #f0f0f0;">${r.datum}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${r.stunden}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.stundenpreis)}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.einnahme)}</td>
              ${!isKunde ? `<td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.fixkosten)}</td><td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;font-weight:600;color:${r.gewinn >= 0 ? '#198754' : '#dc3545'}">${fmtNum(r.gewinn)}</td>` : ''}
            </tr>`;
          });
          html += `</tbody><tfoot><tr style="font-weight:600;border-top:1px solid #bbb;">
            <td colspan="4" style="text-align:right;padding:3px 5px;">Arbeitszeit Summe:</td>
            <td style="text-align:right;padding:3px 5px;">${fmtNum(bd.as)} €</td>
            ${!isKunde ? `<td style="text-align:right;padding:3px 5px;">${fmtNum(bd.afk)} €</td><td style="text-align:right;padding:3px 5px;color:${(bd.as-bd.afk)>=0?'#198754':'#dc3545'}">${fmtNum(bd.as - bd.afk)} €</td>` : ''}
          </tr></tfoot></table>`;
        } else { html += '<p style="font-size:10px;color:#999;">Keine Arbeitszeiten.</p>'; }

        // Pauschalen
        html += '<h3 style="font-size:12px;margin:14px 0 4px;color:#555;">Pauschalen</h3>';
        if (bd.pRows.length > 0) {
          html += `<table style="width:100%;border-collapse:collapse;font-size:10px;"><thead><tr style="background:#f0f4f8;">
            <th style="text-align:left;padding:3px 5px;border-bottom:1px solid #ddd;">Bezeichnung</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Anzahl</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Preis/Stk</th>
            <th style="text-align:right;padding:3px 5px;border-bottom:1px solid #ddd;">Gesamt</th>
          </tr></thead><tbody>`;
          bd.pRows.forEach(r => {
            html += `<tr>
              <td style="padding:2px 5px;border-bottom:1px solid #f0f0f0;">${esc(r.name)}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${r.anzahl}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.preis)}</td>
              <td style="text-align:right;padding:2px 5px;border-bottom:1px solid #f0f0f0;">${fmtNum(r.gesamt)}</td>
            </tr>`;
          });
          html += `</tbody><tfoot><tr style="font-weight:600;border-top:1px solid #bbb;">
            <td colspan="3" style="text-align:right;padding:3px 5px;">Pauschalen Summe:</td>
            <td style="text-align:right;padding:3px 5px;">${fmtNum(bd.ps)} €</td>
          </tr></tfoot></table>`;
        } else { html += '<p style="font-size:10px;color:#999;">Keine Pauschalen.</p>'; }
      }

      // Baustelle summary footer
      html += `<div style="margin-top:10px;padding:6px 10px;background:#f0f4f8;border-radius:4px;font-size:11px;">
        <strong>Gesamt: ${fmtNum(bd.g)} €</strong> - Abschläge: ${fmtNum(bd.abs)} - <strong>Offen: ${fmtNum(bd.offen)} €</strong>
        ${!isKunde ? ` - <span style="color:${bd.gewinn >= 0 ? '#198754' : '#dc3545'};font-weight:700;">Gewinn: ${fmtNum(bd.gewinn)} €</span>` : ''}
      </div></div>`;
    });
  }

  html += '</div>';

  if (typeof html2pdf === 'undefined') {
    const s = document.createElement('script');
    s.src = 'lib/html2pdf.bundle.min.js';
    s.onload = () => _generateOvPDF(html, isKunde);
    document.head.appendChild(s);
  } else {
    _generateOvPDF(html, isKunde);
  }
}

function _generateOvPDF(html, isKunde) {
  const container = document.createElement('div');
  container.innerHTML = html;
  document.body.appendChild(container);
  html2pdf().set({
    margin: [12, 10, 12, 10],
    filename: `Uebersicht_${isKunde ? 'Kunde' : 'Intern'}_${new Date().toISOString().slice(0,10)}.pdf`,
    image: { type: 'jpeg', quality: 0.95 },
    html2canvas: { scale: 2 },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' },
    pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
  }).from(container).save().then(() => { document.body.removeChild(container); });
}

// ============================================================
// EXCEL IMPORT
// ============================================================
function importFromExcel(event) {
  const file = event.target.files[0];
  if (!file) return;
  // Validate file size (max 10MB)
  if (file.size > 10485760) { alert('Datei zu groß (max. 10 MB).'); return; }

  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data  = new Uint8Array(e.target.result);
      const wb    = XLSX.read(data, { type: 'array' });
      let imported = 0, skipped = 0;
      const importedIds = [];
      const MAX_SHEETS = 100, MAX_ROWS = 10000;
      if (wb.SheetNames.length > MAX_SHEETS) { throw new Error(`Zu viele Arbeitsblätter (max. ${MAX_SHEETS}).`); }

      wb.SheetNames.forEach(sheetName => {
        // Skip the summary sheet we create ourselves
        if (sheetName === 'Zusammenfassung') { skipped++; return; }

        const ws   = wb.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
        if (rows.length === 0) { skipped++; return; }

        const bName = String(rows[0][0] || sheetName).trim();
        const b = {
          id:                  appData.nextBaustelleId++,
          name:                bName,
          material:            [],
          arbeitszeit:         [],
          pauschalen:          [],
          abschlaege:          [],
          bautagebuch:         [],
          fehlendesMaterial:   [],
          nextMatId:           1,
          nextAzId:            1,
          nextAbschlagId:      1,
          nextTagebuchId:      1,
          nextFehlendesMatId:  1
        };

        let section     = null;
        let headerFound = false;

        for (let i = 1; i < rows.length; i++) {
          const row   = rows[i];
          const cell0 = String(row[0] || '').trim();

          // Section markers
          if (cell0 === 'MATERIAL')               { section = 'material';       headerFound = false; continue; }
          if (cell0 === 'ARBEITSZEIT')             { section = 'arbeitszeit';    headerFound = false; continue; }
          if (cell0 === 'PAUSCHALEN')              { section = 'pauschalen';     headerFound = false; continue; }
          if (cell0 === 'ABSCHLAGSRECHNUNGEN')     { section = 'abschlaege';     headerFound = false; continue; }
          if (cell0.startsWith('GESAMTSUMME') || cell0.startsWith('OFFENER BETRAG')) { section = null; continue; }

          // Skip until column header row found
          if (!headerFound) {
            if (section === 'material'    && cell0 === 'Bezeichnung')  { headerFound = true; continue; }
            if (section === 'arbeitszeit' && cell0 === 'Beschreibung') { headerFound = true; continue; }
            if (section === 'pauschalen'  && cell0 === 'Bezeichnung')  { headerFound = true; continue; }
            if (section === 'abschlaege'  && cell0 === 'Bezeichnung / Rechnungsnummer') { headerFound = true; continue; }
            continue;
          }

          // Skip empty or placeholder rows
          if (!cell0 || cell0.startsWith('\u2013') || cell0.startsWith('-')) continue;

          if (section === 'material') {
            if (String(row[5] || '').includes('Gesamt')) continue;  // total row
            b.material.push({
              id:          b.nextMatId++,
              bezeichnung: cell0,
              anzahl:      parseFloat(row[1]) || 0,
              einheit:     String(row[2] || 'Stk.').trim() || 'Stk.',
              ek:          parseFloat(row[3]) || 0,
              aufschlag:   parseFloat(row[4]) || 0,
              kategorieId: null
            });

          } else if (section === 'arbeitszeit') {
            if (String(row[2] || '').includes('Gesamt') || String(row[3] || '').includes('Gesamt')) continue;  // total row
            // Detect format: new format has datum (string) in row[1]; old has stunden (number)
            const isNewFmt = isNaN(parseFloat(String(row[1] || '').replace(',','.')));
            b.arbeitszeit.push({
              id:           b.nextAzId++,
              beschreibung: cell0,
              datum:        isNewFmt ? String(row[1] || '') : '',
              stunden:      isNewFmt ? (parseFloat(row[2]) || 0) : (parseFloat(row[1]) || 0),
              stundenpreis: isNewFmt ? (parseFloat(row[3]) || 0) : (parseFloat(row[2]) || 0)
            });

          } else if (section === 'pauschalen') {
            if (cell0.includes('Gesamt')) continue;  // total row
            const preis = parseFloat(row[1]) || 0;
            let existing = appData.pauschalen.find(p => p.name === cell0 && p.preis === preis);
            if (!existing) {
              existing = { id: appData.nextPauschaleId++, name: cell0, preis };
              appData.pauschalen.push(existing);
            }
            if (!b.pauschalen.find(e => e.id === existing.id)) b.pauschalen.push({ id: existing.id, anzahl: 1 });

          } else if (section === 'abschlaege') {
            if (cell0.includes('Gesamt') || cell0.startsWith('—')) continue;
            b.abschlaege.push({
              id:           b.nextAbschlagId++,
              bezeichnung:  cell0,
              betrag:       parseFloat(row[1]) || 0
            });
          }
        }

        appData.baustellen.push(b);
        importedIds.push(b.id);
        imported++;
      });

      saveData();
      renderSidebar();
      if (imported > 0) selectBaustelle(importedIds[0]);

      const skipMsg = skipped > 0 ? `, ${skipped} Blatt/Bl—tter übersprungen` : '';
      alert(`Import erfolgreich!\n${imported} Baustelle(n) importiert${skipMsg}.`);
    } catch (err) {
      console.error(err);
      alert('Fehler beim Import:\n' + err.message);
    }
    event.target.value = '';  // Reset input so same file can be re-imported
  };
  reader.readAsArrayBuffer(file);
}

function applyNumberFormat(ws, fmt) {
  const range = XLSX.utils.decode_range(ws['!ref'] || 'A1');
  for (let R = range.s.r; R <= range.e.r; R++) {
    for (let C = range.s.c; C <= range.e.c; C++) {
      const addr = XLSX.utils.encode_cell({ r: R, c: C });
      if (ws[addr] && ws[addr].t === 'n') ws[addr].z = fmt;
    }
  }
}

// ============================================================
// HELPERS
// ============================================================
function getBaustelle() {
  return appData.baustellen.find(b => b.id === selectedId) || null;
}

function fmt(v) {
  return (v || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
}

function esc(s) {
  if (!s) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function show(id) { const el = document.getElementById(id); if (el) el.classList.remove('hidden'); }
function hide(id) { const el = document.getElementById(id); if (el) el.classList.add('hidden'); }
function setCell(id, val) { const el = document.getElementById(id); if (el) el.textContent = val; }

// ============================================================
// REUSABLE SEARCHABLE BAUSTELLEN-DROPDOWN  (Single + Multi)
// ============================================================
const _bsDd = {};  // uid ? { onchange, allowEmpty, emptyLabel, extraItems, inline }
const _bsMd = {};  // uid ? { onchange }

/** Sorted Baustellen list (A-Z) shared helper */
function _bsSorted() {
  return (appData.baustellen || []).slice().sort((a, b) => a.name.localeCompare(b.name, 'de'));
}

// -- SINGLE-SELECT ------------------------------------------
/**
 * bsDdHtml(uid, opts) - returns innerHTML for a searchable single-select Baustellen dropdown
 * opts: { selected, placeholder, allowEmpty, emptyLabel, onchange, style, inputStyle, extraItems:[{id,label}], inline }
 * After inserting into DOM, call bsDdInit(uid) if needed (or rely on inline handlers).
 */
function bsDdHtml(uid, opts) {
  opts = opts || {};
  _bsDd[uid] = { onchange: opts.onchange || null, allowEmpty: opts.allowEmpty !== false, emptyLabel: opts.emptyLabel || '— Keine —', extraItems: opts.extraItems || [], inline: opts.inline || false };
  const selId = opts.selected || '';
  const selB = selId ? (appData.baustellen || []).find(b => b.id == selId) : null;
  const selName = selB ? selB.name : '';
  const ph = opts.placeholder || 'Baustelle suchen...';
  const wStyle = opts.style || '';
  const iStyle = opts.inputStyle || '';
  return `<div class="bs-dd-wrap" id="bsDd_${uid}" style="${wStyle}">
    <input type="text" class="form-control bs-dd-search" id="bsDdS_${uid}" placeholder="${esc(ph)}" value="${esc(selName)}" autocomplete="off"
      oninput="bsDdFilter('${uid}')" onfocus="bsDdFilter('${uid}')" style="${iStyle}">
    <input type="hidden" id="bsDdV_${uid}" value="${selId}">
    <div class="bs-dd-list" id="bsDdL_${uid}"></div>
  </div>`;
}

function bsDdFilter(uid) {
  const search = document.getElementById('bsDdS_' + uid);
  const list = document.getElementById('bsDdL_' + uid);
  if (!search || !list) return;
  const q = search.value.toLowerCase().trim();
  const sorted = _bsSorted();
  const filtered = sorted.filter(b => !q || b.name.toLowerCase().includes(q) || (b.projektNr || '').toLowerCase().includes(q));
  list.innerHTML = '';
  const cfg = _bsDd[uid] || {};
  if (cfg.allowEmpty) {
    const el = document.createElement('div');
    el.className = 'bs-dd-item bs-dd-item-empty';
    el.textContent = cfg.emptyLabel;
    el.onclick = () => bsDdSelect(uid, '', '');
    list.appendChild(el);
  }
  (cfg.extraItems || []).forEach(ex => {
    const el = document.createElement('div');
    el.className = 'bs-dd-item';
    el.textContent = ex.label;
    el.onclick = () => bsDdSelect(uid, ex.id, ex.label);
    list.appendChild(el);
  });
  filtered.forEach(b => {
    const el = document.createElement('div');
    el.className = 'bs-dd-item';
    el.textContent = (b.projektNr ? b.projektNr + ' - ' : '') + b.name;
    el.onclick = () => bsDdSelect(uid, b.id, b.name);
    list.appendChild(el);
  });
  // Use position:fixed calculated from input rect to escape any overflow:auto clipping
  const rect = search.getBoundingClientRect();
  list.style.position = 'fixed';
  list.style.left = rect.left + 'px';
  list.style.top = (rect.bottom + 2) + 'px';
  list.style.width = rect.width + 'px';
  list.style.right = 'auto';
  list.style.zIndex = '9999';
  list.style.display = (list.children.length > 0) ? 'block' : 'none';
}

// Close/track all bsDd dropdowns on scroll (fixed positions become stale).
// Statt die Liste zu verstecken, wird sie dem Eingabefeld nachgeführt, damit sie
// im scrollbaren Modal nicht „verschoben“ erscheint.
window.addEventListener('scroll', function () {
  document.querySelectorAll('.bs-dd-list').forEach(el => {
    if (el.style.display !== 'block') return;
    const uid = el.id.replace('bsDdL_', '');
    const search = document.getElementById('bsDdS_' + uid);
    if (!search) { el.style.display = 'none'; return; }
    const rect = search.getBoundingClientRect();
    // Eingabefeld aus dem Sichtbereich gescrollt → ausblenden.
    if (rect.bottom < 0 || rect.top > window.innerHeight) { el.style.display = 'none'; return; }
    el.style.left = rect.left + 'px';
    el.style.top = (rect.bottom + 2) + 'px';
    el.style.width = rect.width + 'px';
  });
}, true);

function bsDdSelect(uid, id, name) {
  const search = document.getElementById('bsDdS_' + uid);
  const hidden = document.getElementById('bsDdV_' + uid);
  const list = document.getElementById('bsDdL_' + uid);
  if (search) search.value = name;
  if (hidden) hidden.value = id;
  if (list) list.style.display = 'none';
  const cfg = _bsDd[uid] || {};
  if (typeof cfg.onchange === 'function') cfg.onchange(id, name);
}

function bsDdGetValue(uid) {
  const el = document.getElementById('bsDdV_' + uid);
  return el ? el.value : '';
}

function bsDdSetValue(uid, id) {
  const b = (appData.baustellen || []).find(x => x.id == id);
  const search = document.getElementById('bsDdS_' + uid);
  const hidden = document.getElementById('bsDdV_' + uid);
  if (search) search.value = b ? b.name : '';
  if (hidden) hidden.value = id || '';
}

// -- MULTI-SELECT -------------------------------------------
/**
 * bsMdHtml(uid, opts) - returns innerHTML for a searchable multi-select Baustellen dropdown
 * opts: { selected: [ids] | 'all', onchange(selectedIds_or_all), allLabel }
 */
function bsMdHtml(uid, opts) {
  opts = opts || {};
  _bsMd[uid] = { onchange: opts.onchange || null, allLabel: opts.allLabel || 'Alle Baustellen' };
  const sel = opts.selected;
  const isAll = sel === 'all' || !Array.isArray(sel);
  return `<div class="bs-md-wrap" id="bsMd_${uid}">
    <div class="bs-md-display" id="bsMdDisp_${uid}" onclick="bsMdOpen('${uid}')">
      <span class="bs-md-summary" id="bsMdSum_${uid}"></span>
      <span class="bs-md-arrow">▸</span>
    </div>
    <div class="bs-md-panel" id="bsMdPanel_${uid}" style="display:none">
      <input type="text" class="form-control bs-md-search" id="bsMdS_${uid}" placeholder="Suchen—" autocomplete="off"
        oninput="bsMdRender('${uid}')">
      <div class="bs-md-actions" style="padding:4px 8px;display:flex;gap:6px;border-bottom:1px solid var(--grey-100,#eee)">
        <button type="button" class="btn btn-sm btn-secondary" style="font-size:.7rem;padding:2px 8px" onclick="bsMdSelectAll('${uid}',true)">Alle</button>
        <button type="button" class="btn btn-sm btn-secondary" style="font-size:.7rem;padding:2px 8px" onclick="bsMdSelectAll('${uid}',false)">Keine</button>
      </div>
      <div class="bs-md-items" id="bsMdItems_${uid}"></div>
    </div>
    <input type="hidden" id="bsMdV_${uid}" value="${isAll ? 'all' : JSON.stringify(sel || [])}">
  </div>`;
}

function bsMdOpen(uid) {
  const panel = document.getElementById('bsMdPanel_' + uid);
  if (!panel) return;
  const isOpen = panel.style.display !== 'none';
  // Close all other multi-dropdowns
  document.querySelectorAll('.bs-md-panel').forEach(p => p.style.display = 'none');
  if (!isOpen) {
    panel.style.display = 'block';
    document.getElementById('bsMdS_' + uid)?.focus();
    bsMdRender(uid);
  }
}

function bsMdRender(uid) {
  const items = document.getElementById('bsMdItems_' + uid);
  const search = document.getElementById('bsMdS_' + uid);
  if (!items) return;
  const q = (search?.value || '').toLowerCase().trim();
  const sorted = _bsSorted();
  const filtered = sorted.filter(b => !q || b.name.toLowerCase().includes(q) || (b.projektNr || '').toLowerCase().includes(q));
  const val = bsMdGetValue(uid);
  const isAll = val === 'all';
  items.innerHTML = '';
  filtered.forEach(b => {
    const checked = isAll || (Array.isArray(val) && val.includes(b.id));
    const el = document.createElement('label');
    el.className = 'bs-md-item' + (checked ? ' bs-md-item-checked' : '');
    el.innerHTML = `<input type="checkbox" ${checked ? 'checked' : ''} data-bid="${b.id}"> <span>${esc((b.projektNr ? b.projektNr + ' - ' : '') + b.name)}</span>`;
    el.querySelector('input').onchange = function() { bsMdToggle(uid, b.id, this.checked); };
    items.appendChild(el);
  });
}

function bsMdToggle(uid, bid, checked) {
  let val = bsMdGetValue(uid);
  let arr = val === 'all' ? _bsSorted().map(b => b.id) : (Array.isArray(val) ? [...val] : []);
  if (checked) { if (!arr.includes(bid)) arr.push(bid); }
  else { arr = arr.filter(id => id !== bid); }
  // Check if all selected
  const allIds = _bsSorted().map(b => b.id);
  const newVal = arr.length >= allIds.length ? 'all' : arr;
  document.getElementById('bsMdV_' + uid).value = newVal === 'all' ? 'all' : JSON.stringify(newVal);
  bsMdUpdateSummary(uid);
  const cfg = _bsMd[uid] || {};
  if (typeof cfg.onchange === 'function') cfg.onchange(newVal);
}

function bsMdSelectAll(uid, selectAll) {
  const allIds = _bsSorted().map(b => b.id);
  const newVal = selectAll ? 'all' : [];
  document.getElementById('bsMdV_' + uid).value = selectAll ? 'all' : '[]';
  bsMdRender(uid);
  bsMdUpdateSummary(uid);
  const cfg = _bsMd[uid] || {};
  if (typeof cfg.onchange === 'function') cfg.onchange(newVal);
}

function bsMdGetValue(uid) {
  const el = document.getElementById('bsMdV_' + uid);
  if (!el) return 'all';
  if (el.value === 'all') return 'all';
  try { return JSON.parse(el.value); } catch(_) { return 'all'; }
}

function bsMdUpdateSummary(uid) {
  const sum = document.getElementById('bsMdSum_' + uid);
  if (!sum) return;
  const val = bsMdGetValue(uid);
  const cfg = _bsMd[uid] || {};
  if (val === 'all') { sum.textContent = cfg.allLabel || 'Alle Baustellen'; sum.style.color = ''; return; }
  if (!Array.isArray(val) || val.length === 0) { sum.textContent = 'Keine ausgewählt'; sum.style.color = 'var(--danger,#dc3545)'; return; }
  const names = val.map(id => (appData.baustellen || []).find(b => b.id === id)?.name).filter(Boolean);
  if (names.length <= 2) { sum.textContent = names.join(', '); sum.style.color = ''; }
  else { sum.textContent = names.slice(0, 2).join(', ') + ' +' + (names.length - 2); sum.style.color = ''; }
}

function bsMdInit(uid) {
  bsMdUpdateSummary(uid);
}

// -- Click-away for all BsDropdowns -------------------------
document.addEventListener('click', function(e) {
  // Single-select: close all lists not clicked
  document.querySelectorAll('.bs-dd-list').forEach(dd => {
    const wrap = dd.closest('.bs-dd-wrap');
    if (wrap && !wrap.contains(e.target)) dd.style.display = 'none';
  });
  // Multi-select: close panels
  document.querySelectorAll('.bs-md-panel').forEach(panel => {
    const wrap = panel.closest('.bs-md-wrap');
    if (wrap && !wrap.contains(e.target)) panel.style.display = 'none';
  });
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    closePauschalenModal();
    closeRenameModal();
    closeBackupModal();
  }
});

// ============================================================
// BACKUP  -  server-side (api.php), max 7 Tage
// ============================================================

function updateFooterStatus(ts) {
  const el = document.getElementById('footerBackupTime');
  if (!el) return;
  if (ts) {
    const d       = new Date(ts);
    const isToday = d.toDateString() === new Date().toDateString();
    const label   = isToday
      ? 'Heute ' + d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
      : d.toLocaleDateString('de-DE');
    el.textContent = label;
    el.className   = 'footer-backup-time' + (isToday ? ' fresh' : '');
  } else {
    el.textContent = 'Keine Sicherung';
    el.className   = 'footer-backup-time';
  }
}

async function initBackupStatus() {
  try {
    const r = await fetch('api.php?action=backups');
    if (!r.ok) return;
    const j = await r.json();
    updateFooterStatus(j.backups?.[0]?.ts ?? null);
  } catch (e) {}
}

// -- Backup-Modal ---------------------------------------------
async function openBackupModal() {
  const list = document.getElementById('backupList');
  list.innerHTML = '<p class="hint-text">Lade Sicherungen...</p>';
  show('backupModal');
  try {
    const r = await fetch('api.php?action=backups');
    const j = await r.json();
    list.innerHTML = '';
    if (!j.backups || j.backups.length === 0) {
      list.innerHTML = '<p class="hint-text">Noch keine Sicherungen vorhanden.</p>';
      return;
    }
    j.backups.forEach(b => {
      const ts        = new Date(b.ts);
      const dateLabel = ts.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
      const timeLabel = ts.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
      const div = document.createElement('div');
      div.className = 'backup-item';
      div.innerHTML = `
        <div>
          <div class="backup-item-date">${dateLabel} - ${timeLabel} Uhr</div>
          <div class="backup-item-meta">${b.count} Baustelle(n) · ${b.date}</div>
        </div>
        <div class="backup-item-actions">
          <button class="btn btn-secondary btn-sm" onclick="downloadBackup('${b.date}')" title="Als ZIP herunterladen">💾</button>
          <button class="btn btn-primary btn-sm" onclick="restoreFromBackup('${b.date}')"> Wiederherstellen</button>
        </div>`;
      list.appendChild(div);
    });
  } catch (e) {
    list.innerHTML = '<p class="hint-text">Fehler beim Laden der Sicherungen.</p>';
  }
}

function closeBackupModal()          { hide('backupModal'); }
function closeBackupModalOverlay(e)  { if (e.target === e.currentTarget) closeBackupModal(); }

async function downloadBackup(date) {
  try {
    const url = date
      ? `api.php?action=backup_download&date=${encodeURIComponent(date)}`
      : 'api.php?action=backup_download';
    const r = await fetch(url);
    if (!r.ok) { const j = await r.json().catch(() => ({})); alert('Download fehlgeschlagen: ' + (j.error || r.status)); return; }
    const blob     = await r.blob();
    const link     = document.createElement('a');
    link.href      = URL.createObjectURL(blob);
    link.download  = r.headers.get('Content-Disposition')?.match(/filename="?([^"]+)"?/)?.[1]
                     || `baukalkulation_backup_${date || 'aktuell'}.zip`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(link.href), 10000);
  } catch (e) {
    alert('Fehler beim Download:\n' + e.message);
  }
}

async function createManualBackup() {
  const name = document.getElementById('backupNameInput')?.value?.trim() ?? '';
  try {
    const r = await fetch('api.php?action=backup_create', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    const j = await r.json();
    if (!j.ok) { alert('Sicherung fehlgeschlagen: ' + (j.error || 'Unbekannter Fehler')); return; }
    if (document.getElementById('backupNameInput')) document.getElementById('backupNameInput').value = '';
    openBackupModal();  // Liste neu laden
  } catch (e) {
    alert('Fehler beim Erstellen der Sicherung:\n' + e.message);
  }
}

// Lädt ein Backup-ZIP hoch; fragt bei verschlüsselten Sicherungen nach dem Passwort.
async function _postBackupZip(action, file) {
  let password = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    const fd = new FormData();
    fd.append('backup', file);
    if (password !== null) fd.append('password', password);
    const r = await fetch('api.php?action=' + action, { method: 'POST', body: fd });
    const j = await r.json();
    if (!j.passwordRequired) return j;
    password = prompt(attempt === 0 && password === null
      ? 'Die Sicherung ist verschlüsselt. Bitte Passwort eingeben:'
      : 'Passwort falsch. Bitte erneut eingeben:');
    if (password === null) return { error: 'Abgebrochen.' };
  }
  return { error: 'Passwort falsch.' };
}

async function uploadAndRestoreBackup() {
  const input = document.getElementById('backupUploadInput');
  if (!input?.files?.length) { alert('Bitte zuerst ein ZIP-Archiv auswählen.'); return; }
  if (!confirm('Sicherung hochladen und aktuellen Stand überschreiben?\nDiese Aktion kann nicht rückgängig gemacht werden.')) return;
  try {
    const j = await _postBackupZip('backup_upload', input.files[0]);
    if (!j.ok || !j.data) { alert('Wiederherstellung fehlgeschlagen: ' + (j.error || 'Unbekannter Fehler')); return; }
    appData    = j.data;
    selectedId = null;
    saveData();
    renderSidebar();
    showEmptyState();
    closeBackupModal();
    alert('Backup erfolgreich wiederhergestellt!');
  } catch (e) {
    alert('Fehler beim Hochladen:\n' + e.message);
  }
}

async function uploadAndReplaceBackup() {
  const input = document.getElementById('backupReplaceInput');
  if (!input?.files?.length) { alert('Bitte zuerst ein ZIP-Archiv auswählen.'); return; }
  if (!confirm('KOMPLETT ERSETZEN?\n\nDie aktiven Daten werden 1:1 aus dem Backup übernommen.\nAktive Projekte, die NICHT im Backup stehen, werden ins Archiv verschoben.\nVorhandene Archivdaten bleiben erhalten.\n\nEine Sicherheitskopie wird zuvor automatisch angelegt.')) return;
  try {
    const j = await _postBackupZip('backup_upload_replace', input.files[0]);
    if (!j.ok || !j.data) { alert('Ersetzen fehlgeschlagen: ' + (j.error || 'Unbekannter Fehler')); return; }
    appData    = j.data;
    selectedId = null;
    saveData();
    renderSidebar();
    showEmptyState();
    closeBackupModal();
    const arch = j.archived ? `\n${j.archived} nicht enthaltene Projekt(e) wurden ins Archiv verschoben.` : '';
    alert('Daten erfolgreich ersetzt!' + arch);
  } catch (e) {
    alert('Fehler beim Ersetzen:\n' + e.message);
  }
}

async function restoreFromBackup(dateKey) {
  if (!confirm(`Sicherung vom ${dateKey} wirklich wiederherstellen?\nDer aktuelle Stand wird überschrieben.`)) return;
  try {
    const r = await fetch(`api.php?action=restore&date=${encodeURIComponent(dateKey)}`, { method: 'POST' });
    const j = await r.json();
    if (!j.ok || !j.data) { alert('Sicherung konnte nicht wiederhergestellt werden.' + (j.error ? '\n' + j.error : '')); return; }
    appData    = j.data;
    selectedId = null;
    saveData();
    renderSidebar();
    showEmptyState();
    closeBackupModal();
    alert('Sicherung erfolgreich wiederhergestellt!');
  } catch (e) {
    alert('Fehler beim Wiederherstellen:\n' + e.message);
  }
}

// ============================================================
// AUTH
// ============================================================

// ── Automatische Abmeldung nach Inaktivität (Client-seitig) ───
// Ergänzt die serverseitige Inaktivitätsprüfung: meldet den Nutzer nach der
// eingestellten Zeit (session_timeout_minutes) OHNE Interaktion aktiv ab.
let _idleLogoutTimer = null;
let _idleLastReset   = 0;
let _idleUserActive  = false; // true nur bei ECHTER User-Interaktion (nicht Scroll durch Render)
function _resetIdleLogout(e) {
  if (!currentUser) return;
  // Nur echte User-Interaktion zählt (nicht programmatische Scroll-Events durch Render/Poll)
  if (e && !e.isTrusted) return;
  const nowMs = Date.now();
  if (nowMs - _idleLastReset < 5000) return;    // Drossel: höchstens alle 5 s neu setzen
  _idleLastReset = nowMs;
  _idleUserActive = true;
  const min = Math.min(43200, Math.max(5, parseInt(appSettings?.session_timeout_minutes) || 480));
  clearTimeout(_idleLogoutTimer);
  _idleLogoutTimer = setTimeout(async () => {
    try { showNotification('Automatisch abgemeldet (Inaktivität).'); } catch (_) {}
    await doLogout();
  }, min * 60 * 1000);
}
function _initIdleLogout() {
  ['mousemove', 'mousedown', 'keydown', 'touchstart', 'click', 'wheel'].forEach(ev =>
    window.addEventListener(ev, _resetIdleLogout, { passive: true }));
  // scroll bewusst NICHT – wird durch programmatische Renders getriggert und würde
  // den Timer permanent zurücksetzen (z.B. Wochenplanungs-Poll-Render).
  _resetIdleLogout();
}

async function doLogout() {
  clearTimeout(_idleLogoutTimer);
  _stopProjectPresence();
  localStorage.removeItem('bk_user');
  localStorage.removeItem('bk_appData');
  try {
    await fetch('api.php?action=logout', { method: 'POST' });
  } catch (e) {
    // Offline - Session kann serverseitig nicht beendet werden, aber lokaler
    // State ist bereits gelöscht, sodass login.html nicht zurückleitet
    console.warn('Logout-Request fehlgeschlagen (offline?):', e);
  }
  window.location.replace('login.html');
}

// ============================================================
// PERMISSIONS  -  helper functions
// ============================================================
function canDo(perm) {
  if (currentRole === 'admin') return true;
  return !!currentPerms[perm];
}

// ============================================================
// THEME  -  Dark / Light Mode
// ============================================================
function applyTheme(theme) {
  if (theme === 'dark') {
    document.body.classList.add('dark-theme');
  } else {
    document.body.classList.remove('dark-theme');
  }
  localStorage.setItem('bk_theme', theme);
  const btn = document.getElementById('btnThemeToggle');
  if (btn) btn.textContent = theme === 'dark' ? 'Light Mode' : 'Dark Mode';
}

function toggleTheme() {
  const current = document.body.classList.contains('dark-theme') ? 'dark' : 'light';
  const next = current === 'dark' ? 'light' : 'dark';
  applyTheme(next);
  fetch('api.php?action=set_theme', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ theme: next })
  }).catch(() => {});
}

function getVisibleBaustellen() {
  if (currentVisibility === 'all' || !Array.isArray(currentVisibility)) {
    return appData.baustellen;
  }
  return appData.baustellen.filter(b => currentVisibility.includes(b.id));
}

function applyPermissions() {
  // Hide export buttons if no export permission
  if (!canDo('canExport')) {
    document.querySelectorAll('.btn-success, .btn-import').forEach(el => el.style.display = 'none');
    document.getElementById('importFile')?.parentElement?.querySelectorAll('.btn-import').forEach(el => el.style.display = 'none');
  }
  // Hide ALL prices for non-price users
  if (!canDo('canSeePrices')) {
    showEkCols = false;
    document.body.classList.add('hide-prices');
  } else {
    document.body.classList.remove('hide-prices');
  }
  // Hide Gewinn for non-gewinn users
  if (!canDo('canSeeGewinn')) {
    document.body.classList.add('hide-gewinn');
  } else {
    document.body.classList.remove('hide-gewinn');
  }
  // Hide create-baustelle buttons
  if (!canDo('canCreateBaustelle')) {
    const btn1 = document.getElementById('btnAddBaustelle');
    if (btn1) btn1.style.display = 'none';
    const btn2 = document.getElementById('btnAddBaustelleEmpty');
    if (btn2) btn2.style.display = 'none';
  }
  // Hide price-view buttons for non-price users
  if (!canDo('canSeePrices')) {
    const bb = document.getElementById('btnBlackout');
    if (bb) bb.style.display = 'none';
    const bk = document.getElementById('btnKundenansicht');
    if (bk) bk.style.display = 'none';
  }

  const canSeeRe = canDo('canSeeRechnungen') || canDo('canManageRechnungen');
  const canSeeAn = canDo('canSeeAngebote') || canDo('canManageAngebote');
  const hasAny = canSeeRe || canSeeAn;
  const reBtn = document.getElementById('btnRechnungen');
  if (reBtn) reBtn.style.display = (appSettings.modul_rechnungen === false || !hasAny) ? 'none' : '';
  const reSub = document.getElementById('btnRechnungenSub');
  if (reSub) reSub.style.display = (appSettings.modul_rechnungen === false || !canSeeRe) ? 'none' : '';
  const anSub = document.getElementById('btnAngeboteSub');
  if (anSub) anSub.style.display = (appSettings.modul_rechnungen === false || !canSeeAn) ? 'none' : '';

  const kiBtn = document.getElementById('btnKiScanHeader');
  if (kiBtn) kiBtn.style.display = (canDo('canEditMaterial') || canDo('canEditArbeitszeit')) ? '' : 'none';
}

