      const dbRows = [['Typ', 'Titel', 'Beschreibung', 'Status', 'Priorität', 'Fällig am', 'Zugewiesen an', 'Ersteller', 'Farbe']];
      dbItems.forEach(i => {
        dbRows.push([i.typ || '', i.titel || '', i.beschreibung || '', i.status || '', i.prioritaet || '', i.faelligAm || '', i.zugewiesen_an || '', i.ersteller || '', i.farbe || '']);
      });
