// ── Gruppen-Verwaltung (v2.10.0) ──────────────────────────
async function loadGruppenList() {
  const container = document.getElementById('gruppenList');
  if (!container) return;
  try {
    const r = await fetch('api.php?action=load_gruppen');
    const j = await r.json();
    if (!j.ok) { container.innerHTML = '<em>Fehler beim Laden.</em>'; return; }
    gruppenData = (j.gruppen || []).map(g => ({ id: g.id, name: g.name, farbe: g.farbe }));
    if (!j.gruppen.length) {
      container.innerHTML = '<p style="color:var(--grey-400);font-size:.82rem">Noch keine Gruppen angelegt.</p>';
      return;
    }
    container.innerHTML = j.gruppen.map(g => `
      <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #eee;flex-wrap:wrap">
        <span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:${esc(g.farbe)};flex-shrink:0"></span>
        <span style="font-weight:600;min-width:100px">${esc(g.name)}</span>
        <span style="font-size:.75rem;color:var(--grey-500)">${g.mitglieder.length ? g.mitglieder.map(m => esc(m)).join(', ') : '–'}</span>
        <div style="margin-left:auto;display:flex;gap:6px">
          <button class="btn btn-secondary btn-sm" onclick="openGruppeForm(${g.id})">✏️ Bearbeiten</button>
          <button class="btn btn-secondary btn-sm" style="color:var(--danger)" onclick="deleteGruppe(${g.id})">🗑 Löschen</button>
        </div>
      </div>
    `).join('');
  } catch(e) {
    container.innerHTML = '<em>API nicht erreichbar.</em>';
  }
}

async function openGruppeForm(id) {
  // Benutzer laden für Mitglieder-Auswahl
  let users = [];
  try {
    const r = await fetch('api.php?action=list_users');
    const j = await r.json();
    if (j.ok) users = j.users || [];
  } catch(e) {}

  let existingGruppe = null;
  if (id) {
    try {
      const r = await fetch('api.php?action=load_gruppen');
      const j = await r.json();
      if (j.ok) existingGruppe = (j.gruppen || []).find(g => g.id === id) || null;
    } catch(e) {}
  }

  const name   = existingGruppe ? existingGruppe.name  : '';
  const farbe  = existingGruppe ? existingGruppe.farbe : '#6366f1';
  const mitgls = existingGruppe ? (existingGruppe.mitglieder || []) : [];

  const userCheckboxes = users.map(u => `
    <label style="display:flex;align-items:center;gap:6px;padding:3px 0;cursor:pointer">
      <input type="checkbox" value="${esc(u.username)}" ${mitgls.includes(u.username) ? 'checked' : ''}
             class="gruppe-mitglied-cb">
      <span>${esc(u.username)}${u.kuerzel ? ' (' + esc(u.kuerzel) + ')' : ''}</span>
    </label>
  `).join('');

  const overlay = document.createElement('div');
  overlay.id = 'gruppeFormOverlay';
  overlay.className = 'kunde-form-overlay';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `<div class="kunde-form-card" style="max-width:460px">
    <h3 style="margin:0 0 16px">${id ? 'Gruppe bearbeiten' : 'Neue Gruppe'}</h3>
    <div class="form-row">
      <div class="form-group" style="flex:1">
        <label class="form-label">Gruppenname *</label>
        <input class="form-control" id="gfName" value="${esc(name)}" placeholder="z.B. Montage-Team">
      </div>
      <div class="form-group" style="flex:0 0 70px">
        <label class="form-label">Farbe</label>
        <input type="color" class="form-control" id="gfFarbe" value="${esc(farbe)}" style="height:36px;padding:2px 4px">
      </div>
    </div>
    <div class="form-group">
      <label class="form-label">Mitglieder</label>
      <div style="max-height:200px;overflow-y:auto;border:1px solid #e0e0e0;border-radius:6px;padding:8px">
        ${userCheckboxes || '<em style="font-size:.82rem;color:var(--grey-400)">Keine Benutzer gefunden.</em>'}
      </div>
    </div>
    <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px">
      <button class="btn btn-secondary" onclick="document.getElementById('gruppeFormOverlay')?.remove()">Abbrechen</button>
      <button class="btn btn-primary" onclick="saveGruppe(${id || 'null'})">${id ? 'Speichern' : 'Erstellen'}</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => document.getElementById('gfName')?.focus(), 100);
}

async function saveGruppe(id) {
  const name  = document.getElementById('gfName')?.value?.trim();
  const farbe = document.getElementById('gfFarbe')?.value || '#6366f1';
  if (!name) { alert('Gruppenname ist Pflichtfeld.'); return; }
  const mitglieder = Array.from(
    document.querySelectorAll('.gruppe-mitglied-cb:checked')
  ).map(cb => cb.value);

  try {
    const r = await fetch('api.php?action=save_gruppe', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ id: id || null, name, farbe, mitglieder })
    });
    const j = await r.json();
    if (j.ok) {
      document.getElementById('gruppeFormOverlay')?.remove();
      loadGruppenList();
      // Lokale gruppenData aktualisieren
      fetch('api.php?action=load_gruppen_for_user').then(r2=>r2.json()).then(j2=>{
        if(j2.ok) gruppenData = j2.gruppen || [];
      }).catch(()=>{});
    } else {
      alert(j.error || 'Fehler beim Speichern.');
    }
  } catch(e) { alert('Netzwerkfehler.'); }
}

async function deleteGruppe(id) {
  if (!confirm('Gruppe wirklich löschen?')) return;
  try {
    const r = await fetch('api.php?action=delete_gruppe', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ id })
    });
    const j = await r.json();
    if (j.ok) {
      loadGruppenList();
      gruppenData = gruppenData.filter(g => g.id !== id);
    } else {
      alert(j.error || 'Fehler.');
    }
  } catch(e) { alert('Netzwerkfehler.'); }
}

function resolveZuweisung(val) {
  if (!val) return '';
  if (val === 'alle') return '📢 Alle';
  if (val.startsWith('gruppe:')) {
    const gid = parseInt(val.replace('gruppe:', ''), 10);
    const g   = (gruppenData || []).find(x => x.id === gid);
    return '👥 ' + (g ? g.name : 'Gruppe ' + gid);
  }
  return '👤 ' + val;
}
