function downloadAuditLog(format) {
  const form = document.createElement('form');
  form.method = 'POST';
  form.action = 'api.php?action=download_audit_log';
  form.style.display = 'none';
  const inp = document.createElement('input');
  inp.type = 'hidden'; inp.name = 'body'; inp.value = JSON.stringify({ format });
  form.appendChild(inp);
  document.body.appendChild(form);
  form.submit();
  setTimeout(() => document.body.removeChild(form), 2000);
}

function firmaField(key, label, s) {
  return `<div><label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">${label}</label>
    <input type="text" class="form-control" value="${esc(s[key] || '')}" style="font-size:.85rem;width:100%"
           onchange="updateSetting('${key}',this.value)"></div>`;
}

// ============================================================
// JAHRESWECHSEL-ASSISTENT
// ============================================================

let _jwData = null; // geladene Daten aus get_jahreswechsel_data

function openJahreswechselModal() {
  const modal = document.getElementById('jahreswechselModal');
  if (!modal) return;
  show('jahreswechselModal');
  // Quell-Jahr = laufendes Jahr (Ziel-Jahr = Quell-Jahr + 1). Zuvor wurde
  // fälschlich das Folgejahr als Quelle gesetzt (z.B. 2027 statt 2026).
  const sourceYear = new Date().getFullYear();
  document.getElementById('jwModalBody').innerHTML = `<p style="padding:24px;color:#888">Lädt Daten für ${sourceYear}…</p>`;
  document.getElementById('jwStatus').textContent = '';
  _loadJahreswechselData(sourceYear);
}

function closeJahreswechselModal() {
  hide('jahreswechselModal');
}

async function _loadJahreswechselData(year) {
  try {
    const r = await fetch(`api.php?action=get_jahreswechsel_data&year=${year}`);
    const j = await r.json();
    if (!j.ok) throw new Error(j.error || 'Fehler');
    _jwData = { ...j, year };
    document.getElementById('jwModalBody').innerHTML = _renderJahreswechselModal(j, year);
  } catch(e) {
    document.getElementById('jwModalBody').innerHTML = `<p style="padding:24px;color:#e53935">Fehler: ${esc(e.message)}</p>`;
  }
}

function _renderJahreswechselModal(d, year) {
  const nextYear = year + 1;
  const { users = [], customFeiertage = [], gleitzeitAktiv } = d;

  // --- Abschnitt: Urlaubstage ---
  const urlaubRows = users.map(u => {
    const curVal = (u.urlaubstageProJahr && u.urlaubstageProJahr[year]) ?? 30;
    const nextVal = (u.urlaubstageProJahr && u.urlaubstageProJahr[nextYear]) ?? curVal;
    return `<tr>
      <td style="padding:6px 8px;font-size:.85rem">${esc(u.username)}</td>
      <td style="padding:6px 8px;font-size:.85rem;text-align:center">${curVal}</td>
      <td style="padding:6px 8px">
        <input type="number" min="0" max="365" value="${nextVal}"
               style="width:72px;font-size:.85rem;padding:3px 6px;border:1px solid #ccc;border-radius:4px;text-align:center"
               data-jw-urlaub-user="${esc(u.username)}" data-jw-urlaub-prev="${curVal}">
      </td>
      <td style="padding:6px 8px;text-align:center">
        <input type="checkbox" data-jw-urlaub-check="${esc(u.username)}" checked
               title="Urlaubstage für ${nextYear} setzen">
      </td>
    </tr>`;
  }).join('');

  // --- Abschnitt: Gleitzeit ---
  let gleitzeitSection = '';
  if (gleitzeitAktiv) {
    const gzRows = users.map(u => {
      if (u.gleitzeitSaldo === null) return '';
      const saldo = Number(u.gleitzeitSaldo);
      const sign  = saldo >= 0 ? '+' : '';
      const color = saldo >= 0 ? '#28A745' : '#e53935';
      const defaultKommentar = `Gleitzeitübertrag ${year}→${nextYear}`;
      return `<tr>
        <td style="padding:6px 8px;font-size:.85rem">${esc(u.username)}</td>
        <td style="padding:6px 8px;font-size:.85rem;text-align:right;color:${color};font-weight:600">${sign}${saldo.toFixed(2)} h</td>
        <td style="padding:6px 8px">
          <input type="number" step="0.01" value="${saldo.toFixed(2)}"
                 style="width:90px;font-size:.85rem;padding:3px 6px;border:1px solid #ccc;border-radius:4px;text-align:center"
                 data-jw-gz-betrag="${esc(u.username)}">
        </td>
        <td style="padding:6px 8px">
          <input type="text" value="${esc(defaultKommentar)}" placeholder="Kommentar"
                 style="width:100%;font-size:.82rem;padding:3px 6px;border:1px solid #ccc;border-radius:4px"
                 data-jw-gz-kommentar="${esc(u.username)}">
        </td>
        <td style="padding:6px 8px;text-align:center">
          <input type="checkbox" data-jw-gz-check="${esc(u.username)}" ${Math.abs(saldo) > 0.01 ? 'checked' : ''}
                 title="Gleitzeit-Übertrag für ${nextYear} buchen">
        </td>
      </tr>`;
    }).filter(Boolean).join('');

    gleitzeitSection = `
    <div style="padding:16px 20px;border-top:1px solid #e8e8e8">
      <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">⏱ Gleitzeitkonto-Übertrag</h3>
      <p style="font-size:.8rem;color:#666;margin-bottom:10px">Gebuchter Saldo ${year}. Der Betrag wird als Buchung im neuen Jahr (${nextYear}) eingetragen.</p>
      ${gzRows ? `<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;min-width:480px">
        <thead><tr style="background:#f5f5f5">
          <th style="padding:6px 8px;font-size:.8rem;text-align:left">Mitarbeiter</th>
          <th style="padding:6px 8px;font-size:.8rem;text-align:right">Saldo ${year}</th>
          <th style="padding:6px 8px;font-size:.8rem;text-align:center">Übertragsbet. (h)</th>
          <th style="padding:6px 8px;font-size:.8rem">Kommentar</th>
          <th style="padding:6px 8px;font-size:.8rem;text-align:center">✓</th>
        </tr></thead>
        <tbody>${gzRows}</tbody>
      </table></div>` : '<p style="font-size:.85rem;color:#aaa">Keine Gleitzeit-Daten verfügbar.</p>'}
    </div>`;
  }

  // --- Abschnitt: Custom Feiertage ---
  const cfFiltered = customFeiertage.filter(f => f.datum && String(f.datum).startsWith(String(year)));
  let feiertageSection = '';
  if (cfFiltered.length > 0) {
    const cfRows = cfFiltered.map((f, idx) => {
      const newDatum = `${nextYear}-${String(f.datum).substring(5)}`;
      return `<tr>
        <td style="padding:6px 8px;font-size:.85rem">${esc(f.name || '')}</td>
        <td style="padding:6px 8px;font-size:.85rem;color:#888">${esc(f.datum)}</td>
        <td style="padding:6px 8px;font-size:.85rem">${esc(newDatum)}</td>
        <td style="padding:6px 8px;text-align:center">
          <input type="checkbox" data-jw-cf-check="${idx}" checked
                 data-jw-cf-name="${esc(f.name || '')}" data-jw-cf-datum="${esc(newDatum)}"
                 title="In ${nextYear} kopieren">
        </td>
      </tr>`;
    }).join('');
    feiertageSection = `
    <div style="padding:16px 20px;border-top:1px solid #e8e8e8">
      <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">📅 Betriebliche Feiertage kopieren</h3>
      <p style="font-size:.8rem;color:#666;margin-bottom:10px">Betriebliche Sonderfeiertage aus ${year} werden mit angepasstem Datum nach ${nextYear} übernommen.</p>
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;min-width:380px">
        <thead><tr style="background:#f5f5f5">
          <th style="padding:6px 8px;font-size:.8rem;text-align:left">Bezeichnung</th>
          <th style="padding:6px 8px;font-size:.8rem">Datum ${year}</th>
          <th style="padding:6px 8px;font-size:.8rem">Datum ${nextYear}</th>
          <th style="padding:6px 8px;font-size:.8rem;text-align:center">✓</th>
        </tr></thead>
        <tbody>${cfRows}</tbody>
      </table></div>
    </div>`;
  } else {
    feiertageSection = `
    <div style="padding:16px 20px;border-top:1px solid #e8e8e8">
      <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">📅 Betriebliche Feiertage</h3>
      <p style="font-size:.82rem;color:#aaa">Keine betrieblichen Sonderfeiertage für ${year} konfiguriert.</p>
    </div>`;
  }

  // --- Abschnitt: Stundenbuchungen abschließen ---
  const aktuellAbschluss = parseInt(appSettings.zeiterfassung_abschluss_jahr) || 0;
  const abschlussSection = `
    <div style="padding:16px 20px;border-top:1px solid #e8e8e8">
      <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">📦 Stundenbuchungen abschließen</h3>
      <p style="font-size:.8rem;color:#666;margin-bottom:10px">
        Buchungen des Jahres ${year} (und früher) werden in Stundenerfassung und
        Stundenauswertung <strong>ausgeblendet</strong> – die Daten bleiben vollständig
        erhalten und werden nicht gelöscht. Die Anzeige lässt sich jederzeit wieder
        einschalten oder hier rückgängig machen.
        ${aktuellAbschluss ? `<br><span style="color:#888">Aktuell abgeschlossen: bis einschließlich <strong>${aktuellAbschluss}</strong>.</span>` : ''}
      </p>
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:8px">
        <button type="button" class="btn btn-secondary btn-sm" onclick="saExportZeiterfassungExcel(${year})">⬇ Buchungen ${year} als Excel herunterladen</button>
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer">
        <input type="checkbox" data-jw-abschluss-check value="${year}" style="width:16px;height:16px;cursor:pointer">
        Buchungen bis einschließlich ${year} ausblenden (abschließen)
      </label>
      ${aktuellAbschluss ? `<label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer;margin-top:6px">
        <input type="checkbox" data-jw-abschluss-reset style="width:16px;height:16px;cursor:pointer">
        Abschluss aufheben (alle Jahre wieder einblenden)
      </label>` : ''}
    </div>`;

  // --- Abschnitt: Archivierte Baustellen aus Auswertung ausblenden ---
  const aktuellArchivAbschluss = parseInt(appSettings.auswertung_archiv_abschluss_jahr) || 0;
  const archivAbschlussSection = `
    <div style="padding:16px 20px;border-top:1px solid #e8e8e8">
      <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">🗄 Archivierte Baustellen abschließen</h3>
      <p style="font-size:.8rem;color:#666;margin-bottom:10px">
        Archivierte Baustellen, die ${year} (oder früher) archiviert wurden, werden in der
        kaufmännischen Auswertung <strong>ausgeblendet</strong> – die Archive bleiben
        vollständig erhalten und werden nicht gelöscht. Die Anzeige lässt sich in der
        Auswertung jederzeit wieder einschalten oder hier rückgängig machen.
        ${aktuellArchivAbschluss ? `<br><span style="color:#888">Aktuell ausgeblendet: bis einschließlich <strong>${aktuellArchivAbschluss}</strong>.</span>` : ''}
      </p>
      <label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer">
        <input type="checkbox" data-jw-archiv-check value="${year}" style="width:16px;height:16px;cursor:pointer">
        Archivierte Baustellen bis einschließlich ${year} aus der Auswertung ausblenden
      </label>
      ${aktuellArchivAbschluss ? `<label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer;margin-top:6px">
        <input type="checkbox" data-jw-archiv-reset style="width:16px;height:16px;cursor:pointer">
        Ausblendung aufheben (alle Archive wieder in Auswertung anzeigen)
      </label>` : ''}
    </div>`;

  return `
  <div style="padding:16px 20px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;border-bottom:1px solid #e8e8e8;background:#f9f9f9">
    <span style="font-size:.9rem;font-weight:600">Quell-Jahr:</span>
    <select id="jwYearSelect" class="form-control" style="width:120px;font-size:.9rem" onchange="_loadJahreswechselData(parseInt(this.value))">
      ${[year-1, year, year+1].map(y => `<option value="${y}" ${y === year ? 'selected' : ''}>${y}</option>`).join('')}
    </select>
    <span style="font-size:.82rem;color:#888">→ Ziel-Jahr: <strong>${nextYear}</strong></span>
  </div>
  <div style="padding:16px 20px;border-bottom:1px solid #e8e8e8">
    <h3 style="font-size:.95rem;margin-bottom:4px;color:var(--primary,#00B4D8)">🏖 Urlaubstage für ${nextYear}</h3>
    <p style="font-size:.8rem;color:#666;margin-bottom:10px">Urlaubstage aus ${year} werden als Vorgabewert eingetragen. Anpassen und Haken setzen zum Übernehmen.</p>
    ${urlaubRows ? `<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;min-width:380px">
      <thead><tr style="background:#f5f5f5">
        <th style="padding:6px 8px;font-size:.8rem;text-align:left">Mitarbeiter</th>
        <th style="padding:6px 8px;font-size:.8rem;text-align:center">Urlaubstage ${year}</th>
        <th style="padding:6px 8px;font-size:.8rem;text-align:center">Urlaubstage ${nextYear}</th>
        <th style="padding:6px 8px;font-size:.8rem;text-align:center">✓</th>
      </tr></thead>
      <tbody>${urlaubRows}</tbody>
    </table></div>` : '<p style="font-size:.85rem;color:#aaa">Keine Benutzer gefunden.</p>'}
  </div>
  ${gleitzeitSection}
  ${feiertageSection}
  ${abschlussSection}
  ${archivAbschlussSection}`;
}

async function executeJahreswechsel() {
  if (!_jwData) return;
  const year     = _jwData.year;
  const nextYear = year + 1;
  const btn      = document.getElementById('jwExecuteBtn');
  const status   = document.getElementById('jwStatus');
  btn.disabled   = true;
  status.textContent = 'Wird verarbeitet…';
  status.style.color = '#888';

  let done = 0, errors = [];

  // 1. Urlaubstage setzen
  const urlaubChecks = document.querySelectorAll('[data-jw-urlaub-check]');
  for (const chk of urlaubChecks) {
    if (!chk.checked) continue;
    const username = chk.dataset.jwUrlaubCheck;
    const inp      = document.querySelector(`[data-jw-urlaub-user="${username}"]`);
    const val      = parseUrlaubstageInput(inp?.value);
    try {
      const r = await fetch('api.php?action=set_urlaubstage', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ username, year: nextYear, urlaubstage: val })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      // Lokalen Cache aktualisieren
      const u = (_jwData.users || []).find(u => u.username === username);
      if (u) { if (!u.urlaubstageProJahr) u.urlaubstageProJahr = {}; u.urlaubstageProJahr[nextYear] = val; }
      done++;
    } catch(e) { errors.push(`Urlaub ${username}: ${e.message}`); }
  }

  // 2. Gleitzeit-Überträge buchen
  const gzChecks = document.querySelectorAll('[data-jw-gz-check]');
  for (const chk of gzChecks) {
    if (!chk.checked) continue;
    const username  = chk.dataset.jwGzCheck;
    const betragInp = document.querySelector(`[data-jw-gz-betrag="${username}"]`);
    const komInp    = document.querySelector(`[data-jw-gz-kommentar="${username}"]`);
    const betrag    = parseFloat(betragInp?.value) || 0;
    const kommentar = komInp?.value?.trim() || `Gleitzeitübertrag ${year}→${nextYear}`;
    if (Math.abs(betrag) < 0.001) continue;
    // Buchungsdatum = 01. Januar des Ziel-Jahres
    const datum = `${nextYear}-01-01`;
    try {
      const r = await fetch('api.php?action=save_gleitzeitkonto_buchung', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ username, betrag, kommentar, datum })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      done++;
    } catch(e) { errors.push(`Gleitzeit ${username}: ${e.message}`); }
  }

  // 3. Custom Feiertage kopieren
  const cfChecks = document.querySelectorAll('[data-jw-cf-check]');
  const newCf = [];
  for (const chk of cfChecks) {
    if (!chk.checked) continue;
    newCf.push({ name: chk.dataset.jwCfName, datum: chk.dataset.jwCfDatum });
  }
  if (newCf.length > 0) {
    try {
      // Bestehende custom_feiertage laden und Einträge für nextYear entfernen, dann neue hinzufügen
      let existing = [];
      try { existing = appSettings.custom_feiertage ? JSON.parse(appSettings.custom_feiertage) : []; } catch(e) {}
      const filtered = existing.filter(f => !String(f.datum || '').startsWith(String(nextYear)));
      const merged   = [...filtered, ...newCf];
      const r = await fetch('api.php?action=save_settings', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ custom_feiertage: JSON.stringify(merged) })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      appSettings.custom_feiertage = JSON.stringify(merged);
      done += newCf.length;
    } catch(e) { errors.push(`Feiertage: ${e.message}`); }
  }

  // 4. Stundenbuchungen abschließen / Abschluss aufheben (nur ausblenden, kein Löschen)
  const abschlussChk = document.querySelector('[data-jw-abschluss-check]');
  const abschlussReset = document.querySelector('[data-jw-abschluss-reset]');
  if (abschlussReset?.checked) {
    try {
      const r = await fetch('api.php?action=save_settings', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ zeiterfassung_abschluss_jahr: 0 })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      appSettings.zeiterfassung_abschluss_jahr = 0;
      done++;
    } catch(e) { errors.push(`Abschluss aufheben: ${e.message}`); }
  } else if (abschlussChk?.checked) {
    const abschlussJahr = parseInt(abschlussChk.value) || year;
    try {
      const r = await fetch('api.php?action=save_settings', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ zeiterfassung_abschluss_jahr: abschlussJahr })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      appSettings.zeiterfassung_abschluss_jahr = abschlussJahr;
      done++;
    } catch(e) { errors.push(`Abschluss ${abschlussChk.value}: ${e.message}`); }
  }

  // 5. Archivierte Baustellen aus Auswertung ausblenden / wieder einblenden
  const archivChk = document.querySelector('[data-jw-archiv-check]');
  const archivReset = document.querySelector('[data-jw-archiv-reset]');
  if (archivReset?.checked) {
    try {
      const r = await fetch('api.php?action=save_settings', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ auswertung_archiv_abschluss_jahr: 0 })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      appSettings.auswertung_archiv_abschluss_jahr = 0;
      done++;
    } catch(e) { errors.push(`Archiv-Ausblendung aufheben: ${e.message}`); }
  } else if (archivChk?.checked) {
    const archivJahr = parseInt(archivChk.value) || year;
    try {
      const r = await fetch('api.php?action=save_settings', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ auswertung_archiv_abschluss_jahr: archivJahr })
      });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'Fehler');
      appSettings.auswertung_archiv_abschluss_jahr = archivJahr;
      done++;
    } catch(e) { errors.push(`Archiv-Ausblendung ${archivChk.value}: ${e.message}`); }
  }

  btn.disabled = false;
  if (errors.length === 0) {
    status.textContent = `✓ ${done} Änderung(en) übernommen.`;
    status.style.color = '#388E3C';
    // Feiertags-Anzeige in Einstellungen sofort aktualisieren
    const sec = document.getElementById('feiertageSection');
    if (sec) sec.innerHTML = renderFeiertageSection(appSettings);
  } else {
    status.textContent = `${done} OK – ${errors.length} Fehler: ${errors.join('; ')}`;
    status.style.color = '#e53935';
  }
}

// Exportiert alle Stundenbuchungen eines Jahres (alle Mitarbeiter) als Excel.
// Liest die Daten frisch vom Server – verändert nichts an der Datenbank.
async function saExportZeiterfassungExcel(year) {
  if (typeof XLSX === 'undefined') { showNotification('Excel-Bibliothek nicht geladen.'); return; }
  const status = document.getElementById('jwStatus');
  if (status) { status.textContent = `Exportiere Buchungen ${year}…`; status.style.color = '#888'; }
  try {
    const r = await fetch('api.php?action=load_all_zeiterfassung');
    const j = await r.json();
    if (!j.ok) throw new Error(j.error || 'Fehler beim Laden');
    const data = j.data || {};
    const erweitert = !!appSettings.erweiterte_zeiterfassung;
    const header = erweitert
      ? ['Mitarbeiter','Datum','Typ','Von','Bis','Pause (min)','Baustelle','Bemerkung','Stunden']
      : ['Mitarbeiter','Datum','Typ','Baustelle','Bemerkung','Stunden'];
    const rows = [header];
    const yStr = String(year);
    let count = 0;
    Object.keys(data).sort().forEach(username => {
      const user = saAllUsers.find(item => item.username === username) || { username, sollstundenTag: 8, arbeitstage: '1,2,3,4,5' };
      const entries = (data[username]?.entries || [])
        .filter(e => e.datum && e.datum.startsWith(yStr))
        .sort((a,b) => (a.datum||'').localeCompare(b.datum||''));
      entries.forEach(e => {
        const bName = e.baustelleId ? ((appData.baustellen||[]).find(b=>b.id===e.baustelleId)?.name || ('#'+e.baustelleId)) : '';
        const typLabel = (typeof _seTypLabel === 'function') ? _seTypLabel(e.typ) : (e.typ||'');
        const stunden = bkIstStundenEintrag(user, e, appSettings?.ze_custom_typen || []);
        if (erweitert) {
          rows.push([username, e.datum, typLabel, e.von||'', e.bis||'', e.pause||'', bName, e.bemerkung||'', stunden]);
        } else {
          rows.push([username, e.datum, typLabel, bName, e.bemerkung||'', stunden]);
        }
        count++;
      });
    });
    if (count === 0) {
      if (status) { status.textContent = `Keine Buchungen für ${year} gefunden.`; status.style.color = '#e53935'; }
      return;
    }
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, `Stunden ${year}`);
    XLSX.writeFile(wb, `Stundenbuchungen_${year}.xlsx`);
    if (status) { status.textContent = `✓ ${count} Buchung(en) aus ${year} exportiert.`; status.style.color = '#388E3C'; }
  } catch(e) {
    if (status) { status.textContent = `Fehler beim Export: ${e.message}`; status.style.color = '#e53935'; }
  }
}

// ============================================================
// FEIERTAGE-VERWALTUNG (Einstellungen)
// ============================================================

function _computeEaster(year) {
  const a = year % 19, b = Math.floor(year / 100), c = year % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31) - 1;
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(year, month, day);
}

function renderFeiertageSection(s) {
  const year = new Date().getFullYear();
  const easter = _computeEaster(year);
  const aD = (n) => { const r = new Date(easter); r.setDate(r.getDate() + n); return r; };
  const fmt = (d) => d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
  const fixedHolidays = [
    { name: 'Neujahr',                   date: new Date(year, 0, 1)   },
    { name: 'Heilige Drei Könige',       date: new Date(year, 0, 6)   },
    { name: 'Karfreitag',                date: aD(-2)                  },
    { name: 'Ostermontag',               date: aD(1)                   },
    { name: 'Tag der Arbeit',            date: new Date(year, 4, 1)   },
    { name: 'Christi Himmelfahrt',       date: aD(39)                  },
    { name: 'Pfingstmontag',             date: aD(50)                  },
    { name: 'Fronleichnam',              date: aD(60)                  },
    { name: 'Mariä Himmelfahrt',         date: new Date(year, 7, 15)  },
    { name: 'Tag der Deutschen Einheit', date: new Date(year, 9, 3)   },
    { name: 'Allerheiligen',             date: new Date(year, 10, 1)  },
    { name: '1. Weihnachtstag',          date: new Date(year, 11, 25) },
    { name: '2. Weihnachtstag',          date: new Date(year, 11, 26) },
  ];
  let customList = [];
  try { customList = s.custom_feiertage ? JSON.parse(s.custom_feiertage) : []; } catch(e) {}
  return `
    <h3 style="font-size:.95rem;margin-bottom:8px;color:var(--primary,#00B4D8)">📅 Feiertage &amp; arbeitsfreie Tage</h3>
    <p style="font-size:.8rem;color:#666;margin-bottom:14px">Bayerische Feiertage werden automatisch in Wochenplanung und Sollstundenberechnung berücksichtigt. Zusätzliche betriebliche Feiertage können unten eingetragen werden.</p>
    <div style="display:flex;gap:24px;flex-wrap:wrap;align-items:flex-start">
      <div style="flex:1;min-width:220px">
        <h4 style="font-size:.85rem;font-weight:600;margin-bottom:8px;color:#444">Gesetzliche Feiertage Bayern ${year}</h4>
        ${fixedHolidays.map(h => `
          <div style="display:flex;justify-content:space-between;font-size:.82rem;padding:3px 0;border-bottom:1px solid #eee">
            <span>${esc(h.name)}</span>
            <span style="color:#888;white-space:nowrap;margin-left:8px">${fmt(h.date)}</span>
          </div>`).join('')}
      </div>
      <div style="flex:1;min-width:220px">
        <h4 style="font-size:.85rem;font-weight:600;margin-bottom:8px;color:#444">Betriebliche / zusätzliche Tage</h4>
        ${customList.length === 0
          ? '<p style="font-size:.82rem;color:#aaa;margin-bottom:8px">Keine zusätzlichen Tage konfiguriert.</p>'
          : customList.map((f, idx) => `
          <div style="display:flex;justify-content:space-between;align-items:center;font-size:.82rem;padding:3px 0;border-bottom:1px solid #eee">
            <span>${esc(f.name)}</span>
            <span style="display:flex;align-items:center;gap:6px">
              <span style="color:#888;white-space:nowrap">${esc(f.datum)}</span>
              <button class="btn btn-sm" style="padding:0 6px;font-size:.75rem;color:#e53935;border:none;background:none;cursor:pointer" onclick="deleteCustomFeiertag(${idx})" title="Entfernen">✕</button>
            </span>
          </div>`).join('')}
        <div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap;align-items:center">
          <input type="date" id="neuFeiertag_datum" class="form-control" style="flex:0 0 auto;width:150px;font-size:.85rem">
          <input type="text" id="neuFeiertag_name" class="form-control" style="flex:1;min-width:130px;font-size:.85rem" placeholder="Bezeichnung">
          <button class="btn btn-primary btn-sm" onclick="addCustomFeiertag()">+ Hinzufügen</button>
        </div>
      </div>
    </div>`;
}

async function addCustomFeiertag() {
  const datumEl = document.getElementById('neuFeiertag_datum');
  const nameEl  = document.getElementById('neuFeiertag_name');
  const datum = datumEl ? datumEl.value.trim() : '';
  const name  = nameEl  ? nameEl.value.trim()  : '';
  if (!datum || !name) { showNotification('Datum und Bezeichnung sind erforderlich.'); return; }
  let list = [];
  try { list = appSettings.custom_feiertage ? JSON.parse(appSettings.custom_feiertage) : []; } catch(e) {}
  if (list.some(f => f.datum === datum)) { showNotification('Dieser Tag ist bereits eingetragen.'); return; }
  list.push({ datum, name });
  list.sort((a, b) => a.datum.localeCompare(b.datum));
  await updateSetting('custom_feiertage', JSON.stringify(list));
  const sec = document.getElementById('feiertageSection');
  if (sec) sec.innerHTML = renderFeiertageSection(appSettings);
}

async function deleteCustomFeiertag(idx) {
  let list = [];
  try { list = appSettings.custom_feiertage ? JSON.parse(appSettings.custom_feiertage) : []; } catch(e) {}
  list.splice(idx, 1);
  await updateSetting('custom_feiertage', JSON.stringify(list));
  const sec = document.getElementById('feiertageSection');
  if (sec) sec.innerHTML = renderFeiertageSection(appSettings);
}

