async function loadOciLieferanten() {
  const sec = document.getElementById('ociLieferantenSection');
  if (!sec) return;
  try {
    const r = await fetch('api.php?action=oci_list_lieferanten');
    const j = await r.json();
    if (!j.ok) { sec.innerHTML = `<p style="color:red;font-size:.85rem">Fehler beim Laden${j.error ? ': ' + esc(j.error) : '.'}</p>`; return; }
    renderOciLieferantenTable(j.lieferanten || []);
  } catch (e) {
    if (sec) sec.innerHTML = '<p style="color:red;font-size:.85rem">Netzwerkfehler.</p>';
  }
}

function renderOciLieferantenTable(items) {
  const sec = document.getElementById('ociLieferantenSection');
  if (!sec) return;
  const rows = items.map(l => `
    <tr>
      <td style="padding:6px 8px;font-size:.88rem">${esc(l.name)}</td>
      <td style="padding:6px 8px;font-size:.8rem;color:#555;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(l.url)}">${esc(l.url)}</td>
      <td style="padding:6px 8px;text-align:center">
        <span style="background:${l.aktiv?'#E8F5E9':'#FFEBEE'};color:${l.aktiv?'#2e7d32':'#c62828'};padding:2px 8px;border-radius:10px;font-size:.75rem">
          ${l.aktiv ? 'Aktiv' : 'Inaktiv'}
        </span>
      </td>
      <td style="padding:6px 8px;white-space:nowrap">
        <button class="btn btn-secondary btn-sm" style="margin-right:4px" onclick="showOciLieferantForm(${l.id})">✏️ Bearb.</button>
        <button class="btn btn-secondary btn-sm" style="color:#e53935" onclick="deleteOciLieferant(${l.id},'${esc(l.name)}')">🗑</button>
      </td>
    </tr>`).join('');

  sec.innerHTML = `
    <p style="font-size:.82rem;color:#555;margin-bottom:10px">
      Konfigurieren Sie hier OCI-4.0-Lieferanten (z.&nbsp;B. fega&amp;&nbsp;schmitt, Sonepar, Rexel).
      Anschließend ist im Material-Picker der Button <strong>🏪 OCI</strong> verfügbar.
    </p>
    ${items.length > 0 ? `
    <div class="table-wrapper" style="margin-bottom:10px">
      <table class="data-table" style="width:100%">
        <thead><tr>
          <th>Name</th><th>OCI-URL</th><th style="width:80px;text-align:center">Status</th><th style="width:140px"></th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>` : '<p style="font-size:.85rem;color:#888;margin-bottom:10px">Noch keine Lieferanten konfiguriert.</p>'}
    <button class="btn btn-primary btn-sm" onclick="showOciLieferantForm(0)">+ Lieferant hinzufügen</button>
    <div id="ociLieferantFormWrap" style="display:none;margin-top:16px;border:1px solid #ddd;border-radius:8px;padding:16px;background:#fff"></div>`;
}

function showOciLieferantForm(id) {
  const wrap = document.getElementById('ociLieferantFormWrap');
  if (!wrap) return;

  // Bestehenden Lieferanten laden wenn id > 0
  const fillForm = (l) => {
    wrap.style.display = 'block';
    wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    wrap.innerHTML = `
      <h4 style="font-size:.95rem;margin:0 0 12px">${l && l.id ? 'Lieferant bearbeiten' : 'Neuer Lieferant'}</h4>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;margin-bottom:12px">
        <div>
          <label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">Name *</label>
          <input type="text" id="ociFormName" class="form-control" style="font-size:.88rem" value="${esc(l?.name||'')}" placeholder="z.B. fega &amp; schmitt">
        </div>
        <div style="grid-column:1/-1">
          <label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">OCI-URL * <span style="color:#888">(vom Lieferanten, beginnt mit https://)</span></label>
          <input type="url" id="ociFormUrl" class="form-control" style="font-size:.88rem" value="${esc(l?.url||'')}" placeholder="https://…/oci">
        </div>
        <div>
          <label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">Benutzername</label>
          <input type="text" id="ociFormUsername" class="form-control" style="font-size:.88rem" value="${esc(l?.username||'')}" autocomplete="username">
        </div>
        <div>
          <label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">Passwort ${l?.id ? '(leer = unverändert)' : ''}</label>
          <input type="password" id="ociFormPassword" class="form-control" style="font-size:.88rem" placeholder="${l?.id ? '••••••••' : ''}" autocomplete="new-password">
        </div>
        <div style="grid-column:1/-1">
          <label style="font-size:.78rem;color:#666;display:block;margin-bottom:2px">Notizen</label>
          <input type="text" id="ociFormNotizen" class="form-control" style="font-size:.88rem" value="${esc(l?.notizen||'')}" placeholder="z.B. Kundennummer, Ansprechpartner…">
        </div>
        <div>
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:4px 0">
            <input type="checkbox" id="ociFormAktiv" style="width:16px;height:16px;accent-color:var(--primary,#00B4D8)" ${(l?.aktiv??1)?'checked':''}>
            <span style="font-size:.88rem">Aktiv</span>
          </label>
        </div>
      </div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-primary btn-sm" onclick="saveOciLieferant(${l?.id||0})">Speichern</button>
        <button class="btn btn-secondary btn-sm" onclick="document.getElementById('ociLieferantFormWrap').style.display='none'">Abbrechen</button>
      </div>
      <p id="ociFormError" style="color:#c62828;font-size:.82rem;margin-top:8px;display:none"></p>`;
  };

  if (id > 0) {
    // Lade bestehende Daten via API-Liste (aus gerenderten Zeilen)
    fetch('api.php?action=oci_list_lieferanten')
      .then(r => r.json())
      .then(j => {
        const item = (j.lieferanten || []).find(x => x.id === id) || null;
        fillForm(item);
      })
      .catch(() => fillForm(null));
  } else {
    fillForm(null);
  }
}

async function saveOciLieferant(id) {
  const name     = document.getElementById('ociFormName')?.value.trim()     || '';
  const url      = document.getElementById('ociFormUrl')?.value.trim()      || '';
  const username = document.getElementById('ociFormUsername')?.value.trim() || '';
  const password = document.getElementById('ociFormPassword')?.value        || '';
  const notizen  = document.getElementById('ociFormNotizen')?.value.trim()  || '';
  const aktiv    = document.getElementById('ociFormAktiv')?.checked ? 1 : 0;
  const errEl    = document.getElementById('ociFormError');

  if (!name || !url) {
    if (errEl) { errEl.textContent = 'Name und URL sind Pflichtfelder.'; errEl.style.display = 'block'; }
    return;
  }
  if (errEl) errEl.style.display = 'none';

  try {
    const r = await fetch('api.php?action=oci_save_lieferant', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: id || 0, name, url, username, password, aktiv, notizen })
    });
    const j = await r.json();
    if (!j.ok) {
      if (errEl) { errEl.textContent = j.error || 'Fehler beim Speichern.'; errEl.style.display = 'block'; }
      return;
    }
    document.getElementById('ociLieferantFormWrap').style.display = 'none';
    loadOciLieferanten();
  } catch (e) {
    if (errEl) { errEl.textContent = 'Netzwerkfehler.'; errEl.style.display = 'block'; }
  }
}

async function deleteOciLieferant(id, name) {
  confirmDelete(`Lieferant "${name}" wirklich löschen?`, async () => {
    try {
      const r = await fetch('api.php?action=oci_delete_lieferant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id })
      });
      const j = await r.json();
      if (!j.ok) { alert(j.error || 'Fehler beim Löschen.'); return; }
      loadOciLieferanten();
    } catch (e) {
      alert('Netzwerkfehler.');
    }
  });
}

// Mobile Button-Reihenfolge Hilfsfunktionen
const _mobileBtnDefs = [
  { id: 'btnWochenplanungMobile',     label: '📆 Wochenplanung' },
  { id: 'btnZeituebersichtMobile',    label: '📅 Zeitübersicht' },
  { id: 'btnStundenauswertungMobile', label: '📊 Stundenauswertung' },
  { id: 'btnDienstleisterMobile',     label: '🤝 Dienstleister' },
  { id: 'btnTermineMobile',           label: '🗓 Termine' },
  { id: 'btnDashboardMobile',         label: '📋 Dashboard' },
];

function getMobileBtnOrder(orderStr) {
  let order = [];
  try { order = orderStr ? JSON.parse(orderStr) : []; } catch(e) { order = []; }
  if (!Array.isArray(order) || order.length === 0) {
    order = _mobileBtnDefs.map(b => b.id);
  }
  // Ensure all defined buttons are present, append missing ones
  _mobileBtnDefs.forEach(b => { if (!order.includes(b.id)) order.push(b.id); });
  return order;
}

function renderMobileBtnOrderList(orderStr) {
  const order = getMobileBtnOrder(orderStr);
  return order.map((btnId, idx) => {
    const def = _mobileBtnDefs.find(b => b.id === btnId);
    if (!def) return '';
    return `<div style="display:flex;align-items:center;gap:8px;background:#fff;border:1px solid #e0e0e0;border-radius:6px;padding:6px 10px">
      <span style="flex:1;font-size:.85rem">${def.label}</span>
      <button class="btn btn-secondary" style="padding:2px 8px;font-size:.8rem" onclick="moveMobileBtnInList(${idx},'up')" ${idx===0?'disabled':''}>↑</button>
      <button class="btn btn-secondary" style="padding:2px 8px;font-size:.8rem" onclick="moveMobileBtnInList(${idx},'down')" ${idx===order.length-1?'disabled':''}>↓</button>
    </div>`;
  }).join('');
}

async function moveMobileBtnInList(idx, dir) {
  const orderStr = appSettings.mobile_btn_order || '';
  const order = getMobileBtnOrder(orderStr);
  const swapIdx = dir === 'up' ? idx - 1 : idx + 1;
  if (swapIdx < 0 || swapIdx >= order.length) return;
  [order[idx], order[swapIdx]] = [order[swapIdx], order[idx]];
  const newOrderStr = JSON.stringify(order);
  await updateSetting('mobile_btn_order', newOrderStr);
  const listEl = document.getElementById('mobileBtnOrderList');
  if (listEl) listEl.innerHTML = renderMobileBtnOrderList(newOrderStr);
}

async function resetMobileBtnOrder() {
  await updateSetting('mobile_btn_order', '');
  const listEl = document.getElementById('mobileBtnOrderList');
  if (listEl) listEl.innerHTML = renderMobileBtnOrderList('');
}

async function updateSetting(key, value) {
  const statusEl = document.getElementById('settSaveStatus');
  try {
    const r = await fetch('api.php?action=save_settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ [key]: value })
    });
    const j = await r.json();
    if (j.ok) {
      if (key === 'smtp_pass' || key === 'gemini_api_key') {
        // Geheimnisse bleiben nur auf dem Server
        appSettings[key + '_gesetzt'] = value !== '';
        appSettings[key] = '';
      } else {
        appSettings[key] = value;
      }
      if (statusEl) { statusEl.textContent = 'Gespeichert'; setTimeout(() => statusEl.textContent = '', 2000); }
      applyModuleSettings();
    }
  } catch(e) {}
}

function _renderCustomTypenList(list) {
  const listEl = document.getElementById('seCustomTypenList');
  if (!listEl) return;
  if (!list || list.length === 0) {
    listEl.innerHTML = '<p style="font-size:.8rem;color:#aaa">Keine eigenen Typen definiert.</p>';
    return;
  }
  listEl.innerHTML = list.map((t, i) => {
    const val = typeof t === 'string' ? t : (t.value || t);
    const isArb = typeof t === 'string' ? true : (t.isArbeit !== false);
    const istSoll = typeof t === 'string' ? false : (t.istGleichSoll === true);
    const lbl = val.charAt(0).toUpperCase() + val.slice(1);
    return `<div style="display:flex;align-items:center;gap:8px;padding:3px 0">
      <span style="flex:1;font-size:.9rem">${esc(lbl)}</span>
      <label style="display:flex;align-items:center;gap:4px;font-size:.8rem;cursor:pointer;white-space:nowrap">
        <input type="checkbox" ${isArb ? 'checked' : ''} onchange="toggleSeCustomTypArbeit(${i})" style="cursor:pointer"> Arbeitszeit
      </label>
      <label style="display:flex;align-items:center;gap:4px;font-size:.8rem;cursor:pointer;white-space:nowrap;${isArb ? '' : 'opacity:.4;pointer-events:none'}" title="Beim Erfassen werden automatisch die Soll-Arbeitsstunden als Ist eingetragen (keine Stundeneingabe).">
        <input type="checkbox" ${istSoll ? 'checked' : ''} ${isArb ? '' : 'disabled'} onchange="toggleSeCustomTypIstSoll(${i})" style="cursor:pointer"> Ist = Soll
      </label>
      <button class="btn btn-secondary btn-sm" style="color:#e53935;padding:2px 8px;font-size:.78rem" onclick="removeSeCustomTyp(${i})">Entfernen</button>
    </div>`;
  }).join('');
}

async function addSeCustomTyp() {
  const inp = document.getElementById('seCustomTypInput');
  const raw = (inp?.value || '').trim();
  if (!raw) return;
  // Kleinschreibung intern, Zeichen begrenzen, keine Duplikate mit Builtins
  const normalized = raw.toLowerCase().replace(/[^a-z0-9äöüß_\- ]/gi, '').trim();
  if (!normalized) return;
  const builtins = ['arbeit','urlaub','krank','gleitzeit','sonstig','feiertag'];
  if (builtins.includes(normalized)) { showNotification('Dieser Typ ist bereits als Standard vorhanden.'); return; }
  const existing = appSettings.ze_custom_typen || [];
  const existingVals = existing.map(t => typeof t === 'string' ? t : t.value);
  if (existingVals.includes(normalized)) { showNotification('Typ bereits vorhanden.'); return; }
  const isArbeit = document.getElementById('seCustomTypIsArbeit')?.checked ?? true;
  const istGleichSoll = isArbeit && (document.getElementById('seCustomTypIstSoll')?.checked ?? false);
  const updated = [...existing, { value: normalized, isArbeit, istGleichSoll }];
  await updateSetting('ze_custom_typen', updated);
  if (inp) inp.value = '';
  const istSollCb = document.getElementById('seCustomTypIstSoll');
  if (istSollCb) istSollCb.checked = false;
  _renderCustomTypenList(updated);
}

// Ist=Soll ist nur bei Arbeitszeit sinnvoll – bei deaktivierter Arbeitszeit sperren.
function _seCustomTypInputSync() {
  const arb = document.getElementById('seCustomTypIsArbeit');
  const istSoll = document.getElementById('seCustomTypIstSoll');
  if (!arb || !istSoll) return;
  if (!arb.checked) { istSoll.checked = false; istSoll.disabled = true; }
  else istSoll.disabled = false;
}

async function removeSeCustomTyp(index) {
  const existing = [...(appSettings.ze_custom_typen || [])];
  existing.splice(index, 1);
  await updateSetting('ze_custom_typen', existing);
  _renderCustomTypenList(existing);
}

async function toggleSeCustomTypArbeit(index) {
  const existing = [...(appSettings.ze_custom_typen || [])];
  const cur = existing[index];
  if (cur === undefined) return;
  const curVal = typeof cur === 'string' ? cur : cur.value;
  const curIsArb = typeof cur === 'string' ? true : (cur.isArbeit !== false);
  const curIstSoll = typeof cur === 'string' ? false : (cur.istGleichSoll === true);
  const newIsArb = !curIsArb;
  existing[index] = { value: curVal, isArbeit: newIsArb, istGleichSoll: newIsArb ? curIstSoll : false };
  await updateSetting('ze_custom_typen', existing);
  _renderCustomTypenList(existing);
}

async function toggleSeCustomTypIstSoll(index) {
  const existing = [...(appSettings.ze_custom_typen || [])];
  const cur = existing[index];
  if (cur === undefined) return;
  const curVal = typeof cur === 'string' ? cur : cur.value;
  const curIsArb = typeof cur === 'string' ? true : (cur.isArbeit !== false);
  if (!curIsArb) return; // nur bei Arbeitszeit erlaubt
  const curIstSoll = typeof cur === 'string' ? false : (cur.istGleichSoll === true);
  existing[index] = { value: curVal, isArbeit: true, istGleichSoll: !curIstSoll };
  await updateSetting('ze_custom_typen', existing);
  _renderCustomTypenList(existing);
}

async function uploadFirmenlogo(input) {
  if (!input.files || !input.files[0]) return;
  const file = input.files[0];
  if (file.size > 2 * 1024 * 1024) { alert('Max. 2 MB.'); return; }
  const fd = new FormData();
  fd.append('logo', file);
  try {
    const r = await fetch('api.php?action=upload_logo', { method: 'POST', body: fd });
    const j = await r.json();
    if (j.ok) {
      appSettings.firma_logo_url = j.url;
      showNotification('Logo hochgeladen.');
      showAllgemeinSettings();
    } else {
      alert(j.error || 'Fehler.');
    }
  } catch(e) { alert('Netzwerkfehler.'); }
}

async function deleteFirmenlogo() {
  await updateSetting('firma_logo_url', '');
  _imgB64Cache = {};
  showAllgemeinSettings();
}

function applyModuleSettings() {
  const s = appSettings;
  // Sidebar buttons
  const toggle = (id, key) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.style.display = s[key] === false ? 'none' : '';
  };
  toggle('btnPauschalenView', 'modul_pauschalen');
  toggle('btnSchnellnotizenSidebar', 'modul_schnellnotizen');
  toggle('btnAuswertung', 'modul_auswertung');
  toggle('btnRechnungen', 'modul_rechnungen');
  // Header dropdown items
  const toggleImportant = (id, key) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (s[key] === false) el.style.setProperty('display', 'none', 'important');
    else el.style.removeProperty('display');
  };
  toggleImportant('btnWochenplanung', 'modul_wochenplanung');
  toggleImportant('btnStundenerfassung', 'modul_stundenerfassung');
  toggleImportant('btnStundenabgleich', 'modul_stundenabgleich');
  toggleImportant('btnStundenauswertung', 'modul_stundenauswertung');
  toggleImportant('btnZeituebersicht', 'modul_zeiterfassung');
  toggleImportant('btnTermine', 'modul_termine');

  // ── Optionale Module dynamisch laden ─────────────────────
  if (s.modul_din1090 !== false && (typeof canDo !== 'function' || canDo('canReadDin1090'))) {
    loadOptionalModule('modules/din1090/din1090.js?v=57', 'modules/din1090/din1090.css?v=57', '🏗️ DIN EN 1090', 'btnDin1090', 'showDin1090', 'din1090View');
  }
  if (s.modul_aufmass === true && (typeof canDo !== 'function' || canDo('canReadAufmass'))) {
    loadOptionalModule('modules/aufmass/aufmass.js?v=54', 'modules/aufmass/aufmass.css?v=54', '📏 Aufmaß', 'btnAufmass', 'showAufmass', 'aufmassView');
  }
  if (s.modul_lager === true && (typeof canDo !== 'function' || canDo('canReadLager'))) {
    loadOptionalModule('modules/lager/lager.js?v=57', 'modules/lager/lager.css?v=57', '📦 Lager', 'btnLager', 'showLager', 'lagerView');
  }

  // Dashboard-Button (v2.4)
  const btnDb = document.getElementById('btnDashboard');
  if (btnDb) {
    const show = s.modul_dashboard === true && (typeof canDo !== 'function' || canDo('canReadDashboard'));
    btnDb.style.display = show ? '' : 'none';
  }

  // VDE 0100 Prüfprotokolle (v2.7.0) — Button ist statisch in index.html, hier nur show/hide + Modul laden
  const _showVde = s.modul_vde0100 === true && (typeof canDo !== 'function' || canDo('canReadVde0100'));
  const _btnVde = document.getElementById('btnVde0100');
  if (_btnVde) _btnVde.style.display = _showVde ? '' : 'none';
  if (_showVde) {
    loadOptionalModule('modules/vde0100/vde0100.js?v=94', 'modules/vde0100/vde0100.css?v=94', '⚡ VDE 0100', 'btnVde0100', 'showVde0100', 'vde0100View');
  }
}

function loadOptionalModule(jsPath, cssPath, label, btnId, onClickFn, viewId) {
  // Prüft ob die JS-Datei existiert und lädt sie + CSS + Sidebar-Button dynamisch
  // Guard basiert auf Script-Tag (nicht Button-ID), damit pre-definierte Buttons im HTML funktionieren
  const scriptBase = jsPath.split('?')[0];
  if (document.querySelector('script[src*="' + scriptBase + '"]')) return; // JS bereits geladen
  fetch(jsPath, { method: 'HEAD' }).then(r => {
    if (!r.ok) return; // Modul nicht vorhanden → ignorieren
    // CSS laden
    if (cssPath && !document.querySelector('link[href*="' + cssPath.split('?')[0] + '"]')) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = cssPath;
      document.head.appendChild(link);
    }
    // JS laden
    const script = document.createElement('script');
    script.src = jsPath;
    document.body.appendChild(script);
    // Sidebar-Button nur einfügen wenn noch nicht im DOM (z.B. statisch in HTML definiert)
    if (btnId && !document.getElementById(btnId)) {
      const navSection = document.querySelector('.sidebar-nav-section');
      if (navSection) {
        const btn = document.createElement('button');
        btn.className = 'sidebar-overview-btn';
        btn.id = btnId;
        btn.textContent = label;
        btn.addEventListener('click', () => { if (typeof window[onClickFn] === 'function') window[onClickFn](); });
        navSection.appendChild(btn);
      }
    } else if (btnId && onClickFn) {
      // Button bereits im DOM: Click-Handler aktualisieren
      const existing = document.getElementById(btnId);
      if (existing) existing.onclick = () => { if (typeof window[onClickFn] === 'function') window[onClickFn](); };
    }
    // View-Container einfügen (nur wenn nicht bereits vorhanden)
    if (viewId && !document.getElementById(viewId)) {
      const view = document.createElement('div');
      view.id = viewId;
      view.className = 'hidden';
      document.querySelector('main')?.appendChild(view);
    }
  }).catch(() => {}); // Netzwerkfehler → Modul nicht vorhanden
}

async function maybeAskBrancheOnboarding() {
  if (currentRole !== 'admin') return;
  if (appSettings.branche_initialized) return;
  const choice = prompt('Branche auswählen: "metallbau" oder "elektrotechnik"', appSettings.branche || '');
  if (!choice) return;
  const branche = choice.trim().toLowerCase();
  if (!['metallbau', 'elektrotechnik'].includes(branche)) {
    showNotification('Ungültige Branche. Gültig: metallbau oder elektrotechnik.');
    return;
  }
  const updates = { branche, branche_initialized: true };
  if (branche === 'metallbau') {
    updates.modul_metall_erfassung = true;
    updates.modul_din1090 = true;
    updates.modul_datanorm = false;
    updates.modul_kupfer_del = false;
  } else {
    updates.modul_metall_erfassung = false;
    updates.modul_din1090 = false;
    updates.modul_datanorm = true;
    updates.modul_kupfer_del = true;
  }
  try {
    const r = await fetch('api.php?action=save_settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updates)
    });
    const j = await r.json();
    if (j.ok) {
      Object.assign(appSettings, updates);
      applyModuleSettings();
      applyPermissions();
      showNotification('Branche gespeichert. Module wurden vorkonfiguriert.');
    }
  } catch (e) {
    console.warn('Branche konnte nicht gespeichert werden', e);
  }
}

async function runAutoImport() {
  const resEl = document.getElementById('autoImportResult');
  if (resEl) resEl.textContent = 'Importiere—';
  try {
    const r = await fetch('api.php?action=auto_import_stunden', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const j = await r.json();
    if (j.ok) {
      if (resEl) resEl.textContent = `? ${j.imported} Einträge importiert`;
      if (j.imported > 0) loadData();
    } else {
      if (resEl) { resEl.style.color = '#e53935'; resEl.textContent = j.error || 'Fehler'; }
    }
  } catch(e) {
    if (resEl) { resEl.style.color = '#e53935'; resEl.textContent = 'Netzwerkfehler'; }
  }
}

