let termineData = [];

async function loadTermineData() {
  try {
    const r = await fetch('api.php?action=load_termine');
    const j = await r.json();
    if (j.ok) termineData = j.termine || [];
  } catch(e) { console.warn('Termine laden fehlgeschlagen:', e); }
}

function openTermineModal() {
  let overlay = document.getElementById('termineOverlay');
  if (overlay) overlay.remove();
  overlay = document.createElement('div');
  overlay.id = 'termineOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9000;display:flex;align-items:center;justify-content:center;overflow:auto;padding:20px;';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };

  const modal = document.createElement('div');
  modal.style.cssText = 'background:var(--surface,#fff);color:var(--text,#1a1a2e);border-radius:12px;max-width:960px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 12px 40px rgba(0,0,0,.3);';
  modal.innerHTML = `
    <div style="padding:16px 24px;border-bottom:1px solid var(--grey-200,#e0e0e0);display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#00B4D8,#0096B7);color:#fff;border-radius:12px 12px 0 0;">
      <h2 style="margin:0;font-size:1.15rem;">${ico('calendar')} Terminplanung</h2>
      <div style="display:flex;gap:8px;align-items:center;">
        ${canDo('canManageTermine') ? '<button class="btn btn-sm" style="background:rgba(255,255,255,.2);color:#fff;border:1px solid rgba(255,255,255,.3);border-radius:6px;padding:5px 12px;font-size:.8rem;cursor:pointer" onclick="openTerminFormModal()">+ Neuer Termin</button>' : ''}
        <button onclick="openWpCalendarShare()" title="Kalender abonnieren" style="background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;border-radius:6px;padding:5px 10px;font-size:.85rem;cursor:pointer;">📅</button>
        <button onclick="document.getElementById('termineOverlay').remove()" style="background:none;border:none;color:#fff;font-size:1.5rem;cursor:pointer;line-height:1;">&times;</button>
      </div>
    </div>
    <div style="padding:20px 24px;" id="termineContent"></div>
  `;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  loadTermineData().then(() => renderTermineList());
}

let _terminFilter = { text: '', baustelle: '', person: '', zeitraum: 'upcoming' };

function renderTermineFilterBar() {
  const persons = new Set();
  (termineData||[]).forEach(t => {
    if (t.ersteller) persons.add(t.ersteller);
    (t.zugewiesen||[]).forEach(u => persons.add(u));
  });
  const pOpts = [...persons].sort().map(p => `<option value="${esc(p)}"${_terminFilter.person===p?' selected':''}>${esc(p)}</option>`).join('');

  _bsDd['terminFilter'] = { allowEmpty: true, emptyLabel: 'Alle Baustellen', onchange(id) { _terminFilter.baustelle = id; renderTermineList(); } };
  const bSelName = _terminFilter.baustelle ? ((appData.baustellen||[]).find(b=>b.id==_terminFilter.baustelle)?.name || '') : '';

  return `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;align-items:center">
    <input type="text" class="form-control" placeholder="\uD83D\uDD0D Suche\u2026" value="${esc(_terminFilter.text)}" oninput="_terminFilter.text=this.value;renderTermineList()" style="flex:1;min-width:140px;max-width:240px;font-size:.82rem;padding:6px 10px">
    ${bsDdHtml('terminFilter', { selected: _terminFilter.baustelle, placeholder: 'Alle Baustellen', allowEmpty: true, emptyLabel: 'Alle Baustellen', onchange(id){ _terminFilter.baustelle=id; renderTermineList(); }, style:'flex:0 0 auto;min-width:180px;max-width:240px', inputStyle:'font-size:.82rem;padding:6px 10px' })}
    <select class="form-control" onchange="_terminFilter.person=this.value;renderTermineList()" style="font-size:.82rem;padding:6px 8px;max-width:160px">
      <option value="">Alle Personen</option>${pOpts}
    </select>
    <select class="form-control" onchange="_terminFilter.zeitraum=this.value;renderTermineList()" style="font-size:.82rem;padding:6px 8px;max-width:160px">
      <option value="upcoming"${_terminFilter.zeitraum==='upcoming'?' selected':''}>Kommende</option>
      <option value="past"${_terminFilter.zeitraum==='past'?' selected':''}>Vergangene</option>
      <option value="all"${_terminFilter.zeitraum==='all'?' selected':''}>Alle</option>
      <option value="today"${_terminFilter.zeitraum==='today'?' selected':''}>Heute</option>
      <option value="week"${_terminFilter.zeitraum==='week'?' selected':''}>Diese Woche</option>
      <option value="month"${_terminFilter.zeitraum==='month'?' selected':''}>Dieser Monat</option>
    </select>
    ${(_terminFilter.text || _terminFilter.baustelle || _terminFilter.person || _terminFilter.zeitraum !== 'upcoming') ? '<button class="btn btn-sm btn-secondary" style="font-size:.78rem;padding:4px 10px" onclick="resetTerminFilter()">\u2715 Reset</button>' : ''}
  </div>`;
}

function resetTerminFilter() {
  _terminFilter = { text: '', baustelle: '', person: '', zeitraum: 'upcoming' };
  renderTermineList();
}

function applyTerminFilters(termine) {
  const today = new Date().toISOString().split('T')[0];
  let filtered = [...termine];

  if (_terminFilter.zeitraum === 'upcoming') {
    filtered = filtered.filter(t => t.datum >= today);
  } else if (_terminFilter.zeitraum === 'past') {
    filtered = filtered.filter(t => t.datum < today);
  } else if (_terminFilter.zeitraum === 'today') {
    filtered = filtered.filter(t => t.datum === today);
  } else if (_terminFilter.zeitraum === 'week') {
    const dt = new Date(); const mon = new Date(dt); mon.setDate(dt.getDate() - ((dt.getDay()+6)%7));
    const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
    const monKey = mon.toISOString().split('T')[0]; const sunKey = sun.toISOString().split('T')[0];
    filtered = filtered.filter(t => t.datum >= monKey && t.datum <= sunKey);
  } else if (_terminFilter.zeitraum === 'month') {
    const ym = today.substring(0, 7);
    filtered = filtered.filter(t => t.datum.startsWith(ym));
  }

  if (_terminFilter.baustelle) {
    filtered = filtered.filter(t => t.baustelleId == _terminFilter.baustelle);
  }
  if (_terminFilter.person) {
    filtered = filtered.filter(t => t.ersteller === _terminFilter.person || (t.zugewiesen||[]).includes(_terminFilter.person));
  }
  if (_terminFilter.text) {
    const q = _terminFilter.text.toLowerCase();
    filtered = filtered.filter(t =>
      (t.titel||'').toLowerCase().includes(q) ||
      (t.beschreibung||'').toLowerCase().includes(q) ||
      (t.ort||'').toLowerCase().includes(q) ||
      (t.ersteller||'').toLowerCase().includes(q) ||
      (t.zugewiesen||[]).some(u => u.toLowerCase().includes(q))
    );
  }

  return filtered;
}

function renderTermineList() {
  const el = document.getElementById('termineContent');
  if (!el) return;

  let html = renderTermineFilterBar();

  if (termineData.length === 0) {
    html += '<div style="text-align:center;padding:40px;color:var(--grey-400,#888)"><p style="font-size:1.1rem;margin-bottom:8px">Keine Termine vorhanden</p><p style="font-size:.85rem">Erstellen Sie einen neuen Termin \u00fcber den Button oben.</p></div>';
    el.innerHTML = html;
    return;
  }

  const today = new Date().toISOString().split('T')[0];
  const filtered = applyTerminFilters(termineData);

  if (filtered.length === 0) {
    html += '<div style="text-align:center;padding:30px;color:var(--grey-400,#888)"><p style="font-size:.9rem">Keine Termine f\u00fcr diesen Filter gefunden.</p></div>';
    el.innerHTML = html;
    return;
  }

  if (_terminFilter.zeitraum === 'all') {
    const upcoming = filtered.filter(t => t.datum >= today).sort((a,b) => a.datum.localeCompare(b.datum) || (a.zeitVon||'').localeCompare(b.zeitVon||''));
    const past = filtered.filter(t => t.datum < today).sort((a,b) => b.datum.localeCompare(a.datum));
    if (upcoming.length) {
      html += '<h3 style="font-size:.85rem;color:var(--primary,#00B4D8);margin-bottom:10px;font-weight:700">Kommende Termine</h3>';
      html += renderTerminCards(upcoming);
    }
    if (past.length) {
      html += '<h3 style="font-size:.85rem;color:var(--grey-400,#888);margin:20px 0 10px;font-weight:700">Vergangene Termine</h3>';
      html += renderTerminCards(past);
    }
  } else if (_terminFilter.zeitraum === 'past') {
    const sorted = filtered.sort((a,b) => b.datum.localeCompare(a.datum));
    html += `<div style="font-size:.78rem;color:var(--grey-400,#888);margin-bottom:8px;font-weight:600">${filtered.length} Termin${filtered.length!==1?'e':''}</div>`;
    html += renderTerminCards(sorted);
  } else {
    const sorted = filtered.sort((a,b) => a.datum.localeCompare(b.datum) || (a.zeitVon||'').localeCompare(b.zeitVon||''));
    html += `<div style="font-size:.78rem;color:var(--grey-400,#888);margin-bottom:8px;font-weight:600">${filtered.length} Termin${filtered.length!==1?'e':''}</div>`;
    html += renderTerminCards(sorted);
  }

  el.innerHTML = html;
}

function renderTerminCards(termine) {
  return termine.map(t => {
    const bName = t.baustelleId ? ((appData.baustellen||[]).find(b=>b.id===t.baustelleId)?.name || '') : '';
    const zeit = t.ganztags ? 'Ganztags' : ((t.zeitVon||'') + (t.zeitBis ? ' \u2013 '+t.zeitBis : ''));
    const today = new Date().toISOString().split('T')[0];
    const isPast = t.datum < today;
    return `<div style="display:flex;gap:12px;padding:12px 16px;border:1px solid var(--grey-200,#e0e0e0);border-radius:10px;margin-bottom:8px;border-left:4px solid ${esc(t.farbe||'#00B4D8')};opacity:${isPast?'.6':'1'};background:var(--surface,#fff)">
      <div style="flex:1;min-width:0">
        <div style="font-weight:700;font-size:.92rem">${esc(t.titel)}</div>
        <div style="font-size:.8rem;color:var(--grey-400,#888);margin-top:2px">
          ${ico('calendar')} ${formatDate(t.datum)} ${zeit ? '&nbsp;\u00b7&nbsp; '+ico('clock')+' '+esc(zeit) : ''}
          ${t.ort ? '&nbsp;\u00b7&nbsp; \uD83D\uDCCD <a href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(t.ort)+'" target="_blank" rel="noopener" style="color:var(--blue,#00B4D8);text-decoration:underline;cursor:pointer" onclick="event.stopPropagation()">'+esc(t.ort)+'</a>' : ''}
          ${bName ? '&nbsp;\u00b7&nbsp; \uD83C\uDFD7 '+esc(bName) : ''}
        </div>
        ${t.beschreibung ? '<div style="font-size:.82rem;margin-top:4px;color:var(--text,#333)">'+esc(t.beschreibung)+'</div>' : ''}
        ${t.zugewiesen && t.zugewiesen.length ? '<div style="margin-top:4px;display:flex;gap:4px;flex-wrap:wrap">'+t.zugewiesen.map(u=>'<span style="font-size:.7rem;background:var(--blue-light,#E0F7FA);color:var(--blue,#00B4D8);padding:1px 6px;border-radius:4px;font-weight:600">'+esc(u)+'</span>').join('')+'</div>' : ''}
        <div style="font-size:.68rem;color:var(--grey-400,#aaa);margin-top:4px">Erstellt von ${esc(t.ersteller||'?')}</div>
      </div>
      ${canDo('canManageTermine') ? '<div style="display:flex;gap:4px;flex-shrink:0;align-self:flex-start"><button class="btn btn-sm btn-secondary" onclick="openTerminFormModal('+t.id+')" style="font-size:.75rem;padding:4px 8px">\u270F\uFE0F</button><button class="btn btn-sm" onclick="deleteTermin('+t.id+')" style="font-size:.75rem;padding:4px 8px;background:#FF3B30;color:#fff;border:none;border-radius:6px;cursor:pointer">\uD83D\uDDD1</button></div>' : ''}
    </div>`;
  }).join('');
}

