// ============================================================
// WOCHENPLANUNG  -  Timeline-Kalender (Multi-Entry, MöSa)
// ============================================================
let wpPlan = {};      // { 'username': { '2026-03-02': [ {typ,baustelleId,bemerkung}, ... ] } }
let _wpLoaded = false; // true erst nach erfolgreichem Server-Load -> Overwrite-Schutz (nur online relevant)
let wpUsers = [];     // user list
let wpAllZeit = {};   // zeiterfassung data for Urlaub/Krank/Sonstig detection
let wpCanEdit = false;
let wpCanEditSelf = false;
let wpDirty = false;       // true when unsaved edits exist
let wpStartMonday = null;  // currently displayed start Monday
let wpWeeksToShow = 4;     // how many weeks visible at once
let wpViewMode = 'week';   // 'week' | 'day' | 'year'
let wpSelectedDay = null;  // currently selected day in day view (Date)
let wpYearSelectedYear = new Date().getFullYear(); // Jahr für die Jahresansicht
let wpYearSelectedUsers = null; // null = alle, sonst Set von Usernamen

const WP_MONTEUR_COLORS = [
  '#00B4D8','#E67C73','#57BB8A','#F4B400','#7B61FF',
  '#F06292','#26A69A','#FFA726','#3B7FC4','#AB47BC'
];

/* migrate old {baustelleId,bemerkung} ? [{typ,baustelleId,bemerkung}] */
function wpMigratePlan(plan) {
  for (const user in plan) {
    for (const date in plan[user]) {
      const e = plan[user][date];
      if (e && !Array.isArray(e)) {
        plan[user][date] = e.baustelleId
          ? [{ typ:'baustelle', baustelleId:e.baustelleId, bemerkung:e.bemerkung||'' }]
          : [];
      }
    }
  }
  return plan;
}

function getWeekMonday(date) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = (day === 0 ? -6 : 1) - day;
  d.setDate(d.getDate() + diff);
  d.setHours(0,0,0,0);
  return d;
}

function wpDateKey(d) {
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

function wpGetDays(startMonday, weeks) {
  const days = [];
  for (let w = 0; w < weeks; w++) {
    for (let d = 0; d < 6; d++) {          // MöSa
      const dt = new Date(startMonday);
      dt.setDate(dt.getDate() + w * 7 + d);
      days.push(dt);
    }
  }
  return days;
}

function getISOWeek(d) {
  const tmp = new Date(d.getTime());
  tmp.setDate(tmp.getDate() + 3 - ((tmp.getDay() + 6) % 7));
  const y1 = new Date(tmp.getFullYear(), 0, 4);
  return Math.round(((tmp - y1) / 86400000 + 1) / 7);
}

const wpDayNames = ['Mo','Di','Mi','Do','Fr','Sa'];

let wpPollTimer = null;   // polling interval for near-realtime sync
let wpGruppenData = [];   // [{id, name, farbe, mitglieder:[username]}]

async function wpLoadData() {
  _wpLoaded = false;
  const usersEndpoint = (currentRole === 'admin' || currentRole === 'master')
    ? 'list_users' : 'list_users_basic';
  const gruppenEndpoint = (currentRole === 'admin' || currentRole === 'master')
    ? 'load_gruppen' : 'load_gruppen_for_user';
  try {
    const [planRes, usersRes, zeitRes, gruppenRes] = await Promise.all([
      fetch('api.php?action=load_wochenplanung&_idle=1'),
      fetch('api.php?action=' + usersEndpoint + '&_idle=1'),
      fetch('api.php?action=load_all_zeiterfassung&_idle=1'),
      fetch('api.php?action=' + gruppenEndpoint + '&_idle=1')
    ]);
    const planJ    = await planRes.json();
    const usersJ   = await usersRes.json();
    const zeitJ    = await zeitRes.json();
    const gruppenJ = await gruppenRes.json();
    if (planJ.ok) {
      wpPlan = wpMigratePlan(planJ.plan || {});
      _wpLoaded = true;
      localStorage.setItem('bk_wpPlan_cache', JSON.stringify(wpPlan));
    }
    if (usersJ.ok) {
      wpUsers = usersJ.users || [];
      localStorage.setItem('bk_wpUsers_cache', JSON.stringify(wpUsers));
    }
    if (zeitJ.ok) {
      wpAllZeit = zeitJ.data || {};
      localStorage.setItem('bk_wpZeit_cache', JSON.stringify(wpAllZeit));
    }
    if (gruppenJ.ok) {
      wpGruppenData = gruppenJ.gruppen || [];
      localStorage.setItem('bk_wpGruppen_cache', JSON.stringify(wpGruppenData));
    }
  } catch(e) {
    console.warn('Wochenplanung laden fehlgeschlagen:', e);
    // Offline fallback: load from cache
    const cp = localStorage.getItem('bk_wpPlan_cache');
    const cu = localStorage.getItem('bk_wpUsers_cache');
    const cz = localStorage.getItem('bk_wpZeit_cache');
    const cg = localStorage.getItem('bk_wpGruppen_cache');
    if (cp) wpPlan = wpMigratePlan(JSON.parse(cp));
    if (cu) wpUsers = JSON.parse(cu);
    if (cz) wpAllZeit = JSON.parse(cz);
    if (cg) wpGruppenData = JSON.parse(cg);
  }
}

async function openWochenplanungModal() {
  wpCanEdit = (currentRole === 'admin' || currentRole === 'master');
  wpCanEditSelf = !!currentUser;
  wpStartMonday = getWeekMonday(new Date());  // start at current week
  show('wochenplanungModal');
  const saveBtn = document.getElementById('wpSaveBtn');
  if (saveBtn) saveBtn.style.display = (wpCanEdit || wpCanEditSelf) ? '' : 'none';
  const termineBtn = document.getElementById('wpTermineBtn');
  if (termineBtn) termineBtn.style.display = (canDo('canSeeOwnTermine') || canDo('canSeeAllTermine') || canDo('canManageTermine')) ? '' : 'none';

  await wpLoadData();
  renderWochenplanung();

  // Start near-realtime polling (every 15 seconds)
  if (wpPollTimer) clearInterval(wpPollTimer);
  wpPollTimer = setInterval(async () => {
    if (!document.getElementById('wochenplanungModal') ||
        document.getElementById('wochenplanungModal').classList.contains('hidden')) {
      clearInterval(wpPollTimer); wpPollTimer = null; return;
    }
    // Don't refresh while edit overlay is open or unsaved changes exist
    if (document.querySelector('.wp-edit-overlay') || wpDirty) return;
    const oldJson = JSON.stringify(wpPlan);
    await wpLoadData();
    if (JSON.stringify(wpPlan) !== oldJson) renderWochenplanung();
  }, 15000);
}

function closeWochenplanungModal() {
  if (wpPollTimer) { clearInterval(wpPollTimer); wpPollTimer = null; }
  hide('wochenplanungModal');
}

/** Builds { username -> [gruppenId, ...] } lookup from wpGruppenData */
function wpBuildGruppenMap() {
  const map = {};
  (wpGruppenData || []).forEach(g => {
    (g.mitglieder || []).forEach(uname => {
      if (!map[uname]) map[uname] = [];
      map[uname].push(String(g.id));
    });
  });
  return map;
}

/**
 * Returns true if a termin should be shown for the given user.
 * Supports 'alle', 'gruppe:X', and individual username assignments.
 */
function wpTerminGiltFuerUser(termin, uname, gruppenMap) {
  if (termin.ersteller === uname) return true;
  const z = termin.zugewiesen;
  if (!z || z.length === 0) return false;
  if (z.includes('alle')) return true;
  if (z.includes(uname)) return true;
  const userGruppen = gruppenMap[uname] || [];
  return userGruppen.some(gid => z.includes('gruppe:' + gid));
}

function renderWochenplanung() {
  const el = document.getElementById('wpContent');
  if (!el) return;

  if (wpViewMode === 'year') { renderWochenplanungJahr(); return; }
  if (wpViewMode === 'day') { renderWochenplanungTag(); return; }

  const today = new Date();
  if (!wpStartMonday) wpStartMonday = getWeekMonday(today);
  const thisMonday = new Date(wpStartMonday);
  const days = wpGetDays(thisMonday, wpWeeksToShow);

  const kwNums = [];
  for (let w = 0; w < wpWeeksToShow; w++) {
    const mon = new Date(thisMonday);
    mon.setDate(mon.getDate() + w * 7);
    kwNums.push(getISOWeek(mon));
  }

  // Build KW options for the full current year
  const currentYear = new Date().getFullYear();
  const jan4 = new Date(currentYear, 0, 4);
  const firstMonday = getWeekMonday(jan4);
  const allKws = [];
  for (let i = 0; i < 53; i++) {
    const mon = new Date(firstMonday);
    mon.setDate(mon.getDate() + i * 7);
    if (mon.getFullYear() > currentYear && getISOWeek(mon) > 1) break;
    allKws.push({ kw: getISOWeek(mon), monday: new Date(mon) });
  }

  const currentStartKw = getISOWeek(thisMonday);

  // Holidays (cover full displayed span)
  const year1 = thisMonday.getFullYear();
  const endDate = new Date(thisMonday); endDate.setDate(endDate.getDate() + wpWeeksToShow * 7);
  const holidays = getBavarianHolidays(year1);
  if (endDate.getFullYear() !== year1) holidays.push(...getBavarianHolidays(endDate.getFullYear()));
  const holidayKeys = new Set(holidays.map(h => dateToKey(h)));
  const holidayNameMap = buildHolidayNameMap(year1);
  if (endDate.getFullYear() !== year1) buildHolidayNameMap(endDate.getFullYear()).forEach((name, key) => holidayNameMap.set(key, name));

  // Filter: nur User mit showInWochenplanung anzeigen
  let wpVisibleUsers = wpUsers.filter(u => u.showInWochenplanung !== false);

  // Berechtigung: nur eigenen Plan sehen
  if (!canDo('canSeeAllWochenplan')) {
    wpVisibleUsers = wpVisibleUsers.filter(u => u.username === currentUser);
  }

  if (wpVisibleUsers.length === 0) {
    el.innerHTML = '<p class="hint-text" style="text-align:center;padding:20px">Keine Benutzer für die Wochenplanung konfiguriert.</p>';
    return;
  }

  const _wpGrpMap = wpBuildGruppenMap();
  const kwOptions = allKws.map(k => {
    const monStr = k.monday.toLocaleDateString('de-DE', {day:'2-digit',month:'2-digit'});
    const endStr = new Date(k.monday.getTime() + 5*86400000).toLocaleDateString('de-DE', {day:'2-digit',month:'2-digit'});
    return `<option value="${wpDateKey(k.monday)}" ${k.kw === currentStartKw && k.monday.getTime() === thisMonday.getTime() ? 'selected' : ''}>KW ${k.kw} (${monStr} - ${endStr})</option>`;
  }).join('');

  const todayMondayKey = wpDateKey(getWeekMonday(today));

  let html = `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap;">
    <button class="btn btn-secondary btn-sm" onclick="wpNavWeek(-${wpWeeksToShow})" title="${wpWeeksToShow} Wochen zurück" style="padding:4px 10px;font-size:1rem;">&#171;</button>
    <button class="btn btn-secondary btn-sm" onclick="wpNavWeek(-1)" title="1 Woche zurück" style="padding:4px 10px;font-size:1rem;">&#8249;</button>
    <select class="form-input" style="width:auto;font-size:.85rem;padding:4px 8px;" onchange="wpJumpToWeek(this.value)">${kwOptions}</select>
    <button class="btn btn-secondary btn-sm" onclick="wpNavWeek(1)" title="1 Woche vor" style="padding:4px 10px;font-size:1rem;">&#8250;</button>
    <button class="btn btn-secondary btn-sm" onclick="wpNavWeek(${wpWeeksToShow})" title="${wpWeeksToShow} Wochen vor" style="padding:4px 10px;font-size:1rem;">&#187;</button>
    <button class="btn btn-secondary btn-sm" onclick="wpJumpToWeek('${todayMondayKey}')" style="padding:4px 10px;font-size:.82rem;">Heute</button>
    <span style="font-size:.8rem;color:var(--grey-400);">${currentYear}</span>
    <span style="display:inline-flex;border-radius:6px;overflow:hidden;border:1px solid var(--grey-200);margin-left:auto;">
      <button class="btn btn-primary btn-sm" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;cursor:default;">📅 Woche</button>
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('day')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);">🕐 Tag</button>
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('year')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);">📆 Jahr</button>
    </span>
  </div>`;

  // Legend
  html += `<div class="wp-tl-legend">
    ${wpVisibleUsers.map((u, i) => `<span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:${WP_MONTEUR_COLORS[i % WP_MONTEUR_COLORS.length]}"></span>${esc(u.username)}</span>`).join('')}
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#FFF3E0;border:1px solid #E65100"></span>Feiertag</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#E0F7FA;border:1px solid #00838F"></span>Urlaub</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#FFEBEE;border:1px solid #C62828"></span>Krank</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#F3E5F5;border:1px solid #7B1FA2"></span>Sonstig</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="border:2px dashed var(--grey-400);background:transparent"></span>Aus Stundenerfassung</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#00B4D818;border:1px solid #00B4D8"></span>Termin</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#FFF3E0;border:1px solid #BF360C"></span>Betrieb (Freizeit)</span>
    <span class="wp-tl-legend-item"><span class="wp-tl-dot" style="background:#E8F5E9;border:1px solid #1B5E20"></span>Betrieb (Arbeitszeit)</span>
  </div>
  <div class="wp-tl-scroll">
  <table class="wp-timeline">
    <thead>
      <tr>
        <th class="wp-tl-name-hd" rowspan="2">Monteur</th>
        ${kwNums.map((kw, wi) => (wi > 0 ? '<th class="wp-tl-sep" rowspan="2"></th>' : '') + `<th class="wp-tl-week-hd" colspan="6">KW ${kw}</th>`).join('')}
      </tr>
      <tr>`;

  days.forEach((dt, i) => {
    // Kein manueller Separator hier: die rowspan="2"-Seps aus der KW-Header-Zeile
    // belegen diese Spalten in Zeile 2 bereits automatisch (HTML-rowspan-Mechanismus).
    // Ein zusätzlicher <th> würde die Tagesspalten ab KW2+ um je 1 nach rechts verschieben.
    const todayKey = wpDateKey(today);
    const dKey = wpDateKey(dt);
    const isToday = dKey === todayKey;
    const isHolHd = holidayKeys.has(dKey);
    const holHdName = holidayNameMap.get(dKey) || '';
    html += `<th class="wp-tl-day-hd${isToday ? ' wp-tl-today' : ''}${isHolHd ? ' wp-tl-day-feiertag' : ''}"${isHolHd && holHdName ? ` title="${esc(holHdName)}"` : ''}>${wpDayNames[i % 6]}<br><span class="wp-tl-day-date">${dt.toLocaleDateString('de-DE', {day:'2-digit', month:'2-digit'})}</span></th>`;
  });

  html += `</tr></thead><tbody>`;

  wpVisibleUsers.forEach((user, userIdx) => {
    const uname = user.username;
    const color = WP_MONTEUR_COLORS[userIdx % WP_MONTEUR_COLORS.length];
    const seEntries = wpAllZeit[uname]?.entries || [];
    const urlaubDates = new Set(seEntries.filter(e => e.typ === 'urlaub').map(e => e.datum));
    const krankDates  = new Set(seEntries.filter(e => e.typ === 'krank').map(e => e.datum));
    const sonstigMap  = {};
    seEntries.filter(e => e.typ === 'sonstig').forEach(e => { sonstigMap[e.datum] = e.bemerkung || 'Sonstig'; });
    const arbeitMap   = {};
    seEntries.filter(e => e.typ === 'arbeit' && e.baustelleId).forEach(e => { arbeitMap[e.datum] = e; });
    const urlaubMap   = {};
    seEntries.filter(e => e.typ === 'urlaub').forEach(e => { urlaubMap[e.datum] = e; });
    const krankMap    = {};
    seEntries.filter(e => e.typ === 'krank').forEach(e => { krankMap[e.datum] = e; });

    html += `<tr>
      <td class="wp-tl-name-cell"><span class="wp-tl-dot" style="background:${color}"></span> ${esc(uname)}</td>`;

    days.forEach((dt, idx) => {
      const key = wpDateKey(dt);
      const isHoliday = holidayKeys.has(key);
      const planArr = (wpPlan[uname] || {})[key] || [];
      const isSeUrlaub  = urlaubDates.has(key);
      const isSeKrank   = krankDates.has(key);
      const isSeSonstig = key in sonstigMap;

      if (idx > 0 && idx % 6 === 0) html += '<td class="wp-tl-sep-cell"></td>';

      const todayKey = wpDateKey(today);
      const isToday = key === todayKey;

      // Build blocks array
      let blocks = [];
      if (isHoliday) {
        const holCellName = holidayNameMap.get(key) || 'Feiertag';
        blocks.push(`<div class="wp-block wp-block-feiertag" title="${esc(holCellName)}">🎉 ${esc(holCellName)}</div>`);
      } else {
        // Planned entries from wpPlan
        const hasPlannedUrlaub  = planArr.some(e => e.typ === 'urlaub');
        const hasPlannedSonstig = planArr.some(e => e.typ === 'sonstig');
        const plannedBauIds     = new Set(planArr.filter(e => e.typ === 'baustelle').map(e => String(e.baustelleId)));

        planArr.forEach(e => {
          if (e.typ === 'baustelle') {
            const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || '?';
            const _bTitle = 'Baustelle: ' + bName + (e.bemerkung ? '\nBemerkung: ' + e.bemerkung : '');
            blocks.push(`<div class="wp-block wp-block-bau" style="background:${color}18;border-left:3px solid ${color};color:${color}" title="${esc(_bTitle)}">${esc(bName)}${e.bemerkung ? `<span class="wp-block-bem">${esc(e.bemerkung)}</span>` : ''}</div>`);
          } else if (e.typ === 'urlaub') {
            blocks.push(`<div class="wp-block wp-block-urlaub" title="Urlaub">${ico('palm')} Urlaub</div>`);
          } else if (e.typ === 'sonstig') {
            const _sPlTitle = 'Sonstiges' + (e.bemerkung ? ': ' + e.bemerkung : '');
            blocks.push(`<div class="wp-block wp-block-sonstig" title="${esc(_sPlTitle)}">${ico('alert')} ${esc(e.bemerkung || 'Sonstiges')}</div>`);
          } else if (e.typ === 'betrieb') {
            const bIcon  = e.betriebTyp === 'freizeit' ? '🏖' : '💼';
            const bCls   = e.betriebTyp === 'freizeit' ? 'wp-block-betrieb-frei' : 'wp-block-betrieb-arbeit';
            const bBadge = e.betriebTyp === 'freizeit' ? ' (Freizeit)' : ' (Arbeitszeit)';
            const bTitle = 'Betriebseintrag' + bBadge + (e.bemerkung ? ': ' + e.bemerkung : '');
            blocks.push(`<div class="wp-block ${bCls}" title="${esc(bTitle)}">${bIcon} ${esc(e.bemerkung || 'Betrieb')}</div>`);
          }
        });

        // Synced SE entries (not already in plan)
        if (isSeUrlaub && !hasPlannedUrlaub) {
          const _uEnt = urlaubMap[key];
          const _uTitle = 'Urlaub (aus Stundenerfassung)' + (_uEnt?.bemerkung ? '\nBemerkung: ' + _uEnt.bemerkung : '');
          blocks.push(`<div class="wp-block wp-block-urlaub wp-block-synced" title="${esc(_uTitle)}">${ico('palm')} Urlaub</div>`);
        }
        if (isSeKrank) {
          const _kEnt = krankMap[key];
          const _kTitle = 'Krank (aus Stundenerfassung)' + (_kEnt?.bemerkung ? '\nBemerkung: ' + _kEnt.bemerkung : '');
          blocks.push(`<div class="wp-block wp-block-krank wp-block-synced" title="${esc(_kTitle)}">${ico('thermometer')} Krank</div>`);
        }
        if (isSeSonstig && !hasPlannedSonstig) {
          const _sTitle = 'Sonstiges (aus Stundenerfassung)' + (sonstigMap[key] ? ': ' + sonstigMap[key] : '');
          blocks.push(`<div class="wp-block wp-block-sonstig wp-block-synced" title="${esc(_sTitle)}">${ico('alert')} ${esc(sonstigMap[key])}</div>`);
        }
        if (arbeitMap[key] && !plannedBauIds.has(String(arbeitMap[key].baustelleId))) {
          const ae = arbeitMap[key];
          const bName = appData.baustellen.find(b => b.id == ae.baustelleId)?.name || ae.baustelleName || '?';
          const _aeParts = ['Baustelle: ' + bName];
          if (ae.stunden) _aeParts.push('Stunden: ' + ae.stunden + ' h');
          if (ae.von || ae.vonZeit) _aeParts.push('Von: ' + (ae.von || ae.vonZeit));
          if (ae.bis || ae.bisZeit) _aeParts.push('Bis: ' + (ae.bis || ae.bisZeit));
          if (ae.bemerkung) _aeParts.push('Bemerkung: ' + ae.bemerkung);
          _aeParts.push('(aus Stundenerfassung)');
          blocks.push(`<div class="wp-block wp-block-synced" style="background:${color}0D;border-left:3px dashed ${color};color:${color}" title="${esc(_aeParts.join('\n'))}">${ico('clock')} ${esc(bName)}<span class="wp-block-bem">${ae.stunden ? ae.stunden+'h' : ''}</span></div>`);
        }

        // Termine for this user + date
        (termineData || []).forEach(termin => {
          if (termin.datum !== key) return;
          if (!wpTerminGiltFuerUser(termin, uname, _wpGrpMap)) return;
          const zeit = termin.ganztags ? '' : (termin.zeitVon ? ' ' + termin.zeitVon : '');
          const _tZeit = termin.ganztags ? 'Ganztags' : ((termin.zeitVon || '') + (termin.zeitBis ? ' – ' + termin.zeitBis : ''));
          const _tBau  = termin.baustelleId ? ((appData.baustellen||[]).find(b => b.id === termin.baustelleId)?.name || '') : '';
          const _tParts = [termin.titel];
          if (_tZeit) _tParts.push('Zeit: ' + _tZeit);
          if (termin.ort) _tParts.push('Ort: ' + termin.ort);
          if (_tBau) _tParts.push('Baustelle: ' + _tBau);
          if (termin.beschreibung) _tParts.push('Beschreibung: ' + termin.beschreibung);
          if (termin.zugewiesen && termin.zugewiesen.length) _tParts.push('Zugewiesen: ' + termin.zugewiesen.join(', '));
          _tParts.push('Erstellt von: ' + (termin.ersteller || '?'));
          blocks.push(`<div class="wp-block wp-block-termin" style="background:${esc(termin.farbe||'#00B4D8')}18;border-left:3px solid ${esc(termin.farbe||'#00B4D8')};color:${esc(termin.farbe||'#00B4D8')};font-size:.7rem;cursor:pointer" title="${esc(_tParts.join('\n'))}" onclick="event.stopPropagation();wpShowTerminDetail(${termin.id})">${ico('calendar')} ${esc(termin.titel)}${zeit ? '<span class="wp-block-bem">'+esc(zeit)+'</span>' : ''}</div>`);
        });
      }

      if (blocks.length === 0) blocks.push(`<div class="wp-block wp-block-empty">—</div>`);

      // Determine edit permission for this cell
      const isSelf = (uname === currentUser);
      const canEditCell = !isHoliday && (wpCanEdit || (wpCanEditSelf && isSelf));
      const editAttr = canEditCell
        ? ` onclick="wpCellClick(event,this)" data-user="${esc(uname)}" data-date="${key}" data-color="${color}" data-self="${isSelf && !wpCanEdit ? '1' : '0'}"`
        : '';
      html += `<td class="wp-tl-cell${isToday ? ' wp-tl-today' : ''}"${editAttr}>${blocks.join('')}</td>`;
    });

    html += '</tr>';
  });

  html += '</tbody></table></div>';
  el.innerHTML = html;
}

/* -- Popover edit for timeline cells (multi-entry) -- */
let wpPopState = null;

function wpCellClick(ev, td) {
  ev.stopPropagation();
  if (ev.target.closest('.wp-popover')) return;
  wpPopRemove();

  const uname   = td.dataset.user;
  const dateKey  = td.dataset.date;
  const color    = td.dataset.color;
  const selfOnly = td.dataset.self === '1';    // normal user on own row

  wpPopState = { uname, dateKey, color, td, selfOnly };

  if (!wpPlan[uname]) wpPlan[uname] = {};
  if (!wpPlan[uname][dateKey]) wpPlan[uname][dateKey] = [];

  // Create overlay + modal
  const overlay = document.createElement('div');
  overlay.className = 'wp-edit-overlay';
  overlay.addEventListener('mousedown', e => {
    if (e.target === overlay) wpPopRemove();
  });
  const modal = document.createElement('div');
  modal.className = 'wp-edit-modal';
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  wpPopRenderInner(modal);
}

function wpPopRenderInner(modal) {
  if (!modal) modal = document.querySelector('.wp-edit-modal');
  if (!modal || !wpPopState) return;
  const { uname, dateKey, selfOnly } = wpPopState;
  const entries = wpPlan[uname][dateKey] || [];

  // Entry list
  let listHtml = '';
  entries.forEach((e, i) => {
    let label = '';
    if (e.typ === 'baustelle') {
      const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || '?';
      label = `${ico('tool')} ${esc(bName)}${e.bemerkung ? ' <small>('+esc(e.bemerkung)+')</small>' : ''}`;
    } else if (e.typ === 'urlaub') {
      label = `${ico('palm')} Urlaub`;
    } else if (e.typ === 'sonstig') {
      label = `${ico('alert')} ${esc(e.bemerkung || 'Sonstiges')}`;
    } else if (e.typ === 'betrieb') {
      const bIcon  = e.betriebTyp === 'freizeit' ? '🏖' : '💼';
      const bBadge = e.betriebTyp === 'freizeit'
        ? '<span style="font-size:.7rem;background:#FFF3E0;color:#BF360C;padding:1px 5px;border-radius:3px;margin-left:4px">Freizeit</span>'
        : '<span style="font-size:.7rem;background:#E8F5E9;color:#1B5E20;padding:1px 5px;border-radius:3px;margin-left:4px">Arbeitszeit</span>';
      label = `${bIcon} ${esc(e.bemerkung || 'Betriebseintrag')}${bBadge}`;
    }
    const canDel = selfOnly ? (e.typ !== 'baustelle') : true;
    const delFn  = (e.typ === 'betrieb') ? `wpPopDelBetrieb(${i})` : `wpPopDel(${i})`;
    const delLbl = (e.typ === 'betrieb') ? '✕ alle' : '—';
    listHtml += `<div class="wp-pop-entry">${label}${canDel ? `<button class="wp-pop-entry-del" onclick="${delFn}" title="${e.typ === 'betrieb' ? 'Für alle Mitarbeiter entfernen' : 'Entfernen'}">${delLbl}</button>` : ''}</div>`;
  });

  if (entries.length === 0) listHtml = '<div class="wp-pop-empty">Keine Einträge</div>';

  // Termine für diesen Tag/User anzeigen (nur Info, nicht löschbar hier)
  const userTermine = (termineData || []).filter(t => t.datum === dateKey && (t.ersteller === uname || (t.zugewiesen && t.zugewiesen.includes(uname))));
  userTermine.forEach(t => {
    const zeit = t.ganztags ? 'Ganztags' : (t.zeitVon || '');
    listHtml += `<div class="wp-pop-entry" style="border-left:3px solid ${esc(t.farbe||'#00B4D8')};padding-left:8px;cursor:pointer;opacity:.85" onclick="wpPopRemove();wpShowTerminDetail(${t.id})">${ico('calendar')} <span style="color:${esc(t.farbe||'#00B4D8')}">${esc(t.titel)}</span>${zeit ? ' <small>('+esc(zeit)+')</small>' : ''}</div>`;
  });

  // Type options (admin/master = all, normal = urlaub+sonstig)
  const typOpts = selfOnly
    ? `<option value="urlaub">Urlaub</option><option value="sonstig">Sonstiges</option>`
    : `<option value="baustelle">Baustelle</option><option value="urlaub">Urlaub</option><option value="sonstig">Sonstiges</option><option value="betrieb">🏢 Betriebseintrag (alle MA)</option>`;

  const defaultTyp = selfOnly ? 'urlaub' : 'baustelle';
  const baustellenOpts = appData.baustellen.map(b => `<option value="${b.id}">${esc(b.name)}</option>`).join('');

  modal.innerHTML = `
    <div class="wp-edit-modal-title">${esc(uname)} - ${dateKey.split('-').reverse().join('.')}</div>
    <div class="wp-pop-list">${listHtml}</div>
    <hr style="border:none;border-top:1px solid var(--grey-100);margin:8px 0">
    <label class="wp-edit-modal-label">Typ</label>
    <select class="form-control form-control-sm" id="wpPopTyp" onchange="wpPopTypChanged()">
      ${typOpts}
    </select>
    <div id="wpPopBauDiv" style="${defaultTyp !== 'baustelle' ? 'display:none' : ''}">
      <label class="wp-edit-modal-label" style="margin-top:6px">Baustelle</label>
      ${bsDdHtml('wpPopBaustelle', { selected: '', placeholder: 'Baustelle suchen...', allowEmpty: false, inputStyle: 'font-size:.8rem;padding:4px 8px;height:auto' })}
    </div>
    <div id="wpPopBemDiv" style="${defaultTyp === 'urlaub' ? 'display:none' : ''}">
      <label class="wp-edit-modal-label" style="margin-top:6px">${defaultTyp === 'sonstig' ? 'Grund' : 'Bemerkung'}</label>
      <input type="text" class="form-control form-control-sm" id="wpPopBem" value="" placeholder="${defaultTyp === 'sonstig' ? 'z.B. Berufsschule' : 'optional'}">
    </div>
    <div id="wpPopBetriebDiv" style="display:none">
      <label class="wp-edit-modal-label" style="margin-top:6px">Bezeichnung</label>
      <input type="text" class="form-control form-control-sm" id="wpPopBetriebLabel" placeholder="z.B. Betriebsurlaub, Messebesuch">
      <label class="wp-edit-modal-label" style="margin-top:6px">Art</label>
      <div style="display:flex;gap:14px;margin-top:4px;font-size:.85rem">
        <label style="display:flex;align-items:center;gap:4px;cursor:pointer">
          <input type="radio" name="wpBetriebTyp" value="freizeit" checked> 🏖 Freizeit
        </label>
        <label style="display:flex;align-items:center;gap:4px;cursor:pointer">
          <input type="radio" name="wpBetriebTyp" value="arbeitszeit"> 💼 Arbeitszeit
        </label>
      </div>
      <p style="font-size:.73rem;color:#E65100;margin:5px 0 0;font-weight:600">⚠ Wird für alle sichtbaren Mitarbeiter eingetragen.</p>
    </div>
    <div style="display:flex;gap:6px;margin-top:10px">
      <button class="btn btn-primary btn-sm" style="flex:1" onclick="wpPopAdd()">+ Hinzuf—gen</button>
      <button class="btn btn-secondary btn-sm" style="flex:1" onclick="wpPopClose()">Schließen</button>
    </div>`;
}

function wpPopTypChanged() {
  const typ = document.getElementById('wpPopTyp')?.value || 'baustelle';
  const bauDiv    = document.getElementById('wpPopBauDiv');
  const bemDiv    = document.getElementById('wpPopBemDiv');
  const betriebDiv = document.getElementById('wpPopBetriebDiv');
  const bemLabel  = bemDiv?.querySelector('.wp-popover-label');
  const bemInput  = document.getElementById('wpPopBem');
  if (bauDiv)     bauDiv.style.display     = (typ === 'baustelle') ? '' : 'none';
  if (betriebDiv) betriebDiv.style.display = (typ === 'betrieb')   ? '' : 'none';
  if (bemDiv)     bemDiv.style.display     = (typ === 'urlaub' || typ === 'betrieb') ? 'none' : '';
  if (bemLabel) bemLabel.textContent = (typ === 'sonstig') ? 'Grund' : 'Bemerkung';
  if (bemInput) bemInput.placeholder = (typ === 'sonstig') ? 'z.B. Berufsschule' : 'optional';
}

function wpPopFilterBaustellen() {
  const input = document.getElementById('wpPopBauSearch');
  const dd = document.getElementById('wpPopBauDropdown');
  const hidden = document.getElementById('wpPopSel');
  if (!input || !dd) return;
  const q = input.value.toLowerCase().trim();
  const baustellen = (appData.baustellen || []).filter(b =>
    !q || b.name.toLowerCase().includes(q)
  );
  if (baustellen.length === 0) { dd.style.display = 'none'; return; }
  dd.innerHTML = '';
  baustellen.forEach(b => {
    const opt = document.createElement('div');
    opt.textContent = b.name;
    opt.style.cssText = 'padding:6px 10px;font-size:0.82rem;cursor:pointer;border-bottom:1px solid var(--grey-100,#eee)';
    opt.addEventListener('click', function() {
      input.value = b.name;
      if (hidden) hidden.value = b.id;
      dd.style.display = 'none';
    });
    dd.appendChild(opt);
  });
  dd.style.display = '';
}

// Click-away handler for Baustelle dropdown
document.addEventListener('click', function(e) {
  const dd = document.getElementById('wpPopBauDropdown');
  const input = document.getElementById('wpPopBauSearch');
  if (dd && input && !dd.contains(e.target) && e.target !== input) {
    dd.style.display = 'none';
  }
});

function wpPopAdd() {
  if (!wpPopState) return;
  const { uname, dateKey } = wpPopState;
  const typ = document.getElementById('wpPopTyp')?.value || 'baustelle';
  const bem = document.getElementById('wpPopBem');

  const entry = { typ };
  if (typ === 'baustelle') {
    const bId = parseInt(bsDdGetValue('wpPopBaustelle')) || '';
    if (!bId) { alert('Bitte Baustelle wählen.'); return; }
    entry.baustelleId = bId;
    entry.bemerkung = bem ? bem.value.trim() : '';
  } else if (typ === 'sonstig') {
    entry.bemerkung = bem ? bem.value.trim() : '';
    if (!entry.bemerkung) { alert('Bitte Grund eingeben.'); return; }
  } else if (typ === 'betrieb') {
    const labelVal = document.getElementById('wpPopBetriebLabel')?.value.trim() || '';
    if (!labelVal) { alert('Bitte Bezeichnung eingeben.'); return; }
    const betriebTyp = document.querySelector('input[name="wpBetriebTyp"]:checked')?.value || 'freizeit';
    entry.bemerkung  = labelVal;
    entry.betriebTyp = betriebTyp;
    // Für ALLE sichtbaren Mitarbeiter eintragen
    const targets = wpUsers.filter(u => u.showInWochenplanung !== false);
    targets.forEach(u => {
      if (!wpPlan[u.username]) wpPlan[u.username] = {};
      if (!wpPlan[u.username][dateKey]) wpPlan[u.username][dateKey] = [];
      wpPlan[u.username][dateKey].push({ ...entry });
    });
    wpDirty = true;
    wpPopRemove();          // schließt Popup + speichert automatisch (wpDirty=true)
    renderWochenplanung();  // alle Mitarbeiter-Zellen neu zeichnen
    return;
  }

  // überschneidungsprüfung: bestehende Einträge + Termine für diesen Tag/User
  const existing = (wpPlan[uname]?.[dateKey]) || [];
  const userTermine = (termineData || []).filter(t => t.datum === dateKey && (t.ersteller === uname || (t.zugewiesen && t.zugewiesen.includes(uname))));
  const conflicts = [];
  existing.forEach(e => {
    if (e.typ === 'baustelle') {
      const bn = (appData.baustellen||[]).find(b => b.id == e.baustelleId)?.name || 'Baustelle';
      conflicts.push(bn);
    } else if (e.typ === 'urlaub') { conflicts.push('Urlaub'); }
    else if (e.typ === 'sonstig') { conflicts.push(e.bemerkung || 'Sonstiges'); }
    else if (e.typ === 'betrieb') { conflicts.push((e.betriebTyp === 'freizeit' ? '🏖' : '💼') + ' ' + (e.bemerkung || 'Betriebseintrag')); }
  });
  userTermine.forEach(t => {
    const zeit = t.ganztags ? 'Ganztags' : (t.zeitVon || '');
    conflicts.push('Termin: ' + t.titel + (zeit ? ' (' + zeit + ')' : ''));
  });

  if (conflicts.length > 0) {
    const msg = `Für ${uname} am ${dateKey.split('-').reverse().join('.')} existieren bereits:\n\n` +
      conflicts.map(c => '  - ' + c).join('\n') +
      '\n\nTrotzdem hinzufügen?';
    if (!confirm(msg)) return;
  }

  if (!wpPlan[uname]) wpPlan[uname] = {};
  if (!wpPlan[uname][dateKey]) wpPlan[uname][dateKey] = [];
  wpPlan[uname][dateKey].push(entry);
  wpDirty = true;
  wpPopRefresh();
}

function wpPopDel(idx) {
  if (!wpPopState) return;
  const { uname, dateKey } = wpPopState;
  const arr = wpPlan[uname]?.[dateKey];
  if (arr && idx >= 0 && idx < arr.length) {
    arr.splice(idx, 1);
    wpDirty = true;
  }
  wpPopRefresh();
}

function wpPopDelBetrieb(idx) {
  if (!wpPopState) return;
  const { uname, dateKey } = wpPopState;
  const arr = wpPlan[uname]?.[dateKey];
  if (!arr || idx < 0 || idx >= arr.length) return;
  const entry = arr[idx];
  if (entry.typ !== 'betrieb') return;
  // Gleichen Betriebseintrag bei allen Mitarbeitern für diesen Tag entfernen
  const targets = wpUsers.filter(u => u.showInWochenplanung !== false);
  targets.forEach(u => {
    const userArr = wpPlan[u.username]?.[dateKey];
    if (!userArr) return;
    const removeIdx = userArr.findIndex(e =>
      e.typ === 'betrieb' && e.bemerkung === entry.bemerkung && e.betriebTyp === entry.betriebTyp
    );
    if (removeIdx >= 0) userArr.splice(removeIdx, 1);
  });
  wpDirty = true;
  wpPopRemove();          // schließt Popup + speichert automatisch (wpDirty=true)
  renderWochenplanung();  // alle Mitarbeiter-Zellen neu zeichnen
}

function wpPopRefresh() {
  // Re-render modal content + cell
  const modal = document.querySelector('.wp-edit-modal');
  wpPopRenderInner(modal);
  if (wpPopState) wpCellRedraw(wpPopState.td, wpPopState.uname, wpPopState.dateKey, wpPopState.color);
}

function wpCellRedraw(td, uname, dateKey, color) {
  const arr = (wpPlan[uname] || {})[dateKey] || [];

  let blocks = [];
  arr.forEach(e => {
    if (e.typ === 'baustelle') {
      const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || '?';
      blocks.push(`<div class="wp-block wp-block-bau" style="background:${color}18;border-left:3px solid ${color};color:${color}">${esc(bName)}${e.bemerkung ? `<span class="wp-block-bem">${esc(e.bemerkung)}</span>` : ''}</div>`);
    } else if (e.typ === 'urlaub') {
      blocks.push(`<div class="wp-block wp-block-urlaub">${ico('palm')} Urlaub</div>`);
    } else if (e.typ === 'sonstig') {
      blocks.push(`<div class="wp-block wp-block-sonstig">${ico('alert')} ${esc(e.bemerkung || 'Sonstiges')}</div>`);
    } else if (e.typ === 'betrieb') {
      const bIcon = e.betriebTyp === 'freizeit' ? '🏖' : '💼';
      const bCls  = e.betriebTyp === 'freizeit' ? 'wp-block-betrieb-frei' : 'wp-block-betrieb-arbeit';
      blocks.push(`<div class="wp-block ${bCls}">${bIcon} ${esc(e.bemerkung || 'Betrieb')}</div>`);
    }
  });
  if (blocks.length === 0) blocks.push(`<div class="wp-block wp-block-empty">—</div>`);

  td.innerHTML = blocks.join('');
}

function _wpOutsideHandler(e) {
  // no longer used - overlay handles close
}

function wpPopRemove() {
  const overlay = document.querySelector('.wp-edit-overlay');
  if (overlay) overlay.remove();
  wpPopState = null;
  if (wpDirty) { saveWochenplanung(); wpDirty = false; }
}

function wpPopClose() {
  wpPopRemove();
}

/* -- Termine-Overlay in Wochenplanung -- */
async function openWpTermineOverlay() {
  await loadTermineData();
  const grpMap = wpBuildGruppenMap();

  let ov = document.getElementById('wpTermineOverlay');
  if (ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'wpTermineOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:9400;display:flex;align-items:center;justify-content:center;padding:20px;';
  ov.onclick = e => {
    if (e.target === ov) {
      ov.remove();
      loadTermineData().then(() => renderWochenplanung());
    }
  };

  const box = document.createElement('div');
  box.style.cssText = 'background:var(--surface,#fff);color:var(--text,#1a1a2e);border-radius:14px;max-width:620px;width:100%;max-height:85vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 16px 48px rgba(0,0,0,.3);';

  // Header
  const header = document.createElement('div');
  header.style.cssText = 'padding:14px 20px;background:linear-gradient(135deg,#00B4D8,#0096B7);color:#fff;border-radius:14px 14px 0 0;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;';
  header.innerHTML = `<span style="font-weight:700;font-size:1rem">📋 Termine</span>
    <div style="display:flex;gap:8px;align-items:center;">
      ${canDo('canManageTermine') ? '<button class="btn btn-sm" onclick="openTerminFormModal(null)" style="background:rgba(255,255,255,.2);border:1px solid rgba(255,255,255,.4);color:#fff;font-size:.8rem;padding:4px 12px;border-radius:6px;cursor:pointer">+ Neuer Termin</button>' : ''}
      <button onclick="(function(){document.getElementById(\'wpTermineOverlay\').remove();loadTermineData().then(()=>renderWochenplanung());})()" style="background:none;border:none;color:#fff;font-size:1.5rem;cursor:pointer;line-height:1;">&times;</button>
    </div>`;
  box.appendChild(header);

  // Body
  const body = document.createElement('div');
  body.id = 'wpTermineOverlayBody';
  body.style.cssText = 'overflow-y:auto;flex:1;padding:12px 16px;';
  box.appendChild(body);
  ov.appendChild(box);
  document.body.appendChild(ov);

  wpRenderTermineOverlayBody(grpMap);
}

function wpRenderTermineOverlayBody(grpMap) {
  const body = document.getElementById('wpTermineOverlayBody');
  if (!body) return;
  if (!grpMap) grpMap = wpBuildGruppenMap();

  // Filter by permissions
  let visible = (termineData || []).slice().sort((a, b) => a.datum.localeCompare(b.datum));
  if (!canDo('canSeeAllTermine')) {
    // Only show termine the current user is involved in
    visible = visible.filter(t => wpTerminGiltFuerUser(t, currentUser, grpMap));
  }

  if (visible.length === 0) {
    body.innerHTML = '<p style="text-align:center;color:var(--grey-400,#aaa);padding:20px;font-size:.88rem;">Keine Termine vorhanden.</p>';
    return;
  }

  let html = '';
  let lastDate = '';
  visible.forEach(t => {
    if (t.datum !== lastDate) {
      if (lastDate) html += '</div>';
      html += `<div style="font-size:.72rem;font-weight:700;color:var(--grey-500,#888);text-transform:uppercase;letter-spacing:.5px;padding:10px 0 4px;border-top:1px solid var(--grey-100,#f0f0f0);margin-top:4px;">${formatDate(t.datum)}</div><div>`;
      lastDate = t.datum;
    }
    const zeit = t.ganztags ? 'Ganztags' : ((t.zeitVon || '') + (t.zeitBis ? ' – ' + t.zeitBis : ''));
    const zuLabel = t.zugewiesen && t.zugewiesen.length
      ? t.zugewiesen.map(z => {
          if (z === 'alle') return '<span style="background:#e8f5e9;color:#2e7d32;padding:1px 7px;border-radius:10px;font-size:.72rem;font-weight:600">Alle</span>';
          if (z.startsWith('gruppe:')) {
            const gid = z.replace('gruppe:', '');
            const g = (wpGruppenData || []).find(x => String(x.id) === gid);
            return `<span style="background:${esc((g?.farbe||'#6366f1')+'22')};color:${esc(g?.farbe||'#6366f1')};padding:1px 7px;border-radius:10px;font-size:.72rem;font-weight:600">${esc(g?.name || 'Gruppe')}</span>`;
          }
          return `<span style="background:var(--grey-50,#f5f5f5);padding:1px 7px;border-radius:10px;font-size:.72rem">${esc(z)}</span>`;
        }).join(' ')
      : '';
    html += `<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:8px;margin-bottom:4px;background:var(--grey-50,#fafafa);cursor:pointer;border-left:3px solid ${esc(t.farbe||'#00B4D8')}" onclick="wpShowTerminDetail(${t.id})">
      <div style="flex:1;min-width:0">
        <div style="font-weight:600;font-size:.85rem;color:${esc(t.farbe||'#00B4D8')}">${esc(t.titel)}</div>
        <div style="font-size:.75rem;color:var(--grey-500,#888);margin-top:1px">${zeit ? zeit + ' · ' : ''}${esc(t.ersteller||'')}${zuLabel ? ' · ' + zuLabel : ''}</div>
      </div>
      ${canDo('canManageTermine') ? `<button class="btn btn-sm btn-secondary" style="font-size:.72rem;padding:2px 8px;flex-shrink:0" onclick="event.stopPropagation();openTerminFormModal(${t.id})">✏</button>` : ''}
    </div>`;
  });
  if (lastDate) html += '</div>';
  body.innerHTML = html;
}

function wpShowTerminDetail(terminId) {
  const t = (termineData || []).find(x => x.id === terminId);
  if (!t) return;
  const bName = t.baustelleId ? ((appData.baustellen||[]).find(b=>b.id===t.baustelleId)?.name || '') : '';
  const zeit = t.ganztags ? 'Ganztags' : ((t.zeitVon||'') + (t.zeitBis ? ' - '+t.zeitBis : ''));
  const mapsLink = t.ort ? `<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(t.ort)}" target="_blank" rel="noopener" style="color:var(--blue,#00B4D8);text-decoration:underline">${esc(t.ort)}</a>` : '';

  let ov = document.getElementById('wpTerminDetailOverlay');
  if (ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'wpTerminDetailOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  ov.onclick = e => { if (e.target === ov) ov.remove(); };

  const card = document.createElement('div');
  card.style.cssText = 'background:var(--surface,#fff);color:var(--text,#1a1a2e);border-radius:12px;max-width:480px;width:100%;box-shadow:0 12px 40px rgba(0,0,0,.3);overflow:hidden';
  card.innerHTML = `
    <div style="padding:14px 20px;background:${esc(t.farbe||'#00B4D8')};color:#fff;display:flex;align-items:center;justify-content:space-between;border-radius:12px 12px 0 0">
      <div style="font-weight:700;font-size:1.05rem">${ico('calendar')} ${esc(t.titel)}</div>
      <button onclick="document.getElementById('wpTerminDetailOverlay').remove()" style="background:none;border:none;color:#fff;font-size:1.4rem;cursor:pointer;line-height:1">&times;</button>
    </div>
    <div style="padding:16px 20px">
      <table style="width:100%;font-size:.85rem;border-collapse:collapse">
        <tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Datum</td><td style="padding:5px 0">${formatDate(t.datum)}</td></tr>
        ${zeit ? '<tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Zeit</td><td style="padding:5px 0">'+esc(zeit)+'</td></tr>' : ''}
        ${t.ort ? '<tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Ort</td><td style="padding:5px 0"> '+mapsLink+'</td></tr>' : ''}
        ${bName ? '<tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Baustelle</td><td style="padding:5px 0"> '+esc(bName)+'</td></tr>' : ''}
        ${t.beschreibung ? '<tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Beschreibung</td><td style="padding:5px 0">'+esc(t.beschreibung)+'</td></tr>' : ''}
        ${t.zugewiesen && t.zugewiesen.length ? '<tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Zugewiesen</td><td style="padding:5px 0">'+t.zugewiesen.map(u=>'<span style="display:inline-block;font-size:.75rem;background:var(--blue-light,#E0F7FA);color:var(--blue,#00B4D8);padding:1px 8px;border-radius:4px;font-weight:600;margin:1px 3px 1px 0">'+esc(u)+'</span>').join('')+'</td></tr>' : ''}
        <tr><td style="padding:5px 12px 5px 0;color:var(--grey-400,#888);white-space:nowrap;vertical-align:top;font-weight:600">Erstellt von</td><td style="padding:5px 0">${esc(t.ersteller||'?')}${t.erstelltAm ? ' <span style="color:var(--grey-400,#aaa);font-size:.78rem">am '+esc(t.erstelltAm)+'</span>' : ''}</td></tr>
      </table>
      ${canDo('canManageTermine') ? '<div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end"><button class="btn btn-sm btn-secondary" style="font-size:.8rem" onclick="document.getElementById(\'wpTerminDetailOverlay\').remove();openTerminFormModal('+t.id+')"> Bearbeiten</button><button class="btn btn-sm" style="font-size:.8rem;background:#FF3B30;color:#fff;border:none;border-radius:6px;padding:5px 12px;cursor:pointer" onclick="document.getElementById(\'wpTerminDetailOverlay\').remove();deleteTermin('+t.id+')"> Löschen</button></div>' : ''}
    </div>`;
  ov.appendChild(card);
  document.body.appendChild(ov);
}

async function saveWochenplanung(force = false) {
  // Online, aber Plan nicht frisch geladen -> nicht mit veraltetem Stand überschreiben.
  if (navigator.onLine && !_wpLoaded && !force) {
    showNotification('Wochenplanung wurde nicht vollständig geladen – zum Schutz der Daten wurde nicht gespeichert. Bitte neu laden.');
    return;
  }
  const payload = wpCanEdit
    ? { plan: wpPlan, forceReplace: force }
    : { plan: { [currentUser]: wpPlan[currentUser] || {} }, forceReplace: force };

  try {
    const r = await fetch('api.php?action=save_wochenplanung', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const j = await r.json();
    if (r.status === 409 && j.needsConfirm) {
      if (confirm((j.error || 'Es würden viele Wochenplan-Einträge gelöscht.') + '\n\nWirklich fortfahren?')) {
        return saveWochenplanung(true);
      }
      return;
    }
    if (j.ok) {
      localStorage.setItem('bk_wpPlan_cache', JSON.stringify(wpPlan));
      showNotification('Wochenplanung gespeichert.');
    } else {
      alert(j.error || 'Fehler beim Speichern.');
    }
  } catch(e) {
    // Offline: queue for later sync
    localStorage.setItem('bk_wpPlan_offline', JSON.stringify(payload));
    localStorage.setItem('bk_wpPlan_cache', JSON.stringify(wpPlan));
    markSyncPending();
    showNotification('Offline - Wochenplanung wird bei Verbindung synchronisiert.');
  }
}

/* -- Week navigation for desktop Wochenplanung -- */
function wpNavWeek(delta) {
  if (!wpStartMonday) wpStartMonday = getWeekMonday(new Date());
  wpStartMonday.setDate(wpStartMonday.getDate() + delta * 7);
  renderWochenplanung();
}

function wpJumpToWeek(mondayKey) {
  const parts = mondayKey.split('-');
  wpStartMonday = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
  renderWochenplanung();
}

/* -- Day view helpers -- */

/** Converts "HH:MM" to a percentage position on [dayStart, dayEnd] axis */
function wpTimeToPercent(timeStr, dayStart, dayEnd) {
  if (!timeStr) return null;
  const p = timeStr.split(':');
  const h = parseInt(p[0]) || 0;
  const m = parseInt(p[1]) || 0;
  const total = (dayEnd - dayStart) * 60;
  return Math.max(0, Math.min(100, ((h * 60 + m - dayStart * 60) / total) * 100));
}

function wpSetViewMode(mode) {
  wpViewMode = mode;
  if (mode === 'day' && !wpSelectedDay) {
    if (!wpStartMonday) wpStartMonday = getWeekMonday(new Date());
    const today = new Date();
    const todayKey = wpDateKey(today);
    const monKey   = wpDateKey(wpStartMonday);
    const satKey   = wpDateKey(new Date(wpStartMonday.getTime() + 5 * 86400000));
    if (todayKey >= monKey && todayKey <= satKey) {
      wpSelectedDay = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    } else {
      wpSelectedDay = new Date(wpStartMonday);
    }
  }
  renderWochenplanung();
}

// ============================================================
// WOCHENPLANUNG – JAHRESANSICHT
// ============================================================
function renderWochenplanungJahr() {
  const el = document.getElementById('wpContent');
  if (!el) return;
  const year = wpYearSelectedYear;
  const allUsers = wpUsers.filter(u => u.showInWochenplanung !== false && u.role !== 'admin');
  if (!wpYearSelectedUsers) wpYearSelectedUsers = new Set(allUsers.map(u => u.username));
  const visUsers = allUsers.filter(u => wpYearSelectedUsers.has(u.username));

  // Feiertage für das Jahr
  const holidays = getBavarianHolidays(year);
  const holidaySet = new Set(holidays.map(h => dateToKey(h)));

  // Zeiterfassungs-Daten + Wochenplanungs-Daten
  const showWp = document.getElementById('wpYearShowWp')?.checked ?? true;

  // Mapping: datum -> [{user, typ}]
  const dayMap = {}; // 'yyyy-mm-dd' -> [{username, typ, source:'ze'|'wp'}]
  visUsers.forEach(u => {
    const entries = wpAllZeit[u.username]?.entries || [];
    entries.forEach(e => {
      if (!e.datum || !e.datum.startsWith(String(year))) return;
      if (e.typ === 'arbeit') return; // Nur Abwesenheiten
      if (!dayMap[e.datum]) dayMap[e.datum] = [];
      dayMap[e.datum].push({ username: u.username, typ: e.typ, source: 'ze' });
    });
    if (showWp) {
      const wpEntries = wpPlan[u.username] || {};
      Object.keys(wpEntries).forEach(datum => {
        if (!datum.startsWith(String(year))) return;
        (wpEntries[datum] || []).forEach(we => {
          if (!we.typ || we.typ === 'arbeit') return;
          if (!dayMap[datum]) dayMap[datum] = [];
          dayMap[datum].push({ username: u.username, typ: we.typ || 'sonstig', source: 'wp' });
        });
      });
    }
  });

  const monthNames = ['Jan','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
  const typColors = { urlaub:'#2196F3', krank:'#E53935', gleitzeit:'#00BCD4', sonstig:'#FF9800', feiertag:'#9E9E9E', schulung:'#9C27B0' };
  const typLabel = { urlaub:'Urlaub', krank:'Krank', gleitzeit:'Gleitzeit', sonstig:'Fehlgrund', feiertag:'Feiertag', schulung:'Schulung' };

  // Header mit Navigation + Filter
  let html = `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap;">
    <button class="btn btn-secondary btn-sm" onclick="wpYearNav(-1)" style="padding:4px 10px;font-size:1rem;">◀</button>
    <strong style="font-size:1.1rem;">${year}</strong>
    <button class="btn btn-secondary btn-sm" onclick="wpYearNav(1)" style="padding:4px 10px;font-size:1rem;">▶</button>
    <button class="btn btn-secondary btn-sm" onclick="wpYearSelectedYear=${new Date().getFullYear()};renderWochenplanung()" style="padding:4px 10px;font-size:.82rem;">Heute</button>
    <label style="font-size:.8rem;display:flex;align-items:center;gap:4px;margin-left:12px;cursor:pointer"><input type="checkbox" id="wpYearShowWp" ${showWp?'checked':''} onchange="renderWochenplanung()"> Wochenplanung</label>
    <span style="display:inline-flex;border-radius:6px;overflow:hidden;border:1px solid var(--grey-200);margin-left:auto;">
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('week')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;">📅 Woche</button>
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('day')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);">🕐 Tag</button>
      <button class="btn btn-primary btn-sm" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);cursor:default;">📆 Jahr</button>
    </span>
  </div>`;

  // Personen-Filter
  html += `<div style="display:flex;align-items:center;gap:6px;margin-bottom:10px;flex-wrap:wrap;padding:6px 10px;background:var(--bg-light,#f5f7fa);border-radius:6px;">
    <span style="font-size:.8rem;font-weight:600;">Personen:</span>
    <button class="btn btn-secondary btn-sm" onclick="wpYearToggleAll(true)" style="padding:2px 8px;font-size:.72rem;">Alle</button>
    <button class="btn btn-secondary btn-sm" onclick="wpYearToggleAll(false)" style="padding:2px 8px;font-size:.72rem;">Keine</button>
    ${allUsers.map(u => `<label style="font-size:.78rem;display:flex;align-items:center;gap:3px;cursor:pointer"><input type="checkbox" ${wpYearSelectedUsers.has(u.username)?'checked':''} onchange="wpYearToggleUser('${esc(u.username)}',this.checked)"> ${esc(u.username)}</label>`).join('')}
  </div>`;

  // Legende
  html += `<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px;font-size:.75rem;">
    ${Object.keys(typColors).map(t => `<span style="display:flex;align-items:center;gap:3px"><span style="display:inline-block;width:12px;height:12px;border-radius:2px;background:${typColors[t]}"></span>${typLabel[t]||t}</span>`).join('')}
    <span style="display:flex;align-items:center;gap:3px"><span style="display:inline-block;width:12px;height:12px;border-radius:2px;background:#f0f0f0;border:1px solid #ccc"></span>Wochenende</span>
  </div>`;

  // ── Einzel-Ansicht: genau EIN Mitarbeiter gewählt → Detailkalender mit
  //    IST-Stunden/Differenz je Tag und Urlaubszählung je Monat.
  if (visUsers.length === 1) {
    const u = visUsers[0];
    const atSet = getUserArbeitstage(u);
    const sollBeschreibung = bkSollBeschreibung(u);
    const allUserEntries = wpAllZeit[u.username]?.entries || [];
    const uEntries = allUserEntries.filter(e => e.datum && e.datum.startsWith(String(year)));
    uEntries.push(...getVirtuelleFeiertagEintraege(allUserEntries, u, year));
    const istByDate = {}, absByDate = {};
    uEntries.forEach(e => {
      istByDate[e.datum] = (istByDate[e.datum] || 0) + bkIstStundenEintrag(u, e, appSettings?.ze_custom_typen || []);
      if (e.typ && e.typ !== 'arbeit') absByDate[e.datum] = e.typ;
    });
    const urlaubPlanDates = new Set();
    const uWp = wpPlan[u.username] || {};
    Object.keys(uWp).forEach(datum => {
      if (!datum.startsWith(String(year))) return;
      if ((uWp[datum] || []).some(we => (we.typ || '') === 'urlaub')) urlaubPlanDates.add(datum);
    });
    const urlaubTakenDates = new Set(uEntries.filter(e => e.typ === 'urlaub').map(e => e.datum));
    const todayKey2 = dateToKey(new Date());

    let totalPlan = 0, totalTaken = 0, totalSoll = 0, totalIst = 0;
    let body = `<div style="font-size:.8rem;color:#666;margin-bottom:8px">Einzelansicht <strong>${esc(u.username)}</strong> · Soll ${esc(sollBeschreibung)} · je Tag IST-Stunden mit Differenz (+/-) zu Soll.</div>`;
    body += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px;">';
    for (let mo = 0; mo < 12; mo++) {
      const dim = new Date(year, mo + 1, 0).getDate();
      const firstDow = (new Date(year, mo, 1).getDay() + 6) % 7;
      let moPlan = 0, moTaken = 0, moSoll = 0, moIst = 0, cells = '';
      for (let e = 0; e < firstDow; e++) cells += '<span></span>';
      for (let d = 1; d <= dim; d++) {
        const dt = new Date(year, mo, d);
        const key = dateToKey(dt);
        const weekday = dt.getDay() === 0 ? 7 : dt.getDay();
        const isWorkday = atSet.has(weekday) && !holidaySet.has(key);
        const ist = istByDate[key] || 0;
        const abs = absByDate[key];
        const dailySoll = bkTagesSoll(u, dt);
        if (dailySoll > 0) moSoll += dailySoll;
        moIst += ist;
        if (urlaubPlanDates.has(key)) moPlan++;
        if (urlaubTakenDates.has(key)) moTaken++;
        let bg = isWorkday ? '#fff' : '#f5f5f5', bd = '1px solid #eee';
        if (holidaySet.has(key)) { bg = '#FFF8E1'; bd = '1px solid #FFD54F'; }
        if (abs) { bg = (typColors[abs] || '#ddd') + '33'; bd = '1px solid ' + (typColors[abs] || '#ccc'); }
        let istHtml = '';
        const istPastWorkday = isWorkday && key <= todayKey2;
        if (ist > 0 || istPastWorkday) {
          const diff = ist - dailySoll;
          const dc = diff >= 0 ? '#2E7D32' : '#C62828';
          const ds = (diff >= 0 ? '+' : '') + diff.toFixed(1).replace(/\.0$/, '');
          istHtml = `<div style="font-size:.7rem;font-weight:600">${ist > 0 ? ist.toFixed(1).replace(/\.0$/, '') + 'h' : '0h'}</div><div style="font-size:.62rem;color:${dc}">${istPastWorkday ? ds : ''}</div>`;
        }
        const todayOl = key === todayKey2 ? ';outline:2px solid #00B4D8' : '';
        cells += `<div style="background:${bg};border:${bd};border-radius:4px;min-height:44px;padding:2px 1px;text-align:center;cursor:pointer${todayOl}" title="${key}${abs ? (' · ' + (typLabel[abs] || abs)) : ''}" onclick="wpYearDayClick('${key}')"><div style="font-size:.66rem;color:#888">${d}</div>${istHtml}</div>`;
      }
      totalPlan += moPlan; totalTaken += moTaken; totalSoll += moSoll; totalIst += moIst;
      body += `<div style="border:1px solid var(--border,#e0e0e0);border-radius:8px;padding:8px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">
          <strong style="font-size:.9rem">${monthNames[mo]} ${year}</strong>
          <span style="font-size:.72rem;color:#1565C0" title="Urlaub genommen">🏖 ${moTaken}</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:.68rem;color:#666;margin-bottom:6px">
          <span title="Soll / Ist (Monat)">Soll ${moSoll.toFixed(1).replace(/\.0$/,'')}h · Ist ${moIst.toFixed(1).replace(/\.0$/,'')}h</span>
          <span style="font-weight:600;color:${(moIst-moSoll)>=0?'#2E7D32':'#C62828'}">${(moIst-moSoll)>=0?'+':''}${(moIst-moSoll).toFixed(1).replace(/\.0$/,'')}h</span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;font-size:.66rem">
          <span style="text-align:center;font-weight:600;color:#888">M</span><span style="text-align:center;font-weight:600;color:#888">D</span><span style="text-align:center;font-weight:600;color:#888">M</span><span style="text-align:center;font-weight:600;color:#888">D</span><span style="text-align:center;font-weight:600;color:#888">F</span><span style="text-align:center;font-weight:600;color:#aaa">S</span><span style="text-align:center;font-weight:600;color:#aaa">S</span>
          ${cells}
        </div>
      </div>`;
    }
    body += '</div>';
    const urlaubAnspruch = bkUrlaubsanspruch(u, year);
    const urlaubRest = urlaubAnspruch - totalTaken;
    const jahrDiff = totalIst - totalSoll;
    body += `<div style="margin-top:12px;padding:10px 14px;background:var(--bg-light,#f5f7fa);border-radius:8px;font-size:.9rem;display:flex;gap:20px;flex-wrap:wrap;align-items:center">
      <span>🏖 <strong>Urlaubsanspruch ${year}:</strong> ${urlaubAnspruch} Tage</span>
      <span>✅ <strong>genommen:</strong> ${totalTaken}</span>
      <span> <strong>Resturlaub:</strong> ${urlaubRest} Tage</span>
      <span style="margin-left:auto">Σ Soll ${totalSoll.toFixed(1).replace(/\.0$/,'')}h · Ist ${totalIst.toFixed(1).replace(/\.0$/,'')}h · <span style="font-weight:700;color:${jahrDiff>=0?'#2E7D32':'#C62828'}">${jahrDiff>=0?'+':''}${jahrDiff.toFixed(1).replace(/\.0$/,'')}h</span></span>
    </div>`;
    el.innerHTML = html + body;
    return;
  }

  // 12 Mini-Monats-Blöcke
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px;">';
  for (let mo = 0; mo < 12; mo++) {
    const dim = new Date(year, mo + 1, 0).getDate();
    const firstDow = (new Date(year, mo, 1).getDay() + 6) % 7; // 0=Mo
    html += `<div style="border:1px solid var(--border,#e0e0e0);border-radius:6px;padding:6px;font-size:.7rem;">
      <div style="text-align:center;font-weight:700;font-size:.8rem;margin-bottom:4px;">${monthNames[mo]}</div>
      <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:1px;">
        <span style="text-align:center;font-weight:600;color:#888">M</span><span style="text-align:center;font-weight:600;color:#888">D</span><span style="text-align:center;font-weight:600;color:#888">M</span><span style="text-align:center;font-weight:600;color:#888">D</span><span style="text-align:center;font-weight:600;color:#888">F</span><span style="text-align:center;font-weight:600;color:#aaa">S</span><span style="text-align:center;font-weight:600;color:#aaa">S</span>`;
    // Leading empty cells
    for (let e = 0; e < firstDow; e++) html += '<span></span>';
    for (let d = 1; d <= dim; d++) {
      const dt = new Date(year, mo, d);
      const key = dateToKey(dt);
      const dow = (dt.getDay() + 6) % 7; // 0=Mo
      const isWe = dow >= 5;
      const isHol = holidaySet.has(key);
      const dayEntries = dayMap[key] || [];
      let bg = isWe ? '#f0f0f0' : '#fff';
      let border = '1px solid transparent';
      let title = `${d}.${mo+1}.${year}`;
      if (isHol) { bg = '#FFF8E1'; border = '1px solid #FFD54F'; title += ' (Feiertag)'; }
      if (dayEntries.length) {
        // Dominanter Typ (erster Eintrag bestimmt Farbe)
        const mainTyp = dayEntries[0].typ;
        bg = (typColors[mainTyp] || '#ddd') + '44';
        border = '1px solid ' + (typColors[mainTyp] || '#ccc');
        const names = [...new Set(dayEntries.map(e => e.username))].join(', ');
        const types = [...new Set(dayEntries.map(e => typLabel[e.typ]||e.typ))].join(', ');
        title += `\n${names}: ${types}`;
      }
      const todayMark = (key === dateToKey(new Date())) ? ';font-weight:900;color:#00B4D8' : '';
      html += `<span style="text-align:center;background:${bg};border:${border};border-radius:3px;padding:1px 0;cursor:pointer;min-height:18px;line-height:18px${todayMark}" title="${esc(title)}" onclick="wpYearDayClick('${key}')">${d}</span>`;
    }
    html += '</div></div>';
  }
  html += '</div>';

  el.innerHTML = html;
}

function wpYearNav(delta) {
  wpYearSelectedYear += delta;
  renderWochenplanung();
}
function wpYearToggleAll(on) {
  const allUsers = wpUsers.filter(u => u.showInWochenplanung !== false && u.role !== 'admin');
  wpYearSelectedUsers = on ? new Set(allUsers.map(u => u.username)) : new Set();
  renderWochenplanung();
}
function wpYearToggleUser(username, checked) {
  if (!wpYearSelectedUsers) wpYearSelectedUsers = new Set();
  if (checked) wpYearSelectedUsers.add(username); else wpYearSelectedUsers.delete(username);
  renderWochenplanung();
}

// Klick auf einen Tag in der Jahresansicht → Buchungs-Dialog
function wpYearDayClick(dateKey) {
  const allUsers = wpUsers.filter(u => u.showInWochenplanung !== false && u.role !== 'admin');
  const visUsers = allUsers.filter(u => wpYearSelectedUsers && wpYearSelectedUsers.has(u.username));
  if (!visUsers.length) visUsers.push(...allUsers);
  const canBook = wpCanEdit; // Nur Admin/Master darf für andere buchen
  if (!canBook && !wpCanEditSelf) return;
  const bookUsers = canBook ? visUsers : visUsers.filter(u => u.username === currentUser);
  if (!bookUsers.length) return;

  const prev = document.getElementById('wpYearBookOverlay');
  if (prev) prev.remove();
  const dateParts = dateKey.split('-');
  const dateLabel = `${dateParts[2]}.${dateParts[1]}.${dateParts[0]}`;

  // Bestehende Einträge an diesem Tag
  const existing = [];
  bookUsers.forEach(u => {
    const entries = wpAllZeit[u.username]?.entries || [];
    entries.filter(e => e.datum === dateKey && e.typ !== 'arbeit').forEach(e => {
      existing.push({ username: u.username, entryId: e.id, typ: e.typ, stunden: e.stunden });
    });
  });

  const userOpts = bookUsers.map(u => `<option value="${esc(u.username)}">${esc(u.username)}</option>`).join('');
  // Eigene Erfassungstypen (aus Verwaltung → Allgemein) zusätzlich zum Nachtragen anbieten.
  const _wpStdTypen = ['arbeit','urlaub','gleitzeit','abwesend','krank','sonstig','feiertag'];
  const wpCustomOpts = (typeof _seGetTypen === 'function' ? _seGetTypen() : [])
    .filter(t => !_wpStdTypen.includes(t.value))
    .map(t => `<option value="${esc(t.value)}">${esc(t.label)}</option>`).join('');
  const typOpts = `<option value="urlaub">Urlaub</option><option value="krank">Krank</option><option value="gleitzeit">Gleitzeit</option><option value="sonstig">Sonstiger Fehlgrund</option>` + wpCustomOpts;

  const existingHtml = existing.length ? existing.map(e => `<div style="display:flex;align-items:center;gap:6px;padding:3px 0;border-bottom:1px solid #eee;font-size:.82rem">
    <span>${esc(e.username)}</span> · <span>${esc(e.typ)}</span> · <span>${(e.stunden||0).toFixed(1)} h</span>
    <button class="icon-btn danger" onclick="wpYearDeleteEntry('${esc(e.username)}',${e.entryId})" title="Löschen" style="margin-left:auto">${ico('trash')}</button>
  </div>`).join('') : '<span style="font-size:.8rem;color:#aaa">Keine Abwesenheiten an diesem Tag.</span>';

  const ov = document.createElement('div');
  ov.id = 'wpYearBookOverlay';
  ov.className = 'modal-overlay';
  ov.style.zIndex = '9700';
  ov.onclick = (ev) => { if (ev.target === ov) ov.remove(); };
  ov.innerHTML = `
    <div style="background:var(--surface,#fff);color:var(--text,#1a1a2e);border-radius:12px;max-width:400px;width:100%;box-shadow:0 12px 40px rgba(0,0,0,.3);">
      <div style="padding:12px 16px;border-bottom:1px solid var(--grey-200);background:linear-gradient(135deg,#00B4D8,#0096B7);color:#fff;border-radius:12px 12px 0 0;">
        <h3 style="margin:0;font-size:.95rem;">📆 ${dateLabel}</h3>
      </div>
      <div style="padding:14px 16px;">
        <div style="margin-bottom:10px"><strong style="font-size:.82rem;">Bestehende Einträge:</strong><div style="margin-top:4px">${existingHtml}</div></div>
        <hr style="border:none;border-top:1px solid var(--border);margin:10px 0">
        <div style="font-weight:600;font-size:.82rem;margin-bottom:6px;">Neuen Eintrag anlegen:</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
          <div><label style="font-size:.72rem;color:#666;display:block">Person</label><select id="wpYbUser" class="form-control" style="font-size:.85rem;padding:4px 6px">${userOpts}</select></div>
          <div><label style="font-size:.72rem;color:#666;display:block">Typ</label><select id="wpYbTyp" class="form-control" style="font-size:.85rem;padding:4px 6px">${typOpts}</select></div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;">
          <div><label style="font-size:.72rem;color:#666;display:block">Von (Datum)</label><input type="date" id="wpYbFrom" class="form-control" value="${dateKey}" style="font-size:.85rem;padding:4px 6px"></div>
          <div><label style="font-size:.72rem;color:#666;display:block">Bis (optional)</label><input type="date" id="wpYbTo" class="form-control" value="${dateKey}" style="font-size:.85rem;padding:4px 6px"></div>
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px">
          <button class="btn btn-secondary" onclick="document.getElementById('wpYearBookOverlay')?.remove()">Abbrechen</button>
          <button class="btn btn-primary" onclick="wpYearBookSave('${dateKey}')">Speichern</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
}

async function wpYearBookSave(fallbackDate) {
  const username = document.getElementById('wpYbUser')?.value;
  const typ = document.getElementById('wpYbTyp')?.value || 'urlaub';
  const datumFrom = document.getElementById('wpYbFrom')?.value || fallbackDate;
  const datumTo = document.getElementById('wpYbTo')?.value || datumFrom;
  if (!username || !datumFrom) return;
  try {
    const body = { username, datum: datumFrom, typ, stunden: 0 };
    if (datumTo > datumFrom) body.datumBis = datumTo;
    const r = await fetch('api.php?action=admin_add_zeiterfassung', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    });
    const j = await r.json();
    if (j.ok) {
      showNotification((j.inserted?.length || 1) + ' Eintrag/Einträge gespeichert.');
      // Zeiterfassung neu laden und Ansicht aktualisieren
      try { const zr = await fetch('api.php?action=load_all_zeiterfassung'); const zj = await zr.json(); if (zj.ok) wpAllZeit = zj.data || {}; } catch(_) {}
      document.getElementById('wpYearBookOverlay')?.remove();
      renderWochenplanung();
    } else { showNotification(j.error || 'Fehler', 'error'); }
  } catch(e) { showNotification('Netzwerkfehler', 'error'); }
}

async function wpYearDeleteEntry(username, entryId) {
  if (!confirm('Eintrag löschen?')) return;
  try {
    const r = await fetch('api.php?action=admin_delete_zeiterfassung', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, entryId })
    });
    const j = await r.json();
    if (j.ok) {
      showNotification('Gelöscht.');
      if (wpAllZeit[username]) wpAllZeit[username].entries = (wpAllZeit[username].entries||[]).filter(e => e.id !== entryId);
      document.getElementById('wpYearBookOverlay')?.remove();
      renderWochenplanung();
    } else { showNotification(j.error || 'Fehler', 'error'); }
  } catch(e) { showNotification('Netzwerkfehler', 'error'); }
}

function wpNavDay(delta) {
  if (!wpSelectedDay) { wpSelectedDay = new Date(wpStartMonday || getWeekMonday(new Date())); }
  const d = new Date(wpSelectedDay);
  d.setDate(d.getDate() + delta);
  // skip Sunday
  while (d.getDay() === 0) d.setDate(d.getDate() + (delta >= 0 ? 1 : -1));
  wpSelectedDay = d;
  wpStartMonday = getWeekMonday(d);
  renderWochenplanung();
}

function wpJumpToDay(dateKey) {
  const p = dateKey.split('-');
  wpSelectedDay = new Date(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]));
  wpStartMonday = getWeekMonday(wpSelectedDay);
  renderWochenplanung();
}

/* -- Tagesansicht Render -- */
function renderWochenplanungTag() {
  const el = document.getElementById('wpContent');
  if (!el) return;

  const today = new Date();
  if (!wpStartMonday) wpStartMonday = getWeekMonday(today);

  // Ensure a valid selected day
  if (!wpSelectedDay) {
    const todayKey = wpDateKey(today);
    const monKey   = wpDateKey(wpStartMonday);
    const satKey   = wpDateKey(new Date(wpStartMonday.getTime() + 5 * 86400000));
    wpSelectedDay = (todayKey >= monKey && todayKey <= satKey)
      ? new Date(today.getFullYear(), today.getMonth(), today.getDate())
      : new Date(wpStartMonday);
  }

  const selKey  = wpDateKey(wpSelectedDay);
  const todayKey = wpDateKey(today);
  const kw = getISOWeek(wpStartMonday);

  // Holidays
  const holidays = getBavarianHolidays(wpSelectedDay.getFullYear());
  const holidayKeys = new Set(holidays.map(h => dateToKey(h)));
  const holidayNameMap = buildHolidayNameMap(wpSelectedDay.getFullYear());
  const isHoliday  = holidayKeys.has(selKey);
  const holidayName = holidayNameMap.get(selKey) || '';

  // Visible users
  let wpVisibleUsers = wpUsers.filter(u => u.showInWochenplanung !== false);
  if (!canDo('canSeeAllWochenplan')) {
    wpVisibleUsers = wpVisibleUsers.filter(u => u.username === currentUser);
  }

  // Day dropdown options (Mo–Sa of current week)
  const dayOpts = [];
  for (let d = 0; d < 6; d++) {
    const dt = new Date(wpStartMonday);
    dt.setDate(dt.getDate() + d);
    const dKey = wpDateKey(dt);
    const lbl  = wpDayNames[d] + ' ' + dt.toLocaleDateString('de-DE', { day:'2-digit', month:'2-digit' });
    dayOpts.push(`<option value="${dKey}"${dKey === selKey ? ' selected' : ''}>${lbl}</option>`);
  }

  // "Jump today" key – clamp to Monday if today is Sunday
  const jumpTodayKey = today.getDay() === 0
    ? wpDateKey(getWeekMonday(today))
    : wpDateKey(today);

  const dayLabel = wpSelectedDay.toLocaleDateString('de-DE', { weekday:'long', day:'2-digit', month:'long', year:'numeric' });

  let html = `<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap;">
    <button class="btn btn-secondary btn-sm" onclick="wpNavDay(-1)" title="Vorheriger Tag" style="padding:4px 10px;font-size:1rem;">&#8249;</button>
    <select class="form-input" style="width:auto;font-size:.85rem;padding:4px 8px;" onchange="wpJumpToDay(this.value)">${dayOpts.join('')}</select>
    <button class="btn btn-secondary btn-sm" onclick="wpNavDay(1)" title="Nächster Tag" style="padding:4px 10px;font-size:1rem;">&#8250;</button>
    <button class="btn btn-secondary btn-sm" onclick="wpJumpToDay('${jumpTodayKey}')" style="padding:4px 10px;font-size:.82rem;">Heute</button>
    <span style="font-size:.8rem;color:var(--grey-400);">KW ${kw}</span>
    <span style="display:inline-flex;border-radius:6px;overflow:hidden;border:1px solid var(--grey-200);margin-left:auto;">
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('week')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;">📅 Woche</button>
      <button class="btn btn-primary btn-sm" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);cursor:default;">🕐 Tag</button>
      <button class="btn btn-secondary btn-sm" onclick="wpSetViewMode('year')" style="padding:4px 12px;font-size:.82rem;border-radius:0;border:none;border-left:1px solid var(--grey-200);">📆 Jahr</button>
    </span>
  </div>`;

  // Day title
  html += `<div class="wp-day-title${selKey === todayKey ? ' wp-day-title-today' : ''}${isHoliday ? ' wp-day-title-feiertag' : ''}">
    ${dayLabel}${isHoliday ? ` <span class="wp-day-holiday-badge">🎉 ${esc(holidayName)}</span>` : ''}
  </div>`;

  if (wpVisibleUsers.length === 0) {
    el.innerHTML = html + '<p class="hint-text" style="text-align:center;padding:20px">Keine Benutzer für die Wochenplanung konfiguriert.</p>';
    return;
  }

  // Timeline constants
  const DAY_START = 6;
  const DAY_END   = 18;
  const HOURS     = DAY_END - DAY_START; // 12

  // Hour header labels
  let hoursHtml = '';
  for (let h = DAY_START; h < DAY_END; h++) {
    hoursHtml += `<div class="wp-day-hour-label" style="left:${((h - DAY_START) / HOURS * 100).toFixed(2)}%;width:${(100 / HOURS).toFixed(2)}%">${String(h).padStart(2,'0')}</div>`;
  }

  // Vertical grid lines (per hour incl. last border)
  let gridLines = '';
  for (let h = DAY_START; h <= DAY_END; h++) {
    gridLines += `<div class="wp-day-grid-line" style="left:${((h - DAY_START) / HOURS * 100).toFixed(2)}%"></div>`;
  }

  html += `<div class="wp-tl-scroll">
  <table class="wp-day-table">
    <thead>
      <tr>
        <th class="wp-tl-name-hd">Monteur</th>
        <th class="wp-day-allday-hd">Ganztags</th>
        <th class="wp-day-timehd">
          <div class="wp-day-hours-bar">${hoursHtml}</div>
        </th>
      </tr>
    </thead>
    <tbody>`;

  const _wpGrpMapDay = wpBuildGruppenMap();

  wpVisibleUsers.forEach((user, userIdx) => {
    const uname    = user.username;
    const color    = WP_MONTEUR_COLORS[userIdx % WP_MONTEUR_COLORS.length];
    const seEntries = wpAllZeit[uname]?.entries || [];
    const planArr  = (wpPlan[uname] || {})[selKey] || [];

    // ── Ganztags blocks ─────────────────────────────────────
    const alldayBlocks = [];

    if (isHoliday) {
      alldayBlocks.push(`<div class="wp-block wp-block-feiertag" title="${esc(holidayName)}">🎉 ${esc(holidayName)}</div>`);
    } else {
      const urlaubDates = new Set(seEntries.filter(e => e.typ === 'urlaub').map(e => e.datum));
      const krankDates  = new Set(seEntries.filter(e => e.typ === 'krank').map(e => e.datum));
      const sonstigMap  = {};
      seEntries.filter(e => e.typ === 'sonstig').forEach(e => { sonstigMap[e.datum] = e.bemerkung || 'Sonstig'; });

      const hasPlannedUrlaub  = planArr.some(e => e.typ === 'urlaub');
      const hasPlannedSonstig = planArr.some(e => e.typ === 'sonstig');
      const plannedBauIds     = new Set(planArr.filter(e => e.typ === 'baustelle').map(e => String(e.baustelleId)));

      planArr.forEach(e => {
        if (e.typ === 'baustelle') {
          const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || '?';
          alldayBlocks.push(`<div class="wp-block wp-block-bau" style="background:${color}18;border-left:3px solid ${color};color:${color}" title="${esc('Baustelle: ' + bName + (e.bemerkung ? '\n' + e.bemerkung : ''))}">${esc(bName)}${e.bemerkung ? `<span class="wp-block-bem">${esc(e.bemerkung)}</span>` : ''}</div>`);
        } else if (e.typ === 'urlaub') {
          alldayBlocks.push(`<div class="wp-block wp-block-urlaub">${ico('palm')} Urlaub</div>`);
        } else if (e.typ === 'sonstig') {
          alldayBlocks.push(`<div class="wp-block wp-block-sonstig">${ico('alert')} ${esc(e.bemerkung || 'Sonstiges')}</div>`);
        } else if (e.typ === 'betrieb') {
          const bCls  = e.betriebTyp === 'freizeit' ? 'wp-block-betrieb-frei' : 'wp-block-betrieb-arbeit';
          const bIcon = e.betriebTyp === 'freizeit' ? '🏖' : '💼';
          alldayBlocks.push(`<div class="wp-block ${bCls}">${bIcon} ${esc(e.bemerkung || 'Betrieb')}</div>`);
        }
      });

      if (urlaubDates.has(selKey) && !hasPlannedUrlaub)
        alldayBlocks.push(`<div class="wp-block wp-block-urlaub wp-block-synced">${ico('palm')} Urlaub</div>`);
      if (krankDates.has(selKey))
        alldayBlocks.push(`<div class="wp-block wp-block-krank wp-block-synced">${ico('thermometer')} Krank</div>`);
      if (selKey in sonstigMap && !hasPlannedSonstig)
        alldayBlocks.push(`<div class="wp-block wp-block-sonstig wp-block-synced">${ico('alert')} ${esc(sonstigMap[selKey])}</div>`);

      // Arbeit-SE ohne Zeitangabe → Ganztags-Spalte
      seEntries.filter(e => e.typ === 'arbeit' && e.datum === selKey && !e.von && !e.vonZeit && e.baustelleId).forEach(e => {
        if (plannedBauIds.has(String(e.baustelleId))) return;
        const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || e.baustelleName || '?';
        const tipParts = ['Baustelle: ' + bName];
        if (e.stunden) tipParts.push(e.stunden + ' h');
        if (e.bemerkung) tipParts.push(e.bemerkung);
        tipParts.push('(Stundenerfassung)');
        alldayBlocks.push(`<div class="wp-block wp-block-synced" style="background:${color}0D;border-left:3px dashed ${color};color:${color}" title="${esc(tipParts.join('\n'))}">${ico('clock')} ${esc(bName)}${e.stunden ? `<span class="wp-block-bem">${e.stunden}h</span>` : ''}</div>`);
      });

      // Ganztags Termine
      (termineData || []).forEach(t => {
        if (t.datum !== selKey || !t.ganztags) return;
        if (!wpTerminGiltFuerUser(t, uname, _wpGrpMapDay)) return;
        alldayBlocks.push(`<div class="wp-block wp-block-termin" style="background:${esc(t.farbe||'#00B4D8')}18;border-left:3px solid ${esc(t.farbe||'#00B4D8')};color:${esc(t.farbe||'#00B4D8')};cursor:pointer" onclick="event.stopPropagation();wpShowTerminDetail(${t.id})">${ico('calendar')} ${esc(t.titel)}</div>`);
      });
    }

    // ── Timeline bars ────────────────────────────────────────
    const bars = [];

    if (!isHoliday) {
      // Arbeit entries with von/bis
      seEntries.filter(e => e.typ === 'arbeit' && e.datum === selKey && (e.von || e.vonZeit)).forEach(e => {
        const von   = e.von  || e.vonZeit  || '';
        const bis   = e.bis  || e.bisZeit  || '';
        const left  = wpTimeToPercent(von, DAY_START, DAY_END);
        const right = bis ? wpTimeToPercent(bis, DAY_START, DAY_END) : Math.min(100, (left || 0) + (100 / HOURS));
        if (left === null) return;
        const width = Math.max(0.5, right - left);
        const bName = appData.baustellen.find(b => b.id == e.baustelleId)?.name || e.baustelleName || '?';
        const tipParts = [`Baustelle: ${bName}`];
        if (von) tipParts.push(`Von: ${von}`);
        if (bis) tipParts.push(`Bis: ${bis}`);
        if (e.stunden) tipParts.push(`${e.stunden} h`);
        if (e.bemerkung) tipParts.push(e.bemerkung);
        tipParts.push('(Stundenerfassung)');
        bars.push(`<div class="wp-day-bar" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:${color};border-color:${color}" title="${esc(tipParts.join('\n'))}">${esc(bName)} ${von}${bis ? '–' + bis : ''}</div>`);
      });

      // Timed Termine
      (termineData || []).forEach(t => {
        if (t.datum !== selKey || t.ganztags || !t.zeitVon) return;
        if (!wpTerminGiltFuerUser(t, uname, _wpGrpMapDay)) return;
        const left  = wpTimeToPercent(t.zeitVon, DAY_START, DAY_END);
        const right = t.zeitBis ? wpTimeToPercent(t.zeitBis, DAY_START, DAY_END) : Math.min(100, (left || 0) + (100 / HOURS));
        if (left === null) return;
        const width = Math.max(0.5, right - left);
        const tColor = t.farbe || '#00B4D8';
        bars.push(`<div class="wp-day-bar wp-day-bar-termin" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:${esc(tColor)}33;border-color:${esc(tColor)};color:${esc(tColor)}" title="${esc(t.titel + ' (' + t.zeitVon + '–' + (t.zeitBis||'?') + ')')}" onclick="event.stopPropagation();wpShowTerminDetail(${t.id})">${esc(t.titel)} ${t.zeitVon}–${t.zeitBis||'?'}</div>`);
      });
    }

    html += `<tr>
      <td class="wp-tl-name-cell"><span class="wp-tl-dot" style="background:${color}"></span> ${esc(uname)}</td>
      <td class="wp-day-allday-cell">${alldayBlocks.join('') || '<div class="wp-block wp-block-empty">—</div>'}</td>
      <td class="wp-day-time-cell">
        <div class="wp-day-timeline-track">${gridLines}${bars.join('')}</div>
      </td>
    </tr>`;
  });

  html += `</tbody></table></div>`;
  el.innerHTML = html;
}

/* -- Wochenplan Kalender-Abo (iCal / iOS / Google) -- */
async function openWpCalendarShare() {
  try {
    const res = await fetch('api.php?action=get_wochenplan_cal_token');
    const j = await res.json();
    if (!j.ok || !j.token) { alert('Fehler beim Erstellen des Kalender-Links.'); return; }

    const baseUrl    = window.location.origin + window.location.pathname.replace(/[^/]*$/, '') + 'api.php';
    const httpsUrl   = baseUrl + '?action=export_wochenplan_ical&token=' + encodeURIComponent(j.token);
    const downloadUrl = httpsUrl + '&download=1';
    const webcalUrl  = httpsUrl.replace(/^https?:/, 'webcal:');
    const googleUrl  = 'https://calendar.google.com/calendar/r?cid=' + encodeURIComponent(webcalUrl);

    // Personen-Auswahl nur für Nutzer, die alle Daten sehen dürfen.
    const canPickUsers = canDo('canSeeAllWochenplan') || canDo('canSeeAllTermine');
    const selected = Array.isArray(j.filterUsers) ? j.filterUsers : [];
    let personSection = '';
    if (canPickUsers) {
      const userRows = (wpUsers || []).map(u => {
        const checked = selected.includes(u.username) ? 'checked' : '';
        return `<label style="display:flex;align-items:center;gap:6px;font-size:.82rem;padding:2px 0;cursor:pointer"><input type="checkbox" class="wpcal-user-cb" value="${esc(u.username)}" ${checked}> ${esc(u.username)}${u.kuerzel?' ('+esc(u.kuerzel)+')':''}</label>`;
      }).join('');
      personSection = `
        <div style="margin:4px 0 16px;border:1px solid var(--grey-200,#e0e0e0);border-radius:8px;padding:12px;">
          <div style="font-size:.82rem;font-weight:600;margin-bottom:6px;">Welche Mitarbeiter sollen abonniert werden?</div>
          <div style="font-size:.75rem;color:#888;margin-bottom:8px;">Keine Auswahl = <strong>alle</strong> Mitarbeiter. Die Auswahl gilt für diesen Abo-Link.</div>
          <div style="max-height:170px;overflow-y:auto;border:1px solid var(--grey-100,#eee);border-radius:6px;padding:6px 10px;margin-bottom:8px;">
            ${userRows || '<em style="color:#888;font-size:.8rem">Keine Mitarbeiter verfügbar</em>'}
          </div>
          <div style="display:flex;justify-content:flex-end;gap:8px;">
            <button class="btn btn-secondary btn-sm" onclick="wpCalToggleAllUsers(false)">Keine</button>
            <button class="btn btn-secondary btn-sm" onclick="wpCalToggleAllUsers(true)">Alle</button>
            <button class="btn btn-primary btn-sm" onclick="wpCalApplyFilter()">Auswahl speichern</button>
          </div>
        </div>`;
    }

    // Overlay
    let overlay = document.getElementById('wpCalShareOverlay');
    if (overlay) overlay.remove();
    overlay = document.createElement('div');
    overlay.id = 'wpCalShareOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;';
    overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };

    const modal = document.createElement('div');
    modal.style.cssText = 'background:#fff;border-radius:12px;max-width:520px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 12px 40px rgba(0,0,0,.3);';
    modal.innerHTML = `
      <div style="padding:16px 20px;border-bottom:1px solid #e0e0e0;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#00B4D8,#0096B7);color:#fff;border-radius:12px 12px 0 0;">
        <h3 style="margin:0;font-size:1.1rem;">${ico('calendar')} Kalender abonnieren</h3>
        <button onclick="document.getElementById('wpCalShareOverlay').remove()" style="background:none;border:none;color:#fff;font-size:1.4rem;cursor:pointer;line-height:1;">&times;</button>
      </div>
      <div style="padding:20px;">
        <p style="color:#555;font-size:.9rem;margin:0 0 4px;">Der Feed enthält <strong>Wochenplanung, Termine und Stundenerfassung</strong> (Urlaub, Krank, Arbeitstage).</p>
        <p style="color:#888;font-size:.8rem;margin:0 0 16px;">Der Kalender aktualisiert sich automatisch, wenn Daten geändert werden.</p>
        ${personSection}
        <div style="display:flex;flex-direction:column;gap:10px;">
          <a href="${webcalUrl}" class="btn btn-primary" style="text-align:center;text-decoration:none;display:block;">
            ${ico('calendar')} iPhone / iPad / Mac Kalender
          </a>
          <a href="${googleUrl}" target="_blank" rel="noopener" class="btn btn-secondary" style="text-align:center;text-decoration:none;display:block;">
            Google Kalender öffnen
          </a>
          <div style="margin-top:6px;">
            <label style="font-size:.8rem;color:#888;display:block;margin-bottom:4px;">Abo-URL (für andere Kalender-Apps, z.B. Outlook):</label>
            <div style="display:flex;gap:6px;">
              <input type="text" readonly value="${httpsUrl}" id="wpCalUrl" class="form-control" style="flex:1;font-size:.78rem;padding:6px 8px;">
              <button class="btn btn-secondary btn-sm" onclick="navigator.clipboard.writeText(document.getElementById('wpCalUrl').value).then(()=>this.textContent='Kopiert ✓').catch(()=>{})">Kopieren</button>
            </div>
          </div>
          <a href="${downloadUrl}" class="btn btn-secondary btn-sm" style="text-align:center;text-decoration:none;margin-top:4px;">
            ${ico('download')} .ics Datei herunterladen
          </a>
        </div>
      </div>
    `;
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
  } catch(e) {
    alert('Fehler: ' + e.message);
  }
}

/** Alle/keine Mitarbeiter im Abo-Dialog an-/abwählen. */
function wpCalToggleAllUsers(checked) {
  document.querySelectorAll('.wpcal-user-cb').forEach(cb => { cb.checked = checked; });
}

/** Speichert die Personen-Auswahl für den Abo-Feed (Token bleibt gleich). */
async function wpCalApplyFilter() {
  const users = [];
  document.querySelectorAll('.wpcal-user-cb:checked').forEach(cb => users.push(cb.value));
  try {
    const r = await fetch('api.php?action=get_wochenplan_cal_token', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ users })
    });
    const j = await r.json();
    if (j.ok) {
      showNotification(users.length ? `Auswahl gespeichert (${users.length} Mitarbeiter).` : 'Auswahl gespeichert: alle Mitarbeiter.');
    } else {
      alert(j.error || 'Fehler beim Speichern der Auswahl.');
    }
  } catch(e) {
    alert('Netzwerkfehler: ' + e.message);
  }
}

// ============================================================
// STUNDENABGLEICH  -  SE vs. Arbeitszeit (Admin/Master)
// ============================================================
async function openStundenabgleichModal() {
  show('stundenabgleichModal');
  const el = document.getElementById('stundenabgleichContent');
  el.innerHTML = `<div style="text-align:center;padding:30px;color:var(--grey-400)">${ico('hourglass','ico-xl')} Lade Daten —</div>`;

  try {
    // Load Zeiterfassung data (all users)
    const zeitRes = await fetch('api.php?action=load_all_zeiterfassung');
    const zeitJ = await zeitRes.json();
    if (!zeitJ.ok) { el.innerHTML = '<p class="text-danger">Fehler beim Laden der Zeiterfassung.</p>'; return; }
    const zeitData = zeitJ.data || {};

    renderStundenabgleich(zeitData);
  } catch(e) {
    el.innerHTML = `<p class="text-danger">Netzwerkfehler: ${esc(e.message)}</p>`;
  }
}

function closeStundenabgleichModal() { hide('stundenabgleichModal'); }

function renderStundenabgleich(zeitData) {
  const el = document.getElementById('stundenabgleichContent');
  if (!el) return;

  // 1) Aggregate SE hours per Baustelle
  const seBaustelle = {};   // baustelleId ? { name, stunden, entries: [] }
  const seUser = {};        // username ? { stunden, entries }

  for (const username in zeitData) {
    const entries = zeitData[username]?.entries || [];
    entries.forEach(e => {
      if (e.typ !== 'arbeit' || !e.baustelleId) return;
      const bId = String(e.baustelleId);
      if (!seBaustelle[bId]) seBaustelle[bId] = { name: e.baustelleName || '?', stunden: 0, entries: [] };
      seBaustelle[bId].stunden += (e.stunden || 0);
      seBaustelle[bId].entries.push({ user: username, datum: e.datum, stunden: e.stunden || 0, bemerkung: e.bemerkung || '' });

      if (!seUser[username]) seUser[username] = { stunden: 0 };
      seUser[username].stunden += (e.stunden || 0);
    });
  }

  // 2) Aggregate AZ hours per Baustelle
  const azBaustelle = {};   // baustelleId ? { name, stunden, entries: [] }
  appData.baustellen.forEach(b => {
    const bId = String(b.id);
    const totalH = (b.arbeitszeit || []).reduce((sum, r) => sum + (r.stunden || 0), 0);
    azBaustelle[bId] = { name: b.name, stunden: totalH, entries: b.arbeitszeit || [] };
  });

  // 3) Build union of all baustelleIds
  const allIds = new Set([...Object.keys(seBaustelle), ...Object.keys(azBaustelle)]);
  const rows = [];
  let totalSE = 0, totalAZ = 0;

  allIds.forEach(bId => {
    const se = seBaustelle[bId] || { name: '—', stunden: 0, entries: [] };
    const az = azBaustelle[bId] || { name: '—', stunden: 0, entries: [] };
    const name = az.name !== '—' ? az.name : se.name;
    const diff = se.stunden - az.stunden;
    totalSE += se.stunden;
    totalAZ += az.stunden;
    rows.push({ bId, name, seH: se.stunden, azH: az.stunden, diff, seEntries: se.entries, azEntries: az.entries });
  });

  // Sort: biggest difference first
  rows.sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff));

  const totalDiff = totalSE - totalAZ;

  // 4) Render HTML
  let html = `<p style="font-size:0.82rem;color:var(--grey-500);margin:0 0 12px">
    Vergleich der <strong>Stundenerfassung</strong> (alle Mitarbeiter) mit der <strong>Arbeitszeit</strong> in den Baustellen.
    <span style="color:${Math.abs(totalDiff) < 0.01 ? '#57BB8A' : '#E67C73'};font-weight:700;margin-left:8px">
      Gesamt-Differenz: ${totalDiff >= 0 ? '+' : ''}${totalDiff.toFixed(2)} h
    </span>
  </p>`;

  if (rows.length === 0) {
    html += '<p class="hint-text" style="text-align:center;padding:20px">Keine Daten vorhanden.</p>';
    el.innerHTML = html;
    return;
  }

  html += `<table class="sa-table">
    <thead>
      <tr>
        <th style="text-align:left">Baustelle</th>
        <th style="width:130px">Stundenerfassung (h)</th>
        <th style="width:130px">Arbeitszeit (h)</th>
        <th style="width:120px">Differenz (h)</th>
        <th style="width:80px">Status</th>
        <th style="width:40px"></th>
      </tr>
    </thead>
    <tbody>`;

  rows.forEach((r, idx) => {
    const diffClass = Math.abs(r.diff) < 0.01 ? 'sa-ok' : (r.diff > 0 ? 'sa-more' : 'sa-less');
    const statusIcon = Math.abs(r.diff) < 0.01
      ? `<span class="sa-badge sa-badge-ok">${ico('check')} OK</span>`
      : `<span class="sa-badge sa-badge-diff">${ico('alert')} Diff</span>`;
    const diffStr = (r.diff >= 0 ? '+' : '') + r.diff.toFixed(2);

    html += `<tr class="${diffClass}">
      <td style="font-weight:600">${esc(r.name)}</td>
      <td class="text-right">${r.seH.toFixed(2)}</td>
      <td class="text-right">${r.azH.toFixed(2)}</td>
      <td class="text-right sa-diff-cell">${diffStr}</td>
      <td>${statusIcon}</td>
      <td><button class="icon-btn" onclick="saToggleDetail(${idx})" title="Details">${ico('eye')}</button></td>
    </tr>
    <tr class="sa-detail-row" id="saDetail_${idx}" style="display:none">
      <td colspan="6">
        <div class="sa-detail-box" id="saDetailBox_${idx}"></div>
      </td>
    </tr>`;
  });

  html += `</tbody>
    <tfoot>
      <tr class="sa-total-row">
        <td style="font-weight:700">Gesamt</td>
        <td class="text-right" style="font-weight:700">${totalSE.toFixed(2)}</td>
        <td class="text-right" style="font-weight:700">${totalAZ.toFixed(2)}</td>
        <td class="text-right sa-diff-cell" style="font-weight:700">${(totalDiff >= 0 ? '+' : '') + totalDiff.toFixed(2)}</td>
        <td></td>
        <td></td>
      </tr>
    </tfoot>
  </table>`;

  el.innerHTML = html;

  // Store rows data for detail toggle
  el._saRows = rows;
}

function saToggleDetail(idx) {
  const detailRow = document.getElementById(`saDetail_${idx}`);
  const detailBox = document.getElementById(`saDetailBox_${idx}`);
  if (!detailRow || !detailBox) return;

  if (detailRow.style.display === 'none') {
    detailRow.style.display = '';
    const el = document.getElementById('stundenabgleichContent');
    const row = el?._saRows?.[idx];
    if (!row) return;

    let html = '<div class="sa-detail-cols">';

    // SE entries
    html += '<div class="sa-detail-col"><strong>Stundenerfassung</strong>';
    if (row.seEntries.length === 0) {
      html += '<p class="sa-detail-empty">Keine Einträge</p>';
    } else {
      html += '<table class="sa-mini-table"><thead><tr><th>Mitarbeiter</th><th>Datum</th><th>Stunden</th><th>Bemerkung</th></tr></thead><tbody>';
      const sorted = [...row.seEntries].sort((a,b) => (a.datum||'').localeCompare(b.datum||''));
      sorted.forEach(e => {
        html += `<tr><td>${esc(e.user)}</td><td>${e.datum ? e.datum.split('-').reverse().join('.') : '—'}</td><td class="text-right">${(e.stunden||0).toFixed(2)}</td><td>${esc(e.bemerkung)}</td></tr>`;
      });
      html += '</tbody></table>';
    }
    html += '</div>';

    // AZ entries
    html += '<div class="sa-detail-col"><strong>Arbeitszeit (Baustelle)</strong>';
    if (row.azEntries.length === 0) {
      html += '<p class="sa-detail-empty">Keine Einträge</p>';
    } else {
      html += '<table class="sa-mini-table"><thead><tr><th>Beschreibung</th><th>Datum</th><th>Stunden</th><th>Erstellt von</th></tr></thead><tbody>';
      const sorted = [...row.azEntries].sort((a,b) => (a.datum||'').localeCompare(b.datum||''));
      sorted.forEach(e => {
        html += `<tr><td>${esc(e.beschreibung||'')}</td><td>${e.datum ? e.datum.split('-').reverse().join('.') : '—'}</td><td class="text-right">${(e.stunden||0).toFixed(2)}</td><td>${esc(e.erstelltVon||'')}</td></tr>`;
      });
      html += '</tbody></table>';
    }
    html += '</div></div>';

    detailBox.innerHTML = html;
  } else {
    detailRow.style.display = 'none';
  }
}

// ============================================================
// PDF EXPORT - Zeitübersicht Jahresübersicht
// ============================================================
function exportZeituebersichtPDF() {
  const year = new Date().getFullYear();
  const months = Array.from({length: 12}, (_, i) => i);

  // Build HTML table for PDF
  let html = `<html style="color-scheme:light"><head><meta charset="UTF-8"><title>Zeitübersicht ${year}</title>
  <style>
    @page { margin: 15mm 12mm 15mm 12mm; }
    body { font-family: -apple-system, Arial, sans-serif; font-size: 11px; color: #1D1D1F; margin: 20px; }
    h1 { font-size: 18px; margin-bottom: 4px; color: #00B4D8; }
    h2 { font-size: 13px; color: #86868B; margin-bottom: 16px; font-weight: 400; }
    table { border-collapse: collapse; width: 100%; margin-bottom: 24px; }
    th, td { border: 1px solid #E8E8ED; padding: 5px 8px; text-align: right; font-size: 10px; }
    th { background: #00B4D8; color: white; font-weight: 600; }
    td:first-child, th:first-child { text-align: left; }
    tr { page-break-inside: avoid; }
    .positive { color: #28A745; font-weight: 700; }
    .negative { color: #FF3B30; font-weight: 700; }
    .section-title { font-size: 13px; font-weight: 700; margin: 16px 0 8px; color: #48484A; page-break-after: avoid; }
    @media print { body { margin: 0; } }
  </style></head><body>
  <h1>Zeitübersicht ${year}</h1>
  <h2>Erstellt am ${new Date().toLocaleDateString('de-DE')} - Baukalkulation</h2>`;

  zuAllUsers.filter(u => u.role !== 'admin' && u.showInZeitverwaltung !== false).forEach(user => {
    const allEntries = zuAllZeit[user.username]?.entries || [];
    const sollBeschreibung = bkSollBeschreibung(user);
    const urlaubJahr = bkUrlaubsanspruch(user, year);
    const urlaubGenommen = allEntries.filter(e => e.typ === 'urlaub' && e.datum && e.datum.startsWith(String(year))).length;
    const krankGesamt = allEntries.filter(e => e.typ === 'krank' && e.datum && e.datum.startsWith(String(year))).length;

    html += `<p class="section-title">${esc(user.username)} (${esc(user.role)}) - Soll: ${esc(sollBeschreibung)} - Urlaub: ${urlaubGenommen}/${urlaubJahr} Tage - Krank: ${krankGesamt} Tage</p>`;
    html += `<table><thead><tr><th>Monat</th><th>Werktage</th><th>Soll (h)</th><th>Ist (h)</th><th>+/- (h)</th><th>Urlaub</th><th>Krank</th></tr></thead><tbody>`;

    let totalIst = 0, totalSoll = 0;
    months.forEach(m => {
      const mk = year + '-' + String(m+1).padStart(2,'0');
      const me = allEntries.filter(e => e.datum && e.datum.startsWith(mk));
      const ist = sumIstStunden(me, user)
        + sumIstStunden(getVirtuelleFeiertagEintraege(allEntries, user, year, m), user);
      const soll = calcSollMonat(user, year, m);
      const urlaub = me.filter(e => e.typ === 'urlaub').length;
      const krank = me.filter(e => e.typ === 'krank').length;
      const diff = ist - soll;
      const wd = getWorkingDaysInMonth(year, m, user);
      totalIst += ist;
      totalSoll += soll;
      const cls = diff >= 0 ? 'positive' : 'negative';
      const sign = diff >= 0 ? '+' : '';
      html += `<tr><td>${getMonthName(m)}</td><td>${wd}</td><td>${soll.toFixed(2)}</td><td>${ist.toFixed(2)}</td><td class="${cls}">${sign}${diff.toFixed(2)}</td><td>${urlaub}</td><td>${krank}</td></tr>`;
    });

    const totalDiff = totalIst - totalSoll;
    const totalCls = totalDiff >= 0 ? 'positive' : 'negative';
    const totalSign = totalDiff >= 0 ? '+' : '';
    html += `<tr style="font-weight:700;background:#f5f5f7"><td>Gesamt</td><td></td><td>${totalSoll.toFixed(2)}</td><td>${totalIst.toFixed(2)}</td><td class="${totalCls}">${totalSign}${totalDiff.toFixed(2)}</td><td>${urlaubGenommen}</td><td>${krankGesamt}</td></tr>`;
    html += `</tbody></table>`;
  });

  html += `</body></html>`;

  // Open in new window and trigger print
  const w = window.open('', '_blank', 'width=900,height=700');
  w.document.write(html);
  w.document.close();
  setTimeout(() => w.print(), 500);
}

// ============================================================
// WHATSAPP MESSENGER MODULE
// ============================================================
let waContacts      = [];
let waMessages      = [];
let waTemplates     = [];
let waSelectedPhone = null;   // aktuell ausgewählter Kontakt (Telefonnummer)
let waPollingTimer  = null;

// -- Init -----------------------------------------------------
let waBridgeAvailable = false;

async function initWhatsApp() {
  // Erst prüfen ob Bridge erreichbar ist
  try {
    const r = await fetch('whatsapp_api.php?action=status', { signal: AbortSignal.timeout(3000) });
    const j = await r.json();
    waBridgeAvailable = !!(j.status || j.connected);
  } catch(e) {
    waBridgeAvailable = false;
  }

  if (!waBridgeAvailable) {
    // Bridge nicht erreichbar ? WhatsApp-Button ausblenden
    const btn = document.getElementById('btnWhatsApp');
    if (btn) btn.style.display = 'none';
    console.info('WhatsApp-Bridge nicht erreichbar ? WhatsApp-Funktionen deaktiviert.');
    return;
  }

  // Ungelesene Badge aktualisieren
  await updateWaUnreadBadge();
  // Polling alle 15 Sekunden für neue Nachrichten
  if (waPollingTimer) clearInterval(waPollingTimer);
  waPollingTimer = setInterval(updateWaUnreadBadge, 15000);
}

// -- View anzeigen --------------------------------------------
function showWhatsApp() {
  selectedId = null;
  document.getElementById('btnWhatsApp')?.classList.add('active');
  document.getElementById('btnUebersicht')?.classList.remove('active');
  document.getElementById('btnMaterialKatalog')?.classList.remove('active');
  document.getElementById('btnStundenKatalog')?.classList.remove('active');
  document.getElementById('btnOffenesMaterial')?.classList.remove('active');
  document.getElementById('btnSchnellnotizenSidebar')?.classList.remove('active');
  document.getElementById('btnKundenstamm')?.classList.remove('active');
  renderSidebar();
  hide('emptyState');
  hide('baustelleDetail');
  hide('uebersichtView');
  hide('materialKatalogView');
  hide('stundenKatalogView');
  hide('offenesMaterialView');
  hide('schnellnotizenView');
  hide('kundenstammView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('dashboardView'); hide('vde0100View');
  show('whatsappView');
  loadWaContacts();
  loadWaTemplates();
}

// -- Ungelesen-Badge ------------------------------------------
async function updateWaUnreadBadge() {
  try {
    const r = await fetch('whatsapp_api.php?action=unread_count');
    const j = await r.json();
    const badge = document.getElementById('waUnreadBadge');
    if (badge) {
      if (j.count > 0) {
        badge.textContent = j.count;
        badge.style.display = '';
      } else {
        badge.style.display = 'none';
      }
    }
  } catch (e) { /* Offline - ignorieren */ }
}

// --------------------------------------------------------------
// KONTAKTE
// --------------------------------------------------------------

async function loadWaContacts() {
  try {
    const r = await fetch('whatsapp_api.php?action=contacts');
    const j = await r.json();
    waContacts = j.contacts || [];
    renderWaContacts();
  } catch (e) {
    console.warn('WhatsApp-Kontakte nicht ladbar:', e);
  }
}

function renderWaContacts() {
  const list = document.getElementById('waContactList');
  if (!list) return;

  const search = (document.getElementById('waContactSearch')?.value || '').toLowerCase();
  const filtered = search
    ? waContacts.filter(c => (c.name || '').toLowerCase().includes(search) || c.phone.includes(search))
    : waContacts;

  if (filtered.length === 0) {
    list.innerHTML = `<li style="padding:20px;text-align:center;color:var(--grey-400);font-size:0.85rem">${
      waContacts.length === 0 ? 'Noch keine Kontakte.<br>Nachrichten werden automatisch empfangen.' : 'Kein Treffer.'
    }</li>`;
    return;
  }

  list.innerHTML = filtered.map(c => {
    const initials = getInitials(c.name || c.phone);
    const time = c.lastMessage ? formatWaTime(c.lastMessage) : '';
    const active = c.phone === waSelectedPhone ? ' active' : '';
    const unread = (c.unreadCount || 0) > 0 ? `<span class="wa-contact-unread">${c.unreadCount}</span>` : '';
    const zuordnung = c.zuordnung ? `<span class="wa-contact-zuordnung" data-type="${esc(c.zuordnung)}">${esc(c.zuordnung)}</span>` : '';
    const preview = getLastMessagePreview(c.phone);

    return `<li class="wa-contact-item${active}" onclick="selectWaContact('${esc(c.phone)}')">
      <div class="wa-contact-avatar">${esc(initials)}</div>
      <div class="wa-contact-info">
        <div class="wa-contact-name">${esc(c.name || c.phone)} ${zuordnung}</div>
        <div class="wa-contact-preview">${esc(preview)}</div>
      </div>
      <div class="wa-contact-meta">
        <span class="wa-contact-time">${time}</span>
        ${unread}
      </div>
    </li>`;
  }).join('');
}

function filterWaContacts() { renderWaContacts(); }

function getInitials(name) {
  const parts = name.replace(/[^a-zA-Z ———————\s]/g, '').split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
  return '?';
}

function getLastMessagePreview(phone) {
  const msgs = waMessages.filter(m => {
    const from = (m.from || '').replace(/^whatsapp:/, '');
    const to = (m.to || '').replace(/^whatsapp:/, '');
    return from === phone || to === phone;
  });
  if (msgs.length === 0) return '';
  const last = msgs[msgs.length - 1];
  const prefix = last.direction === 'outgoing' ? '' : '';
  return prefix + (last.body || '').substring(0, 50);
}

function formatWaTime(isoStr) {
  if (!isoStr) return '';
  const d = new Date(isoStr);
  const now = new Date();
  const isToday = d.toDateString() === now.toDateString();
  if (isToday) return d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  if (d.toDateString() === yesterday.toDateString()) return 'Gestern';
  return d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' });
}

// --------------------------------------------------------------
// CHAT
// --------------------------------------------------------------

async function selectWaContact(phone) {
  waSelectedPhone = phone;
  renderWaContacts();

  // Chat-Header aktualisieren
  const contact = waContacts.find(c => c.phone === phone);
  document.getElementById('waChatName').textContent = contact ? (contact.name || phone) : phone;
  document.getElementById('waChatPhone').textContent = phone;
  document.getElementById('waChatHeaderActions').style.display = '';
  document.getElementById('waChatInput').style.display = '';

  // Baustellen-Dropdown befüllen
  populateWaBaustellenSelect('waChatBaustelleWrap', contact?.baustelle);

  // Zuordnung vorbelegen
  const zuordnungSel = document.getElementById('waChatZuordnung');
  if (zuordnungSel && contact) zuordnungSel.value = contact.zuordnung || '';

  // Nachrichten laden
  await loadWaMessages(phone);

  // Als gelesen markieren
  try {
    await fetch('whatsapp_api.php?action=mark_read', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone })
    });
    // Badge & Kontaktliste aktualisieren
    const c = waContacts.find(c => c.phone === phone);
    if (c) c.unreadCount = 0;
    renderWaContacts();
    updateWaUnreadBadge();
  } catch (e) {}
}

async function loadWaMessages(phone) {
  try {
    const r = await fetch('whatsapp_api.php?action=messages&phone=' + encodeURIComponent(phone));
    const j = await r.json();
    waMessages = j.messages || [];
    renderWaChat();
  } catch (e) {
    console.warn('WhatsApp-Nachrichten nicht ladbar:', e);
  }
}

function renderWaChat() {
  const el = document.getElementById('waChatMessages');
  if (!el || !waSelectedPhone) return;

  const msgs = waMessages.filter(m => {
    const from = (m.from || '').replace(/^whatsapp:/, '');
    const to = (m.to || '').replace(/^whatsapp:/, '');
    return from === waSelectedPhone || to === waSelectedPhone;
  });

  if (msgs.length === 0) {
    el.innerHTML = `<div class="wa-chat-empty">
      <div style="font-size:3rem;margin-bottom:12px">${ico('mail')}</div>
      <p>Noch keine Nachrichten mit diesem Kontakt.</p>
    </div>`;
    return;
  }

  let html = '';
  let lastDate = '';

  msgs.forEach(m => {
    const d = new Date(m.timestamp);
    const dateStr = d.toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
    if (dateStr !== lastDate) {
      html += `<div class="wa-msg-date-sep">${dateStr}</div>`;
      lastDate = dateStr;
    }

    const isOut = m.direction === 'outgoing';
    const cls = isOut ? 'wa-msg-outgoing' : 'wa-msg-incoming';
    const time = d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
    const sender = !isOut && m.profileName ? `<div class="wa-msg-sender">${esc(m.profileName)}</div>` : '';
    const sentBy = isOut && m.sentBy ? `<div class="wa-msg-sender">${esc(m.sentBy)}</div>` : '';

    let mediaHtml = '';
    if (m.media && m.media.length > 0) {
      m.media.forEach(med => {
        if (med.url && (med.contentType || '').startsWith('image')) {
          mediaHtml += `<div class="wa-msg-media"><img src="${esc(med.url)}" onclick="window.open('${esc(med.url)}','_blank')"></div>`;
        } else if (med.url) {
          mediaHtml += `<div class="wa-msg-media"><a href="${esc(med.url)}" target="_blank"> Anhang</a></div>`;
        }
      });
    }

    html += `<div class="wa-msg ${cls}">
      ${sender}${sentBy}
      ${mediaHtml}
      <div>${escNl(m.body || '')}</div>
      <div class="wa-msg-time">${time}</div>
    </div>`;
  });

  el.innerHTML = html;
  // Zum Ende scrollen
  el.scrollTop = el.scrollHeight;
}

function escNl(str) {
  return esc(str).replace(/\n/g, '<br>');
}

// -- Nachricht senden -----------------------------------------
async function sendWaMessage() {
  const input = document.getElementById('waMessageInput');
  const message = (input?.value || '').trim();
  if (!message || !waSelectedPhone) return;

  input.value = '';
  input.style.height = 'auto';

  try {
    const r = await fetch('whatsapp_api.php?action=send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: waSelectedPhone,
        message,
        baustelle: getWaSelectedBaustelleId()
      })
    });
    const j = await r.json();
    if (j.error) {
      showNotification('' + j.error, 'error');
      return;
    }
    // Nachricht zur lokalen Liste hinzufügen
    waMessages.push(j.message);
    renderWaChat();
    showNotification('Nachricht gesendet');
  } catch (e) {
    showNotification('Nachricht konnte nicht gesendet werden', 'error');
  }
}

function waInputKeydown(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendWaMessage();
  }
  // Auto-Resize
  const ta = e.target;
  setTimeout(() => {
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight, 120) + 'px';
  }, 0);
}

