// BAUSTELLEN-ZUORDNUNG
// --------------------------------------------------------------

function populateWaBaustellenSelect(wrapperId, selectedValue) {
  const wrap = document.getElementById(wrapperId);
  if (!wrap) return;
  wrap.innerHTML = bsDdHtml(wrapperId, { selected: selectedValue || '', placeholder: 'Baustelle suchen...', allowEmpty: true, emptyLabel: '-- Baustelle zuordnen --', onchange() { if (wrapperId === 'waChatBaustelleWrap') assignWaBaustelle(); }, inputStyle: 'font-size:.8rem;padding:4px 10px' });
}

function getWaSelectedBaustelleId() {
  return bsDdGetValue('waChatBaustelleWrap') || null;
}

async function assignWaBaustelle() {
  if (!waSelectedPhone) return;
  const baustelleId = getWaSelectedBaustelleId();
  try {
    await fetch('whatsapp_api.php?action=assign_baustelle', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: waSelectedPhone, baustelle: baustelleId || null })
    });
    // Lokalen Kontakt aktualisieren
    const c = waContacts.find(c => c.phone === waSelectedPhone);
    if (c) c.baustelle = baustelleId || null;
    showNotification('Baustelle zugeordnet');
  } catch (e) {
    showNotification('Zuordnung fehlgeschlagen', 'error');
  }
}

async function updateWaContactZuordnung() {
  if (!waSelectedPhone) return;
  const zuordnung = document.getElementById('waChatZuordnung')?.value || '';
  try {
    await fetch('whatsapp_api.php?action=save_contact', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: waSelectedPhone, zuordnung })
    });
    const c = waContacts.find(c => c.phone === waSelectedPhone);
    if (c) c.zuordnung = zuordnung;
    renderWaContacts();
  } catch (e) {}
}

