function openMetallzuschlagModal() {
  show('metallzuschlagModal');
  loadMetallzuschlagSettings();
}
function closeMetallzuschlagModal() { hide('metallzuschlagModal'); }

async function loadMetallzuschlagSettings() {
  try {
    const r = await fetch('api.php?action=metallzuschlag_get');
    const j = await r.json();
    const delInput = document.getElementById('mzDelNotierung');
    const info = document.getElementById('mzCurrentInfo');
    if (j && j.delNotierung > 0) {
      if (delInput) delInput.value = j.delNotierung;
      _currentMetallzuschlag = j;
      if (info) {
        info.innerHTML = `<div style="padding:8px 12px;background:#FFF8E1;border:1px solid #FFE082;border-radius:6px;font-size:.82rem;">
          <strong>Aktiv:</strong> DEL ${fmt(j.delNotierung)}/100 kg Cu
          <span style="color:var(--grey-500);margin-left:8px">${mzStandText(j)}</span>
        </div>${mzVeraltetHinweis(j)}`;
      }
    } else {
      if (info) info.innerHTML = '<span style="color:var(--grey-400)">Noch kein Wert hinterlegt - wird bei Katalogsuche automatisch abgerufen.</span>';
    }
  } catch(e) { console.warn('MZ settings load:', e); }
}

/** Manually trigger auto-fetch of DEL copper price */
async function autoFetchDel() {
  const info = document.getElementById('mzCurrentInfo');
  if (info) info.innerHTML = '<div style="padding:8px 12px;font-size:.82rem;color:var(--grey-500);"> Rufe tagesaktuelle DEL-Notierung ab...</div>';
  try {
    const r = await fetch('api.php?action=metallzuschlag_auto_fetch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ force: 1 })
    });
    const j = await r.json();
    if (!r.ok || j.error) {
      showNotification('Fehler: ' + (j.error || 'Abruf nicht möglich'), 'error');
      loadMetallzuschlagSettings();
    } else if (j.fetchError) {
      showNotification('Automatischer Abruf fehlgeschlagen - ' + (j.delNotierung > 0 ? 'letzter Wert bleibt aktiv' : 'bitte manuell eingeben'), 'warning');
      loadMetallzuschlagSettings();
    } else if (j.delNotierung > 0) {
      _currentMetallzuschlag = j;
      const delInput = document.getElementById('mzDelNotierung');
      if (delInput) delInput.value = j.delNotierung;
      showNotification('DEL-Notierung automatisch abgerufen: ' + fmt(j.delNotierung) + '/100 kg');
      loadMetallzuschlagSettings();
    } else {
      showNotification('Automatischer Abruf fehlgeschlagen - bitte manuell eingeben', 'warning');
      loadMetallzuschlagSettings();
    }
  } catch(e) {
    showNotification('Fehler beim automatischen Abruf', 'error');
    loadMetallzuschlagSettings();
  }
}

async function saveMetallzuschlag() {
  const del = parseFloat(document.getElementById('mzDelNotierung')?.value) || 0;
  if (del <= 0) { showNotification('Bitte DEL-Notierung eingeben', 'warning'); return; }
  try {
    const r = await fetch('api.php?action=metallzuschlag_set', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ delNotierung: del, basisNotierung: 0 })
    });
    const j = await r.json();
    if (j.ok) {
      _currentMetallzuschlag = j;
      showNotification('Metallzuschlag gespeichert - DEL ' + fmt(del) + ' €/100kg');
      loadMetallzuschlagSettings();
    } else {
      showNotification('Fehler: ' + (j.error || 'Unbekannt'), 'error');
    }
  } catch(e) {
    showNotification('Fehler beim Speichern', 'error');
  }
}

// -- QR-Code laden --------------------------------------------
async function refreshWaQr() {
  const el = document.getElementById('waQrCode');
  if (!el) return;
  el.innerHTML = '<p style="color:var(--grey-400);font-size:0.85rem">Lade QR-Code...</p>';

  try {
    const r = await fetch('whatsapp_api.php?action=qr');
    const j = await r.json();

    if (j.status === 'ready') {
      el.innerHTML = '<p style="color:var(--success);font-size:1rem"> Bereits verbunden!</p>';
      document.getElementById('waQrSection').style.display = 'none';
      // Status neu laden
      openWaSettings();
      return;
    }

    if (j.qr) {
      el.innerHTML = `<img src="${j.qr}" alt="WhatsApp QR-Code" style="width:250px;height:250px;border-radius:8px;border:2px solid var(--grey-200)">`;
      // Auto-Refresh alle 20 Sekunden
      setTimeout(() => {
        if (document.getElementById('waSettingsModal')?.classList.contains('hidden')) return;
        refreshWaQr();
      }, 20000);
    } else {
      el.innerHTML = `<p style="color:var(--grey-400);font-size:0.85rem">${esc(j.message || 'Bitte warten, QR-Code wird generiert...')}</p>`;
      // Retry nach 3 Sekunden
      setTimeout(() => {
        if (document.getElementById('waSettingsModal')?.classList.contains('hidden')) return;
        refreshWaQr();
      }, 3000);
    }
  } catch (e) {
    el.innerHTML = '<p style="color:var(--danger)"> Bridge nicht erreichbar</p>';
  }
}

// -- Verbindung testen ----------------------------------------
async function testWaConnection() {
  const el = document.getElementById('waTestResult');
  if (el) el.innerHTML = '<p style="color:var(--grey-400)">Teste Verbindung—</p>';

  try {
    const r = await fetch('whatsapp_api.php?action=test_connection');
    const j = await r.json();
    if (el) {
      if (j.connected || j.status === 'ready') {
        el.innerHTML = `<p style="color:var(--success)"> WhatsApp verbunden! Nummer: ${esc(j.number || 'unbekannt')}${j.name ? ' (' + esc(j.name) + ')' : ''}</p>`;
      } else if (j.status === 'qr') {
        el.innerHTML = `<p style="color:#E6A700"> Warte auf QR-Code-Scan. Bitte QR-Code oben scannen.</p>`;
      } else if (j.error) {
        el.innerHTML = `<p style="color:var(--danger)"> ${esc(j.error)}</p>`;
      } else {
        el.innerHTML = `<p style="color:#E6A700"> Status: ${esc(j.status || 'unbekannt')}. Bridge läuft, aber WhatsApp noch nicht verbunden.</p>`;
      }
    }
  } catch (e) {
    if (el) el.innerHTML = `<p style="color:var(--danger)"> Bridge nicht erreichbar. Ist der Node.js-Service gestartet?</p>`;
  }
}

// -- WhatsApp trennen -----------------------------------------
async function logoutWa() {
  if (!confirm('WhatsApp-Verkn—pfung wirklich trennen? Du musst danach erneut den QR-Code scannen.')) return;
  try {
    const r = await fetch('whatsapp_api.php?action=logout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}'
    });
    const j = await r.json();
    showNotification(j.ok ? 'WhatsApp getrennt' : '' + (j.error || 'Fehler'));
    openWaSettings(); // Status neu laden
  } catch (e) {
    showNotification('Fehler beim Trennen', 'error');
  }
}

// -- Bridge neu starten ---------------------------------------
async function restartWaBridge() {
  try {
    const r = await fetch('whatsapp_api.php?action=restart', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}'
    });
    const j = await r.json();
    showNotification(j.ok ? 'Bridge wird neu gestartet...' : '' + (j.error || 'Fehler'));
    setTimeout(() => openWaSettings(), 3000);
  } catch (e) {
    showNotification('Bridge nicht erreichbar', 'error');
  }
}

function renderWaTemplateSettings() {
  const el = document.getElementById('waTemplatesList');
  if (!el) return;
  if (waTemplates.length === 0) {
    el.innerHTML = '<p style="color:var(--grey-400);font-size:0.85rem">Keine Vorlagen vorhanden.</p>';
    return;
  }
  el.innerHTML = waTemplates.map(t => `
    <div class="wa-tpl-item">
      <span class="wa-tpl-item-name">${esc(t.name)}</span>
      <span class="wa-tpl-item-text">${esc(t.text)}</span>
      <button class="btn btn-danger btn-sm" onclick="deleteWaTemplate('${esc(t.name)}')" title="Löschen">${ico('trash')}</button>
    </div>
  `).join('');
}

async function saveWaTemplate() {
  const name = document.getElementById('waNewTplName')?.value.trim();
  const text = document.getElementById('waNewTplText')?.value.trim();
  if (!name || !text) {
    showNotification('Name und Text erforderlich', 'error');
    return;
  }
  try {
    await fetch('whatsapp_api.php?action=save_template', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, text })
    });
    document.getElementById('waNewTplName').value = '';
    document.getElementById('waNewTplText').value = '';
    await loadWaTemplates();
    renderWaTemplateSettings();
    renderWaTemplateChips();
    showNotification('Vorlage gespeichert');
  } catch (e) {
    showNotification('Fehler beim Speichern', 'error');
  }
}

async function deleteWaTemplate(name) {
  confirmDelete(`Vorlage "${name}" wirklich löschen?`, async () => {
    try {
      await fetch('whatsapp_api.php?action=delete_template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name })
      });
      await loadWaTemplates();
      renderWaTemplateSettings();
      renderWaTemplateChips();
    } catch (e) {}
  });
}

// ============================================================
// HEADER DROPDOWN MENUS
// ============================================================
function toggleHeaderDropdown(id) {
  const menu = document.getElementById(id);
  if (!menu) return;
  const dd = menu.closest('.header-dropdown');
  const wasOpen = dd.classList.contains('open');
  closeAllDropdowns();
  if (!wasOpen) dd.classList.add('open');
}

function closeAllDropdowns() {
  document.querySelectorAll('.header-dropdown.open').forEach(d => d.classList.remove('open'));
}

// Klick außerhalb schließt Dropdown
document.addEventListener('click', e => {
  if (!e.target.closest('.header-dropdown')) closeAllDropdowns();
});

// ============================================================
// SCHNELLNOTIZEN PER BAUSTELLE (im Detail-View)
// ============================================================
async function loadBaustelleSchnellnotizen(baustelleId) {
  const el = document.getElementById('baustelleSchnellnotizen');
  if (!el) return;
  try {
    const r = await fetch('api.php?action=load_schnellnotizen&baustelleId=' + encodeURIComponent(baustelleId));
    const j = await r.json();
    if (!j.ok) { el.innerHTML = '<p class="hint-text" style="padding:16px;text-align:center">Fehler beim Laden.</p>'; return; }
    const notes = j.notes || [];
    renderBaustelleSchnellnotizen(el, notes, baustelleId);
  } catch(e) {
    el.innerHTML = '<p class="hint-text" style="padding:16px;text-align:center">Fehler beim Laden.</p>';
  }
}

function renderBaustelleSchnellnotizen(el, notes, baustelleId) {
  const active = notes.filter(n => !n.archiviert).sort((a,b) => (b.datum||'').localeCompare(a.datum||''));
  const archived = notes.filter(n => n.archiviert).sort((a,b) => (b.archiviertAm||b.datum||'').localeCompare(a.archiviertAm||a.datum||''));
  const isAdmin = (currentRole === 'admin' || currentRole === 'master');

  if (active.length === 0 && archived.length === 0) {
    el.innerHTML = '<p class="hint-text" style="padding:16px;text-align:center">Keine Schnellnotizen für diese Baustelle.</p>';
    return;
  }

  let html = '';
  active.forEach(n => {
    const datum = n.datum ? new Date(n.datum).toLocaleString('de-DE', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
    html += `<div class="schnellnotiz-card">
      <div class="schnellnotiz-card-header">
        <div class="sn-meta">
          <span>${datum}</span>
          <span>${esc(n.ersteller || '')}${n.kuerzel ? ' (' + esc(n.kuerzel) + ')' : ''}</span>
        </div>
      </div>
      <div class="sn-text">${esc(n.text)}</div>
      <div class="sn-actions">
        ${isAdmin ? `<button class="btn btn-sm btn-secondary" onclick="archiveBaustelleSchnellnotiz(${n.id},${baustelleId})">Archivieren</button>` : ''}
        ${isAdmin ? `<button class="btn btn-sm btn-secondary" style="color:var(--danger)" onclick="deleteBaustelleSchnellnotiz(${n.id},${baustelleId})">Löschen</button>` : ''}
      </div>
    </div>`;
  });

  if (archived.length > 0) {
    html += `<div style="margin-top:12px">
      <h4 style="font-size:0.85rem;color:var(--grey-400);cursor:pointer" onclick="this.nextElementSibling.classList.toggle('hidden')"> Archiv (${archived.length})</h4>
      <div class="hidden">`;
    archived.forEach(n => {
      const datum = n.datum ? new Date(n.datum).toLocaleString('de-DE', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
      html += `<div class="schnellnotiz-card archived">
        <div class="schnellnotiz-card-header">
          <div class="sn-meta"><span>${datum}</span><span>${esc(n.ersteller || '')}</span></div>
        </div>
        <div class="sn-text">${esc(n.text)}</div>
        <div class="sn-actions">
          ${isAdmin ? `<button class="btn btn-sm btn-secondary" style="color:var(--danger)" onclick="deleteBaustelleSchnellnotiz(${n.id},${baustelleId})">Löschen</button>` : ''}
        </div>
      </div>`;
    });
    html += '</div></div>';
  }

  el.innerHTML = html;
}

// -- Schnellnotiz Desktop Modal --------------------------------
function openSchnellnotizDesktopModal(prefillBaustelleId) {
  const preselect = prefillBaustelleId || (selectedId || '');
  const isAdmin   = (currentRole === 'admin' || currentRole === 'master');

  // Zuweisungs-Optionen für Admin/Master vorbereiten
  let zuweisenHtml = '';
  if (isAdmin) {
    const alleOpt = `<option value="">– Niemanden –</option><option value="alle">📢 Alle Mitarbeiter</option>`;
    const gruppenOpts = (gruppenData || []).map(g =>
      `<option value="gruppe:${g.id}">${esc(g.name)}</option>`
    ).join('');
    const gruppenGroup = gruppenOpts ? `<optgroup label="👥 Gruppen">${gruppenOpts}</optgroup>` : '';
    zuweisenHtml = `
    <div style="margin-bottom:12px">
      <label style="font-size:.82rem;font-weight:600;color:var(--grey-600);display:block;margin-bottom:4px">Zuweisen an</label>
      <select id="snDesktopZugewiesen" class="form-control" style="width:100%">
        ${alleOpt}${gruppenGroup}
      </select>
    </div>`;
  }

  const overlay = document.createElement('div');
  overlay.className = 'kunde-form-overlay';
  overlay.id = 'schnellnotizDesktopOverlay';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `<div class="kunde-form-card" style="max-width:520px">
    <h3> Schnellnotiz</h3>
    <div style="margin-bottom:12px">
      <label style="font-size:.82rem;font-weight:600;color:var(--grey-600);display:block;margin-bottom:4px">Baustelle (optional)</label>
      ${bsDdHtml('snDesktopBaustelle', { selected: preselect, placeholder: 'Baustelle suchen...', allowEmpty: true, emptyLabel: '— Ohne Zuordnung —' })}
    </div>
    ${zuweisenHtml}
    <div style="margin-bottom:12px">
      <label style="font-size:.82rem;font-weight:600;color:var(--grey-600);display:block;margin-bottom:4px">Notiz</label>
      <textarea id="snDesktopText" class="form-control" rows="5" placeholder="Notiz eingeben..." style="width:100%;resize:vertical;padding:8px"></textarea>
    </div>
    <div class="kunde-form-actions">
      <button class="btn btn-ghost btn-sm" onclick="document.getElementById('schnellnotizDesktopOverlay')?.remove()">Abbrechen</button>
      <button class="btn btn-primary btn-sm" onclick="saveSchnellnotizDesktop()">Speichern</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => document.getElementById('snDesktopText')?.focus(), 100);

  // Benutzer-Optionen für Admin/Master nachladen
  if (isAdmin) {
    fetch('api.php?action=list_users').then(r => r.json()).then(j => {
      const sel = document.getElementById('snDesktopZugewiesen');
      if (!sel || !j.ok) return;
      const grp = document.createElement('optgroup');
      grp.label = '👤 Benutzer';
      (j.users || []).forEach(u => {
        const opt = document.createElement('option');
        opt.value = u.username;
        opt.textContent = u.username + (u.kuerzel ? ' (' + u.kuerzel + ')' : '');
        grp.appendChild(opt);
      });
      // Vor bestehende Gruppen-Optgroup einfügen
      const existingGroup = sel.querySelector('optgroup[label="👥 Gruppen"]');
      if (existingGroup) sel.insertBefore(grp, existingGroup);
      else sel.appendChild(grp);
    }).catch(() => {});
  }
}

async function saveSchnellnotizDesktop() {
  const text = document.getElementById('snDesktopText')?.value.trim();
  if (!text) { showNotification('Bitte Notiz eingeben.', 'error'); return; }
  const baustelleId    = parseInt(bsDdGetValue('snDesktopBaustelle')) || null;
  const b              = baustelleId ? appData.baustellen.find(x => x.id === baustelleId) : null;
  const zugewiesen_an  = document.getElementById('snDesktopZugewiesen')?.value || '';
  try {
    const r = await fetch('api.php?action=save_schnellnotiz', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, baustelleId: baustelleId, baustelleName: b ? b.name : '', zugewiesen_an })
    });
    const j = await r.json();
    if (j.ok) {
      showNotification('Schnellnotiz gespeichert!', 'success');
      document.getElementById('schnellnotizDesktopOverlay')?.remove();
      // Update badge + reload if views open
      fetch('api.php?action=load_schnellnotizen').then(r2=>r2.json()).then(j2=>{
        if(j2.ok){schnellnotizenData=j2.notes||[];updateSchnellnotizBadge();
          if(document.getElementById('schnellnotizenView')&&!document.getElementById('schnellnotizenView').classList.contains('hidden'))renderSchnellnotizenDesktop();
        }
      }).catch(()=>{});
      if (baustelleId && selectedId === baustelleId) loadBaustelleSchnellnotizen(baustelleId);
    } else {
      showNotification(j.error || 'Fehler beim Speichern.', 'error');
    }
  } catch(e) { showNotification('Netzwerkfehler: ' + e.message, 'error'); }
}

function addSchnellnotizForBaustelle() {
  const b = getBaustelle();
  if (!b) return;
  openSchnellnotizDesktopModal(b.id);
}

async function archiveBaustelleSchnellnotiz(noteId, baustelleId) {
  try {
    await fetch('api.php?action=archive_schnellnotiz', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: noteId })
    });
    loadBaustelleSchnellnotizen(baustelleId);
    // Update global data
    fetch('api.php?action=load_schnellnotizen').then(r=>r.json()).then(j=>{
      if(j.ok){schnellnotizenData=j.notes||[];updateSchnellnotizBadge();if(document.getElementById('schnellnotizenView')&&!document.getElementById('schnellnotizenView').classList.contains('hidden'))renderSchnellnotizenDesktop();}
    }).catch(()=>{});
  } catch(e) { console.warn(e); }
}

async function deleteBaustelleSchnellnotiz(noteId, baustelleId) {
  if (!confirm('Notiz wirklich löschen?')) return;
  try {
    await fetch('api.php?action=delete_schnellnotiz', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: noteId })
    });
    loadBaustelleSchnellnotizen(baustelleId);
    fetch('api.php?action=load_schnellnotizen').then(r=>r.json()).then(j=>{
      if(j.ok){schnellnotizenData=j.notes||[];updateSchnellnotizBadge();if(document.getElementById('schnellnotizenView')&&!document.getElementById('schnellnotizenView').classList.contains('hidden'))renderSchnellnotizenDesktop();}
    }).catch(()=>{});
  } catch(e) { console.warn(e); }
}

// ============================================================
// SCHNELLNOTIZEN (Desktop - Admin/Master Reiter)
// ============================================================
let schnellnotizenData = [];
let gruppenData = [];  // v2.10.0: Gruppen für aktuellen User

function showSchnellnotizen() {
  selectedId = null;
  document.getElementById('btnSchnellnotizenSidebar')?.classList.add('active');
  document.getElementById('btnUebersicht')?.classList.remove('active');
  document.getElementById('btnMaterialKatalog')?.classList.remove('active');
  document.getElementById('btnStundenKatalog')?.classList.remove('active');
  document.getElementById('btnOffenesMaterial')?.classList.remove('active');
  document.getElementById('btnWhatsApp')?.classList.remove('active');
  document.getElementById('btnKundenstamm')?.classList.remove('active');
  renderSidebar();
  hide('emptyState');
  hide('baustelleDetail');
  hide('uebersichtView');
  hide('materialKatalogView');
  hide('stundenKatalogView');
  hide('offenesMaterialView');
  hide('whatsappView');
  hide('kundenstammView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('dashboardView'); hide('vde0100View');
  show('schnellnotizenView');
  loadSchnellnotizenDesktop();
}

async function loadSchnellnotizenDesktop() {
  try {
    const r = await fetch('api.php?action=load_schnellnotizen');
    const j = await r.json();
    if (j.ok) schnellnotizenData = j.notes || [];
  } catch (e) { console.warn('Schnellnotizen laden fehlgeschlagen:', e); }

  // Baustellen-Dropdown füllen (searchable)
  const snWrap = document.getElementById('snFilterBaustelleWrap');
  if (snWrap && !document.getElementById('bsDd_snFilterBaustelle')) {
    snWrap.innerHTML = bsDdHtml('snFilterBaustelle', { selected: '', placeholder: 'Alle Baustellen', allowEmpty: true, emptyLabel: 'Alle Baustellen', onchange() { renderSchnellnotizenDesktop(); }, inputStyle: 'font-size:.82rem;padding:4px 10px' });
  }
  renderSchnellnotizenDesktop();
  updateSchnellnotizBadge();
}

function renderSchnellnotizenDesktop() {
  const list = document.getElementById('schnellnotizenList');
  const archiv = document.getElementById('schnellnotizenArchiv');
  if (!list || !archiv) return;

  const filterBau = bsDdGetValue('snFilterBaustelle') || '';
  const active = schnellnotizenData.filter(n => !n.archiviert);
  const archived = schnellnotizenData.filter(n => n.archiviert);

  const filteredActive = filterBau
    ? active.filter(n => String(n.baustelleId) === filterBau)
    : active;
  const filteredArchived = filterBau
    ? archived.filter(n => String(n.baustelleId) === filterBau)
    : archived;

  if (filteredActive.length === 0) {
    list.innerHTML = '<div style="text-align:center;color:var(--grey-400);padding:32px 0">Keine offenen Schnellnotizen.</div>';
  } else {
    list.innerHTML = filteredActive
      .sort((a, b) => (b.datum || '').localeCompare(a.datum || ''))
      .map(n => renderSchnellnotizCard(n, false)).join('');
  }

  document.getElementById('snArchivCount').textContent = `(${filteredArchived.length})`;
  if (filteredArchived.length === 0) {
    archiv.innerHTML = '<div style="text-align:center;color:var(--grey-400);padding:16px 0;font-size:0.85rem">Archiv leer.</div>';
  } else {
    archiv.innerHTML = filteredArchived
      .sort((a, b) => (b.archiviertAm || b.datum || '').localeCompare(a.archiviertAm || a.datum || ''))
      .map(n => renderSchnellnotizCard(n, true)).join('');
  }
}

function renderSchnellnotizCard(n, isArchived) {
  const datum = n.datum ? new Date(n.datum).toLocaleString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
  const zuweisungLabel = n.zugewiesen_an ? resolveZuweisung(n.zugewiesen_an) : '';
  const zuweisungBadge = zuweisungLabel
    ? `<span style="display:inline-block;font-size:.7rem;background:#ede9fe;color:#5b21b6;border-radius:4px;padding:1px 6px;margin-top:4px">${esc(zuweisungLabel)}</span>`
    : '';
  return `<div class="schnellnotiz-card${isArchived ? ' archived' : ''}">
    <div class="schnellnotiz-card-header">
      ${n.baustelleName ? `<span class="sn-baustelle">${esc(n.baustelleName)}</span>` : '<span class="sn-baustelle" style="background:var(--grey-100);color:var(--grey-400)">Ohne Zuordnung</span>'}
      <div class="sn-meta">
        <span>${datum}</span>
        <span>${esc(n.ersteller || '')}${n.kuerzel ? ' (' + esc(n.kuerzel) + ')' : ''}</span>
      </div>
    </div>
    <div class="sn-text">${esc(n.text)}</div>
    ${zuweisungBadge}
    <div class="sn-actions">
      ${!isArchived ? `<button class="btn btn-sm btn-secondary" onclick="archiveSchnellnotiz(${n.id})">Archivieren</button>` : ''}
      <button class="btn btn-sm btn-secondary" style="color:var(--danger)" onclick="deleteSchnellnotiz(${n.id})">Löschen</button>
    </div>
  </div>`;
}

function toggleSnArchiv() {
  const el = document.getElementById('schnellnotizenArchiv');
  if (el) el.classList.toggle('hidden');
}

async function archiveSchnellnotiz(id) {
  try {
    await fetch('api.php?action=archive_schnellnotiz', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id })
    });
    await loadSchnellnotizenDesktop();
  } catch (e) { console.warn(e); }
}

async function archiveAllSchnellnotizen() {
  if (!confirm('Alle offenen Schnellnotizen archivieren?')) return;
  try {
    await fetch('api.php?action=archive_all_schnellnotizen', { method: 'POST' });
    await loadSchnellnotizenDesktop();
  } catch (e) { console.warn(e); }
}

async function deleteSchnellnotiz(id) {
  if (!confirm('Notiz wirklich löschen?')) return;
  try {
    await fetch('api.php?action=delete_schnellnotiz', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id })
    });
    await loadSchnellnotizenDesktop();
  } catch (e) { console.warn(e); }
}

async function updateSchnellnotizBadge() {
  const active = schnellnotizenData.filter(n => !n.archiviert).length;
  const badge = document.getElementById('schnellnotizBadge');
  if (badge) {
    if (active > 0) { badge.textContent = active; badge.style.display = ''; }
    else { badge.style.display = 'none'; }
  }
}

// ============================================================
// TAGESBERICHT  -  daily report with customer signature
// ============================================================
let tbSignatureCanvas = null;
let tbSignatureCtx    = null;
let tbDrawing         = false;

function openTagesberichtModal() {
  const b = getBaustelle();
  if (!b) return;
  const today = new Date().toISOString().split('T')[0];
  // Sub-User-Cache für Tagesbericht laden
  fetch('api.php?action=list_users_basic').then(r=>r.json()).then(j=>{
    if(j.ok) window._subUserCache = j.users || [];
  }).catch(()=>{});

  // Build modal overlay
  let overlay = document.getElementById('tagesberichtOverlay');
  if (overlay) overlay.remove();
  overlay = document.createElement('div');
  overlay.id = 'tagesberichtOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9000;display:flex;align-items:center;justify-content:center;overflow:auto;padding:20px;';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };

  const modal = document.createElement('div');
  modal.style.cssText = 'background:#fff;border-radius:12px;max-width:860px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 12px 40px rgba(0,0,0,.3);';

  modal.innerHTML = `
    <div style="padding:20px 24px;border-bottom:1px solid #e0e0e0;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#00B4D8,#0096B7);color:#fff;border-radius:12px 12px 0 0;">
      <h2 style="margin:0;font-size:1.2rem;">${ico('file')} Tagesbericht erstellen</h2>
      <button onclick="document.getElementById('tagesberichtOverlay').remove()" style="background:none;border:none;color:#fff;font-size:1.5rem;cursor:pointer;line-height:1;">&times;</button>
    </div>
    <div style="padding:20px 24px;">
      <div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px;">
        <label style="font-weight:600;font-size:.9rem;">Von:</label>
        <input type="date" id="tbDatumVon" value="${today}" class="form-control" style="width:170px;font-size:.9rem;" onchange="renderTagesberichtPreview()">
        <label style="font-weight:600;font-size:.9rem;">Bis:</label>
        <input type="date" id="tbDatumBis" value="${today}" class="form-control" style="width:170px;font-size:.9rem;" onchange="renderTagesberichtPreview()">
        <button class="btn btn-secondary btn-sm" onclick="renderTagesberichtPreview()">Aktualisieren</button>
      </div>
      <div id="tbPreview" style="border:1px solid #ddd;border-radius:8px;padding:16px;background:#fafafa;max-height:400px;overflow-y:auto;font-size:13px;"></div>
      <div style="margin-top:20px;">
        <p style="font-weight:600;font-size:.9rem;margin-bottom:8px;">Unterschrift Auftraggeber:</p>
        <div style="position:relative;border:2px solid #ccc;border-radius:8px;background:#fff;">
          <canvas id="tbSignatureCanvas" width="500" height="160" style="display:block;width:100%;cursor:crosshair;touch-action:none;"></canvas>
          <button onclick="clearTbSignature()" style="position:absolute;top:6px;right:6px;background:#e74c3c;color:#fff;border:none;border-radius:4px;padding:2px 10px;font-size:.75rem;cursor:pointer;">Löschen</button>
        </div>
        <button onclick="openFullscreenSignature()" style="margin-top:8px;background:none;border:1px solid var(--primary,#00B4D8);color:var(--primary,#00B4D8);border-radius:6px;padding:6px 14px;font-size:.8rem;cursor:pointer;display:flex;align-items:center;gap:6px;"> Vollbild Querformat</button>
      </div>
      <div style="margin-top:16px;display:flex;gap:10px;justify-content:flex-end;">
        <button class="btn btn-secondary" onclick="exportTagesberichtPDF()">Als PDF</button>
        <button class="btn btn-secondary" onclick="printTagesbericht()">Drucken</button>
        <button class="btn btn-primary" onclick="saveTagesbericht()">Unterschreiben & Speichern</button>
      </div>
    </div>
  `;

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  // Init signature canvas
  tbSignatureCanvas = document.getElementById('tbSignatureCanvas');
  tbSignatureCtx    = tbSignatureCanvas.getContext('2d');
  tbSignatureCtx.lineWidth   = 2;
  tbSignatureCtx.lineCap     = 'round';
  tbSignatureCtx.strokeStyle = '#000';
  tbDrawing = false;
  initTbSignatureEvents();
  renderTagesberichtPreview();
}

function initTbSignatureEvents() {
  const c = tbSignatureCanvas;
  if (!c) return;

  function getPos(e) {
    const rect = c.getBoundingClientRect();
    const scaleX = c.width / rect.width;
    const scaleY = c.height / rect.height;
    const touch = e.touches ? e.touches[0] : e;
    return { x: (touch.clientX - rect.left) * scaleX, y: (touch.clientY - rect.top) * scaleY };
  }

  c.addEventListener('mousedown', e => {
    tbDrawing = true;
    const p = getPos(e);
    tbSignatureCtx.beginPath();
    tbSignatureCtx.moveTo(p.x, p.y);
  });
  c.addEventListener('mousemove', e => {
    if (!tbDrawing) return;
    const p = getPos(e);
    tbSignatureCtx.lineTo(p.x, p.y);
    tbSignatureCtx.stroke();
  });
  c.addEventListener('mouseup',   () => { tbDrawing = false; });
  c.addEventListener('mouseleave',() => { tbDrawing = false; });

  c.addEventListener('touchstart', e => {
    e.preventDefault();
    tbDrawing = true;
    const p = getPos(e);
    tbSignatureCtx.beginPath();
    tbSignatureCtx.moveTo(p.x, p.y);
  }, { passive: false });
  c.addEventListener('touchmove', e => {
    e.preventDefault();
    if (!tbDrawing) return;
    const p = getPos(e);
    tbSignatureCtx.lineTo(p.x, p.y);
    tbSignatureCtx.stroke();
  }, { passive: false });
  c.addEventListener('touchend', () => { tbDrawing = false; });
}

function clearTbSignature() {
  if (tbSignatureCtx && tbSignatureCanvas) {
    tbSignatureCtx.clearRect(0, 0, tbSignatureCanvas.width, tbSignatureCanvas.height);
  }
}

function openFullscreenSignature() {
  const fsOverlay = document.createElement('div');
  fsOverlay.id = 'fsSignatureOverlay';
  fsOverlay.style.cssText = 'position:fixed;inset:0;z-index:10000;background:#fff;display:flex;flex-direction:column;';
  fsOverlay.innerHTML = `
    <div style="padding:10px 16px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,var(--primary,#00B4D8),#0096B7);color:#fff;flex-shrink:0;">
      <span style="font-weight:600;font-size:1rem;"> Unterschrift Auftraggeber</span>
      <div style="display:flex;gap:8px;">
        <button id="fsSigClear" style="background:#e74c3c;color:#fff;border:none;border-radius:6px;padding:6px 16px;font-size:.85rem;cursor:pointer;">Löschen</button>
        <button id="fsSigDone" style="background:#27ae60;color:#fff;border:none;border-radius:6px;padding:6px 16px;font-size:.85rem;font-weight:600;cursor:pointer;"> Fertig</button>
      </div>
    </div>
    <div id="fsSigCanvasWrap" style="flex:1;position:relative;background:#fff;border-top:2px solid #e0e0e0;overflow:hidden;">
      <canvas id="fsSignatureCanvas" style="display:block;width:100%;height:100%;touch-action:none;cursor:crosshair;"></canvas>
    </div>
  `;
  document.body.appendChild(fsOverlay);

  // Try fullscreen + landscape lock
  (async () => {
    try { await fsOverlay.requestFullscreen(); } catch(e) {}
    try { if (screen.orientation && screen.orientation.lock) await screen.orientation.lock('landscape'); } catch(e) {}
  })();

  // Init canvas after layout
  requestAnimationFrame(() => {
    const canvas = document.getElementById('fsSignatureCanvas');
    const wrap = document.getElementById('fsSigCanvasWrap');
    if (!canvas || !wrap) return;
    const dpr = window.devicePixelRatio || 1;
    const rect = wrap.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#000';

    // Copy existing signature if present
    if (tbSignatureCanvas && !isTbSignatureEmpty()) {
      ctx.drawImage(tbSignatureCanvas, 0, 0, rect.width, rect.height);
    }

    let drawing = false;
    function getPos(e) {
      const r = canvas.getBoundingClientRect();
      const t = e.touches ? e.touches[0] : e;
      return { x: t.clientX - r.left, y: t.clientY - r.top };
    }
    canvas.addEventListener('mousedown', e => { drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('mousemove', e => { if (!drawing) return; const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); });
    canvas.addEventListener('mouseup', () => { drawing = false; });
    canvas.addEventListener('mouseleave', () => { drawing = false; });
    canvas.addEventListener('touchstart', e => { e.preventDefault(); drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }, { passive: false });
    canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!drawing) return; const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); }, { passive: false });
    canvas.addEventListener('touchend', () => { drawing = false; });
  });

  function closeFs() {
    const canvas = document.getElementById('fsSignatureCanvas');
    if (canvas && tbSignatureCtx && tbSignatureCanvas) {
      tbSignatureCtx.clearRect(0, 0, tbSignatureCanvas.width, tbSignatureCanvas.height);
      tbSignatureCtx.drawImage(canvas, 0, 0, tbSignatureCanvas.width, tbSignatureCanvas.height);
    }
    if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
    try { if (screen.orientation && screen.orientation.unlock) screen.orientation.unlock(); } catch(e) {}
    fsOverlay.remove();
  }

  document.getElementById('fsSigClear').onclick = () => {
    const canvas = document.getElementById('fsSignatureCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };
  document.getElementById('fsSigDone').onclick = closeFs;

  document.addEventListener('fullscreenchange', function handler() {
    if (!document.fullscreenElement && document.getElementById('fsSignatureOverlay')) {
      closeFs();
      document.removeEventListener('fullscreenchange', handler);
    }
  });
}

function isTbSignatureEmpty() {
  if (!tbSignatureCanvas) return true;
  const data = tbSignatureCtx.getImageData(0, 0, tbSignatureCanvas.width, tbSignatureCanvas.height).data;
  for (let i = 3; i < data.length; i += 4) { if (data[i] > 0) return false; }
  return true;
}

function renderTagesberichtPreview() {
  const b = getBaustelle();
  if (!b) return;
  const container = document.getElementById('tbPreview');
  if (!container) return;
  const today = new Date().toISOString().split('T')[0];
  const datumVon = document.getElementById('tbDatumVon')?.value || today;
  const datumBis = document.getElementById('tbDatumBis')?.value || today;
  container.innerHTML = buildTagesberichtHTML(b, datumVon, datumBis, true);
}

function buildTagesberichtHTML(b, datumVon, datumBis, editable) {
  const fmtDE = d => { if (!d) return ''; const p = d.split('-'); return p.length === 3 ? `${p[2]}.${p[1]}.${p[0]}` : d; };
  const fmtC  = v => (v || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const showPrices = canDo('canSeePrices');
  const isRange = datumVon !== datumBis;
  const inRange = d => d >= datumVon && d <= datumBis;

  const title = isRange ? 'Baubericht' : 'Tagesbericht';
  const zeitraum = isRange
    ? `Zeitraum: <strong>${fmtDE(datumVon)} - ${fmtDE(datumBis)}</strong>`
    : `Datum: <strong>${fmtDE(datumVon)}</strong>`;

  const tbLogoUrl = (typeof appSettings !== 'undefined' && appSettings.firma_logo_url) ? 'api.php?action=get_logo' : '';
  let html = `<div class="tb-header" style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;"><div><h1>${title} - ${esc(b.name)}</h1><p class="meta">${zeitraum} &nbsp;|&nbsp; Erstellt von: ${esc(currentKuerzel || currentUser || '—')}</p></div>${tbLogoUrl ? `<img src="${tbLogoUrl}" alt="Logo" class="tb-logo" style="width:240px;height:auto;flex-shrink:0;">` : ''}</div>`;

  // -- Bautagebuch --
  const tbEntries = (b.bautagebuch || []).filter(r => inRange(r.datum));
  html += '<h2>Bautagebuch</h2>';
  if (tbEntries.length === 0) {
    html += `<p class="empty-hint">Keine Einträge für ${isRange ? 'diesen Zeitraum' : 'diesen Tag'}.</p>`;
  } else if (editable) {
    tbEntries.forEach(r => {
      html += `<div style="margin-bottom:8px;padding:8px;border:1px solid #ddd;border-radius:6px;background:#fff;">`;
      html += `<div style="font-size:.8rem;color:#666;margin-bottom:4px;">${fmtDE(r.datum)} ${r.erstelltVon ? '(' + esc(r.erstelltVon) + ')' : ''}</div>`;
      html += `<textarea data-tb-id="${r.id}" rows="2" style="width:100%;border:1px solid #ccc;border-radius:4px;padding:6px;font-size:.9rem;resize:vertical;font-family:inherit;" oninput="updateTbEntry(${r.id},this.value)">${esc(r.eintrag)}</textarea>`;
      html += `</div>`;
    });
  } else {
    html += '<table><thead><tr><th style="width:120px">Datum</th><th>Eintrag</th><th style="width:60px">Von</th></tr></thead><tbody>';
    tbEntries.forEach(r => {
      html += `<tr><td>${fmtDE(r.datum)}</td><td>${esc(r.eintrag)}</td><td>${esc(r.erstelltVon || '')}</td></tr>`;
    });
    html += '</tbody></table>';
  }

  // -- Material --
  const matFiltered = (b.material || []).filter(r => inRange(r.datum));
  html += '<h2>Material</h2>';
  if (matFiltered.length === 0) {
    html += `<p class="empty-hint">Kein Material für ${isRange ? 'diesen Zeitraum' : 'diesen Tag'}.</p>`;
  } else {
    let matSum = 0;
    if (showPrices) {
      html += '<table><thead><tr><th>Bezeichnung</th><th style="width:60px">Menge</th><th style="width:60px">Einheit</th><th class="num" style="width:90px">VK (€)</th><th class="num" style="width:100px">Gesamt (€)</th></tr></thead><tbody>';
      matFiltered.forEach(r => {
        const vk = matVk(r, b);
        const ges = vk * r.anzahl;
        matSum += ges;
        html += `<tr><td>${esc(r.bezeichnung)}</td><td>${r.anzahl}</td><td>${esc(r.einheit)}</td><td class="num">${fmtC(vk)}</td><td class="num">${fmtC(ges)}</td></tr>`;
      });
      html += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;">Material Gesamt:</td><td class="num">${fmtC(matSum)} €</td></tr></tfoot></table>`;
    } else {
      html += '<table><thead><tr><th>Bezeichnung</th><th style="width:60px">Menge</th><th style="width:60px">Einheit</th></tr></thead><tbody>';
      matFiltered.forEach(r => {
        html += `<tr><td>${esc(r.bezeichnung)}</td><td>${r.anzahl}</td><td>${esc(r.einheit)}</td></tr>`;
      });
      html += '</tbody></table>';
    }
  }

  // -- Arbeitszeit --
  const azFiltered = (b.arbeitszeit || []).filter(r => inRange(r.datum));
  html += '<h2>Arbeitszeit</h2>';
  if (azFiltered.length === 0) {
    html += `<p class="empty-hint">Keine Arbeitszeiten für ${isRange ? 'diesen Zeitraum' : 'diesen Tag'}.</p>`;
  } else {
    let azSum = 0;
    if (showPrices) {
      html += '<table><thead><tr><th>Beschreibung</th><th style="width:80px">Datum</th><th class="num" style="width:70px">Stunden</th><th class="num" style="width:100px">Preis (€/h)</th><th class="num" style="width:100px">Gesamt (€)</th></tr></thead><tbody>';
      azFiltered.forEach(r => {
        const ges = r.stunden * r.stundenpreis;
        azSum += ges;
        html += `<tr><td>${esc(r.beschreibung)}</td><td>${fmtDE(r.datum)}</td><td class="num">${r.stunden}</td><td class="num">${fmtC(r.stundenpreis)}</td><td class="num">${fmtC(ges)}</td></tr>`;
      });
      html += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;">Arbeitszeit Gesamt:</td><td class="num">${fmtC(azSum)} €</td></tr></tfoot></table>`;
    } else {
      html += '<table><thead><tr><th>Beschreibung</th><th style="width:80px">Datum</th><th class="num" style="width:70px">Stunden</th></tr></thead><tbody>';
      azFiltered.forEach(r => {
        html += `<tr><td>${esc(r.beschreibung)}</td><td>${fmtDE(r.datum)}</td><td class="num">${r.stunden}</td></tr>`;
      });
      html += '</tbody></table>';
    }
  }

  // -- Pauschalen --
  html += '<h2>Pauschalen</h2>';
  const activePausch = (b.pauschalen || []).map(entry => {
    const pid = typeof entry === 'object' ? entry.id : entry;
    const anz = typeof entry === 'object' ? (entry.anzahl || 1) : 1;
    const datum = typeof entry === 'object' ? (entry.datum || '') : '';
    const p = appData.pauschalen.find(p => p.id === pid);
    if (!p) return null;
    return { ...p, anzahl: anz, datum };
  }).filter(Boolean).filter(p => !p.datum || inRange(p.datum));
  if (activePausch.length === 0) {
    html += '<p class="empty-hint">Keine aktiven Pauschalen.</p>';
  } else if (showPrices) {
    let pSum = 0;
    html += '<table><thead><tr><th>Bezeichnung</th><th style="width:80px">Datum</th><th class="num" style="width:60px">Anzahl</th><th class="num" style="width:120px">Betrag (€)</th></tr></thead><tbody>';
    activePausch.forEach(p => {
      const g = p.preis * p.anzahl;
      pSum += g;
      html += `<tr><td>${esc(p.name)}</td><td>${fmtDE(p.datum)}</td><td class="num">${p.anzahl}</td><td class="num">${fmtC(g)}</td></tr>`;
    });
    html += `</tbody><tfoot><tr><td colspan="3" style="text-align:right;">Pauschalen Gesamt:</td><td class="num">${fmtC(pSum)} €</td></tr></tfoot></table>`;
  } else {
    html += '<table><thead><tr><th>Bezeichnung</th><th style="width:80px">Datum</th><th class="num" style="width:60px">Anzahl</th></tr></thead><tbody>';
    activePausch.forEach(p => {
      html += `<tr><td>${esc(p.name)}</td><td>${fmtDE(p.datum)}</td><td class="num">${p.anzahl}</td></tr>`;
    });
    html += '</tbody></table>';
  }

  // -- Subunternehmer-Zwischenebene --
  // Sammle alle Material/Arbeitszeit-Einträge, die von Subunternehmer-Usern erstellt wurden
  const subKuerzelSet = new Set();
  const subKuerzelDl  = {}; // kuerzel => Firmenname
  if (window._subUserCache) {
    window._subUserCache.forEach(u => {
      if (u.isSubunternehmer && u.kuerzel) {
        subKuerzelSet.add(u.kuerzel);
        const dl = dienstleisterData.find(d => d.id === u.dienstleisterId);
        subKuerzelDl[u.kuerzel] = dl ? dl.firma : 'Subunternehmer';
      }
    });
  }
  const subMatFiltered = matFiltered.filter(r => subKuerzelSet.has(r.erstelltVon));
  const subAzFiltered  = azFiltered.filter(r => subKuerzelSet.has(r.erstelltVon));
  if (subMatFiltered.length > 0 || subAzFiltered.length > 0) {
    html += '<h2 style="color:#7B1FA2;border-bottom:2px solid #9C27B0;padding-bottom:4px"> Subunternehmer-Leistungen</h2>';
    // Gruppiere nach Firma
    const subGroups = {};
    [...subMatFiltered, ...subAzFiltered].forEach(r => {
      const firma = subKuerzelDl[r.erstelltVon] || 'Subunternehmer';
      if (!subGroups[firma]) subGroups[firma] = { material: [], arbeitszeit: [] };
    });
    subMatFiltered.forEach(r => {
      const firma = subKuerzelDl[r.erstelltVon] || 'Subunternehmer';
      subGroups[firma].material.push(r);
    });
    subAzFiltered.forEach(r => {
      const firma = subKuerzelDl[r.erstelltVon] || 'Subunternehmer';
      subGroups[firma].arbeitszeit.push(r);
    });
    Object.entries(subGroups).forEach(([firma, data]) => {
      html += `<h3 style="color:#7B1FA2;font-size:14px;margin-top:12px"> ${esc(firma)}</h3>`;
      if (data.material.length > 0) {
        html += '<p style="font-size:13px;font-weight:600;margin:8px 0 4px">Material:</p>';
        html += '<table><thead><tr><th>Bezeichnung</th><th style="width:60px">Menge</th><th style="width:60px">Einheit</th><th style="width:80px">Datum</th></tr></thead><tbody>';
        data.material.forEach(r => {
          html += `<tr><td>${esc(r.bezeichnung)}</td><td>${r.anzahl}</td><td>${esc(r.einheit || '')}</td><td>${fmtDE(r.datum)}</td></tr>`;
        });
        html += '</tbody></table>';
      }
      if (data.arbeitszeit.length > 0) {
        let subAzSum = 0;
        html += '<p style="font-size:13px;font-weight:600;margin:8px 0 4px">Arbeitszeit:</p>';
        if (showPrices) {
          html += '<table><thead><tr><th>Beschreibung</th><th style="width:80px">Datum</th><th class="num" style="width:70px">Stunden</th><th class="num" style="width:100px">Preis (€/h)</th><th class="num" style="width:100px">Gesamt (€)</th></tr></thead><tbody>';
          data.arbeitszeit.forEach(r => {
            const ges = r.stunden * r.stundenpreis;
            subAzSum += ges;
            html += `<tr><td>${esc(r.beschreibung)}</td><td>${fmtDE(r.datum)}</td><td class="num">${r.stunden}</td><td class="num">${fmtC(r.stundenpreis)}</td><td class="num">${fmtC(ges)}</td></tr>`;
          });
          html += `</tbody><tfoot><tr><td colspan="4" style="text-align:right;">Sub-Gesamt:</td><td class="num">${fmtC(subAzSum)} €</td></tr></tfoot></table>`;
        } else {
          html += '<table><thead><tr><th>Beschreibung</th><th style="width:80px">Datum</th><th class="num" style="width:70px">Stunden</th></tr></thead><tbody>';
          data.arbeitszeit.forEach(r => {
            html += `<tr><td>${esc(r.beschreibung)}</td><td>${fmtDE(r.datum)}</td><td class="num">${r.stunden}</td></tr>`;
          });
          html += '</tbody></table>';
        }
      }
    });
  }

  return html;
}

function updateTbEntry(id, val) {
  const b = getBaustelle();
  if (!b) return;
  const r = (b.bautagebuch || []).find(r => r.id === id);
  if (r) { r.eintrag = val; saveData(); }
}

function printTagesbericht() {
  const b = getBaustelle();
  if (!b) return;
  const today = new Date().toISOString().split('T')[0];
  const datumVon = document.getElementById('tbDatumVon')?.value || today;
  const datumBis = document.getElementById('tbDatumBis')?.value || today;
  const isRange = datumVon !== datumBis;
  const fmtDE = d => { if (!d) return ''; const p = d.split('-'); return p.length === 3 ? `${p[2]}.${p[1]}.${p[0]}` : d; };
  const html = buildTagesberichtHTML(b, datumVon, datumBis);
  const sig = isTbSignatureEmpty() ? '' : tbSignatureCanvas.toDataURL('image/png');

  const printWin = window.open('', '_blank');
  printWin.document.write('<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><title>' + (isRange ? 'Baubericht' : 'Tagesbericht') + '</title>');
  printWin.document.write('<style>body{font-family:Arial,Helvetica,sans-serif;max-width:800px;margin:0 auto;padding:20px;color:#1a1a1a;font-size:14px;}');
  printWin.document.write('h1{font-size:20px;border-bottom:2px solid #00B4D8;padding-bottom:8px;color:#00B4D8;}');
  printWin.document.write('h2{font-size:16px;margin-top:24px;color:#333;border-bottom:1px solid #ddd;padding-bottom:4px;}');
  printWin.document.write('table{width:100%;border-collapse:collapse;margin:8px 0 16px;font-size:13px;}');
  printWin.document.write('th,td{border:1px solid #ccc;padding:6px 8px;text-align:left;}');
  printWin.document.write('th{background:#FDE8EC;font-weight:600;}');
  printWin.document.write('td.num,.num{text-align:right;}');
  printWin.document.write('tfoot td{font-weight:700;background:#FDE8EC;}');
  printWin.document.write('.empty-hint{color:#999;font-style:italic;padding:8px 0;}');
  printWin.document.write('.meta{color:#666;font-size:13px;margin-bottom:16px;}');
  printWin.document.write('.sig-block{margin-top:32px;border-top:1px solid #999;padding-top:16px;}');
  printWin.document.write('.sig-block img{max-width:340px;display:block;}');
  printWin.document.write('.sig-line{margin-top:8px;color:#666;font-size:12px;}');
  printWin.document.write('.tb-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;}');
  printWin.document.write('.tb-header h1{margin:0;}');
  printWin.document.write('.tb-logo{width:120px;height:auto;flex-shrink:0;}');
  printWin.document.write('</style></head><body>');
  printWin.document.write(html);
  if (sig) {
    const datumLabel = isRange ? fmtDE(datumVon) + ' - ' + fmtDE(datumBis) : fmtDE(datumVon);
    printWin.document.write('<div class="sig-block"><p style="font-weight:600;">Unterschrift Auftraggeber:</p>');
    printWin.document.write('<img src="' + sig + '" alt="Unterschrift">');
    printWin.document.write('<p class="sig-line">Datum: ' + datumLabel + ' | Digital unterschrieben</p></div>');
  }
  printWin.document.write('</body></html>');
  printWin.document.close();
  setTimeout(() => printWin.print(), 400);
}

function getTbPrintStyles() {
  return 'body{font-family:Arial,Helvetica,sans-serif;max-width:800px;margin:0 auto;padding:20px;color:#1a1a1a;font-size:14px;}'
    + 'h1{font-size:20px;border-bottom:2px solid #00B4D8;padding-bottom:8px;color:#00B4D8;}'
    + 'h2{font-size:16px;margin-top:24px;color:#333;border-bottom:1px solid #ddd;padding-bottom:4px;}'
    + 'table{width:100%;border-collapse:collapse;margin:8px 0 16px;font-size:13px;}'
    + 'th,td{border:1px solid #ccc;padding:6px 8px;text-align:left;}'
    + 'th{background:#FDE8EC;font-weight:600;}'
    + 'td.num,.num{text-align:right;}'
    + 'tfoot td{font-weight:700;background:#FDE8EC;}'
    + '.empty-hint{color:#999;font-style:italic;padding:8px 0;}'
    + '.meta{color:#666;font-size:13px;margin-bottom:16px;}'
    + '.sig-block{margin-top:32px;border-top:1px solid #999;padding-top:16px;}'
    + '.sig-block img{max-width:340px;display:block;}'
    + '.sig-line{margin-top:8px;color:#666;font-size:12px;}'
    + '.tb-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;}'
    + '.tb-header h1{margin:0;}'
    + '.tb-logo{width:120px;height:auto;flex-shrink:0;}';
}

// Convert logo to base64 data URL for PDF embedding (uses configurable logo)
function getLogoBase64() {
  const logoUrl = (typeof appSettings !== 'undefined' && appSettings.firma_logo_url) ? appSettings.firma_logo_url : '';
  if (!logoUrl) return Promise.resolve('');
  return imgToBase64(logoUrl);
}

async function exportTagesberichtPDF() {
  const b = getBaustelle();
  if (!b) return;
  const today = new Date().toISOString().split('T')[0];
  const datumVon = document.getElementById('tbDatumVon')?.value || today;
  const datumBis = document.getElementById('tbDatumBis')?.value || today;
  const isRange = datumVon !== datumBis;
  const fmtDE = d => { if (!d) return ''; const p = d.split('-'); return p.length === 3 ? `${p[2]}.${p[1]}.${p[0]}` : d; };

  const html = buildTagesberichtHTML(b, datumVon, datumBis);
  const sig = isTbSignatureEmpty() ? '' : tbSignatureCanvas.toDataURL('image/png');

  // Build full HTML for PDF
  let fullHTML = '<div style="' + getTbPrintStyles().replace(/}/g, ';').replace(/{/g, '').replace(/body/g, '') + '">';
  // Actually build a proper container
  fullHTML = '';
  let container = document.createElement('div');
  container.innerHTML = '<style>' + getTbPrintStyles() + '</style>' + html;
  if (sig) {
    const datumLabel = isRange ? fmtDE(datumVon) + ' - ' + fmtDE(datumBis) : fmtDE(datumVon);
    container.innerHTML += '<div class="sig-block"><p style="font-weight:600;">Unterschrift Auftraggeber:</p>'
      + '<img src="' + sig + '" alt="Unterschrift" style="max-width:340px;display:block;">'
      + '<p class="sig-line">Datum: ' + datumLabel + ' | Digital unterschrieben</p></div>';
  }
  container.style.cssText = 'font-family:Arial,Helvetica,sans-serif;max-width:800px;padding:20px;color:#1a1a1a;font-size:14px;background:#fff;';

  // Replace logo src with base64 for PDF rendering
  const logoB64 = await getLogoBase64();
  if (logoB64) {
    const logoEl = container.querySelector('.tb-logo');
    if (logoEl) logoEl.src = logoB64;
  }

  // Load html2pdf dynamically
  if (!window.html2pdf) {
    await new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'lib/html2pdf.bundle.min.js';
      s.onload = resolve;
      s.onerror = () => reject(new Error('html2pdf konnte nicht geladen werden.'));
      document.head.appendChild(s);
    });
  }

  document.body.appendChild(container);
  const title = isRange ? 'Baubericht' : 'Tagesbericht';
  const datumStr = isRange ? datumVon + '_' + datumBis : datumVon;
  try {
    await html2pdf().set({
      margin: [10, 10, 10, 10],
      filename: title + '_' + b.name.replace(/[^a-zA-Z0-9———————_\- ]/gu, '_') + '_' + datumStr + '.pdf',
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    }).from(container).save();
  } catch(e) {
    alert('PDF-Export fehlgeschlagen: ' + e.message);
  } finally {
    container.remove();
  }
}

async function saveTagesbericht() {
  const b = getBaustelle();
  if (!b) return;
  if (isTbSignatureEmpty()) {
    alert('Bitte zuerst unterschreiben.');
    return;
  }
  // Capture signature immediately before any async work (canvas can lose state)
  const signatureData = tbSignatureCanvas.toDataURL('image/png');
  if (!signatureData || signatureData === 'data:,') {
    alert('Unterschrift konnte nicht gelesen werden. Bitte erneut unterschreiben.');
    return;
  }
  const today = new Date().toISOString().split('T')[0];
  const datumVon = document.getElementById('tbDatumVon')?.value || today;
  const datumBis = document.getElementById('tbDatumBis')?.value || today;
  const isRange = datumVon !== datumBis;
  const fmtDE = d => { if (!d) return ''; const p = d.split('-'); return p.length === 3 ? `${p[2]}.${p[1]}.${p[0]}` : d; };
  const htmlReport = buildTagesberichtHTML(b, datumVon, datumBis);
  const signature  = signatureData;

  // PDF erzeugen
  let pdfBase64 = '';
  try {
    const logoB64 = await getLogoBase64();
    let container = document.createElement('div');
    container.innerHTML = '<style>' + getTbPrintStyles() + '</style>' + htmlReport;
    if (signature) {
      const datumLabel = isRange ? fmtDE(datumVon) + ' - ' + fmtDE(datumBis) : fmtDE(datumVon);
      container.innerHTML += '<div class="sig-block"><p style="font-weight:600;">Unterschrift Auftraggeber:</p>'
        + '<img src="' + signature + '" alt="Unterschrift" style="max-width:340px;display:block;">'
        + '<p class="sig-line">Datum: ' + datumLabel + ' | Digital unterschrieben</p></div>';
    }
    container.style.cssText = 'font-family:Arial,Helvetica,sans-serif;max-width:800px;padding:20px;color:#1a1a1a;font-size:14px;background:#fff;';
    if (logoB64) { const le = container.querySelector('.tb-logo'); if (le) le.src = logoB64; }
    await ensureHtml2Pdf();
    document.body.appendChild(container);
    const pdfBlob = await html2pdf().set({
      margin: [10, 10, 10, 10], image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { scale: 2, useCORS: true }, jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    }).from(container).outputPdf('blob');
    container.remove();
    const reader = new FileReader();
    pdfBase64 = await new Promise(resolve => {
      reader.onload = () => resolve(reader.result.split(',')[1] || '');
      reader.readAsDataURL(pdfBlob);
    });
  } catch(e) { console.warn('PDF-Erzeugung fehlgeschlagen:', e); }

  try {
    const res = await fetch('api.php?action=save_tagesbericht', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ baustelleId: b.id, datumVon, datumBis, htmlReport, signature, pdfData: pdfBase64 })
    });
    const j = await res.json();
    if (j.error) throw new Error(j.error);
    const files = [j.fileName, j.pdfFileName].filter(Boolean).join(' + ');
    alert('Tagesbericht gespeichert!\nDatei: ' + files);
    document.getElementById('tagesberichtOverlay')?.remove();
    loadBaustelleFiles();
  } catch (e) {
    alert('Fehler: ' + e.message);
  }
}

