let kundenData = [];

function showKundenstamm() {
  if (!canDo('canReadKunden')) { showNotification('Keine Berechtigung.'); return; }
  selectedId = null;
  document.getElementById('btnKundenstamm')?.classList.add('active');
  document.getElementById('btnUebersicht')?.classList.remove('active');
  document.getElementById('btnMaterialKatalog')?.classList.remove('active');
  document.getElementById('btnStundenKatalog')?.classList.remove('active');
  document.getElementById('btnOffenesMaterial')?.classList.remove('active');
  document.getElementById('btnWhatsApp')?.classList.remove('active');
  document.getElementById('btnSchnellnotizenSidebar')?.classList.remove('active');
  document.getElementById('btnDienstleister')?.classList.remove('active');
  renderSidebar();
  hide('emptyState');
  hide('baustelleDetail');
  hide('uebersichtView');
  hide('materialKatalogView');
  hide('stundenKatalogView');
  hide('offenesMaterialView');
  hide('whatsappView');
  hide('schnellnotizenView');
  hide('dienstleisterView');
  hide('allgemeinSettingsView');
  hide('rechnungenView');
  hide('auswertungView');
  hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('dashboardView'); hide('vde0100View');
  show('kundenstammView');
  loadKundenData();
}

async function loadKundenData() {
  try {
    const r = await fetch('api.php?action=load_kunden');
    const j = await r.json();
    if (j.ok) kundenData = j.kunden || [];
    else kundenData = [];
  } catch (e) { console.warn('Kunden laden fehlgeschlagen:', e); kundenData = []; }
  renderKundenListe();
}

function renderKundenListe() {
  const container = document.getElementById('kundenListContainer');
  if (!container) return;
  const q = (document.getElementById('kundenSearch')?.value || '').toLowerCase().trim();
  const canWrite = canDo('canWriteKunden');

  // Show/hide add button
  const addBtn = document.getElementById('btnAddKunde');
  if (addBtn) addBtn.style.display = canWrite ? '' : 'none';

  let filtered = kundenData;
  if (q) {
    filtered = kundenData.filter(k =>
      [k.kundennummer, k.firma, k.vorname, k.nachname, k.ort, k.email, k.telefon, k.mobil]
        .filter(Boolean).join(' ').toLowerCase().includes(q)
    );
  }

  if (filtered.length === 0) {
    container.innerHTML = `<div class="kunden-empty">${q ? 'Keine Kunden gefunden.' : 'Noch keine Kunden angelegt.'}</div>`;
    return;
  }

  let html = `<table class="kunden-table"><thead><tr>
    <th>Kd.-Nr.</th><th>Firma</th><th>Name</th><th>Ort</th><th>Telefon</th><th>E-Mail</th>
    ${canWrite ? '<th style="width:80px;"></th>' : ''}
  </tr></thead><tbody>`;

  filtered.sort((a, b) => (a.firma || a.nachname || '').localeCompare(b.firma || b.nachname || ''));

  for (const k of filtered) {
    const name = [k.anrede, k.vorname, k.nachname].filter(Boolean).join(' ');
    const tel = k.telefon || k.mobil || '';
    const telCell = tel ? `<a href="tel:${esc(tel)}">${esc(tel)}</a>` : '-';
    const mailCell = k.email ? `<a href="mailto:${esc(k.email)}">${esc(k.email)}</a>` : '-';
    html += `<tr>
      <td>${esc(k.kundennummer || '-')}</td>
      <td>${esc(k.firma || '-')}</td>
      <td>${esc(name || '-')}</td>
      <td>${esc(k.plz ? k.plz + ' ' : '') + esc(k.ort || '-')}</td>
      <td>${telCell}</td>
      <td>${mailCell}</td>
      ${canWrite ? `<td class="kunde-actions">
        <button onclick="openKundeForm(${k.id})" title="Bearbeiten">${ico('edit')}</button>
        <button onclick="deleteKunde(${k.id})" title="Löschen">${ico('trash')}</button>
      </td>` : ''}
    </tr>`;
  }
  html += '</tbody></table>';
  container.innerHTML = html;
}

