let dashboardData = [];

// VDE 0100 – globaler Wrapper, damit loadOptionalModule per onClickFn aufrufen kann
function showVde0100() {
  window.vde0100Modul?.showVde0100View();
}

async function showDashboard() {
  if (!canDo('canReadDashboard')) return;
  selectedId = null;
  document.querySelectorAll('.sidebar-overview-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('btnDashboard')?.classList.add('active');
  renderSidebar();
  hide('emptyState'); hide('baustelleDetail'); hide('uebersichtView');
  hide('materialKatalogView'); hide('stundenKatalogView'); hide('offenesMaterialView');
  hide('whatsappView'); hide('schnellnotizenView'); hide('kundenstammView');
  hide('dienstleisterView'); hide('allgemeinSettingsView'); hide('rechnungenView');
  hide('auswertungView'); hide('din1090View'); hide('lagerView'); hide('aufmassView'); hide('vde0100View');
  show('dashboardView');
  await loadDashboard();
}

async function loadDashboard() {
  try {
    const payload = {};
    if (_dashboardOwnerFilter && _dashboardOwnerFilter !== 'alle') payload.filterUser = _dashboardOwnerFilter;
    const r = await fetch('api.php?action=load_dashboard', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify(payload)
    });
    const j = await r.json();
    if (j.ok) {
      dashboardData = j.items || [];
      _dashboardCanManage = j.canManage === true;
    }
  } catch(e) { console.warn('Dashboard laden:', e); }
  // Termine für das Dashboard-Widget laden (nur wenn berechtigt)
  if (canDo('canSeeOwnTermine') || canDo('canSeeAllTermine') || canDo('canManageTermine')) {
    try { await loadTermineData(); } catch(e) { /* unkritisch */ }
  }
  renderDashboard();
}

let _dashboardFilter = 'alle';
let _dashboardOwnerFilter = 'alle';
let _dashboardCanManage = false;

function renderDashboard() {
  const view = document.getElementById('dashboardView');
  if (!view) return;
  const canWrite = canDo('canWriteDashboard');

  // Filter
  const filters = [
    {key:'alle', label:'Alle'},
    {key:'aufgabe', label:'📋 Aufgaben'},
    {key:'notiz', label:'📝 Notizen'},
    {key:'erinnerung', label:'🔔 Erinnerungen'},
    {key:'offen', label:'Offen'},
    {key:'erledigt', label:'Erledigt'},
  ];
  const filterBar = filters.map(f =>
    `<button class="dashboard-filter-btn${_dashboardFilter===f.key?' active':''}" onclick="_dashboardFilter='${f.key}';renderDashboard()">${f.label}</button>`
  ).join('');

  // Owner-Filter (nur für Manager / Admin)
  let ownerFilterBar = '';
  if (_dashboardCanManage) {
    const ownerFilters = [
      {key:'alle', label:'Alle Mitarbeiter'},
      {key:'mine', label:'Meine Einträge'},
      {key:'assigned', label:'Mir zugewiesen'},
    ];
    ownerFilterBar = `<div class="dashboard-filter-bar" style="margin-top:6px">
      ${ownerFilters.map(f =>
        `<button class="dashboard-filter-btn${_dashboardOwnerFilter===f.key?' active':''}"
          onclick="_dashboardOwnerFilter='${f.key}';loadDashboard()">${f.label}</button>`
      ).join('')}
    </div>`;
  }

  // Owner-Filter client-seitig (nur zusätzlich zu Server-Seitenfilter)
  const curUser = currentUser || '';
  let items = dashboardData.slice();
  if (_dashboardOwnerFilter === 'mine') {
    items = items.filter(i => i.ersteller === curUser);
  } else if (_dashboardOwnerFilter === 'assigned') {
    items = items.filter(i => i.zugewiesen_an === curUser);
  }
  if (_dashboardFilter === 'offen' || _dashboardFilter === 'erledigt') {
    items = items.filter(i => i.status === _dashboardFilter);
  } else if (_dashboardFilter !== 'alle') {
    items = items.filter(i => i.typ === _dashboardFilter);
  }

  // Split into columns (Aufgaben / Notizen / Erinnerungen)
  const cols = [
    { label: '📋 Aufgaben', typ: 'aufgabe', items: items.filter(i => i.typ === 'aufgabe') },
    { label: '📝 Notizen',  typ: 'notiz',   items: items.filter(i => i.typ === 'notiz')   },
    { label: '🔔 Erinnerungen', typ: 'erinnerung', items: items.filter(i => i.typ === 'erinnerung') },
  ];
  // When filter is status-based: show all types in first col
  const singleColMode = _dashboardFilter === 'offen' || _dashboardFilter === 'erledigt';

  let colsHtml;
  if (singleColMode) {
    colsHtml = `<div class="dashboard-cols" style="grid-template-columns:1fr">
      <div class="dashboard-col">${items.map(i => renderDashboardItem(i, canWrite)).join('') || '<div class="dashboard-empty">Keine Einträge</div>'}</div>
    </div>`;
  } else {
    loadDashLayout();
    // Spaltendefinitionen inkl. Termine; Sichtbarkeit/Breite pro Anwender.
    const termineAvailable = canDo('canSeeOwnTermine') || canDo('canSeeAllTermine') || canDo('canManageTermine');
    const columnDefs = cols.map(c => ({ key: c.typ, label: c.label, items: c.items }));
    if (termineAvailable) columnDefs.push({ key: 'termine', label: '📅 Termine', termine: true });

    const visible = columnDefs.filter(c => dashColVisible(c.key));
    const gridParts = [];
    visible.forEach((c, i) => { gridParts.push(dashColWidth(c.key) + 'fr'); if (i < visible.length - 1) gridParts.push('7px'); });

    const inner = visible.map((c, i) => {
      const bodyHtml = c.termine
        ? _dashboardTermineRowsHtml()
        : (c.items.length ? c.items.map(x => renderDashboardItem(x, canWrite)).join('') : '<div class="dashboard-empty">Keine Einträge</div>');
      const addBtn = c.termine
        ? (canDo('canManageTermine') ? `<button class="btn btn-sm" style="font-size:.75rem;padding:2px 8px" onclick="openTerminFormModal(null)">+ Neu</button>` : '')
        : (canWrite ? `<button class="btn btn-sm" style="font-size:.75rem;padding:2px 8px" onclick="openDashboardItemForm(null,'${c.key}')">+ Neu</button>` : '');
      const colHtml = `<div class="dashboard-col" data-col="${c.key}">
        <div class="dashboard-widget">
          <div class="dashboard-widget-header">
            <span>${c.label}</span>
            <span style="display:flex;gap:4px;align-items:center">${addBtn}<button class="dash-col-hide" title="Spalte ausblenden" onclick="toggleDashCol('${c.key}')">✕</button></span>
          </div>
          <div class="dashboard-widget-body">${bodyHtml}</div>
        </div>
      </div>`;
      const handle = i < visible.length - 1
        ? `<div class="dash-resize" data-left="${c.key}" data-right="${visible[i + 1].key}" onmousedown="dashResizeStart(event)" title="Spaltenbreite ziehen"></div>`
        : '';
      return colHtml + handle;
    }).join('');

    const anyWidthCustom = _dashLayout.widths && Object.keys(_dashLayout.widths).length > 0;
    const configBar = `<div class="dashboard-colconfig">
      <span style="font-size:.75rem;color:var(--text-muted);font-weight:600">Spalten:</span>
      ${columnDefs.map(c => `<label class="dash-colchip"><input type="checkbox" ${dashColVisible(c.key) ? 'checked' : ''} onchange="toggleDashCol('${c.key}')"> ${c.label}</label>`).join('')}
      ${anyWidthCustom ? `<button class="btn btn-ghost btn-sm" style="font-size:.72rem;margin-left:auto" onclick="resetDashLayout()">↺ Breiten zurücksetzen</button>` : ''}
    </div>`;

    colsHtml = configBar + (visible.length
      ? `<div class="dashboard-cols" style="grid-template-columns:${gridParts.join(' ')}">${inner}</div>`
      : `<div class="dashboard-empty" style="padding:24px">Alle Spalten ausgeblendet – oben wieder einblenden.</div>`);
  }

  view.innerHTML = `
    <div class="dashboard-view-header">
      <h2>📋 Dashboard</h2>
      ${canWrite ? '<button class="btn btn-primary" onclick="openDashboardItemForm()">+ Neuer Eintrag</button>' : ''}
    </div>
    <div class="dashboard-filter-bar">${filterBar}</div>
    ${ownerFilterBar}
    ${colsHtml}
  `;
}

function renderDashboardItem(item, canWrite) {
  const isErledigt = item.status === 'erledigt';
  const today = new Date().toISOString().split('T')[0];
  const isUeberfaellig = item.faelligAm && item.faelligAm < today && !isErledigt;
  const prioBadge = item.prioritaet !== 'normal'
    ? `<span class="dashboard-item-badge badge-prio-${item.prioritaet}">${item.prioritaet.charAt(0).toUpperCase()+item.prioritaet.slice(1)}</span>`
    : '';
  const faelligBadge = item.faelligAm
    ? `<span style="${isUeberfaellig?'color:#B91C1C;font-weight:600':''}">${isUeberfaellig?'⚠️ ':''}\uD83D\uDCC5 ${formatDate(item.faelligAm)}</span>`
    : '';
  let linkBadge = '';
  if (item.linkTyp === 'baustelle' && item.linkId) {
    const b = (appData.baustellen||[]).find(x=>x.id===item.linkId);
    if (b) linkBadge = `<a href="#" onclick="showBaustelleById(${item.linkId});return false" style="color:var(--blue);text-decoration:none;font-size:.7rem">→ ${esc(b.name)}</a>`;
  }
  const zugewiesenBadge = item.zugewiesen_an
    ? (() => {
        const label = resolveZuweisung(item.zugewiesen_an);
        const isGruppe = item.zugewiesen_an.startsWith('gruppe:');
        const isAlle   = item.zugewiesen_an === 'alle';
        const bg = isAlle ? '#fef3c7' : isGruppe ? '#ede9fe' : '#e0f2fe';
        const fg = isAlle ? '#92400e' : isGruppe ? '#5b21b6' : '#0369a1';
        return `<span class="dashboard-item-badge" style="background:${bg};color:${fg}">${esc(label)}</span>`;
      })()
    : '';
  const actions = canWrite ? `
    <div class="dashboard-item-actions">
      <button onclick="moveDashboardItem(${item.id},'up')" title="Nach oben" style="font-size:.75rem">↑</button>
      <button onclick="moveDashboardItem(${item.id},'down')" title="Nach unten" style="font-size:.75rem">↓</button>
      <button onclick="toggleDashboardStatus(${item.id},'${item.status}')" title="${isErledigt?'Wieder öffnen':'Erledigen'}">${isErledigt?'↩️':'✅'}</button>
      <button onclick="openDashboardItemForm(${item.id})" title="Bearbeiten">✏️</button>
      <button onclick="deleteDashboardItem(${item.id})" title="Löschen" style="color:var(--danger)">🗑</button>
    </div>` : '';

  return `<div class="dashboard-item${isErledigt?' erledigt':''}">
    <div class="dashboard-item-dot" style="background:${esc(item.farbe)}"></div>
    <div class="dashboard-item-content">
      <div class="dashboard-item-title" title="${esc(item.titel)}">${esc(item.titel)}</div>
      ${item.beschreibung ? `<div style="font-size:.78rem;color:var(--text-muted);margin-top:2px;white-space:pre-wrap">${esc(item.beschreibung)}</div>` : ''}
      <div class="dashboard-item-meta">
        ${prioBadge}${faelligBadge}${linkBadge}${zugewiesenBadge}
        <span style="font-size:.67rem;opacity:.6">von ${esc(item.ersteller)}</span>
      </div>
    </div>
    ${actions}
  </div>`;
}

function _dashboardTermineRowsHtml() {
  const canManageT = canDo('canManageTermine');
  const curUser = currentUser || '';
  const today = new Date().toISOString().split('T')[0];

  let list = (termineData || []).slice();
  // Berechtigung: ohne "alle sehen" nur eigene/zugewiesene Termine
  if (!canDo('canSeeAllTermine')) {
    list = list.filter(t => t.ersteller === curUser || (Array.isArray(t.zugewiesen) ? t.zugewiesen.includes(curUser) : (t.zugewiesen || '').includes(curUser)));
  }
  // Nur heutige und kommende Termine
  list = list.filter(t => t.datum && t.datum >= today);
  list.sort((a, b) => (a.datum || '').localeCompare(b.datum || '') || (a.zeitVon || '').localeCompare(b.zeitVon || ''));

  const rows = list.map(t => {
    const b = t.baustelleId ? (appData.baustellen || []).find(x => x.id === t.baustelleId) : null;
    const zeit = (t.ganztags || !t.zeitVon) ? 'ganztägig' : (t.zeitVon + (t.zeitBis ? '–' + t.zeitBis : ''));
    const isToday = t.datum === today;
    const clickAttr = canManageT ? ` onclick="openTerminFormModal(${t.id})" style="cursor:pointer"` : '';
    return `<div class="dashboard-item"${clickAttr} title="${esc(t.titel)}">
      <div class="dashboard-item-dot" style="background:${esc(t.farbe || '#00B4D8')}"></div>
      <div class="dashboard-item-content">
        <div class="dashboard-item-title">${esc(t.titel)}</div>
        <div class="dashboard-item-meta">
          <span style="${isToday ? 'color:#B91C1C;font-weight:600' : ''}">📅 ${formatDate(t.datum)}${isToday ? ' (heute)' : ''}</span>
          <span style="font-size:.7rem;opacity:.75">${esc(zeit)}</span>
          ${b ? `<span style="font-size:.7rem;color:var(--blue)">→ ${esc(b.name)}</span>` : ''}
        </div>
      </div>
    </div>`;
  }).join('');

  return rows || '<div class="dashboard-empty">Keine anstehenden Termine</div>';
}

// ── Dashboard-Layout pro Anwender: Spalten ein-/ausblenden + Breite ──────────
let _dashLayout = null;
function _dashLayoutKey() { return 'bk_dashLayout_' + (currentUser || '_'); }
function loadDashLayout() {
  if (_dashLayout) return _dashLayout;
  let d = { hidden: {}, widths: {} };
  try { const r = localStorage.getItem(_dashLayoutKey()); if (r) { const p = JSON.parse(r); if (p && typeof p === 'object') d = p; } } catch(e) {}
  d.hidden = d.hidden || {}; d.widths = d.widths || {};
  _dashLayout = d; return d;
}
function saveDashLayout() { try { localStorage.setItem(_dashLayoutKey(), JSON.stringify(_dashLayout)); } catch(e) {} }
function dashColVisible(key) { loadDashLayout(); return !_dashLayout.hidden[key]; }
function dashColWidth(key) { loadDashLayout(); const w = parseFloat(_dashLayout.widths[key]); return (w && w > 0) ? w : 1; }
function toggleDashCol(key) { loadDashLayout(); _dashLayout.hidden[key] = !_dashLayout.hidden[key]; saveDashLayout(); renderDashboard(); }
function resetDashLayout() { loadDashLayout(); _dashLayout.widths = {}; saveDashLayout(); renderDashboard(); }

// Ziehen der Trenner zwischen zwei Spalten → Breitenverhältnis anpassen.
function dashResizeStart(e) {
  e.preventDefault();
  const handle = e.currentTarget;
  const cols = handle.parentElement;
  const leftKey = handle.dataset.left, rightKey = handle.dataset.right;
  const leftEl = cols.querySelector(`.dashboard-col[data-col="${leftKey}"]`);
  const rightEl = cols.querySelector(`.dashboard-col[data-col="${rightKey}"]`);
  if (!leftEl || !rightEl) return;
  loadDashLayout();
  const startX = e.clientX;
  const startLpx = leftEl.offsetWidth;
  const totalPx = leftEl.offsetWidth + rightEl.offsetWidth;
  const totalFr = dashColWidth(leftKey) + dashColWidth(rightKey);
  document.body.style.cursor = 'col-resize';
  document.body.style.userSelect = 'none';
  function move(ev) {
    let fracL = (startLpx + (ev.clientX - startX)) / totalPx;
    fracL = Math.max(0.15, Math.min(0.85, fracL));
    _dashLayout.widths[leftKey]  = Math.round(fracL * totalFr * 100) / 100;
    _dashLayout.widths[rightKey] = Math.round((1 - fracL) * totalFr * 100) / 100;
    const order = [...cols.querySelectorAll('.dashboard-col')].map(c => c.dataset.col);
    const parts = [];
    order.forEach((k, i) => { parts.push(dashColWidth(k) + 'fr'); if (i < order.length - 1) parts.push('7px'); });
    cols.style.gridTemplateColumns = parts.join(' ');
  }
  function up() {
    document.removeEventListener('mousemove', move);
    document.removeEventListener('mouseup', up);
    document.body.style.cursor = '';
    document.body.style.userSelect = '';
    saveDashLayout();
  }
  document.addEventListener('mousemove', move);
  document.addEventListener('mouseup', up);
}

function openDashboardItemForm(id, defaultTyp) {
  document.getElementById('dashboardItemOverlay')?.remove();
  const existing = id ? dashboardData.find(i => i.id === id) : null;
  const baustellen = (appData.baustellen || []);
  const bOpts = baustellen.map(b =>
    `<option value="${b.id}"${existing && existing.linkTyp==='baustelle' && existing.linkId===b.id?' selected':''}>${esc(b.name)}</option>`
  ).join('');
  const typVal = existing ? existing.typ : (defaultTyp || 'aufgabe');

  const overlay = document.createElement('div');
  overlay.id = 'dashboardItemOverlay';
  overlay.className = 'kunde-form-overlay';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `<div class="kunde-form-card" style="max-width:560px">
    <h3 style="margin:0 0 16px">${existing ? 'Dashboard-Eintrag bearbeiten' : 'Neuer Dashboard-Eintrag'}</h3>
    <div class="form-row">
      <div class="form-group" style="flex:0 0 140px">
        <label class="form-label">Typ</label>
        <select class="form-control" id="dbfTyp">
          <option value="aufgabe"${typVal==='aufgabe'?' selected':''}>📋 Aufgabe</option>
          <option value="notiz"${typVal==='notiz'?' selected':''}>📝 Notiz</option>
          <option value="erinnerung"${typVal==='erinnerung'?' selected':''}>🔔 Erinnerung</option>
        </select>
      </div>
      <div class="form-group" style="flex:1">
        <label class="form-label">Titel *</label>
        <input class="form-control" id="dbfTitel" value="${existing?esc(existing.titel):''}">
      </div>
    </div>
    <div class="form-group">
      <label class="form-label">Beschreibung</label>
      <textarea class="form-control" id="dbfBeschr" rows="3">${existing?esc(existing.beschreibung||''):''}</textarea>
    </div>
    <div class="form-row">
      <div class="form-group" style="flex:1">
        <label class="form-label">Fällig am</label>
        <input type="date" class="form-control" id="dbfFaellig" value="${existing?existing.faelligAm:''}">
      </div>
      <div class="form-group" style="flex:0 0 130px">
        <label class="form-label">Priorität</label>
        <select class="form-control" id="dbfPrio">
          <option value="niedrig"${existing&&existing.prioritaet==='niedrig'?' selected':''}>Niedrig</option>
          <option value="normal"${!existing||existing.prioritaet==='normal'?' selected':''}>Normal</option>
          <option value="hoch"${existing&&existing.prioritaet==='hoch'?' selected':''}>Hoch</option>
        </select>
      </div>
      <div class="form-group" style="flex:0 0 60px">
        <label class="form-label">Farbe</label>
        <input type="color" class="form-control" id="dbfFarbe" value="${existing?existing.farbe:'#00B4D8'}" style="height:36px;padding:2px 4px">
      </div>
    </div>
    <div class="form-group"${!_dashboardCanManage ? ' style="display:none"' : ''}>
      <label class="form-label">Zuweisen an</label>
      <select class="form-control" id="dbfZugewiesen">
        <option value="">– Niemanden –</option>
      </select>
    </div>
    <div class="form-group">
      <label class="form-label">Verknüpfen mit Projekt</label>
      <select class="form-control" id="dbfBaustelle" onchange="document.getElementById('dbfLinkTyp').value=this.value?'baustelle':''">
        <option value="">– Keine –</option>
        ${bOpts}
      </select>
      <input type="hidden" id="dbfLinkTyp" value="${existing&&existing.linkTyp==='baustelle'?'baustelle':''}">
    </div>
    <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px">
      <button class="btn btn-secondary" onclick="document.getElementById('dashboardItemOverlay')?.remove()">Abbrechen</button>
      <button class="btn btn-primary" onclick="saveDashboardItem(${id||'null'})">${existing ? 'Speichern' : 'Erstellen'}</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  // Benutzer und Gruppen laden und Select befüllen (nur für Admin/Master)
  if (_dashboardCanManage) {
    const zugewiesenVal = existing ? (existing.zugewiesen_an || '') : '';
    const sel = document.getElementById('dbfZugewiesen');
    if (sel) {
      // "Alle Mitarbeiter" Option
      const optAlle = document.createElement('option');
      optAlle.value = 'alle';
      optAlle.textContent = '📢 Alle Mitarbeiter';
      if (zugewiesenVal === 'alle') optAlle.selected = true;
      sel.appendChild(optAlle);

      // Trennlinie Benutzer
      const grpUsers = document.createElement('optgroup');
      grpUsers.label = '👤 Benutzer';
      sel.appendChild(grpUsers);

      // Benutzer laden
      fetch('api.php?action=list_users').then(r => r.json()).then(j => {
        if (!j.ok) return;
        (j.users || []).forEach(u => {
          const opt = document.createElement('option');
          opt.value = u.username;
          opt.textContent = u.username + (u.kuerzel ? ' (' + u.kuerzel + ')' : '');
          if (u.username === zugewiesenVal) opt.selected = true;
          grpUsers.appendChild(opt);
        });
      }).catch(() => {});

      // Gruppen einfügen
      if ((gruppenData || []).length > 0) {
        const grpGruppen = document.createElement('optgroup');
        grpGruppen.label = '👥 Gruppen';
        sel.appendChild(grpGruppen);
        gruppenData.forEach(g => {
          const opt = document.createElement('option');
          opt.value = 'gruppe:' + g.id;
          opt.textContent = g.name;
          if (zugewiesenVal === 'gruppe:' + g.id) opt.selected = true;
          grpGruppen.appendChild(opt);
        });
      }
    }
  }
}

async function saveDashboardItem(id) {
  const titel = document.getElementById('dbfTitel')?.value?.trim();
  if (!titel) { alert('Titel ist Pflichtfeld.'); return; }
  const payload = {
    id: id || null,
    typ: document.getElementById('dbfTyp')?.value || 'aufgabe',
    titel,
    beschreibung: document.getElementById('dbfBeschr')?.value?.trim() || '',
    faelligAm: document.getElementById('dbfFaellig')?.value || '',
    prioritaet: document.getElementById('dbfPrio')?.value || 'normal',
    status: id ? (dashboardData.find(i=>i.id===id)?.status || 'offen') : 'offen',
    linkTyp: document.getElementById('dbfLinkTyp')?.value || '',
    linkId: parseInt(document.getElementById('dbfBaustelle')?.value) || null,
    farbe: document.getElementById('dbfFarbe')?.value || '#00B4D8',
    zugewiesen_an: document.getElementById('dbfZugewiesen')?.value || '',
  };
  try {
    const r = await fetch('api.php?action=save_dashboard_item', {
      method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload)
    });
    const j = await r.json();
    if (j.ok) { document.getElementById('dashboardItemOverlay')?.remove(); await loadDashboard(); }
    else showToast(j.error || 'Fehler beim Speichern', 'error');
  } catch(e) { showToast('Netzwerkfehler', 'error'); }
}

async function deleteDashboardItem(id) {
  if (!confirm('Dashboard-Eintrag wirklich löschen?')) return;
  try {
    const r = await fetch('api.php?action=delete_dashboard_item', {
      method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({id})
    });
    const j = await r.json();
    if (j.ok) await loadDashboard();
    else showToast(j.error || 'Fehler', 'error');
  } catch(e) { showToast('Netzwerkfehler', 'error'); }
}

async function toggleDashboardStatus(id, currentStatus) {
  const newStatus = currentStatus === 'erledigt' ? 'offen' : 'erledigt';
  try {
    const r = await fetch('api.php?action=update_dashboard_item_status', {
      method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({id, status: newStatus})
    });
    const j = await r.json();
    if (j.ok) {
      const idx = dashboardData.findIndex(i => i.id === id);
      if (idx >= 0) dashboardData[idx].status = newStatus;
      renderDashboard();
    } else showToast(j.error || 'Fehler', 'error');
  } catch(e) { showToast('Netzwerkfehler', 'error'); }
}

function showBaustelleById(id) {
  const b = (appData.baustellen||[]).find(x=>x.id===id);
  if (b) selectBaustelle(id);
  else showToast('Verknüpfte Baustelle nicht gefunden (evtl. archiviert oder gelöscht).', 'error');
}

async function moveDashboardItem(id, dir) {
  // Alle Items in gleicher Spalte ermitteln (oder alle bei Status-Filter)
  const singleColMode = _dashboardFilter === 'offen' || _dashboardFilter === 'erledigt';
  const targetItem = dashboardData.find(i => i.id === id);
  if (!targetItem) return;
  let pool;
  if (singleColMode) {
    pool = dashboardData.filter(i => i.status === _dashboardFilter);
  } else {
    pool = dashboardData.filter(i => i.typ === targetItem.typ);
  }
  pool.sort((a, b) => a.sortPos - b.sortPos || a.id - b.id);
  const idx = pool.findIndex(i => i.id === id);
  const swapIdx = dir === 'up' ? idx - 1 : idx + 1;
  if (swapIdx < 0 || swapIdx >= pool.length) return;
  const other = pool[swapIdx];
  // Positionen tauschen
  const posA = targetItem.sortPos || idx;
  const posB = other.sortPos || swapIdx;
  // Sicherstellen unterschiedliche sortPos
  const newA = dir === 'up' ? Math.min(posA, posB) - 1 : Math.max(posA, posB) + 1;
  const newB = targetItem.sortPos;
  targetItem.sortPos = posB;
  other.sortPos = posA;
  renderDashboard();
  try {
    await fetch('api.php?action=update_dashboard_sort', {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ items: [
        { id: targetItem.id, sortPos: targetItem.sortPos },
        { id: other.id,      sortPos: other.sortPos      },
      ]})
    });
  } catch(e) { console.warn('Sort save failed:', e); }
}

