function printAuswertungMitarbeiter() {
  const year = parseInt(document.getElementById('awMaYear')?.value) || new Date().getFullYear();
  const users = awData.users.filter(u => u.role !== 'admin' && u.showInZeitverwaltung !== false);
  const now = new Date().toLocaleDateString('de-DE');
  const bisHeuteLabel = isCurrentAwYear(year) ? ' (bis heute)' : '';
  let rows = '';
  let sumSoll = 0, sumIst = 0, sumUrl = 0, sumUrlR = 0, sumKr = 0;
  users.forEach(u => {
    const entries = (awData.zeit[u.username]?.entries || []).filter(e => e.datum && e.datum.startsWith(String(year)));
    const urlaubJahr = bkUrlaubsanspruch(u, year);
    const jahreswerte = calcJahresSollIst(u, awData.zeit[u.username]?.entries || [], year);
    const totalSoll = jahreswerte.soll;
    const totalIst = jahreswerte.ist;
    const urlG = entries.filter(e => e.typ === 'urlaub').length;
    const urlR = urlaubJahr - urlG;
    const kr = entries.filter(e => e.typ === 'krank').length;
    const diff = totalIst - totalSoll;
    const buchungen = awData.gleitzeit[u.username] || [];
    const gleit = calcGleitzeitSaldo(awData.zeit[u.username]?.entries || [], u, year, buchungen);
    sumSoll += totalSoll; sumIst += totalIst; sumUrl += urlG; sumUrlR += urlR; sumKr += kr;
    const dc = diff >= 0 ? 'pos' : 'neg';
    const gc = gleit >= 0 ? 'pos' : 'neg';
    rows += `<tr><td>${esc(u.username)}</td><td>${totalSoll.toFixed(2)}</td><td>${totalIst.toFixed(2)}</td><td class="${dc}" style="font-weight:600">${diff>=0?'+':''}${diff.toFixed(2)}</td><td>${urlG}</td><td>${urlR}</td><td>${kr}</td><td class="${gc}" style="font-weight:600">${gleit>=0?'+':''}${gleit.toFixed(2)} h</td></tr>`;
  });
  const sumDiff = sumIst - sumSoll;
  const w = window.open('', '_blank', 'width=1000,height=700');
  w.document.write(`<!DOCTYPE html><html style="color-scheme:light"><head><meta charset="utf-8"><title>Mitarbeiter-Auswertung ${year}</title>
<style>
  body{font-family:Arial,sans-serif;font-size:11px;margin:20px;color:#222}
  h1{font-size:18px;margin-bottom:4px} .sub{font-size:11px;color:#666;margin-bottom:16px}
  table{width:100%;border-collapse:collapse;font-size:10px;margin-top:10px}
  th{text-align:right;font-size:9px;text-transform:uppercase;color:#666;padding:4px 6px;border-bottom:2px solid #ccc}
  th:first-child{text-align:left}
  td{padding:5px 6px;text-align:right;border-bottom:1px solid #eee}
  td:first-child{text-align:left;font-weight:600}
  .pos{color:#198754} .neg{color:#dc3545}
  @media print{body{margin:10mm}}
</style></head><body>
<h1>Mitarbeiter-Auswertung ${year}${bisHeuteLabel}</h1><div class="sub">Stand: ${now} - ${users.length} Mitarbeiter</div>
<table><thead><tr><th style="text-align:left">Mitarbeiter</th><th>Soll (h)${bisHeuteLabel}</th><th>Ist (h)${bisHeuteLabel}</th><th>+/- (h)${bisHeuteLabel}</th><th>Urlaub</th><th>Urlaub Rest</th><th>Krank</th><th>Gleitzeitkonto</th></tr></thead><tbody>
${rows}
<tr style="font-weight:700;border-top:2px solid #333"><td>Summe</td><td>${sumSoll.toFixed(2)}</td><td>${sumIst.toFixed(2)}</td><td class="${sumDiff>=0?'pos':'neg'}">${sumDiff>=0?'+':''}${sumDiff.toFixed(2)}</td><td>${sumUrl}</td><td>${sumUrlR}</td><td>${sumKr}</td><td></td></tr>
</tbody></table></body></html>`);
  w.document.close();
  setTimeout(() => w.print(), 300);
}

function drawProjektCharts(projekte) {
  if (typeof Chart === 'undefined') return;
  const primary = '#00B4D8', success = '#198754', danger = '#dc3545', warning = '#ffc107', info = '#0ea5e9';
  // 1) Umsatzverteilung Doughnut
  const cUmsatz = document.getElementById('awChartUmsatz');
  if (cUmsatz) {
    let tM = 0, tA = 0, tP = 0;
    projekte.forEach(p => { tM += p.matVk; tA += p.azEin; tP += p.pSum; });
    awCharts.umsatz = new Chart(cUmsatz, {
      type: 'doughnut',
      data: { labels: ['Material', 'Arbeitszeit', 'Pauschalen'], datasets: [{ data: [tM, tA, tP], backgroundColor: [primary, success, warning], borderWidth: 1 }] },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { font: { size: 11 } } } } }
    });
  }
  // 2) Top 10 Gewinn
  const cGewinn = document.getElementById('awChartGewinn');
  if (cGewinn) {
    const top = [...projekte].sort((a, b) => b.gewinn - a.gewinn).slice(0, 10);
    awCharts.gewinn = new Chart(cGewinn, {
      type: 'bar',
      data: { labels: top.map(p => p.name.length > 20 ? p.name.substring(0,18)+'—' : p.name), datasets: [{ label: 'Gewinn (€)', data: top.map(p => p.gewinn), backgroundColor: top.map(p => p.gewinn >= 0 ? success : danger), borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { ticks: { callback: v => fmtNum(v) } } } }
    });
  }
  // 3) Top 15 Umsatz je Projekt (horizontal bar)
  const cProj = document.getElementById('awChartProjekte');
  if (cProj) {
    const sorted = [...projekte].sort((a, b) => b.gesamt - a.gesamt).slice(0, 15);
    awCharts.projekte = new Chart(cProj, {
      type: 'bar',
      data: {
        labels: sorted.map(p => { const n = p.projektNr ? p.projektNr + ' ' : ''; return (n + p.name).length > 25 ? (n + p.name).substring(0,23)+'—' : n + p.name; }),
        datasets: [
          { label: 'Material', data: sorted.map(p => p.matVk), backgroundColor: primary, borderRadius: 2 },
          { label: 'Arbeitszeit', data: sorted.map(p => p.azEin), backgroundColor: success, borderRadius: 2 },
          { label: 'Pauschalen', data: sorted.map(p => p.pSum), backgroundColor: warning, borderRadius: 2 }
        ]
      },
      options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { stacked: true, ticks: { callback: v => fmtNum(v) } }, y: { stacked: true, ticks: { font: { size: 10 } } } } }
    });
  }
}

function drawMitarbeiterCharts(year) {
  if (typeof Chart === 'undefined') return;
  const primary = '#00B4D8', success = '#198754', danger = '#dc3545', warning = '#ffc107', info = '#6366f1', orange = '#f97316';
  const users = awData.users.filter(u => u.role !== 'admin' && u.showInZeitverwaltung !== false);
  const names = users.map(u => u.username);
  const monthNames = ['Jan','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
  const stichtag = calcJahresStichtag(year);
  const bisHeuteLabel = isCurrentAwYear(year) ? ' (bis heute)' : '';

  // 1) Soll vs. Ist (grouped bar)
  const cStd = document.getElementById('awChartStunden');
  if (cStd) {
    const sollArr = [], istArr = [];
    users.forEach(u => {
      const jahreswerte = calcJahresSollIst(u, awData.zeit[u.username]?.entries || [], year);
      sollArr.push(jahreswerte.soll); istArr.push(jahreswerte.ist);
    });
    awCharts.ma_stunden = new Chart(cStd, {
      type: 'bar',
      data: { labels: names, datasets: [{ label: 'Soll (h)' + bisHeuteLabel, data: sollArr, backgroundColor: '#cbd5e1', borderRadius: 4 }, { label: 'Ist (h)' + bisHeuteLabel, data: istArr, backgroundColor: primary, borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { font: { size: 11 } } } }, scales: { y: { beginAtZero: true } } }
    });
  }

  // 2) überstunden
  const cUe = document.getElementById('awChartUeberstunden');
  if (cUe) {
    const diffArr = [];
    users.forEach(u => {
      const jahreswerte = calcJahresSollIst(u, awData.zeit[u.username]?.entries || [], year);
      diffArr.push(jahreswerte.ist - jahreswerte.soll);
    });
    awCharts.ma_ueber = new Chart(cUe, {
      type: 'bar',
      data: { labels: names, datasets: [{ label: '+/- Stunden', data: diffArr, backgroundColor: diffArr.map(v => v >= 0 ? success : danger), borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: false } } }
    });
  }

  // 3) Urlaub & Krankheit (stacked bar)
  const cUr = document.getElementById('awChartUrlaub');
  if (cUr) {
    const urlArr = [], urlRestArr = [], krArr = [];
    users.forEach(u => {
      const entries = (awData.zeit[u.username]?.entries || []).filter(e => e.datum && e.datum.startsWith(String(year)));
      const urlJ = bkUrlaubsanspruch(u, year);
      const urlG = entries.filter(e => e.typ === 'urlaub').length;
      const krG = entries.filter(e => e.typ === 'krank').length;
      urlArr.push(urlG); urlRestArr.push(Math.max(0, urlJ - urlG)); krArr.push(krG);
    });
    awCharts.ma_urlaub = new Chart(cUr, {
      type: 'bar',
      data: { labels: names, datasets: [
        { label: 'Urlaub genommen', data: urlArr, backgroundColor: primary, borderRadius: 2 },
        { label: 'Urlaub Rest', data: urlRestArr, backgroundColor: '#e0f2fe', borderRadius: 2 },
        { label: 'Krank', data: krArr, backgroundColor: orange, borderRadius: 2 }
      ]},
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { font: { size: 11 } } } }, scales: { x: { stacked: false }, y: { beginAtZero: true } } }
    });
  }

  // 4) Monatsübersicht (line chart - total Ist pro Monat)
  const cMo = document.getElementById('awChartMonat');
  if (cMo) {
    const moSoll = [], moIst = [];
    for (let m = 0; m < 12; m++) {
      let mSoll = 0, mIst = 0;
      users.forEach(u => {
        const monatswerte = calcMonatsSollIstBisStichtag(u, awData.zeit[u.username]?.entries || [], year, m, stichtag);
        mSoll += monatswerte.soll;
        mIst += monatswerte.ist;
      });
      moSoll.push(mSoll); moIst.push(mIst);
    }
    awCharts.ma_monat = new Chart(cMo, {
      type: 'line',
      data: { labels: monthNames, datasets: [
        { label: 'Soll (h)', data: moSoll, borderColor: '#94a3b8', backgroundColor: 'rgba(148,163,184,0.1)', fill: true, tension: 0.3, borderWidth: 2 },
        { label: 'Ist (h)', data: moIst, borderColor: primary, backgroundColor: 'rgba(0,180,216,0.1)', fill: true, tension: 0.3, borderWidth: 2 }
      ]},
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { font: { size: 11 } } } }, scales: { y: { beginAtZero: true } } }
    });
  }
}

// ============================================================
// START
// ============================================================
(async () => {
  try {
    await init();
  } catch (e) {
    console.error('init() fehlgeschlagen:', e);
    // Trotzdem Sidebar rendern damit App benutzbar bleibt
    try { renderSidebar(); } catch (_) {}
  }
  try {
    await initBackupStatus();
  } catch (e) {
    console.error('initBackupStatus() fehlgeschlagen:', e);
  }
})();
